  //----
  // COLUMNS
  //----
  /// Primary key. Unique identifier for the todo user session.
  id String @id @db.Uuid

  /// Todo user that this session is associated with. {@link
  /// todo_app_todousers.id}.
  todo_app_todouser_id String @db.Uuid

  /// IP address from which the todo user accessed the service during this
  /// session.
  ip String

  /// Full URL that the todo user initially accessed when starting this session.
  href String

  /// Referrer URL indicating where the todo user navigated from when the
  /// session started.
  referrer String

  /// Timestamp when this todo user session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this todo user session expired or was invalidated. Null
  /// while the session remains active.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  todoUser todo_app_todousers @relation(fields: [todo_app_todouser_id], references: [id], onDelete: Cascade)

  @@index([todo_app_todouser_id, created_at])
}

