  /// Timestamp when this administrative account record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo_app_todoadmin_sessions todo_app_todoadmin_sessions[]
  todo_app_todo_admin_audits todo_app_todo_admin_audits[]

  @@unique([email])
}

/// Authentication session records for todoAdmin actors.
///
/// Represents login sessions for administrative users, allowing the system
