  //----
  todoAdmin todo_app_todoadmins @relation(fields: [todo_app_todoadmin_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@index([todo_app_todoadmin_id, created_at], map: "todo_app_todoadmin_sessions_todo_app_todoadmin_id_crea_e956d61d")
