import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

/**
 * Validate creation of a new guestUser identity and linked session via POST
 * /auth/guestUser/join.
 *
 * ## Business intent
 *
 * This e2e test exercises the anonymous guest bootstrap flow. A visitor without
 * any prior identity context calls the guest join endpoint with basic request
 * metadata (landing page URL, referrer, and IP) and an optional display name.
 * The backend must:
 *
 * - Create (or select) a guest identity row in todo_app_guestusers
 * - Create a guest session row in todo_app_guestuser_sessions
 * - Issue a pair of JWT tokens wrapped in ITodoAppGuestUser.IAuthorized
 *
 * The scenario here focuses on the "new identity" path by omitting the
 * external_reference from ITodoAppGuestUserJoin.IRequest. This ensures the
 * backend is free to allocate a fresh guest identity and corresponding session
 * using the provided navigation context.
 *
 * ## Validation strategy
 *
 * 1. Construct a ITodoAppGuestUserJoin.IRequest payload with:
 *
 *    - Href: valid URI (landing page)
 *    - Referrer: valid URI (referrer page)
 *    - Ip: plausible IP string
 *    - Display_name: friendly label
 *    - External_reference: intentionally omitted
 * 2. Call api.functional.auth.guestUser.join with this payload.
 * 3. Use typia.assert to fully validate that the response matches
 *    ITodoAppGuestUser.IAuthorized.
 * 4. Perform additional business-level assertions using TestValidator:
 *
 *    - Token.access and token.refresh are non-empty strings.
 *    - Guest.id is non-empty and consistent with the session.guestUser.id.
 *    - Guest.status is a non-empty string.
 *    - Guest.created_at and guest.updated_at are non-empty (format already validated
 *         by typia).
 *    - Session.id is non-empty.
 *    - Session.guestUser.id === guest.id.
 *    - Session.ip, href, and referrer mirror the request payload values since we are
 *         explicitly providing them.
 *    - Session.created_at is non-empty.
 *    - Session.expired_at is either null or undefined (not yet expired).
 * 5. Rely on the SDK behavior that sets connection.headers.Authorization from
 *    token.access as a side-effect. We do not inspect headers directly
 *    (forbidden) and we do not have any other guest-protected endpoints
 *    available in this local API surface, so we limit token validation to
 *    structural checks.
 */
export async function test_api_guestuser_join_new_identity_creation(
  connection: api.IConnection,
) {
  // 1. Build a realistic ITodoAppGuestUserJoin.IRequest payload
  const href: string & tags.Format<"uri"> =
    "https://example.com/todos?source=guest-bootstrap";
  const referrer: string & tags.Format<"uri"> =
    "https://referrer.example.com/landing";
  const ip: string = "203.0.113.42";

  const requestBody = {
    href,
    referrer,
    // Provide an explicit IP even though the server could infer it
    ip,
    display_name: RandomGenerator.name(2),
    // external_reference intentionally omitted to model "new" guest identity
  } satisfies ITodoAppGuestUserJoin.IRequest;

  // 2. Call the guestUser join endpoint
  const authorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: requestBody,
    });

  // 3. Structural type validation
  typia.assert<ITodoAppGuestUser.IAuthorized>(authorized);

  const token: IAuthorizationToken = authorized.token;
  const guest: ITodoAppGuestUser.ISummary = authorized.guest;
  const session: ITodoAppGuestUserSession.ISummary = authorized.session;

  // 4. Business-level assertions
  // 4-1. Token basics
  TestValidator.predicate(
    "guestUser join: access token must be non-empty",
    token.access.length > 0,
  );
  TestValidator.predicate(
    "guestUser join: refresh token must be non-empty",
    token.refresh.length > 0,
  );

  // 4-2. Guest identity fields
  TestValidator.predicate(
    "guestUser join: guest.id must be non-empty",
    guest.id.length > 0,
  );
  TestValidator.predicate(
    "guestUser join: guest.status must be non-empty",
    guest.status.length > 0,
  );
  TestValidator.predicate(
    "guestUser join: guest.created_at must be non-empty",
    guest.created_at.length > 0,
  );
  TestValidator.predicate(
    "guestUser join: guest.updated_at must be non-empty",
    guest.updated_at.length > 0,
  );

  // 4-3. Session fields and relationship to guest
  TestValidator.predicate(
    "guestUser join: session.id must be non-empty",
    session.id.length > 0,
  );

  TestValidator.equals(
    "guestUser join: session.guestUser.id must match guest.id",
    session.guestUser.id,
    guest.id,
  );

  TestValidator.equals(
    "guestUser join: session.ip should mirror the request ip",
    session.ip,
    ip,
  );
  TestValidator.equals(
    "guestUser join: session.href should mirror the request href",
    session.href,
    href,
  );
  TestValidator.equals(
    "guestUser join: session.referrer should mirror the request referrer",
    session.referrer,
    referrer,
  );

  TestValidator.predicate(
    "guestUser join: session.created_at must be non-empty",
    session.created_at.length > 0,
  );

  // expired_at is nullable; for a fresh session it should be null or undefined
  TestValidator.predicate(
    "guestUser join: new session should not be expired",
    session.expired_at === null || session.expired_at === undefined,
  );

  // 5. Consistency sanity checks (re-reading from the same object)
  TestValidator.equals(
    "guestUser join: guest.id remains stable across references",
    authorized.guest.id,
    guest.id,
  );
  TestValidator.equals(
    "guestUser join: session.guestUser.id remains stable",
    authorized.session.guestUser.id,
    session.guestUser.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

/**
 * Validate guestUser identity reuse by external_reference while creating new
 * sessions.
 *
 * Business intent:
 *
 * - External_reference is a stable key that should map repeat join calls to the
 *   same guest identity record in todo_app_guestusers.
 * - Each POST /auth/guestUser/join invocation must still create a new
 *   todo_app_guestuser_sessions row linked to that identity, issuing fresh JWT
 *   token information.
 *
 * Test flow:
 *
 * 1. Generate a stable external_reference string for this test run.
 * 2. Call join() with that external_reference, an initial display_name, and
 *    realistic href/referrer URLs to open the first guest session.
 * 3. Call join() again with the same external_reference but different display_name
 *    and navigation context to simulate a new visit.
 * 4. Assert that the guest identity (guest.id) is reused across both calls.
 * 5. Assert that the session identifier (session.id) differs, confirming a new
 *    session was created.
 * 6. Assert that each session.guestUser.id matches the shared guest.id.
 * 7. Perform lightweight checks on display_name behavior and token shapes.
 */
export async function test_api_guestuser_join_reuse_existing_identity_by_external_reference(
  connection: api.IConnection,
) {
  // 1. Prepare a stable external_reference and first join payload
  const externalReference: string = `ext-${RandomGenerator.alphaNumeric(16)}`;

  const href1 = "https://todo.example.com/landing" as string &
    tags.Format<"uri">;
  const referrer1 = "https://marketing.example.com/campaign" as string &
    tags.Format<"uri">;

  const firstRequestBody = {
    external_reference: externalReference,
    display_name: "First Guest Session",
    href: href1,
    referrer: referrer1,
  } satisfies ITodoAppGuestUserJoin.IRequest;

  // 2. First join call
  const firstAuthorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: firstRequestBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(firstAuthorized);

  const firstGuest = firstAuthorized.guest;
  const firstSession = firstAuthorized.session;
  typia.assert<ITodoAppGuestUser.ISummary>(firstGuest);
  typia.assert<ITodoAppGuestUserSession.ISummary>(firstSession);

  // Basic sanity checks for token fields
  const firstToken: IAuthorizationToken = firstAuthorized.token;
  typia.assert<IAuthorizationToken>(firstToken);
  TestValidator.predicate(
    "first access token must be non-empty",
    firstToken.access.length > 0,
  );
  TestValidator.predicate(
    "first refresh token must be non-empty",
    firstToken.refresh.length > 0,
  );

  // 3. Prepare second join payload with same external_reference but different context
  const href2 = "https://todo.example.com/another-page" as string &
    tags.Format<"uri">;
  const referrer2 = "https://referrer.example.net/article" as string &
    tags.Format<"uri">;

  const secondRequestBody = {
    external_reference: externalReference,
    display_name: "Second Guest Session",
    href: href2,
    referrer: referrer2,
  } satisfies ITodoAppGuestUserJoin.IRequest;

  // 4. Second join call
  const secondAuthorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: secondRequestBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(secondAuthorized);

  const secondGuest = secondAuthorized.guest;
  const secondSession = secondAuthorized.session;
  typia.assert<ITodoAppGuestUser.ISummary>(secondGuest);
  typia.assert<ITodoAppGuestUserSession.ISummary>(secondSession);

  const secondToken: IAuthorizationToken = secondAuthorized.token;
  typia.assert<IAuthorizationToken>(secondToken);
  TestValidator.predicate(
    "second access token must be non-empty",
    secondToken.access.length > 0,
  );
  TestValidator.predicate(
    "second refresh token must be non-empty",
    secondToken.refresh.length > 0,
  );

  // 5. Assert guest identity reuse via external_reference
  TestValidator.equals(
    "guest id must be reused when external_reference matches",
    secondGuest.id,
    firstGuest.id,
  );

  // 6. Assert that a new session has been created
  TestValidator.notEquals(
    "each join invocation must create a distinct session id",
    secondSession.id,
    firstSession.id,
  );

  // 7. Assert that each session is linked to the same guest identity
  TestValidator.equals(
    "first session.guestUser.id must match guest.id",
    firstSession.guestUser.id,
    firstGuest.id,
  );
  TestValidator.equals(
    "second session.guestUser.id must match guest.id",
    secondSession.guestUser.id,
    secondGuest.id,
  );

  // 8. Display name handling: ensure it is present and non-empty in both responses.
  // Business rules do not mandate whether the second display_name overwrites
  // the first, so we only check for non-empty, non-whitespace when present.
  if (
    firstGuest.display_name !== null &&
    firstGuest.display_name !== undefined
  ) {
    TestValidator.predicate(
      "first guest display_name, when present, must be non-empty",
      firstGuest.display_name.trim().length > 0,
    );
  }
  if (
    secondGuest.display_name !== null &&
    secondGuest.display_name !== undefined
  ) {
    TestValidator.predicate(
      "second guest display_name, when present, must be non-empty",
      secondGuest.display_name.trim().length > 0,
    );
  }

  // 9. Ensure session context reflects the second request values where appropriate.
  // We cannot assert server behavior for href/referrer beyond type correctness,
  // but at minimum they must be non-empty strings.
  TestValidator.predicate(
    "first session href must be non-empty",
    firstSession.href.length > 0,
  );
  TestValidator.predicate(
    "first session referrer must be non-empty",
    firstSession.referrer.length > 0,
  );
  TestValidator.predicate(
    "second session href must be non-empty",
    secondSession.href.length > 0,
  );
  TestValidator.predicate(
    "second session referrer must be non-empty",
    secondSession.referrer.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

/**
 * Verify that a guest user can join with only the minimal required navigation
 * context (href and referrer) and that the backend still establishes a valid
 * guest identity, session, and token set.
 *
 * Business intent:
 *
 * - Clients should be able to create a guest session with as little friction as
 *   possible, providing only essential navigation context (landing URL and
 *   referrer).
 * - Optional identity hints like external_reference, display_name, and ip may be
 *   omitted while the server derives or fills in required persistence fields.
 *
 * What this test validates:
 *
 * 1. POST /auth/guestUser/join accepts a payload that only includes href and
 *    referrer and conforms to ITodoAppGuestUserJoin.IRequest.
 * 2. The response is a valid ITodoAppGuestUser.IAuthorized structure as enforced
 *    by typia.assert.
 * 3. The guest identity summary is created/reused with
 *
 *    - Non-null UUID id,
 *    - Non-empty status,
 *    - Valid created_at and updated_at timestamps,
 *    - External_reference and display_name remaining unset (null/undefined) when not
 *         provided in the request.
 * 4. The session summary is created with
 *
 *    - Non-null id,
 *    - Non-null ip string even though ip was omitted in the request (server-side
 *         derivation from connection metadata),
 *    - Href and referrer matching the request payload,
 *    - Non-null created_at timestamp,
 *    - Expired_at null/undefined to indicate an active session.
 * 5. The token structure contains non-empty access and refresh tokens and
 *    date-time strings for expired_at and refreshable_until.
 */
export async function test_api_guestuser_join_minimal_required_payload(
  connection: api.IConnection,
) {
  // 1. Prepare minimal guest join request: only href and referrer.
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  const requestBody = {
    href,
    referrer,
  } satisfies ITodoAppGuestUserJoin.IRequest;

  // 2. Call the guestUser.join endpoint with minimal payload.
  const authorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: requestBody,
    });

  // 3. Strongly assert the entire response shape.
  typia.assert<ITodoAppGuestUser.IAuthorized>(authorized);

  const { token, guest, session } = authorized;

  // 4. Validate token structure (non-empty strings, timestamps present).
  TestValidator.predicate(
    "access token should be a non-empty string",
    typeof token.access === "string" && token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be a non-empty string",
    typeof token.refresh === "string" && token.refresh.length > 0,
  );
  TestValidator.predicate(
    "access token expired_at should be a non-empty string",
    typeof token.expired_at === "string" && token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refresh token refreshable_until should be a non-empty string",
    typeof token.refreshable_until === "string" &&
      token.refreshable_until.length > 0,
  );

  // 5. Validate guest identity summary.
  TestValidator.predicate(
    "guest id should be a non-empty string",
    typeof guest.id === "string" && guest.id.length > 0,
  );
  TestValidator.predicate(
    "guest status should be a non-empty string",
    typeof guest.status === "string" && guest.status.length > 0,
  );
  TestValidator.predicate(
    "guest created_at should be a non-empty string",
    typeof guest.created_at === "string" && guest.created_at.length > 0,
  );
  TestValidator.predicate(
    "guest updated_at should be a non-empty string",
    typeof guest.updated_at === "string" && guest.updated_at.length > 0,
  );

  // Optional identity hints should remain unset when not provided.
  TestValidator.predicate(
    "guest external_reference should be null or undefined when omitted",
    guest.external_reference === null || guest.external_reference === undefined,
  );
  TestValidator.predicate(
    "guest display_name should be null or undefined when omitted",
    guest.display_name === null || guest.display_name === undefined,
  );

  // 6. Validate session summary.
  TestValidator.predicate(
    "session id should be a non-empty string",
    typeof session.id === "string" && session.id.length > 0,
  );

  // Server must derive a non-null ip even if request omitted it.
  TestValidator.predicate(
    "session ip should be a non-empty string even when request omitted ip",
    typeof session.ip === "string" && session.ip.length > 0,
  );

  // href and referrer should match the request payload.
  TestValidator.equals(
    "session href should match request href",
    session.href,
    href,
  );
  TestValidator.equals(
    "session referrer should match request referrer",
    session.referrer,
    referrer,
  );

  TestValidator.predicate(
    "session created_at should be a non-empty string",
    typeof session.created_at === "string" && session.created_at.length > 0,
  );

  // For a fresh session, expired_at should be null or undefined.
  TestValidator.predicate(
    "session expired_at should be null or undefined for a newly created session",
    session.expired_at === null || session.expired_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

/**
 * Validate URI format enforcement for guestUser join navigation fields.
 *
 * Business goal:
 *
 * - Ensure that /auth/guestUser/join strictly enforces the `format: "uri"`
 *   constraint on `href` and `referrer` in ITodoAppGuestUserJoin.IRequest.
 * - Confirm that when these fields are clearly invalid, the join operation fails
 *   with a client-side validation error instead of returning an
 *   ITodoAppGuestUser.IAuthorized payload and updating connection headers.
 * - Confirm that a payload with valid URI formats is accepted and results in a
 *   successful guest authorization response.
 *
 * Scenario:
 *
 * 1. Attempt to call api.functional.auth.guestUser.join with intentionally
 *    malformed `href` and `referrer` values (e.g., simple non-URI strings such
 *    as "not-a-uri"), while keeping optional fields either omitted or valid.
 * 2. Use TestValidator.error to assert that the call fails (validation error),
 *    expressing that invalid navigation URIs must not be accepted.
 * 3. Then call the same endpoint with well-formed URI strings for `href` and
 *    `referrer` to demonstrate that a similar payload with valid URIs succeeds,
 *    returning ITodoAppGuestUser.IAuthorized.
 * 4. Assert the successful response type with typia.assert and ensure the token
 *    and session structures look valid from a type perspective.
 */
export async function test_api_guestuser_join_invalid_navigation_uris_rejected(
  connection: api.IConnection,
) {
  // 1. Try join with obviously invalid href/referrer values.
  const invalidRequest = {
    // optional context left undefined to focus on URI validation
    href: "not-a-uri",
    referrer: "also-not-a-uri",
  } satisfies ITodoAppGuestUserJoin.IRequest;

  await TestValidator.error(
    "guestUser.join must reject invalid navigation URIs",
    async () => {
      await api.functional.auth.guestUser.join(connection, {
        body: invalidRequest,
      });
    },
  );

  // 2. Call join with valid URIs to ensure success path still works.
  const validRequest = {
    external_reference: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(2),
    ip: "203.0.113.10",
    href: "https://todo.example.com/app?source=e2e-uri-valid",
    referrer: "https://landing.example.com/campaign/spring",
  } satisfies ITodoAppGuestUserJoin.IRequest;

  const authorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: validRequest,
    });

  // 3. Validate response structure and basic logical expectations.
  typia.assert<ITodoAppGuestUser.IAuthorized>(authorized);
  typia.assert<IAuthorizationToken>(authorized.token);
  typia.assert<ITodoAppGuestUser.ISummary>(authorized.guest);
  typia.assert<ITodoAppGuestUserSession.ISummary>(authorized.session);

  TestValidator.predicate(
    "guest id must be a non-empty UUID string",
    () => authorized.guest.id.length > 0,
  );

  TestValidator.predicate(
    "session href should be set on successful join",
    () => authorized.session.href.length > 0,
  );

  TestValidator.predicate(
    "session referrer should be set on successful join",
    () => authorized.session.referrer.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserRefresh";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

/**
 * Validate successful token refresh for a guestUser with an active session.
 *
 * Business goals:
 *
 * - Ensure that a guest identity created via /auth/guestUser/join can refresh its
 *   JWT tokens while the underlying session remains valid.
 * - Confirm that token rotation preserves guest identity continuity and exposes a
 *   valid, non-expired session in the summaries.
 *
 * Scenario steps:
 *
 * 1. Call /auth/guestUser/join to establish an initial guest identity and session,
 *    capturing token, guest, and session summaries.
 * 2. Call /auth/guestUser/refresh with the previous refresh token and updated
 *    navigation context.
 * 3. Assert that new tokens are issued, the guest identity (guest.id) is
 *    unchanged, and the session summary reflects an active, non-expired session
 *    linked to the same guest.
 */
export async function test_api_guestuser_refresh_success_with_active_session(
  connection: api.IConnection,
) {
  // 1. Establish an initial guest identity and session via join
  const joinBody = {
    external_reference: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    ip: "203.0.113.42",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppGuestUserJoin.IRequest;

  const joined: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(joined);

  const initialToken: IAuthorizationToken = joined.token;
  const initialGuest: ITodoAppGuestUser.ISummary = joined.guest;
  const initialSession: ITodoAppGuestUserSession.ISummary = joined.session;

  // 2. Prepare refresh request using the initial refresh token
  const refreshBody = {
    refresh_token: initialToken.refresh,
    ip: "203.0.113.99",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: joinBody.href,
  } satisfies ITodoAppGuestUserRefresh.IRequest;

  const refreshed: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: refreshBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(refreshed);

  const refreshedToken: IAuthorizationToken = refreshed.token;
  const refreshedGuest: ITodoAppGuestUser.ISummary = refreshed.guest;
  const refreshedSession: ITodoAppGuestUserSession.ISummary = refreshed.session;

  // 3. Validate token rotation semantics
  TestValidator.notEquals(
    "access token should be rotated on guest refresh",
    refreshedToken.access,
    initialToken.access,
  );
  TestValidator.notEquals(
    "refresh token should be rotated on guest refresh",
    refreshedToken.refresh,
    initialToken.refresh,
  );

  const initialAccessExpiredAt = new Date(initialToken.expired_at).getTime();
  const refreshedAccessExpiredAt = new Date(
    refreshedToken.expired_at,
  ).getTime();
  const initialRefreshableUntil = new Date(
    initialToken.refreshable_until,
  ).getTime();
  const refreshedRefreshableUntil = new Date(
    refreshedToken.refreshable_until,
  ).getTime();

  TestValidator.predicate(
    "refreshed access token should not expire before initial access token",
    refreshedAccessExpiredAt >= initialAccessExpiredAt,
  );
  TestValidator.predicate(
    "refreshed refreshable_until should not be earlier than initial",
    refreshedRefreshableUntil >= initialRefreshableUntil,
  );

  const now = Date.now();
  TestValidator.predicate(
    "refreshed access token expiration should be in the future",
    refreshedAccessExpiredAt > now,
  );
  TestValidator.predicate(
    "refreshed refresh token window should extend into the future",
    refreshedRefreshableUntil > now,
  );

  // 4. Validate identity continuity
  TestValidator.equals(
    "guest id must be stable across token refresh",
    refreshedGuest.id,
    initialGuest.id,
  );

  TestValidator.equals(
    "guest status must remain unchanged on refresh",
    refreshedGuest.status,
    initialGuest.status,
  );

  // 5. Validate session semantics
  TestValidator.equals(
    "session.guestUser.id must match guest.id after refresh",
    refreshedSession.guestUser.id,
    refreshedGuest.id,
  );

  const refreshedExpiredAt =
    refreshedSession.expired_at === undefined
      ? undefined
      : refreshedSession.expired_at;

  TestValidator.predicate(
    "refreshed session must be active (expired_at null or undefined)",
    refreshedExpiredAt === null || refreshedExpiredAt === undefined,
  );

  const initialSessionCreatedAt = new Date(initialSession.created_at).getTime();
  const refreshedSessionCreatedAt = new Date(
    refreshedSession.created_at,
  ).getTime();

  TestValidator.predicate(
    "refreshed session created_at should not be earlier than initial session created_at",
    refreshedSessionCreatedAt >= initialSessionCreatedAt,
  );

  TestValidator.predicate(
    "refreshed session created_at should not be in the distant future",
    refreshedSessionCreatedAt <= Date.now(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserRefresh";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

export async function test_api_guestuser_refresh_rejected_for_malformed_token(
  connection: api.IConnection,
) {
  // 1. Establish a real guestUser session via join to obtain a valid refresh token
  const joinRequestBody = {
    external_reference: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://example.com/landing",
    referrer: "https://example.com/referrer",
  } satisfies ITodoAppGuestUserJoin.IRequest;

  const joined: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinRequestBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(joined);

  const validRefreshToken: string = joined.token.refresh;

  // 2. Build a malformed refresh request payload with clearly invalid token
  const malformedRefreshBody = {
    refresh_token: RandomGenerator.alphaNumeric(24), // clearly not a JWT format
    ip: "127.0.0.1",
    href: "https://example.com/landing",
    referrer: "https://example.com/referrer",
  } satisfies ITodoAppGuestUserRefresh.IRequest;

  // 3. Call refresh with malformed token and expect an HTTP error (4xx)
  await TestValidator.httpError(
    "guestUser refresh should fail for malformed refresh token",
    [400, 401, 403, 422],
    async () => {
      await api.functional.auth.guestUser.refresh(connection, {
        body: malformedRefreshBody,
      });
    },
  );

  // 4. Build a valid refresh request payload using the token from join
  const validRefreshBody = {
    refresh_token: validRefreshToken,
    ip: "127.0.0.1",
    href: "https://example.com/landing",
    referrer: "https://example.com/referrer",
  } satisfies ITodoAppGuestUserRefresh.IRequest;

  const refreshed: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: validRefreshBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(refreshed);

  // 5. Basic business checks on continuity of guest/session identity
  TestValidator.equals(
    "refreshed guest identity should match original join guest",
    refreshed.guest.id,
    joined.guest.id,
  );

  TestValidator.equals(
    "refreshed session should reference same guest user",
    refreshed.session.guestUser.id,
    joined.guest.id,
  );

  TestValidator.notEquals(
    "access token should rotate on refresh",
    refreshed.token.access,
    joined.token.access,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserRefresh";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

/**
 * Ensure guestUser refresh rejects structurally valid but unauthorized refresh
 * tokens.
 *
 * Original business intent is to verify that `/auth/guestUser/refresh` does not
 * resurrect expired or administratively invalidated sessions. However, the
 * provided API surface exposes only two operations:
 *
 * - `POST /auth/guestUser/join` for establishing a guest identity and issuing
 *   access/refresh tokens.
 * - `POST /auth/guestUser/refresh` for rotating tokens for an existing session.
 *
 * There is no test-time API to explicitly expire or invalidate a concrete
 * `todo_app_guestuser_sessions` record, and we cannot rely on real-time TTL
 * expiration within the scope of a single e2e test. Therefore this test focuses
 * on a closely related, implementable rule: refresh must succeed for a
 * legitimately issued refresh_token, and must fail for a synthetically
 * generated refresh_token that does not map to any session at all.
 *
 * Scenario steps:
 *
 * 1. Call `POST /auth/guestUser/join` with a random ITodoAppGuestUserJoin.IRequest
 *    payload to establish a guest identity and session.
 *
 *    - Capture the issued ITodoAppGuestUser.IAuthorized response.
 *    - Extract the `token.refresh` string as a valid refresh token.
 * 2. Call `POST /auth/guestUser/refresh` with ITodoAppGuestUserRefresh.IRequest
 *    using the captured refresh token and new random `href`/`referrer` values.
 *
 *    - Assert the call succeeds and the response shape matches
 *         ITodoAppGuestUser.IAuthorized via typia.assert.
 *    - Optionally verify that the guest/session identity is preserved across refresh
 *         by comparing ids.
 * 3. Generate a fake refresh token string that has never been issued by the
 *    backend, using RandomGenerator.alphaNumeric(64).
 *
 *    - Construct a new ITodoAppGuestUserRefresh.IRequest body with this fake token
 *         and valid `href`/`referrer` fields.
 *    - Wrap the refresh call in `await TestValidator.error(...)` to assert that an
 *         error is thrown when the backend attempts to validate this token.
 *    - Do not inspect HTTP status codes or error details; only the fact that an
 *         error occurs is validated, in line with global constraints.
 *
 * This test therefore exercises both the happy path (join+refresh) and a
 * negative path (refresh with an unknown token) while remaining fully type-safe
 * and compatible with the limited API surface that is available.
 */
export async function test_api_guestuser_refresh_rejected_for_expired_or_invalidated_session(
  connection: api.IConnection,
) {
  // 1. Establish a guest identity and session via join
  const joinBody = typia.random<ITodoAppGuestUserJoin.IRequest>();
  const joined: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(joined);

  // Capture identity and token info for later comparison
  const originalGuestId = joined.guest.id;
  const originalSessionId = joined.session.id;
  const originalRefreshToken = joined.token.refresh;

  // 2. Perform a valid refresh with the issued refresh token
  const refreshBody: ITodoAppGuestUserRefresh.IRequest = {
    refresh_token: originalRefreshToken,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  };

  const refreshed: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: refreshBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(refreshed);

  // Validate that guest identity is preserved across refresh
  TestValidator.equals(
    "guest id remains consistent after refresh",
    refreshed.guest.id,
    originalGuestId,
  );

  // 3. Attempt to refresh with a completely fabricated refresh token
  const fakeRefreshBody: ITodoAppGuestUserRefresh.IRequest = {
    refresh_token: RandomGenerator.alphaNumeric(64),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  };

  await TestValidator.error(
    "refresh should reject an unknown refresh token",
    async () => {
      await api.functional.auth.guestUser.refresh(connection, {
        body: fakeRefreshBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserRefresh";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

/**
 * Validate that guestUser refresh updates session navigation context while
 * preserving guest identity and rotating tokens.
 *
 * Business flow:
 *
 * 1. Establish an initial guestUser identity and session via /auth/guestUser/join
 *    using ITodoAppGuestUserJoin.IRequest with realistic href/referrer.
 * 2. Capture the returned ITodoAppGuestUser.IAuthorized payload (token, guest,
 *    session).
 * 3. Simulate navigation to a new page by constructing
 *    ITodoAppGuestUserRefresh.IRequest with the same refresh_token but
 *    different href/referrer (and modified ip).
 * 4. Call /auth/guestUser/refresh and assert:
 *
 *    - Response is ITodoAppGuestUser.IAuthorized (typia.assert).
 *    - Guest.id remains unchanged across join and refresh.
 *    - Session.guestUser.id matches guest.id in the same response.
 *    - The refreshed session remains active (expired_at is null/undefined).
 *    - Navigation fields (href, referrer, ip) reflect the updated values to model
 *         latest-touch tracking semantics.
 *    - A new access token is issued (access string changes) while the refresh token
 *         may or may not rotate depending on implementation.
 */
export async function test_api_guestuser_refresh_updates_session_context_with_new_navigation_data(
  connection: api.IConnection,
) {
  // 1. Establish initial guest session via join with baseline navigation context.
  const initialHref: string & tags.Format<"uri"> =
    "https://todo-app.example.com/welcome";
  const initialReferrer: string & tags.Format<"uri"> =
    "https://landing.example.com/campaign-123";

  const joinBody = {
    href: initialHref,
    referrer: initialReferrer,
    external_reference: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    ip: "192.0.2.1",
  } satisfies ITodoAppGuestUserJoin.IRequest;

  const joined: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  const initialToken: IAuthorizationToken = joined.token;
  const initialGuest: ITodoAppGuestUser.ISummary = joined.guest;
  const initialSession: ITodoAppGuestUserSession.ISummary = joined.session;

  // Initial business sanity checks (non-type-level) on relationships.
  TestValidator.predicate(
    "initial session belongs to same guest",
    () => initialSession.guestUser.id === initialGuest.id,
  );
  TestValidator.predicate(
    "initial session is active (expired_at is null/undefined)",
    () =>
      initialSession.expired_at === null ||
      initialSession.expired_at === undefined,
  );
  TestValidator.equals(
    "initial session href should match join request href",
    initialSession.href,
    joinBody.href,
  );
  TestValidator.equals(
    "initial session referrer should match join request referrer",
    initialSession.referrer,
    joinBody.referrer,
  );

  // 2. Simulate navigation to a new page and build refresh request.
  const refreshedHref: string & tags.Format<"uri"> =
    "https://todo-app.example.com/boards/active";
  const refreshedReferrer: string & tags.Format<"uri"> =
    "https://todo-app.example.com/welcome";

  const refreshBody = {
    refresh_token: initialToken.refresh,
    href: refreshedHref,
    referrer: refreshedReferrer,
    ip: "198.51.100.42",
  } satisfies ITodoAppGuestUserRefresh.IRequest;

  // 3. Call refresh endpoint with updated navigation context.
  const refreshed: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: refreshBody,
    });
  typia.assert(refreshed);

  const refreshedToken: IAuthorizationToken = refreshed.token;
  const refreshedGuest: ITodoAppGuestUser.ISummary = refreshed.guest;
  const refreshedSession: ITodoAppGuestUserSession.ISummary = refreshed.session;

  // 4. Assert guest identity continuity.
  TestValidator.equals(
    "guest id must remain stable across join and refresh",
    refreshedGuest.id,
    initialGuest.id,
  );
  TestValidator.equals(
    "refreshed session must reference same guest id",
    refreshedSession.guestUser.id,
    refreshedGuest.id,
  );

  // 5. Assert navigation context reflects latest refresh payload.
  TestValidator.equals(
    "refreshed session href should reflect new navigation href",
    refreshedSession.href,
    refreshBody.href,
  );
  TestValidator.equals(
    "refreshed session referrer should reflect new navigation referrer",
    refreshedSession.referrer,
    refreshBody.referrer,
  );
  TestValidator.equals(
    "refreshed session ip should reflect new ip when provided",
    refreshedSession.ip,
    refreshBody.ip,
  );

  // 6. Assert session remains active after refresh.
  TestValidator.predicate(
    "refreshed session is still active (expired_at null/undefined)",
    () =>
      refreshedSession.expired_at === null ||
      refreshedSession.expired_at === undefined,
  );

  // 7. Basic lifecycle sanity: refreshed session should not be older than original.
  TestValidator.predicate(
    "refreshed session created_at must be >= initial session created_at",
    () => refreshedSession.created_at >= initialSession.created_at,
  );

  // 8. Token rotation behavior: expect a new access token while preserving refresh semantics.
  TestValidator.notEquals(
    "access token should rotate on refresh to represent new session context",
    refreshedToken.access,
    initialToken.access,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppSystemConfigRuntime } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfigRuntime";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate runtime system configuration snapshot for todoAdmin.
 *
 * Business goal: Ensure that when a todoAdmin creates a concrete system
 * configuration entry, the admin-only runtime snapshot endpoint GET
 * /todoApp/todoAdmin/systemConfigs/runtime correctly reflects that active
 * configuration in the appropriate scope.
 *
 * High-level flow:
 *
 * 1. Register a fresh todoAdmin using the public join endpoint.
 * 2. As that authenticated admin, create a deterministic system config row (scope
 *    "todo", key "deletion_model", value "soft").
 * 3. Fetch the runtime snapshot for system configs.
 * 4. Assert that the snapshot structure matches ITodoAppSystemConfigRuntime and
 *    that the created key appears under the "todo" scope with the expected
 *    string value.
 * 5. Lightly verify that other scopes (auth, system) are present as objects,
 *    without enforcing specific keys.
 */
export async function test_api_system_config_runtime_snapshot_for_admin(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin via /auth/todoAdmin/join
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todoapp.test/settings/system-configs",
    referrer: "https://admin.todoapp.test/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequest,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);
  typia.assert<IAuthorizationToken>(admin.token);

  // 2. Create a deterministic system configuration row as this admin
  const configScope = "todo";
  const configKey = "deletion_model";
  const configValue = "soft";

  const createBody = {
    scope: configScope,
    key: configKey,
    value: configValue,
    description: RandomGenerator.paragraph({ sentences: 4 }),
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  const createdConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppSystemConfig>(createdConfig);

  // Basic sanity checks on created configuration
  TestValidator.equals(
    "created config scope must match input scope",
    createdConfig.scope,
    configScope,
  );
  TestValidator.equals(
    "created config key must match input key",
    createdConfig.key,
    configKey,
  );
  TestValidator.equals(
    "created config value must match input value",
    createdConfig.value,
    configValue,
  );
  TestValidator.predicate(
    "created config must be active",
    createdConfig.is_active === true,
  );

  // 3. Retrieve the runtime snapshot
  const runtimeSnapshot: ITodoAppSystemConfigRuntime =
    await api.functional.todoApp.todoAdmin.systemConfigs.runtime.at(connection);
  typia.assert<ITodoAppSystemConfigRuntime>(runtimeSnapshot);

  // 4. Assert that the todo scope contains our key with the expected value
  TestValidator.predicate(
    "todo scope must contain deletion_model key",
    Object.prototype.hasOwnProperty.call(runtimeSnapshot.todo, configKey),
  );
  TestValidator.equals(
    "runtime todo.deletion_model value must equal created config value",
    runtimeSnapshot.todo[configKey],
    configValue,
  );

  // 5. Verify that auth and system scopes are present as objects (may be empty)
  TestValidator.predicate(
    "auth scope object must be defined",
    typeof runtimeSnapshot.auth === "object" && runtimeSnapshot.auth !== null,
  );
  TestValidator.predicate(
    "system scope object must be defined",
    typeof runtimeSnapshot.system === "object" &&
      runtimeSnapshot.system !== null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppSystemConfigRuntime } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfigRuntime";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Ensure runtime system configuration snapshot reflects latest active values.
 *
 * Business goal: Validate that the admin-facing runtime configuration endpoint
 * `/todoApp/todoAdmin/systemConfigs/runtime` returns an aggregated
 * ITodoAppSystemConfigRuntime object whose scoped key/value pairs match the
 * most recent _active_ rows in `todo_app_system_configs`, per (scope, key).
 *
 * Scenario:
 *
 * 1. Register a fresh todoAdmin via `/auth/todoAdmin/join` using
 *    ITodoAppTodoAdminJoin.IRequest. Rely on the SDK to automatically store the
 *    access token into `connection.headers.Authorization` for authenticated
 *    calls.
 * 2. As this admin, create three baseline configuration rows using
 *    `/todoApp/todoAdmin/systemConfigs`
 *    (api.functional.todoApp.todoAdmin.systemConfigs.create):
 *
 *    - Scope="todo", key="deletion_model", value="soft" (implicit is_active=true)
 *    - Scope="auth", key="session_timeout_minutes", value="30" (implicit
 *         is_active=true)
 *    - Scope="system", key="maintenance_mode", value="off" (implicit is_active=true)
 * 3. Create an additional configuration entry for the same logical key
 *    "system"/"maintenance_mode" but with a different value (e.g., "on") and
 *    explicitly set `is_active: true` to emulate an updated active row.
 * 4. Call `/todoApp/todoAdmin/systemConfigs/runtime` via
 *    api.functional.todoApp.todoAdmin.systemConfigs.runtime.at.
 * 5. Validate that:
 *
 *    - The response conforms to ITodoAppSystemConfigRuntime using typia.assert.
 *    - `runtime.todo.deletion_model === "soft"`.
 *    - `runtime.auth.session_timeout_minutes === "30"`.
 *    - `runtime.system.maintenance_mode` equals the value from the most recently
 *         created active configuration row (e.g., "on").
 *
 * Notes:
 *
 * - We cannot directly manipulate deleted_at or inactive rows with the provided
 *   DTOs, so the test focuses on the "latest active wins" behavior by creating
 *   only active rows and expecting the runtime snapshot to pick the last one
 *   for a given (scope, key).
 */
export async function test_api_system_config_runtime_reflects_latest_values(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin account and obtain authorized context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  // Validate authorized admin structure
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);
  // Also validate embedded token type
  typia.assert<IAuthorizationToken>(admin.token);

  // 2. Create baseline configuration rows for todo, auth, and system scopes.
  const todoConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: {
        scope: "todo",
        key: "deletion_model",
        value: "soft",
        description: "Todo deletion behavior model",
        // omit is_active to allow server default (expected true)
      } satisfies ITodoAppSystemConfig.ICreate,
    });
  typia.assert<ITodoAppSystemConfig>(todoConfig);

  const authConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: {
        scope: "auth",
        key: "session_timeout_minutes",
        value: "30",
        description: "Session timeout in minutes for todoAdmin UI",
      } satisfies ITodoAppSystemConfig.ICreate,
    });
  typia.assert<ITodoAppSystemConfig>(authConfig);

  const initialSystemConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: {
        scope: "system",
        key: "maintenance_mode",
        value: "off",
        description: "Initial maintenance mode flag",
      } satisfies ITodoAppSystemConfig.ICreate,
    });
  typia.assert<ITodoAppSystemConfig>(initialSystemConfig);

  // 3. Create an additional active configuration row for the same
  //    (scope, key) pair system/maintenance_mode to emulate an updated value.
  const latestMaintenanceValue = "on";
  const updatedSystemConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: {
        scope: "system",
        key: "maintenance_mode",
        value: latestMaintenanceValue,
        description: "Updated maintenance mode flag",
        is_active: true,
      } satisfies ITodoAppSystemConfig.ICreate,
    });
  typia.assert<ITodoAppSystemConfig>(updatedSystemConfig);

  // 4. Fetch the runtime configuration snapshot for the authenticated admin.
  const runtime: ITodoAppSystemConfigRuntime =
    await api.functional.todoApp.todoAdmin.systemConfigs.runtime.at(connection);
  typia.assert<ITodoAppSystemConfigRuntime>(runtime);

  // 5. Validate that runtime snapshot reflects latest active values.
  TestValidator.equals(
    "todo.deletion_model matches created config value",
    runtime.todo.deletion_model,
    "soft",
  );

  TestValidator.equals(
    "auth.session_timeout_minutes matches created config value",
    runtime.auth.session_timeout_minutes,
    "30",
  );

  TestValidator.equals(
    "system.maintenance_mode uses the latest active config value",
    runtime.system.maintenance_mode,
    latestMaintenanceValue,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestuser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

export async function test_api_guest_users_search_basic_filters(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin (join) to obtain authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://admin.todo-app.example.com/join",
    referrer: "https://landing.todo-app.example.com/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create at least one Todo status to satisfy dependent admin views
  const statusBody = {
    code: RandomGenerator.alphaNumeric(8).toUpperCase(),
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: 1,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusBody,
    });
  typia.assert(createdStatus);

  // 3. Perform guest users search with basic filters (status, page, limit, order)
  const requestPage = 1 as number & tags.Type<"int32">;
  const requestLimit = 10 as number & tags.Type<"int32">;

  const guestSearchBody = {
    page: requestPage,
    limit: requestLimit,
    status: "active",
    orderBy: "created_at",
    orderDirection: "desc",
  } satisfies ITodoAppGuestUser.IRequest;

  const guestPage: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
      body: guestSearchBody,
    });
  typia.assert(guestPage);

  const pagination = guestPage.pagination;
  const data = guestPage.data;

  // 4. Validate pagination metadata basics
  TestValidator.predicate(
    "pagination current must be non-negative",
    pagination.current >= 0,
  );

  TestValidator.predicate(
    "pagination limit must be non-negative",
    pagination.limit >= 0,
  );

  TestValidator.predicate(
    "pagination records must be non-negative",
    pagination.records >= 0,
  );

  TestValidator.predicate(
    "pagination pages must be non-negative",
    pagination.pages >= 0,
  );

  // records/pages/data length coherence
  if (pagination.records === 0) {
    TestValidator.equals(
      "no records should yield empty data array",
      data.length,
      0,
    );

    TestValidator.equals(
      "no records should have zero pages",
      pagination.pages,
      0,
    );
  } else {
    TestValidator.predicate(
      "when records > 0, pages should be at least 1",
      pagination.pages >= 1,
    );

    TestValidator.predicate(
      "data length must not exceed limit",
      data.length <= pagination.limit,
    );
  }

  // 5. Validate that all returned guest users match the requested status filter
  for (const guest of data) {
    typia.assert<ITodoAppGuestUser.ISummary>(guest);

    TestValidator.equals(
      "guest status should match requested filter 'active'",
      guest.status,
      guestSearchBody.status,
    );
  }

  // 6. Secondary search: omit status filter and use a different combination
  const secondaryBody = {
    page: requestPage,
    limit: requestLimit,
    // no status filter here
    orderBy: "created_at",
    orderDirection: "asc",
  } satisfies ITodoAppGuestUser.IRequest;

  const secondaryPage: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
      body: secondaryBody,
    });
  typia.assert(secondaryPage);

  const secondaryPagination = secondaryPage.pagination;
  const secondaryData = secondaryPage.data;

  // repeat core pagination validations for secondary search
  TestValidator.predicate(
    "secondary pagination current must be non-negative",
    secondaryPagination.current >= 0,
  );

  TestValidator.predicate(
    "secondary pagination limit must be non-negative",
    secondaryPagination.limit >= 0,
  );

  TestValidator.predicate(
    "secondary pagination records must be non-negative",
    secondaryPagination.records >= 0,
  );

  TestValidator.predicate(
    "secondary pagination pages must be non-negative",
    secondaryPagination.pages >= 0,
  );

  if (secondaryPagination.records === 0) {
    TestValidator.equals(
      "secondary search with no records should yield empty data array",
      secondaryData.length,
      0,
    );

    TestValidator.equals(
      "secondary search with no records should have zero pages",
      secondaryPagination.pages,
      0,
    );
  } else {
    TestValidator.predicate(
      "secondary search when records > 0, pages should be at least 1",
      secondaryPagination.pages >= 1,
    );

    TestValidator.predicate(
      "secondary search data length must not exceed limit",
      secondaryData.length <= secondaryPagination.limit,
    );

    for (const guest of secondaryData) {
      typia.assert<ITodoAppGuestUser.ISummary>(guest);
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestuser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate admin guest user search with text and date filters plus pagination.
 *
 * Business scope:
 *
 * - A todoAdmin must be registered and authenticated to access guestUsers.
 * - The system is assumed to have guest user records already (created by other
 *   flows).
 * - The search endpoint must honor ITodoAppGuestUser.IRequest filters and return
 *   paginated IPageITodoAppGuestuser.ISummary results.
 *
 * Test steps:
 *
 * 1. Register a todoAdmin via /auth/todoAdmin/join to obtain an authorized admin
 *    context; this also sets Authorization headers in the shared connection.
 * 2. Create a couple of Todo status catalogue entries via
 *    /todoApp/todoAdmin/todoStatuses to satisfy the conceptual dependency that
 *    statuses exist (even though they are not directly joined to guest users in
 *    this test).
 * 3. Perform a baseline guest user search with only pagination parameters to
 *    obtain at least one page of data and record sample guest summaries.
 * 4. If data exists, derive filter values from a real guest row: build
 *    externalReferenceLike, displayNameLike, createdFrom/createdTo, and a
 *    statusList containing that guest's status. Call the search endpoint with
 *    those combined filters and validate that all returned rows are consistent
 *    with the filters where applicable.
 * 5. Validate pagination by using a small limit (e.g., 1) and a stable sorting
 *    order (orderBy "created_at", orderDirection "asc"). Request the first and
 *    second pages and check that pagination metadata is coherent and that, when
 *    there are multiple records, the sets of IDs in page 1 and page 2 do not
 *    overlap.
 */
export async function test_api_guest_users_search_with_text_and_date_filters(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin to obtain authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    href: "https://admin.todoapp.example.com/register",
    referrer: "https://landing.todoapp.example.com/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Create a couple of Todo status catalogue entries (environment setup)
  const statusInputs = [
    {
      code: `ACTIVE_${RandomGenerator.alphaNumeric(8)}`,
      label: "Active",
      description: RandomGenerator.paragraph({ sentences: 3 }),
      group: "core",
      sort_order: 1,
      is_default: true,
      is_active: true,
    } satisfies ITodoAppTodoStatus.ICreate,
    {
      code: `ARCHIVED_${RandomGenerator.alphaNumeric(8)}`,
      label: "Archived",
      description: RandomGenerator.paragraph({ sentences: 3 }),
      group: "core",
      sort_order: 2,
      is_default: false,
      is_active: true,
    } satisfies ITodoAppTodoStatus.ICreate,
  ];

  for (const body of statusInputs) {
    const createdStatus: ITodoAppTodoStatus =
      await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
        body,
      });
    typia.assert<ITodoAppTodoStatus>(createdStatus);
  }

  // 3. Baseline guest users search with simple pagination
  const baselineRequest = {
    page: 1,
    limit: 5,
  } satisfies ITodoAppGuestUser.IRequest;

  const baselinePage: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
      body: baselineRequest,
    });
  typia.assert<IPageITodoAppGuestuser.ISummary>(baselinePage);

  const pagination = baselinePage.pagination;
  const baselineData = baselinePage.data;

  TestValidator.predicate(
    "baseline pagination limit should be non-negative",
    pagination.limit >= 0,
  );
  TestValidator.predicate(
    "baseline pagination records should be non-negative",
    pagination.records >= 0,
  );

  // 4. If we have at least one guest user, derive filters and validate
  if (baselineData.length > 0) {
    const sample: ITodoAppGuestUser.ISummary = baselineData[0];

    const createdAt = sample.created_at;
    const createdDate = new Date(createdAt);
    const tenMinutes = 10 * 60 * 1000;

    const createdFrom = new Date(
      createdDate.getTime() - tenMinutes,
    ).toISOString();
    const createdTo = new Date(
      createdDate.getTime() + tenMinutes,
    ).toISOString();

    let externalReferenceLike: string | undefined = undefined;
    if (sample.external_reference != null) {
      const ref = sample.external_reference;
      if (ref.length > 0) {
        const mid = Math.max(1, Math.floor(ref.length / 2));
        externalReferenceLike = ref.substring(0, mid);
      }
    }

    let displayNameLike: string | undefined = undefined;
    if (sample.display_name != null) {
      const name = sample.display_name;
      if (name.length > 0) {
        const mid = Math.max(1, Math.floor(name.length / 2));
        displayNameLike = name.substring(0, mid);
      }
    }

    const combinedRequest: ITodoAppGuestUser.IRequest = {
      page: 1,
      limit: 5,
      statusList: [sample.status],
      createdFrom,
      createdTo,
      orderBy: "created_at",
      orderDirection: "asc",
      ...(externalReferenceLike !== undefined ? { externalReferenceLike } : {}),
      ...(displayNameLike !== undefined ? { displayNameLike } : {}),
    };

    const filteredPage: IPageITodoAppGuestuser.ISummary =
      await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
        body: combinedRequest,
      });
    typia.assert<IPageITodoAppGuestuser.ISummary>(filteredPage);

    for (const guest of filteredPage.data) {
      TestValidator.predicate(
        "guest created_at should be within [createdFrom, createdTo]",
        guest.created_at >= createdFrom && guest.created_at <= createdTo,
      );

      TestValidator.predicate(
        "guest status should be in statusList",
        combinedRequest.statusList !== undefined &&
          combinedRequest.statusList.includes(guest.status),
      );

      if (combinedRequest.externalReferenceLike !== undefined) {
        if (guest.external_reference != null) {
          TestValidator.predicate(
            "guest external_reference should contain filter substring when provided",
            guest.external_reference.includes(
              combinedRequest.externalReferenceLike,
            ),
          );
        }
      }

      if (combinedRequest.displayNameLike !== undefined) {
        if (guest.display_name != null) {
          TestValidator.predicate(
            "guest display_name should contain filter substring when provided",
            guest.display_name.includes(combinedRequest.displayNameLike),
          );
        }
      }
    }
  }

  // 5. Pagination behaviour with small limit
  const paginationLimit = 1;

  const page1Request: ITodoAppGuestUser.IRequest = {
    page: 1,
    limit: paginationLimit,
    orderBy: "created_at",
    orderDirection: "asc",
  };
  const page1: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
      body: page1Request,
    });
  typia.assert<IPageITodoAppGuestuser.ISummary>(page1);

  TestValidator.predicate(
    "page1 current page index should be non-negative",
    page1.pagination.current >= 0,
  );

  if (page1.pagination.records > paginationLimit) {
    const page2Request: ITodoAppGuestUser.IRequest = {
      page: page1.pagination.current + 1,
      limit: paginationLimit,
      orderBy: "created_at",
      orderDirection: "asc",
    };

    const page2: IPageITodoAppGuestuser.ISummary =
      await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
        body: page2Request,
      });
    typia.assert<IPageITodoAppGuestuser.ISummary>(page2);

    TestValidator.predicate(
      "total pages should be >= 2 when records exceed limit",
      page2.pagination.pages >= 2,
    );

    const ids1 = page1.data.map((g) => g.id);
    const ids2 = page2.data.map((g) => g.id);

    if (ids1.length > 0 && ids2.length > 0) {
      const overlapping = ids1.some((id) => ids2.includes(id));
      TestValidator.predicate(
        "guest IDs in page1 and page2 should not overlap when both pages have data",
        overlapping === false,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate creation of Todo status entries by an authenticated todoAdmin.
 *
 * Business goal:
 *
 * - Ensure that a freshly registered todoAdmin can create a new Todo status entry
 *   in the centralized `todo_app_todo_statuses` catalogue using the dedicated
 *   administrative endpoint.
 * - Confirm that the created status echoes back the core configuration fields
 *   supplied in the ITodoAppTodoStatus.ICreate payload.
 * - Verify that an unauthenticated connection cannot call the protected creation
 *   endpoint successfully.
 *
 * High-level steps:
 *
 * 1. Register (join) a new todoAdmin account and obtain an authorized context with
 *    JWT tokens via /auth/todoAdmin/join.
 * 2. Using the authenticated connection (with SDK-managed Authorization header),
 *    call POST /todoApp/todoAdmin/todoStatuses with a valid
 *    ITodoAppTodoStatus.ICreate payload to create a new status.
 * 3. Assert that the response is a full ITodoAppTodoStatus object, and validate
 *    that its business fields (code, label, description, group, sort_order,
 *    is_default, is_active) match the sent values.
 * 4. Build an unauthenticated connection and verify that the same creation attempt
 *    fails via TestValidator.error, proving that authorization is enforced.
 */
export async function test_api_todo_status_creation_by_todoadmin(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin (join) to obtain authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(2),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(adminAuthorized);

  // 2. Prepare a valid Todo status creation payload
  const statusCodePrefix = "IN_PROGRESS_";
  const statusCodeSuffix = RandomGenerator.alphaNumeric(8).toUpperCase();
  const statusCode = `${statusCodePrefix}${statusCodeSuffix}`;

  const createBody = {
    code: statusCode,
    label: RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.paragraph({
      sentences: 4,
      wordMin: 4,
      wordMax: 10,
    }),
    group: "core",
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  // 3. Call the admin Todo status creation endpoint with authenticated context
  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodoStatus>(createdStatus);

  // 3-1. Validate that response maps business fields correctly
  TestValidator.equals(
    "todo status code should match request payload",
    createdStatus.code,
    createBody.code,
  );
  TestValidator.equals(
    "todo status label should match request payload",
    createdStatus.label,
    createBody.label,
  );
  TestValidator.equals(
    "todo status description should match request payload",
    createdStatus.description,
    createBody.description,
  );
  TestValidator.equals(
    "todo status group should match request payload",
    createdStatus.group,
    createBody.group,
  );
  TestValidator.equals(
    "todo status sort_order should match request payload",
    createdStatus.sort_order,
    createBody.sort_order,
  );
  TestValidator.equals(
    "todo status is_default flag should match request payload",
    createdStatus.is_default,
    createBody.is_default,
  );
  TestValidator.equals(
    "todo status is_active flag should match request payload",
    createdStatus.is_active,
    createBody.is_active,
  );

  // 4. Unauthorized scenario: construct an unauthenticated connection
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  const unauthorizedCreateBody = {
    code: `${statusCode}_UNAUTH`,
    label: RandomGenerator.paragraph({ sentences: 1, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.paragraph({
      sentences: 2,
      wordMin: 4,
      wordMax: 10,
    }),
    group: "core",
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  await TestValidator.error(
    "creating todo status without admin token must fail",
    async () => {
      await api.functional.todoApp.todoAdmin.todoStatuses.create(
        unauthConnection,
        {
          body: unauthorizedCreateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

export async function test_api_todo_status_creation_with_default_flag_invariant(
  connection: api.IConnection,
) {
  /**
   * Scenario:
   *
   * - We need an authenticated todoAdmin to create statuses.
   * - We must verify that creating Todo statuses with is_default=true works and
   *   produce consistent data, while respecting the invariant that business
   *   rules will not allow broken state.
   * - Available APIs in this context:
   *
   *   - POST /auth/todoAdmin/join -> api.functional.auth.todoAdmin.join
   *   - POST /todoApp/todoAdmin/todoStatuses ->
   *       api.functional.todoApp.todoAdmin.todoStatuses.create
   * - No listing or detail endpoints for statuses are provided, so we validate
   *   behavior using only create responses and error expectations.
   *
   * Business rule interpretation (due to limited APIs):
   *
   * - We cannot query “all statuses” to see that only one is_default=true exists
   *   at a time.
   * - Instead, we validate that:
   *
   *   1. A first status with is_default=true can be created successfully.
   *   2. A second status with a different code and is_default=true can also be
   *        created successfully, so the system permits multiple default
   *        candidates at creation time.
   *   3. Both responses are structurally valid ITodoAppTodoStatus objects.
   * - We do NOT assert a particular rejection or auto-adjustment behavior when a
   *   second default is created, because that requires read/list APIs that do
   *   not exist in the provided SDK. Instead, this test focuses on positive
   *   creation flows and on authorization rules.
   *
   * Additionally, we validate authorization by ensuring that an unauthenticated
   * connection cannot create a status.
   */

  // 0. Prepare a fresh unauthenticated connection for negative auth test.
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 1. Try creating a status without admin token, expect failure.
  await TestValidator.error(
    "unauthenticated status creation should fail",
    async () => {
      await api.functional.todoApp.todoAdmin.todoStatuses.create(
        unauthenticatedConnection,
        {
          body: {
            code: "UNAUTH_TEST",
            label: "Unauth Test",
            description: RandomGenerator.paragraph({ sentences: 3 }),
            group: "test",
            sort_order: 1 as number & tags.Type<"int32">,
            is_default: true,
            is_active: true,
          } satisfies ITodoAppTodoStatus.ICreate,
        },
      );
    },
  );

  // 2. Register (join) a new todoAdmin to obtain authorized context.
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequest,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);
  typia.assert<IAuthorizationToken>(admin.token);

  // 3. Create the first status with is_default=true and is_active=true.
  const firstStatusRequest = {
    code: "ACTIVE",
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const firstStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: firstStatusRequest,
    });
  typia.assert<ITodoAppTodoStatus>(firstStatus);

  TestValidator.equals(
    "first status code should match request",
    firstStatus.code,
    firstStatusRequest.code,
  );
  TestValidator.equals(
    "first status label should match request",
    firstStatus.label,
    firstStatusRequest.label,
  );
  TestValidator.equals(
    "first status is_default should be true",
    firstStatus.is_default,
    true,
  );
  TestValidator.equals(
    "first status is_active should be true",
    firstStatus.is_active,
    true,
  );

  // 4. Create a second status with a different code and is_default=true.
  const secondStatusRequest = {
    code: "COMPLETED",
    label: "Completed",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const secondStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: secondStatusRequest,
    });
  typia.assert<ITodoAppTodoStatus>(secondStatus);

  TestValidator.equals(
    "second status code should match request",
    secondStatus.code,
    secondStatusRequest.code,
  );
  TestValidator.equals(
    "second status label should match request",
    secondStatus.label,
    secondStatusRequest.label,
  );
  TestValidator.equals(
    "second status is_default should be true",
    secondStatus.is_default,
    true,
  );
  TestValidator.equals(
    "second status is_active should be true",
    secondStatus.is_active,
    true,
  );

  // 5. Basic invariant sanity checks on returned objects.
  TestValidator.predicate(
    "first and second statuses must have different ids",
    firstStatus.id !== secondStatus.id,
  );
  TestValidator.predicate(
    "first and second statuses must have different codes",
    firstStatus.code !== secondStatus.code,
  );

  // Note: deeper enforcement of single-default invariant would require
  // read/list APIs to inspect the full catalogue, which are not available
  // in this context. This test focuses on authorization and that multiple
  // default-flagged statuses can be created successfully without violating
  // type contracts.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate that an authenticated todoAdmin can update an existing Todo status
 * by its business key `statusCode`, and that authorization, path binding, and
 * immutable fields behave correctly.
 *
 * Business flow:
 *
 * 1. Register a new todoAdmin using /auth/todoAdmin/join. This also sets the
 *    Authorization header on the shared connection with an access token.
 * 2. Using the authenticated admin connection, create a new Todo status via POST
 *    /todoApp/todoAdmin/todoStatuses with a specific `code`, `label`,
 *    `sort_order`, `is_default`, and `is_active`.
 * 3. With the same admin context, call PUT
 *    /todoApp/todoAdmin/todoStatuses/{statusCode} targeting the created status
 *    by its `code` and providing an ITodoAppTodoStatus.IUpdate body that
 *    changes multiple mutable fields.
 * 4. Assert that the update succeeds, returned ITodoAppTodoStatus passes
 *    typia.assert, and that:
 *
 *    - Id, code, and created_at are preserved.
 *    - Label, description, group, sort_order, is_default, is_active reflect the
 *         requested updates.
 *    - Updated_at differs from the original value (has advanced).
 * 5. Derive an unauthenticated connection with empty headers and attempt the same
 *    update call, expecting it to fail due to missing Authorization. Validate
 *    this with TestValidator.error without inspecting HTTP status.
 */
export async function test_api_todo_status_update_by_todoadmin(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin and obtain authorized context
  const joinRequestBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const authorizedAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequestBody,
    });
  typia.assert(authorizedAdmin);

  // 2. Create baseline Todo status
  const baseCode: string = `STATUS_${RandomGenerator.alphaNumeric(8).toUpperCase()}`;
  const createBody = {
    code: baseCode,
    label: "Active Todos",
    description: "Status representing active and ongoing Todo items.",
    group: "core",
    sort_order: 10,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: createBody,
    });
  typia.assert(createdStatus);

  // 3. Prepare update payload targeting the created status by its code
  const updateStatusCode: string = createdStatus.code;

  const updateBody = {
    label: "In Progress Todos",
    description: "Status for Todos that are currently being worked on.",
    group: "workflow",
    sort_order: 20,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.IUpdate;

  const updatedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.update(connection, {
      statusCode: updateStatusCode,
      body: updateBody,
    });
  typia.assert(updatedStatus);

  // 4. Data integrity assertions
  // Immutable fields: id, code, created_at
  TestValidator.equals(
    "status id must remain unchanged after update",
    updatedStatus.id,
    createdStatus.id,
  );
  TestValidator.equals(
    "status code must match path parameter and remain unchanged",
    updatedStatus.code,
    updateStatusCode,
  );
  TestValidator.equals(
    "status created_at must remain unchanged after update",
    updatedStatus.created_at,
    createdStatus.created_at,
  );

  // Mutable fields: reflect the update payload
  TestValidator.equals(
    "label should be updated to new value",
    updatedStatus.label,
    updateBody.label,
  );
  TestValidator.equals(
    "description should reflect updated value (including nullability)",
    updatedStatus.description ?? null,
    updateBody.description ?? null,
  );
  TestValidator.equals(
    "group should reflect updated grouping",
    updatedStatus.group ?? null,
    updateBody.group ?? null,
  );
  TestValidator.equals(
    "sort_order should be updated to new integer value",
    updatedStatus.sort_order,
    updateBody.sort_order as number,
  );
  TestValidator.equals(
    "is_default flag should reflect update payload",
    updatedStatus.is_default,
    updateBody.is_default,
  );
  TestValidator.equals(
    "is_active flag should reflect update payload",
    updatedStatus.is_active,
    updateBody.is_active,
  );

  // updated_at should have changed compared to the original value
  TestValidator.notEquals(
    "updated_at should change after status update",
    updatedStatus.updated_at,
    createdStatus.updated_at,
  );

  // 5. Negative case: unauthenticated update attempt must fail
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated todoAdmin update must fail due to missing Authorization",
    async () => {
      await api.functional.todoApp.todoAdmin.todoStatuses.update(
        unauthenticatedConnection,
        {
          statusCode: updateStatusCode,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate updating Todo status default/active flags for a todoAdmin.
 *
 * Business context:
 *
 * - A todoAdmin manages a catalogue of Todo statuses in `todo_app_todo_statuses`.
 * - Each status has a stable `code`, user-facing label/description/group, display
 *   `sort_order`, and two behavior flags: `is_default` and `is_active`.
 * - The update endpoint identified by status `code` lets admins change
 *   user-facing metadata and these flags while keeping identifiers (id/code)
 *   and `created_at` immutable.
 *
 * This test covers the happy-path workflow of promoting a non-default status to
 * default and ensuring that identifiers and timestamps behave correctly for the
 * updated record.
 *
 * Steps:
 *
 * 1. Register a new todoAdmin account with /auth/todoAdmin/join.
 *
 *    - Rely on the SDK to attach Authorization header using returned token.
 * 2. As that admin, create two statuses via POST /todoApp/todoAdmin/todoStatuses:
 *
 *    - Status A: code="ACTIVE", is_default=true, is_active=true.
 *    - Status B: code="COMPLETED", is_default=false, is_active=true.
 * 3. Promote Status B to default using PUT
 *    /todoApp/todoAdmin/todoStatuses/{statusCode}:
 *
 *    - StatusCode="COMPLETED".
 *    - Body ITodoAppTodoStatus.IUpdate with new label/description/group and
 *         is_default=true.
 * 4. Validate the update response for Status B:
 *
 *    - Type-safe via typia.assert.
 *    - `id` remains unchanged compared to creation response.
 *    - `code` remains "COMPLETED" (immutable business identifier).
 *    - `label`, `description`, and `group` are updated to the new values.
 *    - `is_default` is true and `is_active` is still true.
 *    - `created_at` is unchanged and `updated_at` is the same or later than
 *         `created_at`.
 * 5. (Optional within same test) Deactivate Status B:
 *
 *    - Call PUT again for `statusCode="COMPLETED"` with body { is_active: false }.
 *    - Validate that:
 *
 *         - `id` and `code` remain unchanged.
 *         - `is_active` becomes false.
 *         - `updated_at` advances again relative to the prior update.
 */
export async function test_api_todo_status_update_default_flag_rules(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin and obtain authorized context
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(2),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequest,
    });
  typia.assert(admin);

  // 2. Create Status A (ACTIVE, default, active)
  const statusACreate = {
    code: "ACTIVE",
    label: `ACTIVE-${RandomGenerator.name(1)}`,
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const statusA: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusACreate,
    });
  typia.assert(statusA);

  TestValidator.equals(
    "status A code matches request",
    statusA.code,
    statusACreate.code,
  );
  TestValidator.equals(
    "status A is_default true as requested",
    statusA.is_default,
    true,
  );
  TestValidator.equals(
    "status A is_active true as requested",
    statusA.is_active,
    true,
  );

  // 3. Create Status B (COMPLETED, non-default, active)
  const statusBCreate = {
    code: "COMPLETED",
    label: `COMPLETED-${RandomGenerator.name(1)}`,
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 2,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const statusB: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusBCreate,
    });
  typia.assert(statusB);

  TestValidator.equals(
    "status B code matches request",
    statusB.code,
    statusBCreate.code,
  );
  TestValidator.equals(
    "status B initially non-default",
    statusB.is_default,
    false,
  );
  TestValidator.equals("status B initially active", statusB.is_active, true);

  const originalBId = statusB.id;
  const originalBCreatedAt = statusB.created_at;
  const originalBUpdatedAt = statusB.updated_at;

  // 4. Promote Status B to default and update user-facing metadata
  const updatedLabel = `COMPLETED-UPDATED-${RandomGenerator.name(1)}`;
  const updatedDescription = RandomGenerator.paragraph({ sentences: 4 });
  const updatedGroup = "core-updated";

  const statusBUpdateBody = {
    label: updatedLabel,
    description: updatedDescription,
    group: updatedGroup,
    // Test default promotion; keep is_active unchanged by omitting it
    is_default: true,
  } satisfies ITodoAppTodoStatus.IUpdate;

  const statusBPromoted: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.update(connection, {
      statusCode: statusB.code,
      body: statusBUpdateBody,
    });
  typia.assert(statusBPromoted);

  // 4-a. Validate identity immutability
  TestValidator.equals(
    "status B id is stable across update",
    statusBPromoted.id,
    originalBId,
  );
  TestValidator.equals(
    "status B code remains immutable",
    statusBPromoted.code,
    statusB.code,
  );

  // 4-b. Validate user-facing metadata changes
  TestValidator.equals(
    "status B label updated as requested",
    statusBPromoted.label,
    updatedLabel,
  );
  TestValidator.equals(
    "status B description updated as requested",
    statusBPromoted.description,
    updatedDescription,
  );
  TestValidator.equals(
    "status B group updated as requested",
    statusBPromoted.group,
    updatedGroup,
  );

  // 4-c. Validate flags
  TestValidator.equals(
    "status B promoted to default",
    statusBPromoted.is_default,
    true,
  );
  TestValidator.equals(
    "status B remains active after default promotion",
    statusBPromoted.is_active,
    true,
  );

  // 4-d. Validate timestamps: created_at unchanged, updated_at advanced or same-time
  TestValidator.equals(
    "status B created_at remains unchanged",
    statusBPromoted.created_at,
    originalBCreatedAt,
  );

  await TestValidator.predicate(
    "status B updated_at not before created_at",
    async () => {
      const created = new Date(originalBCreatedAt).getTime();
      const updated = new Date(statusBPromoted.updated_at).getTime();
      return updated >= created;
    },
  );

  await TestValidator.predicate(
    "status B updated_at advanced or stayed same compared to previous updated_at",
    async () => {
      const prev = new Date(originalBUpdatedAt).getTime();
      const next = new Date(statusBPromoted.updated_at).getTime();
      return next >= prev;
    },
  );

  // 5. Optional: deactivate Status B and validate local invariants
  const statusBDeactivateBody = {
    is_active: false,
  } satisfies ITodoAppTodoStatus.IUpdate;

  const statusBDeactivated: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.update(connection, {
      statusCode: statusB.code,
      body: statusBDeactivateBody,
    });
  typia.assert(statusBDeactivated);

  TestValidator.equals(
    "status B id remains stable after deactivation",
    statusBDeactivated.id,
    originalBId,
  );
  TestValidator.equals(
    "status B code remains immutable after deactivation",
    statusBDeactivated.code,
    statusB.code,
  );
  TestValidator.equals(
    "status B remains default after deactivation unless business rules change it",
    statusBDeactivated.is_default,
    statusBPromoted.is_default,
  );
  TestValidator.equals(
    "status B is_active becomes false after deactivation",
    statusBDeactivated.is_active,
    false,
  );

  await TestValidator.predicate(
    "status B updated_at advances again after deactivation",
    async () => {
      const prev = new Date(statusBPromoted.updated_at).getTime();
      const next = new Date(statusBDeactivated.updated_at).getTime();
      return next >= prev;
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate successful logical deprecation of a Todo status by todoAdmin.
 *
 * Business goal: Ensure that a privileged todoAdmin can deprecate (logically
 * disable) a specific Todo status by its business `statusCode` (the `code`
 * column), such that:
 *
 * - The status exists and is initially active and non-default.
 * - The first DELETE call succeeds and marks it as deprecated.
 * - A subsequent DELETE for the same code fails, implying the first call changed
 *   catalogue state instead of being a no-op.
 *
 * Constraints and assumptions from available APIs:
 *
 * - We only have join, create, and erase operations in this test scope. There is
 *   no read/list API for statuses exposed here, so we validate deprecation via
 *   behavior (success then failure) rather than direct re-fetch.
 * - The admin authentication context is established by /auth/todoAdmin/join,
 *   which sets Authorization headers on the provided connection via its
 *   token.access field.
 * - The status being deprecated must not be default, so we create a status with
 *   is_default=false.
 * - The status must be initially active, so we set is_active=true.
 *
 * Step-by-step scenario:
 *
 * 1. Register a new todoAdmin account with POST /auth/todoAdmin/join.
 * 2. Using the authenticated admin connection, create a new Todo status with a
 *    unique business code via POST /todoApp/todoAdmin/todoStatuses.
 * 3. Deprecate that status by calling DELETE
 *    /todoApp/todoAdmin/todoStatuses/{statusCode} once; expect success.
 * 4. Call the same DELETE again for the same statusCode and assert that an error
 *    is thrown, confirming that the previous call changed the catalogue state
 *    and that double deprecation is not allowed.
 */
export async function test_api_todo_status_deprecate_success_by_todoadmin(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin account and obtain authorized context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Create a new active, non-default Todo status to be deprecated.
  const statusCodePrefix = "TEST_DEPRECATE_";
  const statusCode = `${statusCodePrefix}${RandomGenerator.alphaNumeric(8)}`;

  const createBody = {
    code: statusCode,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: null,
    group: null,
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodoStatus>(createdStatus);

  // Ensure that the created status code matches our requested business code.
  TestValidator.equals(
    "created status must keep requested business code",
    createdStatus.code,
    statusCode,
  );

  // 3. First deprecation attempt should succeed (no error thrown).
  await api.functional.todoApp.todoAdmin.todoStatuses.erase(connection, {
    statusCode: createdStatus.code,
  });

  // 4. Second deprecation attempt for the same code should now fail.
  await TestValidator.error(
    "second deprecate call must fail for already deprecated code",
    async () => {
      await api.functional.todoApp.todoAdmin.todoStatuses.erase(connection, {
        statusCode: createdStatus.code,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate that a default Todo status configured as active cannot be deprecated
 * via the administrative DELETE endpoint.
 *
 * ## Business context
 *
 * The Todo application keeps a catalogue of allowed Todo statuses in the
 * `todo_app_todo_statuses` table. Each status has a stable business `code`, a
 * human-facing `label`, ordering metadata, and behavior flags such as
 * `is_default` (the default status for new Todos) and `is_active`.
 *
 * Administrative operators (todoAdmin) can manage this catalogue through
 * protected APIs. However, when a status is currently configured as the system
 * default, higher level business rules (potentially backed by
 * `todo_app_system_configs`) must prevent that status from being logically
 * deprecated/erased while it is still mandatory for new Todos.
 *
 * This test ensures that attempting to deprecate such a protected default
 * status fails and that other statuses remain unaffected.
 *
 * ## Test flow
 *
 * 1. Register a new todoAdmin using `/auth/todoAdmin/join` so that subsequent
 *    catalogue operations are authorized.
 * 2. Using the admin context, create two Todo status entries via
 *    `/todoApp/todoAdmin/todoStatuses`:
 *
 *    - `defaultStatus`: a status marked as `is_default=true` and `is_active=true`,
 *         representing the protected default status.
 *    - `backupStatus`: a separate status marked as `is_default=false` and
 *         `is_active=true`, representing a normal active status.
 * 3. Attempt to deprecate `defaultStatus` by calling `DELETE
 *    /todoApp/todoAdmin/todoStatuses/{statusCode}` with `statusCode =
 *    defaultStatus.code`.
 * 4. Assert, using `TestValidator.error`, that the erase operation fails (throws)
 *    when targeting this default status, reflecting protection by business
 *    rules.
 * 5. Confirm that our in-memory representations still show
 *    `defaultStatus.is_default === true` and `defaultStatus.is_active ===
 *    true`, and that `backupStatus.is_default === false` and
 *    `backupStatus.is_active === true` — indicating no unintended mutation from
 *    the failed call.
 *
 * Note: As this test scope does not expose read/list endpoints or explicit
 * system configuration APIs, we cannot re-fetch or inspect the catalogue state
 * from the backend. Instead, we focus on verifying that the DELETE operation
 * fails for the default status and that our locally captured status objects
 * remain logically consistent.
 */
export async function test_api_todo_status_deprecate_protected_default_status(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin (join) to acquire authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.example.com/join",
    referrer: "https://admin.todo-app.example.com/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create a default active status and a backup active status
  const suffix = RandomGenerator.alphaNumeric(8);

  const defaultStatusBody = {
    code: `DEFAULT_STATUS_${suffix}`,
    label: `Default Status ${suffix}`,
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const defaultStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: defaultStatusBody,
    });
  typia.assert(defaultStatus);

  const backupStatusBody = {
    code: `BACKUP_STATUS_${suffix}`,
    label: `Backup Status ${suffix}`,
    description: RandomGenerator.paragraph({ sentences: 2 }),
    group: "core",
    sort_order: 2,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const backupStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: backupStatusBody,
    });
  typia.assert(backupStatus);

  // Basic sanity checks on created statuses
  TestValidator.equals(
    "default status is_default flag should be true",
    defaultStatus.is_default,
    true,
  );
  TestValidator.equals(
    "default status is_active flag should be true",
    defaultStatus.is_active,
    true,
  );
  TestValidator.equals(
    "backup status is_default flag should be false",
    backupStatus.is_default,
    false,
  );
  TestValidator.equals(
    "backup status is_active flag should be true",
    backupStatus.is_active,
    true,
  );

  // 3. Attempt to deprecate (erase) the default status by its business code
  await TestValidator.error(
    "deprecating a default active status should fail",
    async () => {
      await api.functional.todoApp.todoAdmin.todoStatuses.erase(connection, {
        statusCode: defaultStatus.code,
      });
    },
  );

  // 4. Confirm our captured objects remain logically consistent
  TestValidator.equals(
    "default status remains marked as default after failed erase",
    defaultStatus.is_default,
    true,
  );
  TestValidator.equals(
    "default status remains active after failed erase",
    defaultStatus.is_active,
    true,
  );
  TestValidator.equals(
    "backup status remains non-default after failed erase of default",
    backupStatus.is_default,
    false,
  );
  TestValidator.equals(
    "backup status remains active after failed erase of default",
    backupStatus.is_active,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Ensure that attempting to deprecate an already-deprecated Todo status fails.
 *
 * Business goal:
 *
 * - Todo statuses are centrally defined in `todo_app_todo_statuses` and addressed
 *   by their business `code`.
 * - DELETE /todoApp/todoAdmin/todoStatuses/{statusCode} must _not_ behave as a
 *   silently idempotent delete when the status is already deprecated. Instead,
 *   a second deprecation attempt for the same `statusCode` must respond with an
 *   error to keep administrators' mental model of catalogue state accurate.
 *
 * Scenario steps:
 *
 * 1. Register a new todoAdmin using POST /auth/todoAdmin/join and obtain an
 *    authenticated connection (the SDK wires the JWT into headers).
 * 2. As that admin, create a new active, non-default Todo status via POST
 *    /todoApp/todoAdmin/todoStatuses with a unique code such as
 *    "TEST_ALREADY_DEPRECATED_*".
 * 3. Call DELETE /todoApp/todoAdmin/todoStatuses/{statusCode} once using the
 *    created status.code. This is expected to succeed and logically deprecate
 *    the status in the catalogue.
 * 4. Call the same DELETE endpoint a second time with the identical `statusCode`.
 *    This second call must _fail_ with an error instead of silently succeeding,
 *    reflecting the "already deprecated" constraint described in the endpoint
 *    documentation.
 * 5. Assert that the second call throws by wrapping it with `await
 *    TestValidator.error`. We do not inspect HTTP status codes or error
 *    bodies—only that an error is raised.
 */
export async function test_api_todo_status_deprecate_already_deprecated_status(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin and obtain an authorized context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin = await api.functional.auth.todoAdmin.join(connection, {
    body: joinBody,
  });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Create a new active, non-default Todo status to be deprecated.
  const uniqueSuffix = RandomGenerator.alphaNumeric(8).toUpperCase();
  const statusCode = `TEST_ALREADY_DEPRECATED_${uniqueSuffix}`;

  const createBody = {
    code: statusCode,
    label: `Already deprecated test ${uniqueSuffix}`,
    description: RandomGenerator.paragraph({ sentences: 5 }),
    group: "e2e-test",
    sort_order: 100,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodoStatus>(createdStatus);

  // Sanity check: ensure the status code we will use for deletion matches.
  TestValidator.equals(
    "created status.code must equal requested statusCode",
    createdStatus.code,
    statusCode,
  );

  // 3. First deprecation attempt: should succeed without throwing.
  await api.functional.todoApp.todoAdmin.todoStatuses.erase(connection, {
    statusCode: createdStatus.code,
  });

  // 4. Second deprecation attempt: must fail with an error because the status
  //    is already deprecated.
  await TestValidator.error(
    "second erase on already-deprecated status must throw",
    async () => {
      await api.functional.todoApp.todoAdmin.todoStatuses.erase(connection, {
        statusCode: createdStatus.code,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemConfig";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

export async function test_api_system_configs_search_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin and obtain authenticated context
  const joinRequest = typia.random<ITodoAppTodoAdminJoin.IRequest>();

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequest,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Seed multiple system configuration entries under a common scope
  const scope = "todo";
  const seedConfigs: ITodoAppSystemConfig[] = [];

  const createConfig = async (key: string, value: string): Promise<void> => {
    const created: ITodoAppSystemConfig =
      await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
        body: {
          scope,
          key,
          value,
          description: RandomGenerator.paragraph({ sentences: 3 }),
          is_active: true,
        } satisfies ITodoAppSystemConfig.ICreate,
      });
    typia.assert<ITodoAppSystemConfig>(created);
    seedConfigs.push(created);
  };

  await createConfig("deletion_model", "soft_delete");
  await createConfig("soft_delete_retention_days", "30");
  await createConfig("max_open_todos_per_user", "50");

  const seededCount = seedConfigs.length;

  // 3. Call index with basic pagination: page 0, small limit, null filters
  const page = 0;
  const limit = 2;

  const requestBody = {
    page,
    limit,
    scope: null,
    key: null,
    is_active: null,
    include_deleted: null,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppSystemConfig.IRequest;

  const pageResult: IPageITodoAppSystemConfig.ISummary =
    await api.functional.todoApp.todoAdmin.systemConfigs.index(connection, {
      body: requestBody,
    });
  typia.assert<IPageITodoAppSystemConfig.ISummary>(pageResult);

  const pagination: IPage.IPagination = pageResult.pagination;
  const data: ITodoAppSystemConfig.ISummary[] = pageResult.data;

  // 4. Validate pagination metadata
  TestValidator.equals(
    "pagination.current should be first page (0)",
    pagination.current,
    page,
  );

  TestValidator.equals(
    "pagination.limit should match requested limit",
    pagination.limit,
    limit,
  );

  TestValidator.predicate(
    "pagination.records should be at least the number of seeded configs",
    pagination.records >= seededCount,
  );

  TestValidator.predicate(
    "pagination.pages should be at least 1 when there are any records",
    pagination.records === 0 ? pagination.pages === 0 : pagination.pages >= 1,
  );

  TestValidator.predicate(
    "current page index should be within total pages when there are records",
    pagination.records === 0
      ? pagination.current === 0
      : pagination.current < pagination.pages,
  );

  // 5. Validate data array constraints
  TestValidator.predicate(
    "data length should not exceed pagination.limit",
    data.length <= pagination.limit,
  );

  // Ensure that at least one seeded configuration appears in the current page
  const seededKeys = seedConfigs.map((c) => `${c.scope}:${c.key}`);
  const pageKeys = data.map((c) => `${c.scope}:${c.key}`);

  TestValidator.predicate(
    "at least one seeded configuration should appear in the first page when possible",
    pagination.records === 0
      ? data.length === 0
      : pageKeys.some((k) => seededKeys.includes(k)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemConfig";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate scope-only and scope+key filtering behavior of system configuration
 * search.
 *
 * Business context: The TodoApp exposes administrative APIs to manage
 * system-wide configuration entries backed by the `todo_app_system_configs`
 * table. Each configuration row is identified by a `scope` and `key` pair (for
 * example, `todo/deletion_model`) and is consumed by various subsystems such as
 * todo lifecycle management and authentication policies.
 *
 * This test ensures that the system configuration search endpoint (PATCH
 * /todoApp/todoAdmin/systemConfigs) correctly honors the `scope` and `key`
 * filters provided through `ITodoAppSystemConfig.IRequest` when invoked by an
 * authenticated todoAdmin.
 *
 * End-to-end workflow:
 *
 * 1. Register a new todoAdmin account using POST /auth/todoAdmin/join to obtain an
 *    authorized admin context and token. The SDK automatically stores the
 *    access token in the connection headers.
 * 2. Insert multiple configuration entries using POST
 *    /todoApp/todoAdmin/systemConfigs, covering at least two scopes:
 *
 *    - Scope: "todo", keys: "deletion_model", "soft_delete_retention_days"
 *    - Scope: "auth", key: "max_login_attempts"
 * 3. Call PATCH /todoApp/todoAdmin/systemConfigs (index) with a request body
 *    where:
 *
 *    - Page = 0
 *    - Limit is large enough to include all inserted rows (for example 10)
 *    - Scope = "todo"
 *    - Key = null (no key filter)
 *    - Is_active, include_deleted, order_by, order_direction = null so that default
 *         behavior applies Then assert that:
 *    - All returned entries have scope === "todo"
 *    - No entry with scope === "auth" is present.
 * 4. Call PATCH /todoApp/todoAdmin/systemConfigs again with the same pagination
 *    but now with:
 *
 *    - Scope = "todo"
 *    - Key = "deletion_model" Then assert that:
 *    - At least one entry is returned
 *    - Every returned entry has scope === "todo" and key === "deletion_model".
 *
 * Type safety and validation rules:
 *
 * - Use ITodoAppTodoAdminJoin.IRequest for the join payload via `satisfies`.
 * - Use ITodoAppSystemConfig.ICreate for create bodies via `satisfies`.
 * - Use ITodoAppSystemConfig.IRequest for search bodies via `satisfies`.
 * - Always call typia.assert on non-void API responses to validate runtime
 *   typing.
 * - Use TestValidator.predicate / equals for business rule assertions, with
 *   descriptive titles.
 * - Never test type errors, HTTP status codes, or deliberately invalid payloads.
 */
export async function test_api_system_configs_search_with_scope_and_key_filters(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin to obtain an authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todoapp.example.com/register",
    referrer: "https://admin.todoapp.example.com/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Create configuration entries in multiple scopes/keys
  const todoDeletionModelCreate = {
    scope: "todo",
    key: "deletion_model",
    value: "soft_delete",
    description: "Deletion model for todos (soft_delete vs hard_delete)",
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  const todoRetentionDaysCreate = {
    scope: "todo",
    key: "soft_delete_retention_days",
    value: "30",
    description: "Number of days to retain soft-deleted todos",
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  const authMaxLoginAttemptsCreate = {
    scope: "auth",
    key: "max_login_attempts",
    value: "5",
    description: "Maximum allowed consecutive failed login attempts",
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  const todoDeletionModel: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: todoDeletionModelCreate,
    });
  typia.assert<ITodoAppSystemConfig>(todoDeletionModel);

  const todoRetentionDays: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: todoRetentionDaysCreate,
    });
  typia.assert<ITodoAppSystemConfig>(todoRetentionDays);

  const authMaxLoginAttempts: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: authMaxLoginAttemptsCreate,
    });
  typia.assert<ITodoAppSystemConfig>(authMaxLoginAttempts);

  // 3. Search by scope only (scope = "todo", key = null)
  const scopeOnlyRequest = {
    page: 0 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    scope: "todo",
    key: null,
    is_active: null,
    include_deleted: null,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppSystemConfig.IRequest;

  const scopeOnlyPage: IPageITodoAppSystemConfig.ISummary =
    await api.functional.todoApp.todoAdmin.systemConfigs.index(connection, {
      body: scopeOnlyRequest,
    });
  typia.assert<IPageITodoAppSystemConfig.ISummary>(scopeOnlyPage);

  // Ensure we got at least the two todo configs we just created
  TestValidator.predicate(
    "scope-only search should return at least two todo scoped configs",
    scopeOnlyPage.data.length >= 2,
  );

  // Assert that all configs are in the "todo" scope and no "auth" scope entry exists
  const hasOnlyTodoScope = scopeOnlyPage.data.every(
    (cfg) => cfg.scope === "todo",
  );
  TestValidator.predicate(
    'all configs from scope-only search must have scope "todo"',
    hasOnlyTodoScope,
  );

  const hasAuthScope = scopeOnlyPage.data.some((cfg) => cfg.scope === "auth");
  TestValidator.predicate(
    'scope-only search results must not contain scope "auth"',
    hasAuthScope === false,
  );

  // 4. Search by scope + key (scope = "todo", key = "deletion_model")
  const scopeAndKeyRequest = {
    page: 0 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    scope: "todo",
    key: "deletion_model",
    is_active: null,
    include_deleted: null,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppSystemConfig.IRequest;

  const scopeAndKeyPage: IPageITodoAppSystemConfig.ISummary =
    await api.functional.todoApp.todoAdmin.systemConfigs.index(connection, {
      body: scopeAndKeyRequest,
    });
  typia.assert<IPageITodoAppSystemConfig.ISummary>(scopeAndKeyPage);

  TestValidator.predicate(
    "scope+key search for todo/deletion_model should return at least one row",
    scopeAndKeyPage.data.length >= 1,
  );

  const allMatchScopeAndKey = scopeAndKeyPage.data.every(
    (cfg) => cfg.scope === "todo" && cfg.key === "deletion_model",
  );
  TestValidator.predicate(
    'all configs from scope+key search must match scope "todo" and key "deletion_model"',
    allMatchScopeAndKey,
  );

  // Optionally, ensure that the created deletion_model config is among the results
  const containsCreatedDeletionModel = scopeAndKeyPage.data.some(
    (cfg) => cfg.id === todoDeletionModel.id,
  );
  TestValidator.predicate(
    "scope+key search should include the created todo/deletion_model config",
    containsCreatedDeletionModel,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemConfig";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate that system configuration search respects is_active and
 * include_deleted filters.
 *
 * Business goal: Ensure that the admin-facing search endpoint for
 * `todo_app_system_configs` returns only active, non-deleted configurations
 * when requested, excludes active rows when `is_active` is false, and that
 * `include_deleted` only broadens the result set rather than excluding
 * non-deleted rows.
 *
 * High level steps:
 *
 * 1. Join as a new todoAdmin so that subsequent systemConfig calls are
 *    authenticated.
 * 2. Create several system configuration entries with distinct scope/key
 *    combinations; rely on server defaults for is_active and deleted_at.
 * 3. Search with `is_active: true` and `include_deleted: false` and ensure all
 *    returned rows are active and not soft-deleted.
 * 4. Search with `is_active: false` and confirm that, because we've only created
 *    active configs, zero records are returned.
 * 5. Search with `include_deleted: true` and confirm that the dataset is at least
 *    as large as the active-only view and that deleted_at remains null for our
 *    newly created configs.
 */
export async function test_api_system_configs_search_active_vs_inactive_and_deleted(
  connection: api.IConnection,
) {
  // 1. Join as a new todoAdmin (authentication dependency).
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todoapp.example.com/join",
    referrer: "https://admin.todoapp.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create several system configuration entries.
  const createConfig = async (
    scope: string,
    key: string,
  ): Promise<ITodoAppSystemConfig> => {
    const body = {
      scope,
      key,
      value: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 2 }),
      is_active: true,
    } satisfies ITodoAppSystemConfig.ICreate;

    const config: ITodoAppSystemConfig =
      await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
        body,
      });
    typia.assert(config);
    return config;
  };

  const configActive1 = await createConfig("todo", "feature_flag_alpha");
  const configActive2 = await createConfig("todo", "feature_flag_beta");
  const configActive3 = await createConfig("system", "retention_policy_days");

  const createdConfigs = [configActive1, configActive2, configActive3];

  // Helper to run index with arbitrary filters.
  const search = async (
    override: Partial<ITodoAppSystemConfig.IRequest>,
  ): Promise<IPageITodoAppSystemConfig.ISummary> => {
    const base: ITodoAppSystemConfig.IRequest = {
      page: 0 as number & tags.Type<"int32">,
      limit: 50 as number & tags.Type<"int32">,
      scope: null,
      key: null,
      is_active: null,
      include_deleted: null,
      order_by: null,
      order_direction: null,
    };

    const body: ITodoAppSystemConfig.IRequest = {
      ...base,
      ...override,
    };

    const pageResult: IPageITodoAppSystemConfig.ISummary =
      await api.functional.todoApp.todoAdmin.systemConfigs.index(connection, {
        body,
      });
    typia.assert(pageResult);
    return pageResult;
  };

  // 3. Search active, non-deleted configs.
  const activePage = await search({
    is_active: true,
    include_deleted: false,
  });

  const activePagination = activePage.pagination;
  const activeData = activePage.data;

  // Basic sanity checks on pagination structure.
  TestValidator.predicate(
    "active search pagination limit is positive",
    activePagination.limit > 0,
  );
  TestValidator.predicate(
    "active search records non-negative",
    activePagination.records >= 0,
  );

  // All results must be active and non-deleted.
  for (const row of activeData) {
    TestValidator.predicate(
      "row in active search is_active must be true",
      row.is_active === true,
    );
    TestValidator.predicate(
      "row in active search deleted_at must be null",
      row.deleted_at === null,
    );
  }

  // Ensure that our created configs appear in the active search (by id).
  for (const created of createdConfigs) {
    const found = activeData.find((row) => row.id === created.id);
    TestValidator.predicate(
      `created config ${created.scope}/${created.key} appears in active search`,
      !!found,
    );
  }

  // 4. Search inactive-only configs.
  const inactivePage = await search({
    is_active: false,
    include_deleted: null,
  });

  const inactivePagination = inactivePage.pagination;
  const inactiveData = inactivePage.data;

  TestValidator.equals(
    "inactive search has zero records because only active configs were created",
    inactivePagination.records,
    0,
  );
  TestValidator.equals(
    "inactive search data length is zero",
    inactiveData.length,
    0,
  );

  // 5. Search including deleted entries.
  const includeDeletedPage = await search({
    is_active: null,
    include_deleted: true,
  });

  const includeDeletedPagination = includeDeletedPage.pagination;
  const includeDeletedData = includeDeletedPage.data;

  TestValidator.predicate(
    "include_deleted search has records >= active search",
    includeDeletedPagination.records >= activePagination.records,
  );

  // Every active result should still be present when including deleted.
  for (const activeRow of activeData) {
    const found = includeDeletedData.find((row) => row.id === activeRow.id);
    TestValidator.predicate(
      `active config ${activeRow.scope}/${activeRow.key} still present when include_deleted is true`,
      !!found,
    );
  }

  // Our created configs should still be non-deleted even when include_deleted=true.
  for (const created of createdConfigs) {
    const found = includeDeletedData.find((row) => row.id === created.id);
    TestValidator.predicate(
      `created config ${created.scope}/${created.key} present in include_deleted search`,
      !!found,
    );
    if (found) {
      TestValidator.predicate(
        `created config ${created.scope}/${created.key} deleted_at is null even in include_deleted search`,
        found.deleted_at === null,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
