  const adminJoinOutput: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoinOutput);

  // 2. As admin, create an ACTIVE Todo status
  const statusCode = "ACTIVE";
  const statusCreateBody = {
    code: statusCode,
    label: "Active",
    description: "Active todo status for open items",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const statusOutput: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(statusOutput);
  TestValidator.equals(
    "created status code should match request",
    statusOutput.code,
    statusCode,
  );

  // 3. Register first todoUser (userA)
  const userAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const userAPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const userAJoinBody = {
    email: userAEmail,
    password: userAPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAJoinOutput: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userAJoinBody,
    });
  typia.assert(userAJoinOutput);

  const userAId = userAJoinOutput.id;

  // 4. As userA, create at least one todo
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 1 }),
    due_date: new Date().toISOString(),
    status_code: statusCode,
  } satisfies ITodoAppTodo.ICreate;

  const todoOutput: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todoOutput);
  TestValidator.equals(
    "created todo should use requested status code",
    todoOutput.status.code,
    statusCode,
  );

  // 5. Switch back to admin via login
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://admin.todo-app.example.com/login",
    referrer: "https://admin.todo-app.example.com/",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminLoginOutput: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginOutput);
  TestValidator.equals(
    "admin login id should match joined admin id",
    adminLoginOutput.id,
    adminJoinOutput.id,
  );

  // 6. As admin, delete userA
  await api.functional.todoApp.todoAdmin.todoUsers.erase(connection, {
    todoUserId: userAId,
  });

  // 7. Attempt to log in again as userA and expect failure
  const userALoginBody = {
    email: userAEmail,
    password: userAPassword,
    ip: null,
    href: "https://todo-app.example.com/login",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  await TestValidator.error(
    "deleted user should not be able to log in",
    async () => {
      await api.functional.auth.todoUser.login(connection, {
        body: userALoginBody,
      });
    },
  );

  // 8. Create second todoUser (userB) and ensure they cannot call erase
  const userBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const userBPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const userBJoinBody = {
    email: userBEmail,
    password: userBPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userBJoinOutput: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userBJoinBody,
    });
  typia.assert(userBJoinOutput);

  await TestValidator.error(
    "todoUser actor must not be able to call admin delete user endpoint",
    async () => {
      await api.functional.todoApp.todoAdmin.todoUsers.erase(connection, {
        todoUserId: userAId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Ensure that deleting a non-existent todo user as an admin produces a
 * not-found style HTTP error and does not corrupt the admin context so that
 * subsequent operations continue to work.
 *
 * Business context:
 *
 * - The DELETE /todoApp/todoAdmin/todoUsers/{todoUserId} endpoint is reserved for
 *   administrative operators (todoAdmin) to remove end-user accounts held in
 *   the `todo_app_todousers` table.
 * - When an admin attempts to delete a user ID that does not exist, the system
 *   must respond with a not-found style error (typically HTTP 404), rather than
 *   treating it as success or leaking internal details.
 * - The failed delete must not impact the admin authentication context or other
 *   users; it should be a clean, contained error.
 *
 * Test steps:
 *
 * 1. Register a new admin via POST /auth/todoAdmin/join, using a random but valid
 *    ITodoAppTodoAdminJoin.IRequest payload. This call should succeed and cause
 *    the SDK to attach a valid access token onto the connection object for
 *    authenticated admin operations.
 * 2. Generate a random UUID string to represent a todoUserId that does not
 *    correspond to any existing user. The test does not create any todo users,
 *    so any UUID is effectively non-existent from the perspective of this
 *    test.
 * 3. Invoke api.functional.todoApp.todoAdmin.todoUsers.erase(connection, {
 *    todoUserId }) inside TestValidator.httpError to assert that the operation
 *    throws an HttpError with 404 status (not found semantics).
 * 4. After the error has been verified, perform a simple follow-up admin operation
 *    (another join with a different email) to confirm that the connection and
 *    backend remain usable after the failed delete.
 */
export async function test_api_todo_admin_delete_nonexistent_user(
  connection: api.IConnection,
) {
  // 1. Register an initial admin to establish an authenticated context.
  const firstJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const firstAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: firstJoinBody,
    });
  typia.assert(firstAdmin);

  // Basic sanity check on returned admin identity.
  TestValidator.equals(
    "joined admin email should match input email",
    firstAdmin.email,
    firstJoinBody.email,
  );

  // 2. Generate a random UUID for a todoUserId that does not exist.
  const nonExistentTodoUserId = typia.random<string & tags.Format<"uuid">>();

  // 3. Attempt to delete the non-existent user and assert not-found error.
  await TestValidator.httpError(
    "deleting non-existent todo user should yield 404 not found error",
    404,
    async () => {
      await api.functional.todoApp.todoAdmin.todoUsers.erase(connection, {
        todoUserId: nonExistentTodoUserId,
      });
    },
  );

  // 4. Follow-up join to ensure admin-related operations still work
  //    after the failed delete attempt.
  const secondJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const secondAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: secondJoinBody,
    });
  typia.assert(secondAdmin);

  TestValidator.equals(
    "second joined admin email should match its input email",
    secondAdmin.email,
    secondJoinBody.email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";

/**
 * Validate that todoAdmin cannot delete todoUser accounts that are in a
 * restricted/protected status.
 *
 * Business context: Administrative operators (todoAdmin) manage end-user
 * accounts (todoUser) through privileged APIs. Certain lifecycle statuses, such
 * as a hypothetical "protected" status, should prevent permanent deletion of a
 * user record to preserve auditability or comply with policy.
 *
 * This E2E test walks through the full workflow to ensure that when a todoUser
 * is set to a restricted status, a delete attempt via the admin deletion
 * endpoint fails and leaves the account intact.
 *
 * Step-by-step process:
 *
 * 1. Register a new todoAdmin via /auth/todoAdmin/join to obtain an administrative
 *    session.
 * 2. Register a new todoUser via /auth/todoUser/join and capture its id.
 * 3. Ensure the connection is authenticated as todoAdmin (re-join admin if
 *    necessary, because todoUser.join also sets Authorization header).
 * 4. As todoAdmin, update the todoUser via PUT
 *    /todoApp/todoAdmin/todoUsers/{todoUserId} to set status to a restricted
 *    value, e.g. "protected".
 * 5. Attempt to delete the same todoUser via DELETE
 *    /todoApp/todoAdmin/todoUsers/{todoUserId}. Expect this operation to fail
 *    with some domain-rule error (we only assert that an error occurs, not the
 *    specific HTTP status code).
 * 6. Finally, GET the todoUser via the admin GET endpoint and assert that:
 *
 *    - The user still exists (id matches original id).
 *    - The status is still "protected" (no change from the failed delete).
 */
export async function test_api_todo_admin_delete_user_with_restricted_status(
  connection: api.IConnection,
) {
  // 1. Register an admin (todoAdmin.join)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Register a todoUser (todoUser.join)
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userAuthorized);

  const todoUserId = userAuthorized.id;

  // 3. Ensure connection is authenticated as admin again
  const adminRejoinBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    displayName: adminJoinBody.displayName ?? null,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminReauthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminRejoinBody,
    });
  typia.assert(adminReauthorized);

  // 4. As admin, set the user status to a restricted/protected value
  const restrictedStatus = "protected";

  const updatedUser: ITodoAppTodoUser =
    await api.functional.todoApp.todoAdmin.todoUsers.update(connection, {
      todoUserId,
      body: {
        status: restrictedStatus,
      } satisfies ITodoAppTodoUser.IUpdate,
    });
  typia.assert(updatedUser);

  TestValidator.equals(
    "updated user id should match original",
    updatedUser.id,
    todoUserId,
  );
  TestValidator.equals(
    "updated user status should be protected",
    updatedUser.status,
    restrictedStatus,
  );

  // 5. Attempt to delete the protected user and expect failure
  await TestValidator.error(
    "deleting a protected-status todoUser should fail",
    async () => {
      await api.functional.todoApp.todoAdmin.todoUsers.erase(connection, {
        todoUserId,
      });
    },
  );

  // 6. Verify the user still exists and status remains protected
  const reloadedUser: ITodoAppTodoUser =
    await api.functional.todoApp.todoAdmin.todoUsers.at(connection, {
      todoUserId,
    });
  typia.assert(reloadedUser);

  TestValidator.equals(
    "reloaded user id should match original",
    reloadedUser.id,
    todoUserId,
  );
  TestValidator.equals(
    "reloaded user status should still be protected",
    reloadedUser.status,
    restrictedStatus,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodouserSession";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";
import type { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";

/**
 * E2E: todoAdmin lists authentication sessions for an active todoUser.
 *
 * Business purpose:
 *
 * - Ensure that the administrative session listing endpoint PATCH
 *   /todoApp/todoAdmin/todoUsers/{todoUserId}/sessions correctly returns
 *   paginated session summaries only for the specified todo user, and that it
 *   is accessible only with todoAdmin credentials.
 *
 * Test steps:
 *
 * 1. Register an admin account (POST /auth/todoAdmin/join).
 *
 *    - Use deterministic, valid email, password, href, referrer.
 *    - Typia.assert the ITodoAppTodoAdmin.IAuthorized response.
 *    - This call sets an admin JWT into `connection.headers`.
 * 2. Register a todoUser account (POST /auth/todoUser/join).
 *
 *    - Provide ITodoAppTodoUserJoin.IRequest with email, password, display_name
 *         (optional), and realistic href/referrer.
 *    - Typia.assert the ITodoAppTodoUser.IAuthorized response.
 *    - Capture the todoUser id and email for later assertions.
 *    - This call also creates an initial session row for the user and sets the
 *         connection Authorization header to the todoUser token.
 * 3. Perform multiple logins as the same todoUser (POST /auth/todoUser/login).
 *
 *    - Call login 2~3 times with the same email/password and different href/referrer
 *         to simulate realistic activity.
 *    - Each successful login should create a new todo_app_todouser_sessions record.
 *    - After each login, typia.assert the ITodoAppTodoUser.IAuthorized response.
 *    - Track how many login attempts succeeded (for basic expectations that total
 *         session records should be at least that many plus the registration
 *         session).
 * 4. Re-authenticate as an admin.
 *
 *    - Easiest approach: call /auth/todoAdmin/join again with a different admin
 *         email.
 *    - Typia.assert the ITodoAppTodoAdmin.IAuthorized response.
 *    - This overwrites `connection.headers.Authorization` with an admin token so
 *         subsequent calls execute in admin context.
 * 5. Call PATCH /todoApp/todoAdmin/todoUsers/{todoUserId}/sessions via
 *    api.functional.todoApp.todoAdmin.todoUsers.sessions.index.
 *
 *    - Pass todoUserId from the created todoUser.
 *    - For the body, construct ITodoAppTodouserSession.IRequest with: page = 1
 *         (first page, 1-based), limit = 2 (small page size to exercise
 *         pagination), other filters omitted (undefined) so we get a simple
 *         listing of most recent sessions.
 *    - Await the response of type IPageITodoAppTodouserSession.ISummary and validate
 *         with typia.assert.
 * 6. Validate pagination metadata and general structure.
 *
 *    - Pagination.current must be 0 for the first page.
 *    - Pagination.limit should equal 2 (the requested limit).
 *    - Pagination.records must be >= data.length.
 *    - Pagination.pages must be >= 1 when records > 0.
 *    - Data.length should be > 0 (because we created multiple sessions) and <=
 *         limit.
 * 7. Validate each ITodoAppTodouserSession.ISummary item.
 *
 *    - TodoUser.id equals the created user's id.
 *    - TodoUser.email equals the created user's email.
 *    - Ip, href, referrer are non-empty strings.
 *    - Created_at is a non-empty string.
 *    - Expired_at can be null/undefined or a date-time string, but typia.assert
 *         already guarantees the type, so only business checks on presence are
 *         performed where reasonable.
 * 8. Optionally request a second page of sessions.
 *
 *    - Call the same index endpoint with page = 2 and the same limit.
 *    - Validate that pagination.current is 1, limit still equals 2, and data.length
 *         is between 0 and 2.
 *    - For all returned records, again confirm that todoUser.id and email match the
 *         created todoUser.
 * 9. Error scenarios (kept simple and business-level):
 *
 *    - We skip explicit unauthorized error tests because the E2E template and SDK
 *         already assume valid authorization; focusing here on the happy path
 *         and data-scoping guarantees.
 */
export async function test_api_todo_admin_list_sessions_for_active_user(
  connection: api.IConnection,
) {
  // 1. Register an initial admin to ensure admin capabilities exist.
  const adminJoinBody = {
    email: `admin+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "AdminPass123!",
    displayName: RandomGenerator.name(2),
    ip: "127.0.0.1",
    href: "https://admin.example.com/register",
    referrer: "https://admin.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const initialAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(initialAdmin);

  // 2. Register a todoUser account who will own the sessions.
  const userEmail = `user+${RandomGenerator.alphaNumeric(8)}@example.com`;
  const userPassword = "UserPass123!";

  const userJoinBody = {
    email: userEmail as string & tags.Format<"email">,
    password: userPassword as string & tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    ip: "192.168.0.10",
    href: "https://app.example.com/signup",
    referrer: "https://app.example.com/marketing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const joinedUser: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(joinedUser);

  const todoUserId = joinedUser.id;
  const todoUserEmail = joinedUser.email;

  // 3. Perform multiple logins as the same todoUser to create extra sessions.
  const loginAttempts = 3;
  for (let i = 0; i < loginAttempts; i += 1) {
    const loginBody = {
      email: todoUserEmail,
      password: userPassword,
      ip: `192.168.0.${20 + i}`,
      href: `https://app.example.com/login?try=${i + 1}`,
      referrer: "https://app.example.com/home",
    } satisfies ITodoAppTodoUserLogin.IRequest;

    const loggedInUser: ITodoAppTodoUser.IAuthorized =
      await api.functional.auth.todoUser.login(connection, {
        body: loginBody,
      });
    typia.assert(loggedInUser);

    TestValidator.equals(
      `logged-in user id matches joined user id on attempt ${i + 1}`,
      loggedInUser.id,
      todoUserId,
    );
  }

  // 4. Re-authenticate as an admin so that the listing endpoint executes
  // in admin context. Use a new admin account to avoid any coupling
  // with the initial admin join call.
  const secondAdminJoinBody = {
    email: `admin2+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "AdminPass456!",
    displayName: RandomGenerator.name(2),
    ip: "127.0.0.2",
    href: "https://admin.example.com/register2",
    referrer: "https://admin.example.com/landing2",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const secondAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: secondAdminJoinBody,
    });
  typia.assert(secondAdmin);

  // 5. Call the admin sessions listing endpoint for page 1.
  const requestPage1 = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 2 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies ITodoAppTodouserSession.IRequest;

  const page1: IPageITodoAppTodouserSession.ISummary =
    await api.functional.todoApp.todoAdmin.todoUsers.sessions.index(
      connection,
      {
        todoUserId,
        body: requestPage1,
      },
    );
  typia.assert(page1);

  const pagination1 = page1.pagination;
  const data1 = page1.data;

  // 6. Pagination metadata assertions for first page.
  TestValidator.equals(
    "first page current index should be 0 (0-based)",
    pagination1.current,
    0,
  );

  TestValidator.equals(
    "page1 limit equals requested limit",
    pagination1.limit,
    requestPage1.limit,
  );

  TestValidator.predicate(
    "records count must be >= number of returned items on page1",
    pagination1.records >= data1.length,
  );

  TestValidator.predicate(
    "pages must be >= 1 when any records exist",
    pagination1.records === 0 || pagination1.pages >= 1,
  );

  TestValidator.predicate(
    "page1 data length must be > 0 and <= limit (we created several sessions)",
    data1.length > 0 && data1.length <= pagination1.limit,
  );

  // 7. Validate each session summary item in page1.
  for (const [index, session] of data1.entries()) {
    typia.assert<ITodoAppTodouserSession.ISummary>(session);

    TestValidator.equals(
      `session[${index}] todoUser.id matches target user id`,
      session.todoUser.id,
      todoUserId,
    );

    TestValidator.equals(
      `session[${index}] todoUser.email matches target user email`,
      session.todoUser.email,
      todoUserEmail,
    );

    TestValidator.predicate(
      `session[${index}] ip is a non-empty string`,
      session.ip.length > 0,
    );

    TestValidator.predicate(
      `session[${index}] href is a non-empty string`,
      session.href.length > 0,
    );

    TestValidator.predicate(
      `session[${index}] referrer is a non-empty string`,
      session.referrer.length > 0,
    );

    TestValidator.predicate(
      `session[${index}] created_at is a non-empty string`,
      session.created_at.length > 0,
    );
  }

  // 8. Optionally fetch the second page to validate pagination further.
  const requestPage2 = {
    page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: requestPage1.limit,
  } satisfies ITodoAppTodouserSession.IRequest;

  const page2: IPageITodoAppTodouserSession.ISummary =
    await api.functional.todoApp.todoAdmin.todoUsers.sessions.index(
      connection,
      {
        todoUserId,
        body: requestPage2,
      },
    );
  typia.assert(page2);

  const pagination2 = page2.pagination;
  const data2 = page2.data;

  TestValidator.equals(
    "second page current index should be 1 (0-based)",
    pagination2.current,
    1,
  );

  TestValidator.equals(
    "page2 limit equals requested limit",
    pagination2.limit,
    requestPage2.limit,
  );

  TestValidator.predicate(
    "page2 data length must be between 0 and limit",
    data2.length >= 0 && data2.length <= pagination2.limit,
  );

  for (const [index, session] of data2.entries()) {
    typia.assert<ITodoAppTodouserSession.ISummary>(session);

    TestValidator.equals(
      `page2 session[${index}] todoUser.id matches target user id`,
      session.todoUser.id,
      todoUserId,
    );

    TestValidator.equals(
      `page2 session[${index}] todoUser.email matches target user email`,
      session.todoUser.email,
      todoUserEmail,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodouserSession";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";
import type { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";

/**
 * Admin can filter a todoUser's authentication sessions by active/expired
 * status.
 *
 * Business goal:
 *
 * - Verify that the admin sessions listing endpoint honours the `isActive` filter
 *   flag in `ITodoAppTodouserSession.IRequest`.
 * - Ensure that all records are scoped to the specified `todoUserId` and that
 *   active vs expired sessions are correctly distinguished using `expired_at`.
 *
 * Scenario steps:
 *
 * 1. Register a new todoAdmin using /auth/todoAdmin/join, letting the SDK attach
 *    the admin Authorization token to the shared `connection`.
 * 2. Register a new todoUser using /auth/todoUser/join, capturing the created
 *    user's id from ITodoAppTodoUser.IAuthorized.
 * 3. Perform two separate logins as the todoUser via /auth/todoUser/login so that
 *    at least two session records exist for this user.
 * 4. As the admin (connection now holding admin token), call PATCH
 *    /todoApp/todoAdmin/todoUsers/{todoUserId}/sessions with `isActive: true`
 *    and explicit pagination fields.
 * 5. Assert that:
 *
 *    - Response type matches IPageITodoAppTodouserSession.ISummary.
 *    - All `data` entries have `todoUser.id` equal to the registered todoUser's id.
 *    - All `data` entries have `expired_at === null` (active sessions).
 * 6. Call the same endpoint with `isActive: false` to fetch inactive sessions for
 *    the same todoUser.
 * 7. Assert that:
 *
 *    - All `data` entries (if any) have `todoUser.id` equal to the user id.
 *    - All `data` entries have `expired_at !== null` (expired sessions).
 *    - If there are no expired sessions, the pagination.records is 0 and `data` is
 *         an empty array, which is still considered a success case.
 */
export async function test_api_todo_admin_filter_active_sessions_only(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin to obtain admin token
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "admin-password",
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Register a new todoUser
  const userEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const todoUserJoinBody = {
    email: userEmail,
    password: "user-password" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: todoUserJoinBody,
    });
  typia.assert(todoUserAuthorized);

  // Capture the todoUserId for later admin queries
  const todoUserId: string & tags.Format<"uuid"> = todoUserAuthorized.id;

  // 3. Perform at least two logins as the todoUser to create multiple sessions
  const loginBodyBase = {
    email: userEmail,
    password: "user-password",
    ip: null,
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const firstLogin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: loginBodyBase,
    });
  typia.assert(firstLogin);

  const secondLogin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: loginBodyBase,
    });
  typia.assert(secondLogin);

  // 4. Admin queries active sessions for the todoUser
  // The connection currently holds the todoUser token after login calls.
  // Rejoin admin to ensure we have an admin token for privileged endpoint.
  const adminRejoin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminRejoin);

  const activeRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 20 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    isActive: true,
    createdFrom: undefined,
    createdTo: undefined,
    expiredFrom: undefined,
    expiredTo: undefined,
    orderBy: "created_at" as const,
    orderDirection: "desc" as const,
  } satisfies ITodoAppTodouserSession.IRequest;

  const activePage: IPageITodoAppTodouserSession.ISummary =
    await api.functional.todoApp.todoAdmin.todoUsers.sessions.index(
      connection,
      {
        todoUserId,
        body: activeRequestBody,
      },
    );
  typia.assert(activePage);

  // 5. Validate that all returned sessions are active and belong to the user
  TestValidator.predicate(
    "active sessions pagination records non-negative",
    activePage.pagination.records >= 0,
  );

  for (const session of activePage.data) {
    typia.assert<ITodoAppTodouserSession.ISummary>(session);
    TestValidator.equals(
      "active session belongs to requested todoUser",
      session.todoUser.id,
      todoUserId,
    );
    TestValidator.equals(
      "active session expired_at must be null",
      session.expired_at ?? null,
      null,
    );
  }

  // 6. Admin queries inactive (expired) sessions for the same todoUser
  const inactiveRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 20 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    isActive: false,
    createdFrom: undefined,
    createdTo: undefined,
    expiredFrom: undefined,
    expiredTo: undefined,
    orderBy: "created_at" as const,
    orderDirection: "desc" as const,
  } satisfies ITodoAppTodouserSession.IRequest;

  const inactivePage: IPageITodoAppTodouserSession.ISummary =
    await api.functional.todoApp.todoAdmin.todoUsers.sessions.index(
      connection,
      {
        todoUserId,
        body: inactiveRequestBody,
      },
    );
  typia.assert(inactivePage);

  // 7. Validate inactive sessions behaviour.
  if (inactivePage.pagination.records === 0) {
    TestValidator.equals(
      "no inactive sessions implies empty data array",
      inactivePage.data.length,
      0,
    );
  } else {
    TestValidator.predicate(
      "inactive sessions pagination records positive",
      inactivePage.pagination.records > 0,
    );
  }

  for (const session of inactivePage.data) {
    typia.assert<ITodoAppTodouserSession.ISummary>(session);
    TestValidator.equals(
      "inactive session belongs to requested todoUser",
      session.todoUser.id,
      todoUserId,
    );
    TestValidator.predicate(
      "inactive session expired_at must be non-null",
      session.expired_at !== null && session.expired_at !== undefined,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodouserSession";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";
import type { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";

export async function test_api_todo_admin_sessions_time_range_filtering(
  connection: api.IConnection,
) {
  // 1) Register and authenticate a todoAdmin (admin context)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 2) Register a todoUser (this also creates an initial session)
  const userEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const userPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const userJoinBody = {
    email: userEmail,
    password: userPassword,
    display_name: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://app.todo-app.test/join",
    referrer: "https://app.todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const user: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(user);

  // 3) Create additional sessions for the todoUser by logging in multiple times
  const loginBody1 = {
    email: userEmail,
    password: userPassword,
    ip: "127.0.0.1",
    href: "https://app.todo-app.test/login1",
    referrer: "https://app.todo-app.test/home",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const login1: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: loginBody1,
    });
  typia.assert(login1);

  const loginBody2 = {
    email: userEmail,
    password: userPassword,
    ip: "127.0.0.2",
    href: "https://app.todo-app.test/login2",
    referrer: "https://app.todo-app.test/home",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const login2: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: loginBody2,
    });
  typia.assert(login2);

  // 4) Switch back to admin context by registering another admin (simplest way
  // to restore admin Authorization header using SDK behavior)
  const adminJoinBody2 = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.10",
    href: "https://admin.todo-app.test/join2",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin2: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody2,
    });
  typia.assert(admin2);

  // 5) Call sessions.index without filters to get baseline sessions list
  const baselineRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies ITodoAppTodouserSession.IRequest;

  const baseline: IPageITodoAppTodouserSession.ISummary =
    await api.functional.todoApp.todoAdmin.todoUsers.sessions.index(
      connection,
      {
        todoUserId: user.id,
        body: baselineRequestBody,
      },
    );
  typia.assert(baseline);

  // Basic sanity checks on pagination and ownership
  const baselinePagination: IPage.IPagination = baseline.pagination;
  const baselineData: ITodoAppTodouserSession.ISummary[] = baseline.data;

  TestValidator.predicate(
    "baseline sessions should contain at least 3 records",
    baselinePagination.records >= 3,
  );

  TestValidator.predicate(
    "baseline data length should not exceed limit",
    baselineData.length <= baselinePagination.limit,
  );
  TestValidator.predicate(
    "baseline data length should not exceed total records",
    baselineData.length <= baselinePagination.records,
  );

  for (const session of baselineData) {
    TestValidator.equals(
      "each session.todoUser.id must match queried todoUserId",
      session.todoUser.id,
      user.id,
    );
  }

  // 6) Identify a created_at value to use as a narrow filter window.
  // We will sort the in-memory baseline data by created_at ascending and pick
  // the middle session’s created_at.
  if (baselineData.length === 0) {
    // Defensive guard: although we expect >=3, do not fail the test with
    // runtime error; just return early.
    return;
  }

  const sortedByCreatedAt = [...baselineData].sort((a, b) => {
    if (a.created_at < b.created_at) return -1;
    if (a.created_at > b.created_at) return 1;
    return 0;
  });

  const middleIndex = Math.floor(sortedByCreatedAt.length / 2);
  const middleSession = sortedByCreatedAt[middleIndex];
  const targetCreatedAt = middleSession.created_at;

  // 7) Call sessions.index with createdFrom/createdTo filtering around
  // targetCreatedAt and explicit ordering by created_at desc.
  const filteredRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    createdFrom: targetCreatedAt,
    createdTo: targetCreatedAt,
    orderBy: "created_at" as const,
    orderDirection: "desc" as const,
  } satisfies ITodoAppTodouserSession.IRequest;

  const filtered: IPageITodoAppTodouserSession.ISummary =
    await api.functional.todoApp.todoAdmin.todoUsers.sessions.index(
      connection,
      {
        todoUserId: user.id,
        body: filteredRequestBody,
      },
    );
  typia.assert(filtered);

  const filteredPagination: IPage.IPagination = filtered.pagination;
  const filteredData: ITodoAppTodouserSession.ISummary[] = filtered.data;

  // All returned sessions must belong to the same todoUser and satisfy the
  // created_at time window.
  for (const session of filteredData) {
    TestValidator.equals(
      "filtered session.todoUser.id must match queried todoUserId",
      session.todoUser.id,
      user.id,
    );

    TestValidator.predicate(
      "filtered session.created_at must be >= createdFrom",
      session.created_at >= targetCreatedAt,
    );
    TestValidator.predicate(
      "filtered session.created_at must be <= createdTo",
      session.created_at <= targetCreatedAt,
    );
  }

  // When limit is sufficiently large and the filter is narrow, the number of
  // records should equal the data length on the first page. To satisfy
  // TestValidator.equals typing, use the plain number as the first argument.
  TestValidator.equals(
    "filtered pagination.records should equal filtered data length on first page",
    filteredData.length,
    filteredPagination.records,
  );

  // Validate descending order by created_at
  for (let i = 1; i < filteredData.length; ++i) {
    const prev = filteredData[i - 1];
    const curr = filteredData[i];
    TestValidator.predicate(
      "filtered sessions must be ordered by created_at desc",
      prev.created_at >= curr.created_at,
    );
  }

  // 8) Additional sanity check: pagination.pages consistency on baseline
  const expectedPages =
    baselinePagination.records === 0
      ? 0
      : Math.ceil(baselinePagination.records / baselinePagination.limit);

  TestValidator.equals(
    "baseline pagination.pages should match records/limit",
    expectedPages,
    baselinePagination.pages,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";

export async function test_api_todo_user_join_successful_registration(
  connection: api.IConnection,
) {
  // 1. Build a realistic registration payload for ITodoAppTodoUserJoin.IRequest
  const body = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(1),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  // 2. Call the public join endpoint without prior authentication
  const authorized = await api.functional.auth.todoUser.join(connection, {
    body,
  });

  // 3. Strong type assertion on the response structure
  typia.assert<ITodoAppTodoUser.IAuthorized>(authorized);

  // 4. Basic field-level business validations
  TestValidator.equals(
    "email echoes the registration request",
    authorized.email,
    body.email,
  );

  // displayName should reflect display_name when provided (non-null)
  if (body.display_name !== null && body.display_name !== undefined) {
    TestValidator.equals(
      "displayName matches display_name when provided",
      authorized.displayName ?? null,
      body.display_name,
    );
  }

  // status should be a non-empty string (scenario suggests "active" but DTO
  // doesn’t fix the allowed values, so we only assert non-empty)
  TestValidator.predicate(
    "status is initialized to a non-empty value",
    authorized.status.length > 0,
  );

  // created_at and updated_at must be valid date-time strings already ensured
  // by typia.assert, here we only check the ordering created_at <= updated_at
  const createdAt = new Date(authorized.created_at).getTime();
  const updatedAt = new Date(authorized.updated_at).getTime();
  TestValidator.predicate(
    "created_at is not after updated_at",
    createdAt <= updatedAt,
  );

  // last_login_at should be null on first registration according to scenario.
  // The DTO allows undefined, so we normalize with nullish coalescing.
  TestValidator.equals(
    "last_login_at is null on first registration",
    authorized.last_login_at ?? null,
    null,
  );

  // 5. Token structure and basic semantics
  typia.assert<IAuthorizationToken>(authorized.token);

  TestValidator.predicate(
    "access token is a non-empty string",
    authorized.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token is a non-empty string",
    authorized.token.refresh.length > 0,
  );

  const now = Date.now();
  const expiredAt = new Date(authorized.token.expired_at).getTime();
  const refreshableUntil = new Date(
    authorized.token.refreshable_until,
  ).getTime();

  TestValidator.predicate(
    "access token expiry is in the future",
    expiredAt > now,
  );
  TestValidator.predicate(
    "refresh token refreshable_until is in the future",
    refreshableUntil > now,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";

/**
 * Verify that todoUser self-registration rejects duplicate emails.
 *
 * Business rule:
 *
 * - /auth/todoUser/join must enforce uniqueness of
 *   ITodoAppTodoUserJoin.IRequest.email against the todo_app_todousers.email
 *   unique index.
 * - First registration with a fresh email should succeed and return a
 *   ITodoAppTodoUser.IAuthorized payload.
 * - A second registration attempt using the same email must fail with a
 *   business-level validation error (duplicate email), without creating any
 *   additional account and without exposing sensitive fields like
 *   password_hash.
 *
 * Scenario steps:
 *
 * 1. Build a valid registration payload `firstJoin` with a random email, a
 *    password string satisfying tags.Format<"password">, and realistic href and
 *    referrer URIs. Optionally include a display_name and ip.
 * 2. Call api.functional.auth.todoUser.join(connection, { body: firstJoin }) and
 *    assert that:
 *
 *    - The call succeeds without throwing.
 *    - The response conforms to ITodoAppTodoUser.IAuthorized (typia.assert).
 * 3. Build a second payload `secondJoin` that reuses the same email but may vary
 *    in display_name, href, referrer, or ip.
 * 4. Invoke api.functional.auth.todoUser.join again with `secondJoin` inside
 *    TestValidator.error, asserting that a runtime error is thrown (business
 *    rule violation for duplicate email). Do not inspect HTTP status codes or
 *    error messages, only that an error occurs.
 * 5. Optionally, perform a light sanity check that the first successful
 *    authorization payload remains structurally valid (typia.assert) and that
 *    token fields look non-empty, without attempting to validate any internal
 *    security details.
 */
export async function test_api_todo_user_join_duplicate_email_rejected(
  connection: api.IConnection,
) {
  // 1. Build first registration payload with unique email
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const firstJoin = {
    email,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: RandomGenerator.mobile(),
    href: "https://todo.example.com/signup" as string & tags.Format<"uri">,
    referrer: "https://todo.example.com/landing" as string & tags.Format<"uri">,
  } satisfies ITodoAppTodoUserJoin.IRequest;

  // 2. First join call must succeed and return authorized session
  const firstAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: firstJoin,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(firstAuthorized);

  // 3. Build second payload with the same email but different metadata
  const secondJoin = {
    email,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: RandomGenerator.mobile(),
    href: "https://todo.example.com/signup?step=2" as string &
      tags.Format<"uri">,
    referrer: "https://todo.example.com/campaign" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppTodoUserJoin.IRequest;

  // 4. Second join with duplicate email must fail with a business-level error
  await TestValidator.error(
    "duplicate email registration must be rejected",
    async () => {
      await api.functional.auth.todoUser.join(connection, {
        body: secondJoin,
      });
    },
  );

  // 5. Sanity check: first authorization payload still structurally valid and has non-empty tokens
  typia.assert<ITodoAppTodoUser.IAuthorized>(firstAuthorized);
  TestValidator.predicate(
    "access token should be non-empty",
    firstAuthorized.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be non-empty",
    firstAuthorized.token.refresh.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
