import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

export async function test_api_todouser_detail_requires_todoadmin_auth(
  connection: api.IConnection,
) {
  // 1. Create a real todoUser so we have a concrete todoUserId
  const todoUserJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: RandomGenerator.mobile(),
    href: "https://todo-app.example.com/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: todoUserJoinBody,
    });
  typia.assert(todoUserAuthorized);

  const createdTodoUserId = todoUserAuthorized.id;
  const createdTodoUserEmail = todoUserAuthorized.email;

  // 2. Prepare a todoAdmin account (join)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "AdminPassword123!",
    displayName: RandomGenerator.name(),
    ip: RandomGenerator.mobile(),
    href: "https://todo-app.example.com/admin/join",
    referrer: "https://todo-app.example.com/admin/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorizedFromJoin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 3. Create a Todo status to satisfy dependency intent
  const sortOrderValue = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1>
  >();

  const statusCreateBody = {
    code: `ACTIVE_${RandomGenerator.alphaNumeric(8)}`,
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: sortOrderValue,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(status);

  // 4. Create at least one Todo for the todoUser (mainly to exercise dependencies)
  // Switch to todoUser context explicitly via login (even though join already authenticated)
  const todoUserLoginBody = {
    email: todoUserAuthorized.email,
    password: todoUserJoinBody.password,
    ip: todoUserJoinBody.ip ?? undefined,
    href: todoUserJoinBody.href,
    referrer: todoUserJoinBody.referrer,
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const todoUserAuthorizedFromLogin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: todoUserLoginBody,
    });
  typia.assert(todoUserAuthorizedFromLogin);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date().toISOString(),
    status_code: status.code,
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo = await api.functional.todoApp.todoUser.todos.create(
    connection,
    {
      body: todoCreateBody,
    },
  );
  typia.assert(todo);

  // 5. Unauthenticated access attempt using a fresh connection without headers
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated todoAdmin access to todo user detail must fail",
    async () => {
      await api.functional.todoApp.todoAdmin.todoUsers.at(unauthConn, {
        todoUserId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 6. Authenticated admin access should succeed
  // Ensure we are authenticated as todoAdmin via login (exercise dependency)
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: adminJoinBody.ip ?? null,
    href: adminJoinBody.href,
    referrer: adminJoinBody.referrer,
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminAuthorizedFromLogin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  const fetchedTodoUser: ITodoAppTodoUser =
    await api.functional.todoApp.todoAdmin.todoUsers.at(connection, {
      todoUserId: createdTodoUserId,
    });
  typia.assert(fetchedTodoUser);

  // 7. Business assertions
  TestValidator.equals(
    "fetched todo user id should match created todo user id",
    fetchedTodoUser.id,
    createdTodoUserId,
  );

  TestValidator.equals(
    "fetched todo user email should match created todo user email",
    fetchedTodoUser.email,
    createdTodoUserEmail,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate that a todoAdmin can update mutable fields of a todo user.
 *
 * Business context:
 *
 * - TodoAdmin accounts are privileged operators who can manage todoUser accounts,
 *   including changing display names, emails, and account status.
 * - TodoUser accounts own Todo items and authenticate via their own auth
 *   endpoints.
 *
 * This test exercises a realistic multi-actor flow:
 *
 * 1. Admin registration and authentication lifecycle
 * 2. Todo status catalogue setup
 * 3. End-user registration and login
 * 4. Todo creation under the todoUser account
 * 5. Admin-driven update of the todoUser profile
 * 6. Validation that updated fields changed, immutable fields remain stable, and
 *    timestamps behave as expected.
 */
export async function test_api_todouser_update_by_todoadmin(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin via /auth/todoAdmin/join
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: RandomGenerator.alphaNumeric(8),
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorizedFromJoin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // Preserve original admin profile snapshot for later comparisons if needed
  const originalAdminId = adminAuthorizedFromJoin.id;

  // 2. As todoAdmin, create at least one Todo status
  const todoStatusCreateBody = {
    code: `ACTIVE_${RandomGenerator.alphaNumeric(6)}`,
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: todoStatusCreateBody,
    });
  typia.assert(createdStatus);

  // 3. Register a todoUser via /auth/todoUser/join
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: RandomGenerator.alphaNumeric(8),
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorizedFromJoin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userAuthorizedFromJoin);

  const todoUserId = userAuthorizedFromJoin.id;
  const originalUserEmail = userAuthorizedFromJoin.email;
  const originalUserDisplayName = userAuthorizedFromJoin.displayName ?? null;
  const originalUserStatus = userAuthorizedFromJoin.status;
  const originalUserCreatedAt = userAuthorizedFromJoin.created_at;
  const originalUserUpdatedAt = userAuthorizedFromJoin.updated_at;

  TestValidator.equals(
    "todoUser join should yield stable id",
    todoUserId,
    userAuthorizedFromJoin.id,
  );

  // 4. Explicit login as todoUser (even though join already authenticated)
  const userLoginBody = {
    email: userJoinBody.email,
    password: userJoinBody.password,
    ip: userJoinBody.ip ?? null,
    href: userJoinBody.href,
    referrer: userJoinBody.referrer,
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const userAuthorizedFromLogin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userLoginBody,
    });
  typia.assert(userAuthorizedFromLogin);

  TestValidator.equals(
    "todoUser id must remain same between join and login",
    userAuthorizedFromLogin.id,
    todoUserId,
  );

  // 5. As todoUser, create at least one Todo item
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date().toISOString(),
    status_code: createdStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo should use requested status code",
    createdTodo.status.code,
    createdStatus.code,
  );

  // 6. Switch context back to todoAdmin by logging in with admin credentials
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: adminJoinBody.ip ?? null,
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/dashboard",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminAuthorizedFromLogin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  TestValidator.equals(
    "todoAdmin id should remain same between join and login",
    adminAuthorizedFromLogin.id,
    originalAdminId,
  );

  // 7. As todoAdmin, update the todoUser using PUT /todoApp/todoAdmin/todoUsers/{todoUserId}
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newDisplayName = RandomGenerator.name();
  const newStatus = originalUserStatus === "active" ? "suspended" : "active";

  const updateBody = {
    email: newEmail,
    display_name: newDisplayName,
    status: newStatus,
  } satisfies ITodoAppTodoUser.IUpdate;

  const updatedUser: ITodoAppTodoUser =
    await api.functional.todoApp.todoAdmin.todoUsers.update(connection, {
      todoUserId,
      body: updateBody,
    });
  typia.assert(updatedUser);

  // 8. Validate updated fields and immutable fields
  TestValidator.equals(
    "updated user id should match target",
    updatedUser.id,
    todoUserId,
  );
  TestValidator.equals(
    "updated user email should reflect new email",
    updatedUser.email,
    newEmail,
  );
  TestValidator.equals(
    "updated user display_name should reflect new display name",
    updatedUser.display_name ?? null,
    newDisplayName,
  );
  TestValidator.equals(
    "updated user status should reflect new status",
    updatedUser.status,
    newStatus,
  );

  TestValidator.equals(
    "created_at must remain unchanged after update",
    updatedUser.created_at,
    originalUserCreatedAt,
  );

  TestValidator.predicate(
    "updated_at must be refreshed after update",
    updatedUser.updated_at !== originalUserUpdatedAt,
  );

  // 9. Perform a second partial update: change only status back, leaving email and display_name intact
  const revertedStatus = originalUserStatus;
  const partialUpdateBody = {
    status: revertedStatus,
  } satisfies ITodoAppTodoUser.IUpdate;

  const partiallyUpdatedUser: ITodoAppTodoUser =
    await api.functional.todoApp.todoAdmin.todoUsers.update(connection, {
      todoUserId,
      body: partialUpdateBody,
    });
  typia.assert(partiallyUpdatedUser);

  TestValidator.equals(
    "partial update should keep email unchanged",
    partiallyUpdatedUser.email,
    updatedUser.email,
  );
  TestValidator.equals(
    "partial update should keep display_name unchanged",
    partiallyUpdatedUser.display_name ?? null,
    updatedUser.display_name ?? null,
  );
  TestValidator.equals(
    "partial update should reflect reverted status",
    partiallyUpdatedUser.status,
    revertedStatus,
  );

  TestValidator.predicate(
    "second update should advance updated_at further",
    partiallyUpdatedUser.updated_at !== updatedUser.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate that admin todoUser update enforces email uniqueness and rejects
 * attempts to change a user’s email to another user’s existing email.
 *
 * Business context:
 *
 * - Todo_app_todousers.email is globally unique.
 * - Admins manage todo users via /todoApp/todoAdmin/todoUsers/{todoUserId}.
 * - When updating email, the service must enforce uniqueness and reject conflicts
 *   without mutating the account.
 *
 * Scenario steps:
 *
 * 1. Register a todoAdmin via /auth/todoAdmin/join and obtain an authorized admin
 *    session.
 * 2. As the admin, create at least one Todo status via POST
 *    /todoApp/todoAdmin/todoStatuses for realistic catalog setup.
 * 3. Register two distinct todoUser accounts (userA and userB) via
 *    /auth/todoUser/join, capturing their ids and emails.
 * 4. For each user, while authenticated as that user, create at least one Todo via
 *    POST /todoApp/todoUser/todos to ensure they have associated business
 *    data.
 * 5. Re-authenticate as the todoAdmin via /auth/todoAdmin/login to ensure admin
 *    context.
 * 6. Attempt to update userB’s email via PUT
 *    /todoApp/todoAdmin/todoUsers/{todoUserId}, setting body.email to userA’s
 *    existing email. This should violate the unique constraint.
 * 7. Assert that the update call fails with an HTTP error using
 *    TestValidator.error, without checking specific status codes.
 * 8. Assert precondition that userA and userB had different emails so the
 *    attempted update truly collides with another user’s email.
 */
export async function test_api_todouser_update_email_uniqueness_violation(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin via /auth/todoAdmin/join
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string = "Admin!234";

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    displayName: RandomGenerator.name(2),
    ip: null,
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As admin, create at least one Todo status
  const statusCodeBase: string = RandomGenerator.alphabets(6).toUpperCase();
  const statusCreateBody = {
    code: `ACTIVE_${statusCodeBase}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(status);

  // 3. Register two distinct todoUser accounts
  // 3-1. userA join
  const userAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const userAPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const userAJoinBody = {
