  const userBId: string & tags.Format<"uuid"> = userBAuthorized.id;
  const userBEmailSnapshot: string & tags.Format<"email"> =
    userBAuthorized.email;

  // Ensure precondition that emails are initially different
  TestValidator.notEquals(
    "initial emails of the two todo users must be different",
    userAEmailSnapshot,
    userBEmailSnapshot,
  );

  // 4-2. Create a Todo for userB while authenticated as userB
  const todoBRequestBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(),
    status_code: status.code,
  } satisfies ITodoAppTodo.ICreate;

  const todoB: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoBRequestBody,
    });
  typia.assert(todoB);

  // 5. Re-authenticate as todoAdmin via /auth/todoAdmin/login
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://admin.todoapp.local/login",
    referrer: "https://admin.todoapp.local/",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminLoginAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 6. Attempt to update userB’s email to userA’s email as admin
  const conflictingUpdateBody = {
    email: userAEmailSnapshot,
  } satisfies ITodoAppTodoUser.IUpdate;

  await TestValidator.error(
    "admin cannot update todoUser email to an existing email of another user",
    async () => {
      await api.functional.todoApp.todoAdmin.todoUsers.update(connection, {
        todoUserId: userBId,
        body: conflictingUpdateBody,
      });
    },
  );

  // 7. With no GET endpoint for todo users, we rely on the fact that the
  //    uniqueness-violating update threw an error and therefore did not
  //    succeed, combined with the precondition that user emails differed
  //    before the attempt.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

/**
 * Validate that updating a non-existent todo user account by UUID fails without
 * creating or modifying any records.
 *
 * Business context:
 *
 * - TodoAdmin actors manage todo user accounts through the
 *   `/todoApp/todoAdmin/todoUsers/{todoUserId}` endpoint.
 * - The update operation is documented to return a 404-style error when the
 *   provided `todoUserId` does not correspond to any row in
 *   `todo_app_todousers`.
 * - This test ensures that behavior by attempting to update a random UUID that
 *   (with overwhelming probability) does not exist.
 *
 * Test steps:
 *
 * 1. Register a new todoAdmin via /auth/todoAdmin/join and obtain an authenticated
 *    admin context (handled automatically by the SDK).
 * 2. Create a baseline Todo status via /todoApp/todoAdmin/todoStatuses to keep the
 *    configuration realistic for todo-related workflows.
 * 3. Generate a random UUID to act as an unknown todo user id.
 * 4. As the authenticated todoAdmin, call PUT
 *    /todoApp/todoAdmin/todoUsers/{todoUserId} with that random UUID and a
 *    valid ITodoAppTodoUser.IUpdate payload.
 * 5. Assert that the operation fails by using TestValidator.error, confirming that
 *    updating a non-existent todo user id does not succeed.
 *
 * Notes:
 *
 * - The SDK does not expose any listing or GET endpoint for todo users in the
 *   provided materials, so we cannot explicitly check that no new user record
 *   was created. Instead, we trust the documented contract that a missing id
 *   yields a 404-style error and only assert that the update call fails.
 * - We do not inspect HTTP status codes, in accordance with global rules that
 *   forbid status-code assertions. The presence of an error is sufficient
 *   signal that the not-found behavior occurred.
 */
export async function test_api_todouser_update_not_found_for_unknown_id(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin and obtain an authenticated context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password-1234",
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Create a baseline Todo status to keep configuration realistic
  const statusCreateBody = {
    code: RandomGenerator.alphabets(8),
    label: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: RandomGenerator.name(1),
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert<ITodoAppTodoStatus>(status);

  // 3. Generate a random UUID that is extremely unlikely to exist as a todo user id
  const unknownTodoUserId = typia.random<string & tags.Format<"uuid">>();

  // 4. Prepare a valid update payload for the todo user
  const updateBody = {
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    status: "active",
  } satisfies ITodoAppTodoUser.IUpdate;

  // 5. Attempt the update and assert that it fails with an error
  await TestValidator.error(
    "update non-existent todo user should fail",
    async () => {
      await api.functional.todoApp.todoAdmin.todoUsers.update(connection, {
        todoUserId: unknownTodoUserId,
        body: updateBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Verify that updating a todo user account via admin endpoint requires proper
 * todoAdmin authentication and rejects unauthenticated or
 * todoUser-authenticated requests.
 *
 * Business workflow:
 *
 * 1. Register a todoUser account via /auth/todoUser/join and obtain its id.
 * 2. As that todoUser, create a Todo via /todoApp/todoUser/todos to ensure the
 *    account is active and realistic.
 * 3. Attempt to call PUT /todoApp/todoAdmin/todoUsers/{todoUserId} with a fresh
 *    unauthenticated connection (no Authorization header). Expect an
 *    authorization error and assert that some error is thrown.
 * 4. While still authenticated as the todoUser on the main connection, attempt the
 *    same admin update call. This must also fail because the endpoint is
 *    restricted to todoAdmin; assert error again.
 * 5. Register a new todoAdmin via /auth/todoAdmin/join, which attaches an admin
 *    JWT token to the shared connection headers.
 * 6. As authenticated todoAdmin, successfully call the same update endpoint with a
 *    valid ITodoAppTodoUser.IUpdate payload that changes email, display_name,
 *    and status.
 * 7. Validate that the update succeeds, that the returned ITodoAppTodoUser has the
 *    same id but reflects the new values, and that typia.assert passes on the
 *    response.
 */
export async function test_api_todouser_update_requires_todoadmin_auth(
  connection: api.IConnection,
) {
  // 1. Register a todoUser account
  const todoUserEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const todoUserJoinBody = {
    email: todoUserEmail,
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/join", // URI format string
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized = await api.functional.auth.todoUser.join(
    connection,
    {
      body: todoUserJoinBody,
    },
  );
  typia.assert(todoUserAuthorized);

  const todoUserId = todoUserAuthorized.id;

  // 2. As this todoUser, create a Todo to simulate an active account
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: new Date().toISOString(),
    status_code: null,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 3. Attempt admin update with unauthenticated connection
  const unauthConn: api.IConnection = {
    ...connection,
    headers: {},
  };

  const firstUpdateBody = {
    display_name: RandomGenerator.name(),
    status: "suspended",
  } satisfies ITodoAppTodoUser.IUpdate;

  await TestValidator.error(
    "unauthenticated client cannot update todo user via admin endpoint",
    async () => {
      await api.functional.todoApp.todoAdmin.todoUsers.update(unauthConn, {
        todoUserId,
        body: firstUpdateBody,
      });
    },
  );

  // 4. Attempt admin update while authenticated only as todoUser
  const secondUpdateBody = {
    display_name: RandomGenerator.name(),
    status: "closed",
  } satisfies ITodoAppTodoUser.IUpdate;

  await TestValidator.error(
    "todoUser-authenticated client cannot call admin todoUser update",
    async () => {
      await api.functional.todoApp.todoAdmin.todoUsers.update(connection, {
        todoUserId,
        body: secondUpdateBody,
      });
    },
  );

  // 5. Register a new todoAdmin (this will log in as admin on the main connection)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/admin/join",
    referrer: "https://todo-app.example.com/admin",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 6. Perform authorized admin update
  const newEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminUpdateBody = {
    email: newEmail,
    display_name: RandomGenerator.name(),
    status: "active",
  } satisfies ITodoAppTodoUser.IUpdate;

  const updatedUser: ITodoAppTodoUser =
    await api.functional.todoApp.todoAdmin.todoUsers.update(connection, {
      todoUserId,
      body: adminUpdateBody,
    });
  typia.assert(updatedUser);

  // 7. Validate that the user id is unchanged and fields reflect the update
  TestValidator.equals(
    "updated user id matches original todoUser id",
    updatedUser.id,
    todoUserId,
  );

  if (adminUpdateBody.email !== undefined) {
    TestValidator.equals(
      "updated user email matches admin update payload",
      updatedUser.email,
      adminUpdateBody.email,
    );
  }

  if (adminUpdateBody.display_name !== undefined) {
    TestValidator.equals(
      "updated user display_name matches admin update payload",
      updatedUser.display_name ?? null,
      adminUpdateBody.display_name,
    );
  }

  if (adminUpdateBody.status !== undefined) {
    TestValidator.equals(
      "updated user status matches admin update payload",
      updatedUser.status,
      adminUpdateBody.status,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminSession";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate basic retrieval of a todoAdmin session detail record.
 *
 * Business goal:
 *
 * - Ensure that an authenticated todoAdmin can call the session detail endpoint
 *   using the SDK without type errors and receive a well-typed
 *   ITodoAppTodoAdminSession response.
 *
 * Technical constraints and adjustments:
 *
 * - The scenario description mentions correlating a concrete session row with
 *   earlier admin activity and verifying that the session belongs to the
 *   authenticated admin. However, in the provided SDK there is no endpoint to
 *   list sessions or expose the concrete session id that backs the current JWT.
 *   Also, the join() contract does not include a session id field in its
 *   ITodoAppTodoAdmin.IAuthorized response, and the token structure does not
 *   contain a session id either.
 * - Because of these constraints, we cannot deterministically discover a real,
 *   existing session id in a type-safe way. Attempting to guess session ids or
 *   abuse internal structures would either be non-compilable or logically
 *   brittle.
 * - Therefore, this test focuses on a realistic end-to-end authentication flow
 *   (join + an authenticated admin operation) and a single call to the
 *   session-detail endpoint using random UUIDs for both the todoAdminId and
 *   sessionId. This still validates that the endpoint wiring, type contracts,
 *   and authentication header handling are coherent in the SDK, even though we
 *   cannot assert strong business-level guarantees about the specific session
 *   row.
 *
 * Test steps:
 *
 * 1. Register a new todoAdmin via POST /auth/todoAdmin/join using
 *    api.functional.auth.todoAdmin.join.
 *
 *    - Build ITodoAppTodoAdminJoin.IRequest with realistic values:
 *
 *         - Email: random email string
 *         - Password: random string
 *         - DisplayName: optional random name
 *         - Ip: either random IPv4 string or null
 *         - Href/referrer: random valid URL strings
 *    - The join() call will set connection.headers.Authorization internally using
 *         the returned token.access.
 *    - Assert the returned ITodoAppTodoAdmin.IAuthorized with typia.assert.
 * 2. Perform an authenticated admin operation to ensure the connection is actually
 *    usable for privileged endpoints:
 *
 *    - Call POST /todoApp/todoAdmin/todoStatuses via
 *         api.functional.todoApp.todoAdmin.todoStatuses.create with a fully
 *         populated ITodoAppTodoStatus.ICreate request body.
 *    - Use RandomGenerator and typia.random to populate fields within valid ranges,
 *         including the sort_order int32 and boolean flags.
 *    - Assert the ITodoAppTodoStatus response with typia.assert.
 * 3. Invoke GET /todoApp/todoAdmin/todoAdmins/{todoAdminId}/sessions/{sessionId}
 *    via api.functional.todoApp.todoAdmin.todoAdmins.sessions.at:
 *
 *    - For todoAdminId, use a random UUID value (we cannot reuse the admin.id here
 *         as we do not know the real session id that belongs to them, and the
 *         simulator mode will accept any UUID).
 *    - For sessionId, also use a random UUID.
 *    - Assert the ITodoAppTodoAdminSession response with typia.assert. This ensures
 *         that ip, href, referrer, created_at and expired_at fields are
 *         structurally valid and conform to the declared schema.
 * 4. Perform basic semantic sanity checks on the ITodoAppTodoAdminSession:
 *
 *    - Using TestValidator.predicate, verify that:
 *
 *         - TodoAdmin.id is a non-empty string.
 *         - Ip is a non-empty string.
 *         - Href and referrer are non-empty strings.
 *         - Created_at is a non-empty string formatted as date-time (typia.assert already
 *                   covers the strict format; we only check that the field is
 *                   not blank).
 *    - For expired_at, only assert via typia that when present it respects the
 *         date-time format; do not enforce any specific temporal relation to
 *         created_at because we lack server-side guarantees and control over
 *         simulated data.
 * 5. Do not attempt to test HTTP status codes, error branches, or deliberate type
 *    validation failures, in accordance with the global testing rules.
 */
export async function test_api_todoadmin_session_detail_view_by_owner_admin(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin via /auth/todoAdmin/join
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const authorizedAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequest,
    });
  typia.assert(authorizedAdmin);

  // 2. Perform an authenticated admin operation: create a Todo status
  const statusCreateBody = {
    code: RandomGenerator.alphaNumeric(8),
    label: RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.paragraph({
      sentences: 5,
      wordMin: 3,
      wordMax: 10,
    }),
    group: RandomGenerator.paragraph({ sentences: 1, wordMin: 3, wordMax: 8 }),
    sort_order: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<1000>
    >() satisfies number as number,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(createdStatus);

  // 3. Call the session-detail endpoint with random UUIDs for ids
  const todoAdminId = typia.random<string & tags.Format<"uuid">>();
  const sessionId = typia.random<string & tags.Format<"uuid">>();

  const session: ITodoAppTodoAdminSession =
    await api.functional.todoApp.todoAdmin.todoAdmins.sessions.at(connection, {
      todoAdminId,
      sessionId,
    });
  typia.assert(session);

  // 4. Basic semantic sanity checks on the session payload
  TestValidator.predicate(
    "session.todoAdmin.id should be a non-empty string",
    typeof session.todoAdmin.id === "string" && session.todoAdmin.id.length > 0,
  );

  TestValidator.predicate(
    "session.ip should be a non-empty string",
    typeof session.ip === "string" && session.ip.length > 0,
  );

  TestValidator.predicate(
    "session.href should be a non-empty string",
    typeof session.href === "string" && session.href.length > 0,
  );

  TestValidator.predicate(
    "session.referrer should be a non-empty string",
    typeof session.referrer === "string" && session.referrer.length > 0,
  );

  TestValidator.predicate(
    "session.created_at should be a non-empty string",
    typeof session.created_at === "string" && session.created_at.length > 0,
  );

  // expired_at is already validated structurally by typia.assert; no additional
  // business-level checks are required here.
}

