import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";

/**
 * Validate pagination behavior of unified actor session search for todoAdmin.
 *
 * 1. Create multiple todoAdmin accounts using /auth/todoAdmin/join to ensure
 *    multiple admin sessions exist in the system.
 * 2. As an admin, call PATCH /todoApp/todoAdmin/actors/sessions with a small limit
 *    (e.g., 2) and page=1, filtered to actor_type="admin".
 * 3. Assert that pagination metadata (limit, records, pages, current) is
 *    consistent with expectations and that the returned data length respects
 *    the limit and is non-zero.
 * 4. Call the same endpoint again with page=2 and the same limit and filters.
 * 5. When at least two pages exist, confirm that the second page has a different
 *    slice of session IDs than the first page and that actorType is
 *    consistently "admin" across records.
 */
export async function test_api_actor_sessions_pagination_behavior(
  connection: api.IConnection,
) {
  // 1. Create multiple todoAdmin accounts to ensure multiple admin sessions
  const adminJoinCount = 5;
  for (let i = 0; i < adminJoinCount; i++) {
    const joinBody = {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      displayName: RandomGenerator.name(),
      ip: "127.0.0.1",
      href: "https://admin.todo.example.com/register",
      referrer: "https://todo.example.com/landing",
    } satisfies ITodoAppTodoAdminJoin.IRequest;

    const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
      await api.functional.auth.todoAdmin.join(connection, {
        body: joinBody,
      });
    typia.assert(adminAuthorized);
  }

  // 2. Query actor sessions page 1 with small limit for admin sessions only
  const limit = 2 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const page1Request = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit,
    actor_type: "admin",
  } satisfies ITodoAppActorSession.IRequest;

  const page1: IPageITodoAppActorSession.ISummary =
    await api.functional.todoApp.todoAdmin.actors.sessions.index(connection, {
      body: page1Request,
    });
  typia.assert(page1);

  const pagination1 = page1.pagination;
  const data1 = page1.data;

  // 3. Validate pagination metadata for page 1
  TestValidator.equals(
    "page1 limit matches requested limit",
    pagination1.limit,
    limit,
  );

  TestValidator.predicate(
    "page1 records count covers returned data length",
    pagination1.records >= data1.length,
  );

  TestValidator.predicate(
    "page1 data length is positive and within limit",
    data1.length > 0 && data1.length <= pagination1.limit,
  );

  TestValidator.predicate(
    "page1 pages is non-negative",
    pagination1.pages >= 0,
  );

  // current is zero-based index; requesting page=1 should give current=0
  TestValidator.equals(
    "page1 current index is zero-based for first page",
    pagination1.current,
    0,
  );

  // Actor type consistency for page 1
  for (const session of data1) {
    TestValidator.equals(
      "page1 session actorType should be admin",
      session.actorType,
      "admin",
    );
  }

  // 4. Query actor sessions page 2 with the same limit and filter
  const page2Request = {
    page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit,
    actor_type: "admin",
  } satisfies ITodoAppActorSession.IRequest;

  const page2: IPageITodoAppActorSession.ISummary =
    await api.functional.todoApp.todoAdmin.actors.sessions.index(connection, {
      body: page2Request,
    });
  typia.assert(page2);

  const pagination2 = page2.pagination;
  const data2 = page2.data;

  TestValidator.equals(
    "page2 limit matches requested limit",
    pagination2.limit,
    limit,
  );

  TestValidator.predicate(
    "page2 records count covers returned data length",
    pagination2.records >= data2.length,
  );

  TestValidator.predicate(
    "page2 pages is non-negative",
    pagination2.pages >= 0,
  );

  // If there are at least 2 pages, current for page=2 should be 1
  if (pagination2.pages >= 2) {
    TestValidator.equals(
      "page2 current index is one for second page",
      pagination2.current,
      1,
    );
  }

  TestValidator.predicate(
    "page2 data length is within limit (may be zero on last page)",
    data2.length <= pagination2.limit,
  );

  // Actor type consistency for page 2
  for (const session of data2) {
    TestValidator.equals(
      "page2 session actorType should be admin",
      session.actorType,
      "admin",
    );
  }

  // 5. Compare slices when there are at least two pages and enough records
  if (pagination1.pages >= 2 && pagination1.records > limit) {
    const ids1 = data1.map((s) => s.id);
    const ids2 = data2.map((s) => s.id);

    // Ensure the page slices are not identical
    TestValidator.notEquals(
      "page1 and page2 ID lists should not be identical",
      ids1,
      ids2,
    );

    // Ensure there is at least one ID that differs between the two pages
    const hasDifference =
      ids1.some((id) => !ids2.includes(id)) ||
      ids2.some((id) => !ids1.includes(id));

    TestValidator.predicate(
      "page1 and page2 have at least one differing session ID",
      hasDifference,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate that a todoAdmin can create and then update a system configuration
 * entry identified by (scope, key), while immutable identity fields stay stable
 * and audit timestamps behave correctly.
 *
 * Business workflow:
 *
 * 1. Register a new todoAdmin via /auth/todoAdmin/join to obtain an authenticated
 *    admin context.
 * 2. Create an initial system configuration row via POST
 *    /todoApp/todoAdmin/systemConfigs using ITodoAppSystemConfig.ICreate.
 * 3. Update that configuration via PUT
 *    /todoApp/todoAdmin/systemConfigs/{scope}/{configKey} using
 *    ITodoAppSystemConfig.IUpdate to change value, description, and is_active.
 * 4. Assert that id/scope/key/created_at remain stable, value/description/
 *    is_active reflect the update, updated_at is refreshed, and deleted_at is
 *    not set.
 */
export async function test_api_system_config_update_basic_flow(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin and obtain authorized context
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequest,
    });
  typia.assert(adminAuthorized);

  // 2. Create initial system configuration
  const scope = "todo";
  const key = "deletion_model";

  const createBody = {
    scope,
    key,
    value: "soft",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  const createdConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: createBody,
    });
  typia.assert(createdConfig);

  // Basic invariants on created config
  TestValidator.equals(
    "created config scope should match request",
    createdConfig.scope,
    scope,
  );
  TestValidator.equals(
    "created config key should match request",
    createdConfig.key,
    key,
  );
  TestValidator.equals(
    "created config value should match request",
    createdConfig.value,
    createBody.value,
  );
  TestValidator.predicate(
    "created_at should be a non-empty ISO string",
    createdConfig.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at should be a non-empty ISO string",
    createdConfig.updated_at.length > 0,
  );

  // 3. Update the configuration via PUT with changed value/description/is_active
  const updatedValue = "hard";
  const updatedDescription = RandomGenerator.paragraph({ sentences: 4 });
  const updatedIsActive = !createdConfig.is_active;

  const updateBody = {
    value: updatedValue,
    description: updatedDescription,
    is_active: updatedIsActive,
  } satisfies ITodoAppSystemConfig.IUpdate;

  const updatedConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.update(connection, {
      scope,
      configKey: key,
      body: updateBody,
    });
  typia.assert(updatedConfig);

  // 4. Business assertions on update result
  // Identity invariants
  TestValidator.equals(
    "id should remain unchanged after update",
    updatedConfig.id,
    createdConfig.id,
  );
  TestValidator.equals(
    "scope should remain unchanged after update",
    updatedConfig.scope,
    createdConfig.scope,
  );
  TestValidator.equals(
    "key should remain unchanged after update",
    updatedConfig.key,
    createdConfig.key,
  );

  // Mutated fields should reflect new values
  TestValidator.equals(
    "value should reflect updated configuration",
    updatedConfig.value,
    updatedValue,
  );
  TestValidator.equals(
    "description should reflect updated configuration",
    updatedConfig.description,
    updatedDescription,
  );
  TestValidator.equals(
    "is_active should reflect updated configuration",
    updatedConfig.is_active,
    updatedIsActive,
  );

  // Audit timestamps
  TestValidator.equals(
    "created_at must remain unchanged after update",
    updatedConfig.created_at,
    createdConfig.created_at,
  );
  TestValidator.notEquals(
    "updated_at must change after update",
    updatedConfig.updated_at,
    createdConfig.updated_at,
  );

  // deleted_at should remain null/undefined (not soft-deleted)
  TestValidator.equals(
    "deleted_at should remain null or undefined after normal update",
    updatedConfig.deleted_at ?? null,
    createdConfig.deleted_at ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

export async function test_api_system_config_update_inactive_toggle(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin and obtain authorized context
  const joinBody = {
    email: `admin+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "P@ssw0rd!",
    displayName: RandomGenerator.name(2),
    ip: null,
    href: "https://admin.todoapp.example.com/settings/system-configs",
    referrer: "https://admin.todoapp.example.com/login",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create an active system configuration entry
  const scope = "todo";
  const key = `deletion_model_${RandomGenerator.alphaNumeric(6)}`;

  const createBody = {
    scope,
    key,
    value: "soft_delete",
    description: "Soft deletion model for todos (initial active config)",
    // is_active omitted so that backend defaults it, expected to true
  } satisfies ITodoAppSystemConfig.ICreate;

  const created: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  // Basic invariants on created config
  TestValidator.equals(
    "created config scope matches request",
    created.scope,
    scope,
  );
  TestValidator.equals("created config key matches request", created.key, key);
  TestValidator.equals(
    "created config value matches request",
    created.value,
    createBody.value,
  );

  // is_active should be truthy/true for a newly created active config
  TestValidator.predicate(
    "created config is initially active",
    created.is_active === true,
  );

  // Ensure not soft-deleted at creation time
  TestValidator.predicate(
    "created config is not soft-deleted (deleted_at null or undefined)",
    created.deleted_at === null || created.deleted_at === undefined,
  );

  const originalUpdatedAt = created.updated_at;
  const originalCreatedAt = created.created_at;

  // 3. Update the config to set is_active=false while keeping value the same
  const updateBody = {
    value: created.value,
    description: "Soft deletion model (temporarily disabled by admin)",
    is_active: false,
  } satisfies ITodoAppSystemConfig.IUpdate;

  const updated: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.update(connection, {
      scope: created.scope,
      configKey: created.key,
      body: updateBody,
    });
  typia.assert(updated);

  // 4. Assertions on the updated configuration state
  TestValidator.equals(
    "updated config id remains unchanged",
    updated.id,
    created.id,
  );
  TestValidator.equals(
    "updated config scope remains unchanged",
    updated.scope,
    created.scope,
  );
  TestValidator.equals(
    "updated config key remains unchanged",
    updated.key,
    created.key,
  );
  TestValidator.equals(
    "updated config value remains unchanged",
    updated.value,
    created.value,
  );

  // is_active should now be false
  TestValidator.equals(
    "updated config is now inactive",
    updated.is_active,
    false,
  );

  // deleted_at should still represent not-deleted
  TestValidator.predicate(
    "updated config is still not soft-deleted (deleted_at null or undefined)",
    updated.deleted_at === null || updated.deleted_at === undefined,
  );

  // created_at should not change
  TestValidator.equals(
    "created_at remains the same after update",
    updated.created_at,
    originalCreatedAt,
  );

  // updated_at should advance
  TestValidator.notEquals(
    "updated_at should change after update",
    updated.updated_at,
    originalUpdatedAt,
  );
}

