import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate that an authenticated todoAdmin can create a new system
 * configuration entry.
 *
 * Business context:
 *
 * - System configurations are managed by administrative operators (todoAdmin).
 * - Creation is restricted to authenticated admins; the SDK handles token wiring
 *   when we call the join endpoint on the same connection.
 * - The goal is to verify that the POST /todoApp/todoAdmin/systemConfigs endpoint
 *   accepts a well-formed ITodoAppSystemConfig.ICreate payload and returns a
 *   persisted ITodoAppSystemConfig that reflects our input while populating
 *   server-managed fields.
 *
 * Scenario steps:
 *
 * 1. Register a fresh todoAdmin using /auth/todoAdmin/join with a realistic
 *    ITodoAppTodoAdminJoin.IRequest body.
 *
 *    - Use typia.random to generate a syntactically valid email and URIs.
 *    - Optionally set a displayName; omit ip so the backend can infer it.
 *    - After this call, the SDK sets connection.headers.Authorization for us.
 * 2. Build a concrete ITodoAppSystemConfig.ICreate payload.
 *
 *    - Scope: "todo" (as per examples in the DTO docs)
 *    - Key: "deletion_model"
 *    - Value: "soft_delete"
 *    - Description: human-readable explanation string
 *    - Is_active: true (explicitly, avoiding reliance on defaults)
 * 3. Call api.functional.todoApp.todoAdmin.systemConfigs.create with the
 *    constructed body.
 * 4. Validate the result:
 *
 *    - First, run typia.assert(createdConfig) to ensure the shape is exactly
 *         ITodoAppSystemConfig.
 *    - Then, use TestValidator.equals to assert business expectations:
 *
 *         - CreatedConfig.scope equals the requested scope.
 *         - CreatedConfig.key equals the requested key.
 *         - CreatedConfig.value equals the requested value.
 *         - CreatedConfig.description equals the requested description.
 *         - CreatedConfig.is_active equals true.
 *    - Additionally, confirm server-managed fields behave logically:
 *
 *         - CreatedConfig.id is non-empty (UUID validity is already covered by
 *                   typia.assert, so we do not re-check format).
 *         - CreatedConfig.created_at and createdConfig.updated_at are non-empty strings.
 *         - CreatedConfig.deleted_at is null or undefined (indicating not soft-deleted).
 */
export async function test_api_system_config_creation_by_todoadmin(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin; SDK will wire Authorization on the same connection.
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin = await api.functional.auth.todoAdmin.join(connection, {
    body: joinRequest,
  });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Build the system config creation payload.
  const createConfigBody = {
    scope: "todo",
    key: "deletion_model",
    value: "soft_delete",
    description: RandomGenerator.paragraph({
      sentences: 5,
      wordMin: 3,
      wordMax: 10,
    }),
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  // 3. Call the systemConfigs.create endpoint as the authenticated admin.
  const createdConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: createConfigBody,
    });
  typia.assert<ITodoAppSystemConfig>(createdConfig);

  // 4. Business-level validations: input vs. output mapping and lifecycle fields.
  TestValidator.equals(
    "system config scope should match input",
    createdConfig.scope,
    createConfigBody.scope,
  );
  TestValidator.equals(
    "system config key should match input",
    createdConfig.key,
    createConfigBody.key,
  );
  TestValidator.equals(
    "system config value should match input",
    createdConfig.value,
    createConfigBody.value,
  );
  TestValidator.equals(
    "system config description should match input",
    createdConfig.description,
    createConfigBody.description,
  );
  TestValidator.equals(
    "system config is_active should match input",
    createdConfig.is_active,
    createConfigBody.is_active,
  );

  // Server-managed fields: basic logical checks without re-validating types/formats.
  TestValidator.predicate(
    "system config id should be a non-empty string",
    createdConfig.id.length > 0,
  );
  TestValidator.predicate(
    "system config created_at should be a non-empty string",
    createdConfig.created_at.length > 0,
  );
  TestValidator.predicate(
    "system config updated_at should be a non-empty string",
    createdConfig.updated_at.length > 0,
  );
  TestValidator.predicate(
    "system config deleted_at should be null or undefined on creation",
    createdConfig.deleted_at === null || createdConfig.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Verify that creating a todoApp system configuration enforces uniqueness on
 * the (scope, key) pair and rejects duplicates while keeping the original
 * record intact.
 *
 * Business flow:
 *
 * 1. Register a new todoAdmin using /auth/todoAdmin/join to obtain authenticated
 *    administrative context (JWT is managed automatically by the SDK via
 *    connection headers).
 * 2. Using that admin context, create a new system configuration via POST
 *    /todoApp/todoAdmin/systemConfigs with a fixed (scope, key).
 * 3. Attempt to create another configuration with the same (scope, key) but a
 *    different value/description and verify that the second request fails
 *    (duplicate unique index violation on (scope, key)).
 * 4. Optionally, create a third configuration with the same scope but a different
 *    key to confirm that non-conflicting entries are still accepted.
 *
 * Validations:
 *
 * - The join endpoint returns a valid ITodoAppTodoAdmin.IAuthorized object.
 * - The first systemConfigs.create call succeeds and returns an
 *   ITodoAppSystemConfig whose scope/key match the request body.
 * - The second systemConfigs.create call with the same (scope, key) results in an
 *   error observable via TestValidator.error, demonstrating uniqueness
 *   enforcement without inspecting specific HTTP status codes.
 * - The optional third create call with a new key succeeds normally and returns a
 *   configuration whose scope/key match the new request.
 */
export async function test_api_system_config_creation_enforces_unique_scope_and_key(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin via /auth/todoAdmin/join
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd!",
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin = await api.functional.auth.todoAdmin.join(connection, {
    body: joinBody,
  });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Create initial system config with fixed (scope, key)
  const scope = "auth";
  const key = "max_login_attempts";

  const createBody1 = {
    scope,
    key,
    value: "5",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  const config1 = await api.functional.todoApp.todoAdmin.systemConfigs.create(
    connection,
    { body: createBody1 },
  );
  typia.assert<ITodoAppSystemConfig>(config1);

  TestValidator.equals(
    "created config1 scope matches request",
    config1.scope,
    scope,
  );
  TestValidator.equals("created config1 key matches request", config1.key, key);

  // 3. Attempt duplicate creation with same (scope, key) but different value/description
  const createBodyDuplicate = {
    scope,
    key,
    value: "10", // different value to prove we are not overwriting silently
    description: RandomGenerator.paragraph({ sentences: 2 }),
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  await TestValidator.error(
    "duplicate system config create with same (scope, key) must fail",
    async () => {
      await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
        body: createBodyDuplicate,
      });
    },
  );

  // 4. Sanity check: create non-conflicting configuration with different key
  const otherKey = "max_login_attempts_per_ip";

  const createBody2 = {
    scope,
    key: otherKey,
    value: "3",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  const config2 = await api.functional.todoApp.todoAdmin.systemConfigs.create(
    connection,
    { body: createBody2 },
  );
  typia.assert<ITodoAppSystemConfig>(config2);

  TestValidator.equals(
    "created config2 scope matches request",
    config2.scope,
    scope,
  );
  TestValidator.equals(
    "created config2 key matches request",
    config2.key,
    otherKey,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate creation of system configurations with and without optional fields.
 *
 * Business goal: Ensure that the TodoApp system configuration creation endpoint
 * correctly applies defaults for optional fields when omitted, and faithfully
 * persists explicit values when they are provided. This protects configuration
 * behavior such as feature flags and global settings where omission of an
 * option should not unintentionally disable or enable features.
 *
 * End-to-end flow:
 *
 * 1. Register a new todoAdmin via /auth/todoAdmin/join to obtain an authenticated
 *    administrative context. The SDK will automatically attach the access token
 *    to the shared connection.
 * 2. Using that authenticated connection, call
 *    api.functional.todoApp.todoAdmin.systemConfigs.create with a minimal
 *    ITodoAppSystemConfig.ICreate payload containing only the required fields:
 *
 *    - Scope
 *    - Key
 *    - Value and omit the optional fields `description` and `is_active`.
 * 3. Assert the response type using typia.assert, then verify that:
 *
 *    - `scope`, `key`, and `value` match the request payload.
 *    - `description` is left as undefined (because the DTO models description as an
 *         optional string without null), meaning the backend did not inject any
 *         unexpected description.
 *    - `is_active` is true, reflecting the documented default behavior when not
 *         explicitly provided in the create DTO.
 * 4. Next, call the same create endpoint again with a fully populated
 *    ITodoAppSystemConfig.ICreate payload that explicitly sets:
 *
 *    - `description` to a non-empty string such as "Beta UI exposure flag".
 *    - `is_active` to false so that the configuration is created in an inactive
 *         state from the outset.
 * 5. Assert the second response via typia.assert and verify that:
 *
 *    - `scope`, `key`, and `value` round-trip exactly as requested.
 *    - `description` is exactly the string sent in the request.
 *    - `is_active` is false, confirming that explicit values override any default
 *         behavior.
 * 6. Use TestValidator.equals and TestValidator.predicate with descriptive titles
 *    for all business rule assertions, and avoid any tests based on HTTP status
 *    codes or type error scenarios.
 *
 * Edge considerations and constraints:
 *
 * - Scope and key pairs must be unique; therefore, use randomized or highly
 *   specific `key` values for each configuration to avoid conflicts with other
 *   tests or previously created rows.
 * - Description is modeled as an optional string (no null/undefined union on the
 *   concrete ITodoAppSystemConfig type), so for the first creation we only
 *   assert that it remains undefined rather than attempting to compare to
 *   null.
 * - For the first creation, we do not send `is_active` in the request but expect
 *   the backend to default `is_active` to true.
 */
export async function test_api_system_config_creation_with_optional_fields_and_defaults(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin to obtain authorized context.
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todoapp.example.com/settings/system-configs",
    referrer: "https://admin.todoapp.example.com/login",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequest,
    });
  typia.assert(admin);

  // 2. Create a minimal configuration omitting optional fields.
  const minimalConfigRequest = {
    scope: "system",
    key: `feature_flag_beta_ui_${RandomGenerator.alphaNumeric(8)}`,
    value: "true",
  } satisfies ITodoAppSystemConfig.ICreate;

  const minimalConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: minimalConfigRequest,
    });
  typia.assert(minimalConfig);

  // 3. Validate minimal configuration behavior.
  TestValidator.equals(
    "minimal config: scope should match request",
    minimalConfig.scope,
    minimalConfigRequest.scope,
  );
  TestValidator.equals(
    "minimal config: key should match request",
    minimalConfig.key,
    minimalConfigRequest.key,
  );
  TestValidator.equals(
    "minimal config: value should match request",
    minimalConfig.value,
    minimalConfigRequest.value,
  );
  TestValidator.predicate(
    "minimal config: description should be undefined when omitted",
    minimalConfig.description === undefined,
  );
  TestValidator.equals(
    "minimal config: is_active should default to true when omitted",
    minimalConfig.is_active,
    true,
  );

  // 4. Create a configuration with explicit optional fields.
  const explicitDescription = "Beta UI exposure flag";
  const explicitConfigRequest = {
    scope: "system",
    key: `feature_flag_beta_ui_explicit_${RandomGenerator.alphaNumeric(8)}`,
    value: "false",
    description: explicitDescription,
    is_active: false,
  } satisfies ITodoAppSystemConfig.ICreate;

  const explicitConfig: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: explicitConfigRequest,
    });
  typia.assert(explicitConfig);

  // 5. Validate explicit configuration behavior.
  TestValidator.equals(
    "explicit config: scope should match request",
    explicitConfig.scope,
    explicitConfigRequest.scope,
  );
  TestValidator.equals(
    "explicit config: key should match request",
    explicitConfig.key,
    explicitConfigRequest.key,
  );
  TestValidator.equals(
    "explicit config: value should match request",
    explicitConfig.value,
    explicitConfigRequest.value,
  );
  TestValidator.equals(
    "explicit config: description should match request",
    explicitConfig.description,
    explicitConfigRequest.description,
  );
  TestValidator.equals(
    "explicit config: is_active should match explicit false",
    explicitConfig.is_active,
    explicitConfigRequest.is_active,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate that system configuration creation is restricted to authenticated
 * todoAdmin accounts.
 *
 * Original intent was to ensure that suspended or otherwise non-active admins
 * are rejected, but the available SDK only exposes /auth/todoAdmin/join for
 * admin lifecycle and does not provide any operation to change an admin’s
 * status. Therefore, this test instead validates the closely related rule that
 * unauthenticated (thus invalid) callers cannot create system configs, while a
 * properly authenticated admin can.
 *
 * Test steps:
 *
 * 1. Join as a new todoAdmin using /auth/todoAdmin/join. This returns an
 *    ITodoAppTodoAdmin.IAuthorized and implicitly sets
 *    connection.headers.Authorization to the admin’s access token.
 * 2. Using this authenticated connection, call POST
 *    /todoApp/todoAdmin/systemConfigs with a valid ITodoAppSystemConfig.ICreate
 *    body and assert that it succeeds and returns a valid
 *    ITodoAppSystemConfig.
 * 3. Derive an unauthenticated connection by shallow-cloning the original
 *    connection but providing an empty headers object. This simulates a client
 *    that has no Authorization header and therefore no valid todoAdmin
 *    context.
 * 4. Using this unauthenticated connection, attempt to create another system
 *    config with a valid ITodoAppSystemConfig.ICreate body and assert, via
 *    TestValidator.httpError, that the call fails with an HTTP 401 or 403 type
 *    status.
 *
 * This verifies that the system configuration creation endpoint enforces
 * authentication for todoAdmin actors and does not allow configuration writes
 * from invalid (unauthenticated) contexts.
 */
export async function test_api_system_config_creation_rejected_for_inactive_or_invalid_admin(
  connection: api.IConnection,
) {
  // 1. Join as a new todoAdmin (authenticated admin context)
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.example.com/register",
    referrer: "https://admin.todo-app.example.com/login",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // Sanity check: status field is a non-empty string
  TestValidator.predicate(
    "joined admin has non-empty status",
    () => admin.status.length > 0,
  );

  // 2. Authenticated admin can create a system config
  const createBody1 = {
    scope: "todo",
    key: `max_open_todos_${RandomGenerator.alphaNumeric(6)}`,
    value: "100",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  const config1: ITodoAppSystemConfig =
    await api.functional.todoApp.todoAdmin.systemConfigs.create(connection, {
      body: createBody1,
    });
  typia.assert<ITodoAppSystemConfig>(config1);

  TestValidator.equals(
    "authenticated admin can create system config",
    config1.scope,
    createBody1.scope,
  );
  TestValidator.equals(
    "created config key matches request",
    config1.key,
    createBody1.key,
  );
  TestValidator.equals(
    "created config value matches request",
    config1.value,
    createBody1.value,
  );

  // 3. Build an unauthenticated connection (no Authorization header)
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 4. Attempt to create another system config without authentication and
  //    assert that it fails with an HTTP auth-style error (401 or 403).
  const createBody2 = {
    scope: "todo",
    key: `soft_delete_retention_days_${RandomGenerator.alphaNumeric(6)}`,
    value: "30",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    is_active: true,
  } satisfies ITodoAppSystemConfig.ICreate;

  await TestValidator.httpError(
    "unauthenticated caller cannot create system config",
    [401, 403],
    async () => {
      await api.functional.todoApp.todoAdmin.systemConfigs.create(
        unauthenticatedConnection,
        {
          body: createBody2,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
