import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate that a todoUser can update basic mutable fields of their own Todo.
 *
 * Business workflow
 *
 * 1. Admin registers and creates an active Todo status in the catalogue.
 * 2. Todo user registers and becomes authenticated.
 * 3. Todo user creates a Todo with explicit title, description, due_date and
 *    status_code.
 * 4. Todo user updates the Todo's title, description, and due_date via PUT
 *    /todoApp/todoUser/todos/{todoId}.
 * 5. Verify that mutable fields are updated, immutable fields remain stable, and
 *    status is unchanged.
 */
export async function test_api_todo_update_basic_fields_by_owner(
  connection: api.IConnection,
) {
  // 1. Admin joins to gain privileges for creating a status
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todoapp.test/join",
    referrer: "https://admin.todoapp.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an active default Todo status
  const statusCode = "ACTIVE";
  const statusCreateBody = {
    code: statusCode,
    label: "Active",
    description: "Default active status for todos",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(status);

  TestValidator.equals(
    "created status code should match",
    status.code,
    statusCode,
  );
  TestValidator.predicate(
    "created status should be active",
    status.is_active === true,
  );

  // 3. Todo user joins (registers) and becomes authenticated
  const userPassword = typia.random<string & tags.Format<"password">>();

  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: userPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.test/join",
    referrer: "https://todoapp.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userAuthorized);

  // 4. User creates an initial Todo
  const originalTitle = RandomGenerator.paragraph({ sentences: 3 });
  const originalDescription = RandomGenerator.paragraph({ sentences: 6 });
  const originalDueDate = new Date(
    Date.now() + 24 * 60 * 60 * 1000,
  ).toISOString();

  const todoCreateBody = {
    title: originalTitle,
    description: originalDescription,
    due_date: originalDueDate,
    status_code: status.code,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo title should match input",
    createdTodo.title,
    originalTitle,
  );
  TestValidator.equals(
    "created todo description should match input",
    createdTodo.description,
    originalDescription,
  );
  TestValidator.equals(
    "created todo due_date should match input",
    createdTodo.due_date,
    originalDueDate,
  );
  TestValidator.equals(
    "created todo status code should match selected status",
    createdTodo.status.code,
    status.code,
  );

  const createdId = createdTodo.id;
  const createdStatus = createdTodo.status;
  const createdCreatedAt = createdTodo.created_at;
  const createdUpdatedAt = createdTodo.updated_at;
  const createdCompletedAt = createdTodo.completed_at ?? null;
  const createdDeletedAt = createdTodo.deleted_at ?? null;

  // 5. User updates title, description, and due_date
  const updatedTitle = RandomGenerator.paragraph({ sentences: 4 });
  const updatedDescription = RandomGenerator.paragraph({ sentences: 8 });
  const updatedDueDate = new Date(
    Date.now() + 48 * 60 * 60 * 1000,
  ).toISOString();

  const todoUpdateBody = {
    title: updatedTitle,
    description: updatedDescription,
    due_date: updatedDueDate,
  } satisfies ITodoAppTodo.IUpdate;

  const updatedTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.update(connection, {
      todoId: createdId,
      body: todoUpdateBody,
    });
  typia.assert(updatedTodo);

  // 6. Validate immutable and mutable fields
  TestValidator.equals(
    "updated todo id should remain unchanged",
    updatedTodo.id,
    createdId,
  );

  TestValidator.equals(
    "updated todo status.id should remain unchanged",
    updatedTodo.status.id,
    createdStatus.id,
  );
  TestValidator.equals(
    "updated todo status.code should remain unchanged",
    updatedTodo.status.code,
    createdStatus.code,
  );
  TestValidator.equals(
    "updated todo status.label should remain unchanged",
    updatedTodo.status.label,
    createdStatus.label,
  );
  TestValidator.equals(
    "updated todo status.is_default should remain unchanged",
    updatedTodo.status.is_default,
    createdStatus.is_default,
  );
  TestValidator.equals(
    "updated todo status.is_active should remain unchanged",
    updatedTodo.status.is_active,
    createdStatus.is_active,
  );

  TestValidator.equals(
    "updated todo title should reflect update",
    updatedTodo.title,
    updatedTitle,
  );
  TestValidator.equals(
    "updated todo description should reflect update",
    updatedTodo.description,
    updatedDescription,
  );
  TestValidator.equals(
    "updated todo due_date should reflect update",
    updatedTodo.due_date,
    updatedDueDate,
  );

  TestValidator.equals(
    "created_at should be immutable across update",
    updatedTodo.created_at,
    createdCreatedAt,
  );
  TestValidator.notEquals(
    "updated_at should change after update",
    updatedTodo.updated_at,
    createdUpdatedAt,
  );

  const updatedCompletedAt = updatedTodo.completed_at ?? null;
  const updatedDeletedAt = updatedTodo.deleted_at ?? null;

  TestValidator.equals(
    "completed_at should remain unchanged by basic field update",
    updatedCompletedAt,
    createdCompletedAt,
  );
  TestValidator.equals(
    "deleted_at should remain unchanged by basic field update",
    updatedDeletedAt,
    createdDeletedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Verify that a todoUser can transition a Todo from an active status to a
 * completed status using PUT /todoApp/todoUser/todos/{todoId}, and that
 * lifecycle fields and other properties behave correctly.
 *
 * Business workflow:
 *
 * 1. Register a todoUser (self-signup) and obtain an authenticated context.
 * 2. Register a todoAdmin and obtain an authenticated context for admin.
 * 3. As todoAdmin, create two Todo statuses:
 *
 *    - ACTIVE: is_default=true, is_active=true.
 *    - COMPLETED: is_default=false, is_active=true.
 * 4. As todoUser, create a Todo which implicitly uses the default ACTIVE status.
 * 5. Update the Todo’s todo_status_id to point to the COMPLETED status.
 * 6. Validate that the returned Todo:
 *
 *    - Has status.id and status.code corresponding to the COMPLETED status.
 *    - Has completed_at set to a non-null timestamp when moved to completed.
 *    - Preserves title, description, and due_date.
 */
export async function test_api_todo_update_status_transition_to_completed(
  connection: api.IConnection,
) {
  // 1. Register todoUser (join) to get an authenticated user context.
  const todoUserEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const todoUserJoinHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const todoUserJoinReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const todoUserJoinBody = {
    email: todoUserEmail,
    password: "P@ssw0rd-User",
    display_name: RandomGenerator.name(2),
    ip: null,
    href: todoUserJoinHref,
    referrer: todoUserJoinReferrer,
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: todoUserJoinBody,
    });
  typia.assert(todoUserAuthorized);

  // 2. Register todoAdmin and get admin authentication context.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const adminReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "P@ssw0rd-Admin",
    displayName: RandomGenerator.name(2),
    ip: null,
    href: adminHref,
    referrer: adminReferrer,
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. As todoAdmin, create ACTIVE and COMPLETED statuses.
  const activeStatusBody = {
    code: "ACTIVE",
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusBody,
    });
  typia.assert(activeStatus);

  const completedStatusBody = {
    code: "COMPLETED",
    label: "Completed",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const completedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: completedStatusBody,
    });
  typia.assert(completedStatus);

  // 4. As todoUser, create a Todo using default ACTIVE status.
  // The SDK automatically manages Authorization headers, and admin.join
  // overwrote the token, so re-login as todoUser to switch actor.
  const todoUserLoginBody = {
    email: todoUserEmail,
    password: "P@ssw0rd-User",
    ip: null,
    href: todoUserJoinHref,
    referrer: todoUserJoinReferrer,
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const todoUserReAuth: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: todoUserLoginBody,
    });
  typia.assert(todoUserReAuth);

  const originalTitle = RandomGenerator.paragraph({ sentences: 2 });
  const originalDescription = RandomGenerator.paragraph({ sentences: 4 });
  const originalDueDate: string & tags.Format<"date-time"> = typia.random<
    string & tags.Format<"date-time">
  >();

  const todoCreateBody = {
    title: originalTitle,
    description: originalDescription,
    due_date: originalDueDate,
    status_code: null,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // Basic sanity checks on created Todo.
  TestValidator.equals(
    "created todo title should match input",
    createdTodo.title,
    originalTitle,
  );
  TestValidator.equals(
    "created todo description should match input",
    createdTodo.description ?? null,
    originalDescription,
  );
  TestValidator.equals(
    "created todo due_date should match input",
    createdTodo.due_date ?? null,
    originalDueDate,
  );

  // We expect createdTodo.status to correspond to ACTIVE status, but since
  // business rules may choose any default, only assert that it's active.
  TestValidator.predicate(
    "created todo should have an active status",
    createdTodo.status.is_active === true,
  );

  // 5. Update the Todo’s status to COMPLETED via PUT /todoApp/todoUser/todos/{todoId}.
  const updateBody = {
    todo_status_id: completedStatus.id,
  } satisfies ITodoAppTodo.IUpdate;

  const updatedTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.update(connection, {
      todoId: createdTodo.id,
      body: updateBody,
    });
  typia.assert(updatedTodo);

  // 6. Validation of status transition and lifecycle fields.

  // Status must now refer to COMPLETED status.
  TestValidator.equals(
    "updated todo status id should match completed status id",
    updatedTodo.status.id,
    completedStatus.id,
  );
  TestValidator.equals(
    "updated todo status code should match completed status code",
    updatedTodo.status.code,
    completedStatus.code,
  );

  // completed_at should be set when moving to completed.
  TestValidator.predicate(
    "updated todo completed_at should be non-null after completion",
    updatedTodo.completed_at !== null && updatedTodo.completed_at !== undefined,
  );

  // Other fields (title, description, due_date) should remain unchanged.
  TestValidator.equals(
    "updated todo title should remain unchanged",
    updatedTodo.title,
    originalTitle,
  );
  TestValidator.equals(
    "updated todo description should remain unchanged",
    updatedTodo.description ?? null,
    originalDescription,
  );
  TestValidator.equals(
    "updated todo due_date should remain unchanged",
    updatedTodo.due_date ?? null,
    originalDueDate,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

export async function test_api_todo_update_rejects_cross_user_access(
  connection: api.IConnection,
) {
  // 1. Create and authenticate a todoAdmin (administrator) account
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todoapp.test/join",
    referrer: "https://admin.todoapp.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(adminAuthorized);

  // 2. As todoAdmin, create a valid Todo status for later use
  const statusBody = {
    code: "ACTIVE",
    label: "Active",
    description: "Active todo that is not yet completed",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusBody,
    });
  typia.assert<ITodoAppTodoStatus>(createdStatus);

  // 3. Create and authenticate todoUser A via join
  const userAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const userAPassword = RandomGenerator.alphaNumeric(12) as string &
    tags.Format<"password">;

  const userAJoinBody = {
    email: userAEmail,
    password: userAPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.test/join",
    referrer: "https://todoapp.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userAJoinBody,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(userAAuthorized);

  // 4. As user A, create a Todo using the created status code
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date().toISOString() as string & tags.Format<"date-time">,
    status_code: createdStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const todoA: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert<ITodoAppTodo>(todoA);

  // 5. Create and authenticate todoUser B via join
  const userBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const userBPassword = RandomGenerator.alphaNumeric(12) as string &
    tags.Format<"password">;

  const userBJoinBody = {
    email: userBEmail,
    password: userBPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.test/join",
    referrer: "https://todoapp.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userBAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userBJoinBody,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(userBAuthorized);

  // 6. As user B, attempt to update todoA (owned by user A) and expect failure
  const crossUserUpdateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    todo_status_id: createdStatus.id as string & tags.Format<"uuid">,
  } satisfies ITodoAppTodo.IUpdate;

  await TestValidator.error(
    "cross-user todo update should be rejected",
    async () => {
      await api.functional.todoApp.todoUser.todos.update(connection, {
        todoId: todoA.id,
        body: crossUserUpdateBody,
      });
    },
  );

  // 7. Re-authenticate as user A via login to restore user A context
  const userALoginBody = {
    email: userAEmail,
    password: userAPassword,
    ip: null,
    href: "https://todoapp.test/login",
    referrer: "https://todoapp.test/landing",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const userALoginAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userALoginBody,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(userALoginAuthorized);

  // 8. As user A, successfully update the Todo to verify ownership and data integrity
  const ownerUpdateBody = {
    title: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies ITodoAppTodo.IUpdate;

  const updatedTodoA: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.update(connection, {
      todoId: todoA.id,
      body: ownerUpdateBody,
    });
  typia.assert<ITodoAppTodo>(updatedTodoA);

  // Business assertions
  TestValidator.equals(
    "owner update should apply new title",
    updatedTodoA.title,
    ownerUpdateBody.title,
  );

  TestValidator.equals(
    "todo id should remain unchanged after updates",
    updatedTodoA.id,
    todoA.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate partial update and null-handling behavior for Todo description.
 *
 * Business workflow:
 *
 * 1. Register a todoAdmin account and obtain admin authentication context.
 * 2. As todoAdmin, create a concrete Todo status row that is active and can be
 *    used by Todos.
 * 3. Register a todoUser account and obtain user authentication context.
 * 4. As todoUser, create a Todo with:
 *
 *    - Non-null description,
 *    - Non-null due_date,
 *    - An explicit status_code referring to the admin-created status.
 * 5. Capture the original Todo fields: title, description, due_date, status
 *    summary, created_at, updated_at.
 * 6. As the same todoUser, perform a partial update via PUT
 *    /todoApp/todoUser/todos/{todoId} with body:
 *
 *    - Description: null (explicitly clear description),
 *    - All other fields omitted (title, due_date, todo_status_id).
 * 7. Validate that:
 *
 *    - Description is now null.
 *    - Title is unchanged.
 *    - Due_date is unchanged.
 *    - Status summary (id, code, label, is_default, is_active) is unchanged.
 *    - Created_at is unchanged while updated_at is strictly more recent than before.
 */
export async function test_api_todo_update_partial_fields_and_null_handling(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin via join, establishing admin auth context
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
