  TestValidator.equals(
    "created todo status code should match created status code",
    createdTodo.status.code,
    createdStatus.code,
  );

  const originalTitle = createdTodo.title;
  const originalDescription = createdTodo.description;
  const originalDueDate = createdTodo.due_date;
  const originalStatus = createdTodo.status;
  const originalCreatedAt = createdTodo.created_at;
  const originalUpdatedAt = createdTodo.updated_at;

  TestValidator.predicate(
    "original description must be non-null",
    () => originalDescription !== null && originalDescription !== undefined,
  );
  TestValidator.predicate(
    "original due_date must be non-null",
    () => originalDueDate !== null && originalDueDate !== undefined,
  );

  // 5. Partial update: clear description by setting it to null
  const updateBody = {
    description: null,
  } satisfies ITodoAppTodo.IUpdate;

  const updatedTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.update(connection, {
      todoId: createdTodo.id,
      body: updateBody,
    });
  typia.assert(updatedTodo);

  // 6. Validate business rules after update
  TestValidator.equals(
    "description should be cleared to null after update",
    updatedTodo.description,
    null,
  );

  TestValidator.equals(
    "title should remain unchanged after partial update",
    updatedTodo.title,
    originalTitle,
  );

  TestValidator.equals(
    "due_date should remain unchanged after partial update",
    updatedTodo.due_date,
    originalDueDate,
  );

  TestValidator.equals(
    "status id should remain unchanged after partial update",
    updatedTodo.status.id,
    originalStatus.id,
  );
  TestValidator.equals(
    "status code should remain unchanged after partial update",
    updatedTodo.status.code,
    originalStatus.code,
  );
  TestValidator.equals(
    "status label should remain unchanged after partial update",
    updatedTodo.status.label,
    originalStatus.label,
  );
  TestValidator.equals(
    "status is_default should remain unchanged after partial update",
    updatedTodo.status.is_default,
    originalStatus.is_default,
  );
  TestValidator.equals(
    "status is_active should remain unchanged after partial update",
    updatedTodo.status.is_active,
    originalStatus.is_active,
  );

  TestValidator.equals(
    "created_at should remain unchanged after update",
    updatedTodo.created_at,
    originalCreatedAt,
  );

  TestValidator.predicate(
    "updated_at should be more recent than original updated_at",
    () => updatedTodo.updated_at > originalUpdatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Verify that a todoUser can delete a Todo they own using the DELETE
 * /todoApp/todoUser/todos/{todoId} endpoint, and that attempting to delete the
 * same Todo again results in an error.
 *
 * ## Business context
 *
 * In the todoApp service, each Todo belongs to a specific todoUser and is
 * stored in the `todo_app_todos` table. Only the owning todoUser should be
 * allowed to delete their Todo via the /todoApp/todoUser/todos/{todoId} DELETE
 * API, exposed in the SDK as api.functional.todoApp.todoUser.todos.erase.
 *
 * A valid Todo also participates in the status catalogue defined in
 * `todo_app_todo_statuses`. Therefore, an admin actor must be able to create at
 * least one active status entry so that todos can optionally reference an
 * initial status via `status_code` at creation time.
 *
 * This scenario uses both admin and user actors:
 *
 * - TodoAdmin: manages the status catalogue.
 * - TodoUser: owns and manipulates personal Todos.
 *
 * ## Step-by-step scenario
 *
 * 1. Register and authenticate a todoAdmin
 *
 *    - Call POST /auth/todoAdmin/join via api.functional.auth.todoAdmin.join
 *    - Use realistic but random email/password and URLs for href/referrer
 *    - Confirm the response shape with typia.assert
 *    - (Optionally) Call /auth/todoAdmin/login with the same credentials to exercise
 *         the login path and ensure SDK token handling works; this is not
 *         strictly necessary for status creation but gives a richer flow within
 *         one test.
 * 2. Create a Todo status entry
 *
 *    - Call POST /todoApp/todoAdmin/todoStatuses via
 *         api.functional.todoApp.todoAdmin.todoStatuses.create
 *    - Build an ITodoAppTodoStatus.ICreate body with:
 *
 *         - Code: a deterministic value such as "ACTIVE" (or a variant including a random
 *                   suffix to avoid unique constraint conflicts when tests run
 *                   repeatedly)
 *         - Label: a readable label like "Active"
 *         - Description/group: optional text or null
 *         - Sort_order: a small int32 (e.g., 1)
 *         - Is_default: true
 *         - Is_active: true
 *    - Assert the ITodoAppTodoStatus response with typia.assert and optionally basic
 *         invariants with TestValidator.predicate.
 * 3. Register and authenticate a todoUser
 *
 *    - Call POST /auth/todoUser/join via api.functional.auth.todoUser.join
 *    - Use another random email/password and href/referrer URIs
 *    - Assert the ITodoAppTodoUser.IAuthorized response
 *    - (Optionally) Call /auth/todoUser/login with the same credentials to verify
 *         login + token refresh behavior.
 * 4. Create a Todo owned by this todoUser
 *
 *    - Call POST /todoApp/todoUser/todos via
 *         api.functional.todoApp.todoUser.todos.create
 *    - Build an ITodoAppTodo.ICreate body:
 *
 *         - Title: a small random paragraph
 *         - Description: a longer random paragraph or null
 *         - Due_date: an ISO 8601 date-time string in the near future, or null
 *         - Status_code: the `code` from the created Todo status, so the Todo starts in
 *                   the "ACTIVE" (or similar) state
 *    - Assert the ITodoAppTodo response via typia.assert.
 * 5. Delete the Todo as its owner
 *
 *    - Call DELETE /todoApp/todoUser/todos/{todoId} via
 *         api.functional.todoApp.todoUser.todos.erase with todoId =
 *         createdTodo.id
 *    - This endpoint returns void; the fact that the Promise resolves without
 *         throwing indicates success.
 * 6. Attempt to delete the same Todo again and expect failure
 *
 *    - Use TestValidator.error with an async callback that calls
 *         api.functional.todoApp.todoUser.todos.erase again with the same
 *         todoId.
 *    - The expectation is that the backend will now treat the Todo as non-existent
 *         (or otherwise invalid for deletion) and throw an HttpError or
 *         similar.
 *    - This serves as an indirect confirmation that the resource is no longer
 *         deletable after the first successful erase.
 *
 * ## Important constraints and adaptations
 *
 * - The original natural-language scenario mentioned verifying that the deleted
 *   Todo is no longer returned by GET/detail or list endpoints. However, such
 *   endpoints are not present in the provided SDK, so this test adapts the
 *   verification to a double-delete pattern, which is implementable with
 *   existing functions.
 * - The SDK’s auth functions automatically manage Authorization headers on the
 *   connection object (via token.access). The test must NOT modify
 *   connection.headers directly.
 * - All request bodies must strictly satisfy the provided DTO types using the
 *   `satisfies` keyword; we never use `as any` or type-unsafe casts.
 * - We avoid checking raw HTTP status codes and instead rely on
 *   TestValidator.error to assert that a second delete fails.
 */
export async function test_api_todo_delete_by_owner(
  connection: api.IConnection,
) {
  // 1. Admin registration (join)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const adminHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const adminReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    displayName: RandomGenerator.name(),
    ip: null,
    href: adminHref,
    referrer: adminReferrer,
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminJoinOutput: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoinOutput);

  // Optional admin login to exercise login path
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: adminHref,
    referrer: adminReferrer,
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminLoginOutput: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginOutput);

  // 2. Admin creates a Todo status
  const statusCodeBase = "ACTIVE";
  const statusCodeSuffix = RandomGenerator.alphaNumeric(6);
  const statusCode = `${statusCodeBase}_${statusCodeSuffix}`;

  const statusCreateBody = {
    code: statusCode,
    label: "Active",
    description: "Active todo status for newly created todos",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const statusOutput: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(statusOutput);

  TestValidator.predicate(
    "created status is active",
    statusOutput.is_active === true,
  );
  TestValidator.predicate(
    "created status is default",
    statusOutput.is_default === true,
  );

  // 3. User registration (join)
  const userEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const userPassword: string = RandomGenerator.alphaNumeric(12);
  const userHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const userReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const userJoinBody = {
    email: userEmail,
    password: userPassword as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: null,
    href: userHref,
    referrer: userReferrer,
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userJoinOutput: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userJoinOutput);

  // Optional user login to exercise login path
  const userLoginBody = {
    email: userEmail,
    password: userPassword,
    ip: null,
    href: userHref,
    referrer: userReferrer,
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const userLoginOutput: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userLoginBody,
    });
  typia.assert(userLoginOutput);

  // 4. User creates a Todo
  const todoTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 8,
  });
  const todoDescription = RandomGenerator.paragraph({
    sentences: 6,
    wordMin: 3,
    wordMax: 8,
  });

  const now = new Date();
  const oneWeekMs = 7 * 24 * 60 * 60 * 1000;
  const futureDueDate = RandomGenerator.date(now, oneWeekMs).toISOString();

  const todoCreateBody = {
    title: todoTitle,
    description: todoDescription,
    due_date: futureDueDate,
    status_code: statusOutput.code,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo title matches input",
    createdTodo.title,
    todoTitle,
  );

  // 5. Delete the Todo as its owner
  await api.functional.todoApp.todoUser.todos.erase(connection, {
    todoId: createdTodo.id,
  });

  // 6. Second delete must fail
  await TestValidator.error("double delete should fail", async () => {
    await api.functional.todoApp.todoUser.todos.erase(connection, {
      todoId: createdTodo.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

export async function test_api_todo_delete_rejects_cross_user_access(
  connection: api.IConnection,
) {
  // 1. Admin joins to obtain privileges for creating a Todo status
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates a concrete Todo status so todos can reference a valid status_code
  const statusCreateBody = {
    code: "ACTIVE",
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1 satisfies number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(status);

  // 3. todoUser A joins (and becomes authenticated)
  const userAPassword = typia.random<string & tags.Format<"password">>();
  const userAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: userAPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userA: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userAJoinBody,
    });
  typia.assert(userA);

  // 4. As user A, create Todo A with the created status.code as status_code
  const todoCreateBodyA = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    due_date: typia.random<string & tags.Format<"date-time">>(),
    status_code: status.code,
  } satisfies ITodoAppTodo.ICreate;

  const todoA: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBodyA,
    });
  typia.assert(todoA);

  // 5. todoUser B joins (and becomes authenticated)
  const userBPassword = typia.random<string & tags.Format<"password">>();
  const userBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: userBPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userB: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userBJoinBody,
    });
  typia.assert(userB);

  // 6. As user B, attempt to delete Todo A - must fail with authorization/not-found error
  await TestValidator.error("cross-user todo delete must fail", async () => {
    await api.functional.todoApp.todoUser.todos.erase(connection, {
      todoId: todoA.id,
    });
  });

  // 7. Re-authenticate as user A via login
  const userALoginBody = {
    email: userA.email,
    password: userAPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const userALogin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userALoginBody,
    });
  typia.assert(userALogin);

  // 8. As user A (rightful owner), delete Todo A - should succeed without error
  await api.functional.todoApp.todoUser.todos.erase(connection, {
    todoId: todoA.id,
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";

/**
 * Validate idempotent delete behavior for missing Todo items.
 *
 * Business purpose
 *
 * - Ensure that an authenticated todoUser can safely call DELETE
 *   /todoApp/todoUser/todos/{todoId} even when the target Todo does not exist.
 * - Confirm that repeated deletes on the same non-existing todoId behave
 *   consistently and do not cause unexpected failures from the SDK
 *   perspective.
 *
 * High-level steps
 *
 * 1. Register and authenticate a new todoUser via POST /auth/todoUser/join.
 * 2. Generate a random UUID to be used as a non-existing todoId.
 * 3. Call DELETE /todoApp/todoUser/todos/{todoId} with that todoId once.
 * 4. Call the same DELETE again with the same todoId to simulate idempotent
 *    behavior on a missing resource.
 * 5. Assert that both operations complete without throwing and that the join
 *    response matches ITodoAppTodoUser.IAuthorized.
 */
export async function test_api_todo_delete_idempotent_behavior_on_missing_todo(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new todoUser
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const authorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: joinRequest,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(authorized);

  // Basic sanity check on user status and token
  TestValidator.predicate(
    "todoUser status should be a non-empty string",
    !!authorized.status && authorized.status.length > 0,
  );
  TestValidator.predicate(
    "todoUser token.access should be non-empty",
    !!authorized.token.access && authorized.token.access.length > 0,
  );

  // 2. Generate a random UUID for a likely non-existing Todo
  const missingTodoId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 3. First delete attempt on the missing Todo
  await api.functional.todoApp.todoUser.todos.erase(connection, {
    todoId: missingTodoId,
  });

  // If we reached here, the first delete did not throw.
  TestValidator.predicate(
    "first delete on missing todoId completes without throwing",
    true,
  );

  // 4. Second delete attempt on the same missing Todo (idempotence check)
  await api.functional.todoApp.todoUser.todos.erase(connection, {
    todoId: missingTodoId,
  });

  TestValidator.predicate(
    "second delete on the same missing todoId also completes without throwing",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoAdminAudit";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminAudit";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate that a todoAdmin can list administrative audit records for a single
 * todo.
 *
 * Business context:
 *
 * - TodoAdmin is a privileged actor who can inspect administrative audit trails
 *   for individual todos using the PATCH
 *   /todoApp/todoAdmin/todos/{todoId}/adminAudits endpoint.
 * - A todoUser owns todos and triggers business activity, but is not allowed to
 *   read admin audits directly.
 * - The audit list is paginated and returns lightweight summary DTOs
 *   (ITodoAppTodoAdminAudit.ISummary) wrapped in
 *   IPageITodoAppTodoAdminAudit.ISummary.
 *
 * This E2E test executes a realistic multi-actor flow to reach the listing call
 * and then validates the shape and scoping of the response.
 *
 * High-level steps:
 *
 * 1. Register a new todoAdmin using /auth/todoAdmin/join. The SDK attaches the
 *    admin JWT token to the connection automatically.
 * 2. As todoAdmin, create a Todo status using POST /todoApp/todoAdmin/todoStatuses
 *    with ITodoAppTodoStatus.ICreate, so there is at least one valid status for
 *    todos.
 * 3. Register a new todoUser using /auth/todoUser/join and rely on SDK to set the
 *    todoUser token on the connection.
 * 4. As todoUser, create a new todo via POST /todoApp/todoUser/todos with
 *    ITodoAppTodo.ICreate and capture its id as todoId.
 * 5. Switch the authentication context back to todoAdmin using
 *    /auth/todoAdmin/login so that the subsequent adminAudits.index call is
 *    performed as an administrative actor.
 * 6. Call api.functional.todoApp.todoAdmin.todos.adminAudits.index with todoId and
 *    a request body (ITodoAppTodoAdminAudit.IRequest) specifying page=1 and
 *    limit=10 and no additional filters.
 * 7. Validate the response type with
 *    typia.assert<IPageITodoAppTodoAdminAudit.ISummary>(output).
 * 8. Assert that pagination.current and pagination.limit obey the documented
 *    non-negative and positive invariants, and that limit is greater than
 *    zero.
 * 9. If the page contains any audit entries (data.length > 0), perform additional
 *    business validations on the first entry and on all entries:
 *
 *    - Each audit.todo.id must equal the todoId we queried, confirming that the
 *         result set is scoped to a single todo.
 *    - Basic structural sanity: action is a non-empty string, created_at is present,
 *         and embedded todo and admin summaries are populated.
 *
 * Note:
 *
 * - We cannot force specific admin audit rows to exist using available APIs, so
 *   the test must be tolerant to the case where data is empty. In that case, we
 *   only check type-level and pagination invariants.
 * - We do not validate HTTP status codes or error branches, in accordance with
 *   the E2E framework rules.
 */
export async function test_api_todo_admin_audit_list_for_single_todo_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin and obtain authorized admin context.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todoapp.test/join",
    referrer: "https://admin.todoapp.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminJoin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(adminJoin);

  // 2. Create at least one Todo status as the admin.
  const statusCreateBody = {
    code: `STATUS_${RandomGenerator.alphaNumeric(8)}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: null,
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert<ITodoAppTodoStatus>(status);

  // 3. Register a new todoUser and obtain authorized todoUser context.
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://app.todoapp.test/join",
    referrer: "https://app.todoapp.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userJoin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(userJoin);

  // 4. As todoUser, create a new todo item.
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date().toISOString(),
    status_code: status.code,
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo = await api.functional.todoApp.todoUser.todos.create(
    connection,
    {
      body: todoCreateBody,
    },
  );
  typia.assert<ITodoAppTodo>(todo);

  // 5. Switch authentication back to todoAdmin using login
  const adminLoginBody = {
    email: adminJoin.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.todoapp.test/login",
    referrer: "https://admin.todoapp.test/audits",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminLogin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(adminLogin);

  // 6. Call adminAudits.index as todoAdmin for the created todo.
  const requestBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    action: null,
    field_name: null,
    admin_id: null,
    created_from: null,
    created_to: null,
  } satisfies ITodoAppTodoAdminAudit.IRequest;

  const page: IPageITodoAppTodoAdminAudit.ISummary =
    await api.functional.todoApp.todoAdmin.todos.adminAudits.index(connection, {
      todoId: todo.id,
      body: requestBody,
    });
  typia.assert<IPageITodoAppTodoAdminAudit.ISummary>(page);

  // 7. Basic pagination invariants.
  const pagination: IPage.IPagination = page.pagination;
  TestValidator.predicate(
    "pagination.current is non-negative",
    pagination.current >= 0,
  );
  TestValidator.predicate("pagination.limit is positive", pagination.limit > 0);
  TestValidator.predicate(
    "pagination.records is non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination.pages is non-negative",
    pagination.pages >= 0,
  );

  // 8. If there are audit records, validate scoping and core fields.
  if (page.data.length > 0) {
    const first: ITodoAppTodoAdminAudit.ISummary = page.data[0];

    // Ensure the audit is for the requested todo.
    TestValidator.equals(
      "first audit todo.id matches requested todoId",
      first.todo.id,
      todo.id,
    );

    // Basic action field sanity.
    TestValidator.predicate(
      "first audit action is non-empty",
      first.action.length > 0,
    );

    // Ensure nested todo summary is populated with same id.
    TestValidator.equals(
      "first audit nested todo summary id matches",
      first.todo.id,
      todo.id,
    );
    TestValidator.predicate(
      "first audit nested todo title is non-empty",
      first.todo.title.length > 0,
    );

    // Admin summary basic sanity: email non-empty.
    TestValidator.predicate(
      "first audit admin email is non-empty",
      first.admin.email.length > 0,
    );

    // 9. All entries must be scoped to the same todoId.
    for (const audit of page.data) {
      TestValidator.equals(
        "each audit todo.id matches requested todoId",
        audit.todo.id,
        todo.id,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoAdminAudit";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminAudit";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

export async function test_api_todo_admin_audit_list_filtered_by_action_and_admin(
  connection: api.IConnection,
) {
  // 1. Register adminA and obtain authorized context
  const adminJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminA: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinRequest,
    });
  typia.assert(adminA);

  // 2. As adminA, create at least one Todo status so catalogue is populated
  const statusCreateBody = {
    code: `STATUS_${RandomGenerator.alphaNumeric(8)}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: 1,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(createdStatus);

  // 3. Register a todoUser and create a Todo as that user
  const todoUserPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const userJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: todoUserPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUser: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinRequest,
    });
  typia.assert(todoUser);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
    status_code: createdStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 4. Switch back to adminA (to ensure we are an admin when calling adminAudits.index)
  const adminLoginRequest = {
    email: adminJoinRequest.email,
    password: adminJoinRequest.password,
    ip: null,
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminALogin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginRequest,
    });
  typia.assert(adminALogin);

  TestValidator.equals(
    "admin login should return same admin id as join",
    adminALogin.id,
    adminA.id,
  );

  // 5. Call adminAudits.index filtered by admin_id and scoped to createdTodo.id
  const auditRequestBody = {
    page: 1,
    limit: 20,
    action: null,
    field_name: null,
    admin_id: adminA.id,
    created_from: null,
    created_to: null,
  } satisfies ITodoAppTodoAdminAudit.IRequest;

  const auditPage: IPageITodoAppTodoAdminAudit.ISummary =
    await api.functional.todoApp.todoAdmin.todos.adminAudits.index(connection, {
      todoId: createdTodo.id,
      body: auditRequestBody,
    });
  typia.assert(auditPage);

  // 6. Basic pagination assertions
  TestValidator.predicate(
    "pagination current page should be non-negative",
    auditPage.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit should be non-negative",
    auditPage.pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination records should be non-negative",
    auditPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages should be non-negative",
    auditPage.pagination.pages >= 0,
  );

  // 7. Verify every returned audit matches admin_id and todoId
  for (const audit of auditPage.data) {
    typia.assert<ITodoAppTodoAdminAudit.ISummary>(audit);

    TestValidator.equals(
      "audit admin.id should equal filter adminA.id",
      audit.admin.id,
      adminA.id,
    );

    TestValidator.equals(
      "audit todo.id should equal path todoId",
      audit.todo.id,
      createdTodo.id,
    );
  }

  if (auditPage.data.length > 0) {
    TestValidator.predicate(
      "pagination.records should be at least number of returned audits",
      auditPage.pagination.records >= auditPage.data.length,
    );
  }

  // 8. Negative scenario: todoUser must not be able to access admin audits
  const userLoginRequest = {
    email: userJoinRequest.email,
    password: todoUserPassword,
    ip: null,
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const loggedInUser: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userLoginRequest,
    });
  typia.assert(loggedInUser);

  await TestValidator.error(
    "todoUser must not access admin audits",
    async () => {
      await api.functional.todoApp.todoAdmin.todos.adminAudits.index(
        connection,
        {
          todoId: createdTodo.id,
          body: auditRequestBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoAdminAudit";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminAudit";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate pagination boundary behavior for admin audit listing on a todo.
 *
 * Business flow:
 *
 * 1. Register a todoAdmin via /auth/todoAdmin/join (admin token stored into
 *    connection by SDK).
 * 2. As admin, create at least one Todo status so that todo creation is valid.
 * 3. Register a todoUser via /auth/todoUser/join (connection now authenticated as
 *    todoUser).
 * 4. As todoUser, create a single todo via /todoApp/todoUser/todos.create and
 *    capture its id.
 * 5. Switch back to admin via /auth/todoAdmin/login so the connection is again an
 *    admin.
 * 6. Call PATCH /todoApp/todoAdmin/todos/{todoId}/adminAudits with page=1 and a
 *    modest limit (5) using ITodoAppTodoAdminAudit.IRequest. Record pagination
 *    metadata and data length.
 * 7. Compute a page index strictly beyond the last available page (pages+1 when
 *    pages>0, or 1 when pages===0) and call the same endpoint again with that
 *    page and same limit.
 * 8. Assert that pagination.limit, pagination.records, and pagination.pages are
 *    identical between the two responses, proving stable total counts.
 * 9. Assert that pagination.current in both responses is within [0, pages] as
 *    required by IPage.IPagination.
 * 10. If pages===0, assert that both responses have empty data arrays, current===0,
 *     and records===0.
 * 11. If pages>0, assert that the first page has between 1 and limit records and
 *     that the beyond-last-page call returns an empty data array while keeping
 *     total counts intact.
 */
export async function test_api_todo_admin_audit_list_pagination_boundaries(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin and keep its email for later login
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    ip: null,
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create at least one Todo status so that todos are valid
  const todoStatusBody = {
    code: RandomGenerator.alphabets(8).toUpperCase(),
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: null,
    group: null,
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: todoStatusBody,
    });
  typia.assert(status);

  // 3. Register a todoUser (connection token switches to todoUser)
  const userEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const userJoinBody = {
    email: userEmail,
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(2),
    ip: null,
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(todoUserAuthorized);

  // 4. As todoUser, create a single todo
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: null,
    status_code: status.code,
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo = await api.functional.todoApp.todoUser.todos.create(
    connection,
    {
      body: todoCreateBody,
    },
  );
  typia.assert(todo);

  // 5. Switch back to admin using login (token is updated by SDK)
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/login-form",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminLoginAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 6. First admin audit list call for the todo
  const limit = 5 as number & tags.Type<"int32">;

  const firstRequest: ITodoAppTodoAdminAudit.IRequest = {
    page: 1 as number & tags.Type<"int32">,
    limit,
    action: undefined,
    field_name: undefined,
    admin_id: undefined,
    created_from: undefined,
    created_to: undefined,
  };

  const firstPage: IPageITodoAppTodoAdminAudit.ISummary =
    await api.functional.todoApp.todoAdmin.todos.adminAudits.index(connection, {
      todoId: todo.id,
      body: firstRequest,
    });
  typia.assert(firstPage);

  const firstPagination = firstPage.pagination;
  const firstData = firstPage.data;

  // Basic invariants: non-negative pagination numbers
  TestValidator.predicate(
    "first pagination current is non-negative",
    firstPagination.current >= 0,
  );
  TestValidator.predicate(
    "first pagination limit is non-negative",
    firstPagination.limit >= 0,
  );
  TestValidator.predicate(
    "first pagination records is non-negative",
    firstPagination.records >= 0,
  );
  TestValidator.predicate(
    "first pagination pages is non-negative",
    firstPagination.pages >= 0,
  );

  const pages = firstPagination.pages;

  // 7. Compute a page index strictly beyond the last available page
  const beyondLastPageIndex: number & tags.Type<"int32"> = (
    pages === 0 ? 1 : pages + 1
  ) as number & tags.Type<"int32">;

  const secondRequest: ITodoAppTodoAdminAudit.IRequest = {
    page: beyondLastPageIndex,
    limit,
    action: undefined,
    field_name: undefined,
    admin_id: undefined,
    created_from: undefined,
    created_to: undefined,
  };

  const secondPage: IPageITodoAppTodoAdminAudit.ISummary =
    await api.functional.todoApp.todoAdmin.todos.adminAudits.index(connection, {
      todoId: todo.id,
      body: secondRequest,
    });
  typia.assert(secondPage);

  const secondPagination = secondPage.pagination;
  const secondData = secondPage.data;

  // 8. pagination.limit, records, pages must be stable across requests
  TestValidator.equals(
    "limit is stable across pagination requests",
    secondPagination.limit,
    firstPagination.limit,
  );
  TestValidator.equals(
    "records is stable across pagination requests",
    secondPagination.records,
    firstPagination.records,
  );
  TestValidator.equals(
    "pages is stable across pagination requests",
    secondPagination.pages,
    firstPagination.pages,
  );

  // 9. pagination.current must be within [0, pages]
  TestValidator.predicate(
    "first current within [0, pages]",
    firstPagination.current >= 0 &&
      firstPagination.current <= firstPagination.pages,
  );
  TestValidator.predicate(
    "second current within [0, pages]",
    secondPagination.current >= 0 &&
      secondPagination.current <= secondPagination.pages,
  );

  // 10 & 11. Data behavior depending on pages
  if (pages === 0) {
    TestValidator.equals(
      "no records: first data is empty",
      firstData.length,
      0,
    );
    TestValidator.equals(
      "no records: second data is empty",
      secondData.length,
      0,
    );
    TestValidator.equals(
      "no records: current is 0 in first page",
      firstPagination.current,
      0,
    );
    TestValidator.equals(
      "no records: current is 0 in second page",
      secondPagination.current,
      0,
    );
    TestValidator.equals(
      "no records: records is 0",
      firstPagination.records,
      0,
    );
  } else {
    // There is at least one audit record in total
    TestValidator.predicate(
      "first page has between 1 and limit items when pages>0",
      firstData.length >= 1 && firstData.length <= limit,
    );

    TestValidator.equals(
      "beyond last page returns empty data",
      secondData.length,
      0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
