import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminAudit";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate that administrative audit detail retrieval works for a todoAdmin
 * session and returns a structurally correct ITodoAppTodoAdminAudit payload.
 *
 * Original business idea: ensure that audit records remain visible for
 * logically deleted todos and that the embedded todo summary reflects the
 * deleted state. However, the current SDK surface does not expose any deletion
 * or audit-creation mutation endpoints. Therefore, this test focuses on the
 * feasible aspects:
 *
 * 1. Establish a todoAdmin actor and verify that admin-only operations are
 *    accessible (by creating a Todo status catalogue entry).
 * 2. Establish a todoUser actor and create a Todo item as that user so the
 *    environment has realistic Todo data.
 * 3. Switch back to the todoAdmin account to obtain an admin-authenticated
 *    connection.
 * 4. Invoke GET /todoApp/todoAdmin/todos/{todoId}/adminAudits/{auditId} using
 *    random UUIDs for todoId and auditId. In simulate mode this returns a
 *    typia.random<ITodoAppTodoAdminAudit> payload; against a real backend it
 *    may either succeed or fail depending on database state.
 * 5. When the call succeeds, assert that the response conforms to
 *    ITodoAppTodoAdminAudit and perform basic business sanity checks on the
 *    nested todo and admin summaries (non-empty title, valid timestamps,
 *    etc.).
 *
 * This validates:
 *
 * - Proper todoAdmin authentication and ability to hit admin-only endpoints.
 * - Structural integrity of ITodoAppTodoAdminAudit, ITodoAppTodo.ISummary, and
 *   ITodoAppTodoAdmin.ISummary.
 * - That the audit detail endpoint is wired correctly in the SDK.
 */
export async function test_api_todo_admin_audit_detail_for_soft_deleted_todo(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin and obtain an authorized admin session.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.example.com/join",
    referrer: "https://admin.todo-app.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create a Todo status row as the admin to assert admin-only access.
  const statusCreateBody = {
    code: "ACTIVE",
    label: "Active",
    description: "Active todos",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(createdStatus);

  // 3. Register a todoUser and create a todo for realistic data context.
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userAuthorized);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 8 }),
    due_date: new Date().toISOString(),
    status_code: createdStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 4. Switch back to todoAdmin via login to ensure admin token is active.
  const adminLoginBody = {
    email: adminAuthorized.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.todo-app.example.com/login",
    referrer: "https://admin.todo-app.example.com/landing",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminLoggedIn: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 5. Call the admin audit detail endpoint with random UUIDs.
  const randomTodoId = typia.random<string & tags.Format<"uuid">>();
  const randomAuditId = typia.random<string & tags.Format<"uuid">>();

  const audit: ITodoAppTodoAdminAudit =
    await api.functional.todoApp.todoAdmin.todos.adminAudits.at(connection, {
      todoId: randomTodoId,
      auditId: randomAuditId,
    });
  typia.assert(audit);

  // 6. Business sanity checks on the audit payload.
  // Ensure audit id and action are present.
  TestValidator.predicate(
    "audit id should be a non-empty string",
    typeof audit.id === "string" && audit.id.length > 0,
  );
  TestValidator.predicate(
    "audit action should be a non-empty string",
    typeof audit.action === "string" && audit.action.length > 0,
  );

  // Validate nested todo summary.
  const todoSummary = audit.todo;
  TestValidator.predicate(
    "todo summary title should be non-empty",
    typeof todoSummary.title === "string" && todoSummary.title.length > 0,
  );
  TestValidator.predicate(
    "todo summary created_at should not be after updated_at",
    new Date(todoSummary.created_at).getTime() <=
      new Date(todoSummary.updated_at).getTime(),
  );

  // Validate nested admin summary.
  const adminSummary = audit.admin;
  TestValidator.equals(
    "admin summary id should match authorized admin id type-wise",
    typeof adminSummary.id,
    typeof adminAuthorized.id,
  );
  TestValidator.equals(
    "admin summary email should match email type-wise",
    typeof adminSummary.email,
    typeof adminAuthorized.email,
  );
  TestValidator.predicate(
    "admin summary status should be non-empty",
    typeof adminSummary.status === "string" && adminSummary.status.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoStatus";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate basic pagination behavior of the Todo status listing endpoint.
 *
 * This scenario focuses on the read-only catalogue endpoint PATCH
 * /todoApp/todoStatuses, ensuring that:
 *
 * 1. A todoAdmin can create multiple Todo status catalogue entries.
 * 2. The public list endpoint returns paginated summaries when requested with only
 *    `page` and `limit` fields in ITodoAppTodoStatus.IRequest.
 * 3. The `pagination` metadata reflects the requested paging parameters (1-based
 *    page -> 0-based `current`, and matching `limit`).
 * 4. The `data` array respects the requested `limit` and contains valid
 *    ITodoAppTodoStatus.ISummary objects.
 * 5. Multiple pages (page 1, page 2) together cover a consistent portion of the
 *    catalogue without duplicating items across pages.
 */
export async function test_api_todo_status_list_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Register a fresh todoAdmin to obtain an authenticated context.
  const adminJoinBody = typia.random<ITodoAppTodoAdminJoin.IRequest>();
  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Seed the Todo status catalogue with multiple entries.
  // Choose a limit that allows multiple pages.
  const pageSize = 5;
  const totalStatusesToCreate = 2 * pageSize + 1; // ensure more than 2 pages worth of data

  const indices: number[] = ArrayUtil.repeat(
    totalStatusesToCreate,
    (index) => index,
  );

  const createdStatuses: ITodoAppTodoStatus[] = await ArrayUtil.asyncMap(
    indices,
    async (index) => {
      // Ensure `code` uniqueness by embedding the index and a random suffix.
      const createBody = {
        code: `STATUS_${index}_${RandomGenerator.alphaNumeric(6)}`,
        label: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        group: RandomGenerator.paragraph({ sentences: 1 }),
        sort_order: index as number & tags.Type<"int32">,
        is_default: index === 0,
        is_active: index % 2 === 0,
      } satisfies ITodoAppTodoStatus.ICreate;

      const created: ITodoAppTodoStatus =
        await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
          body: createBody,
        });
      typia.assert<ITodoAppTodoStatus>(created);
      return created;
    },
  );

  TestValidator.equals<number, number>(
    "number of created statuses matches intended seed size",
    createdStatuses.length,
    totalStatusesToCreate,
  );

  // 3. Call the listing endpoint for page 1 with only page/limit.
  const requestPage1 = {
    page: 1 as number & tags.Type<"int32">,
    limit: pageSize as number & tags.Type<"int32">,
  } satisfies ITodoAppTodoStatus.IRequest;

  const page1: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: requestPage1,
    });
  typia.assert<IPageITodoAppTodoStatus.ISummary>(page1);

  const pagination1: IPage.IPagination = page1.pagination;
  typia.assert<IPage.IPagination>(pagination1);

  // 4. Validate pagination meta for page 1.
  TestValidator.equals<number, number>(
    "pagination.limit matches requested limit for page 1",
    pagination1.limit,
    requestPage1.limit,
  );

  TestValidator.equals<number, number>(
    "pagination.current is request page - 1 for page 1",
    pagination1.current,
    (requestPage1.page as number) - 1,
  );

  TestValidator.predicate(
    "page 1 data length does not exceed limit",
    page1.data.length <= requestPage1.limit,
  );

  // Ensure each summary entry looks valid (typia.assert already checked types).
  for (const summary of page1.data) {
    typia.assert<ITodoAppTodoStatus.ISummary>(summary);
    TestValidator.predicate(
      "summary.id should be a non-empty string",
      typeof summary.id === "string" && summary.id.length > 0,
    );
    TestValidator.predicate(
      "summary.code should be non-empty",
      summary.code.length > 0,
    );
    TestValidator.predicate(
      "summary.label should be non-empty",
      summary.label.length > 0,
    );
  }

  // 5. Request page 2 and validate non-duplication and coverage.
  const requestPage2 = {
    page: 2 as number & tags.Type<"int32">,
    limit: pageSize as number & tags.Type<"int32">,
  } satisfies ITodoAppTodoStatus.IRequest;

  const page2: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: requestPage2,
    });
  typia.assert<IPageITodoAppTodoStatus.ISummary>(page2);

  const pagination2: IPage.IPagination = page2.pagination;
  typia.assert<IPage.IPagination>(pagination2);

  TestValidator.equals<number, number>(
    "pagination.limit matches requested limit for page 2",
    pagination2.limit,
    requestPage2.limit,
  );

  TestValidator.equals<number, number>(
    "pagination.current is request page - 1 for page 2",
    pagination2.current,
    (requestPage2.page as number) - 1,
  );

  TestValidator.predicate(
    "page 2 data length does not exceed limit",
    page2.data.length <= requestPage2.limit,
  );

  // Compare IDs across pages for non-duplication.
  const idsPage1 = new Set(page1.data.map((s) => s.id));
  const idsPage2 = new Set(page2.data.map((s) => s.id));

  const intersection = [...idsPage1].filter((id) => idsPage2.has(id));

  TestValidator.equals<string[], string[]>(
    "no duplicated status IDs between page 1 and page 2",
    intersection,
    [],
  );

  // 6. Cross-check pagination records/pages coherence.
  const observedUniqueIds = new Set<string>([...idsPage1, ...idsPage2]);

  TestValidator.predicate(
    "pagination.records is at least the number of unique items observed in first two pages",
    pagination1.records >= observedUniqueIds.size,
  );

  TestValidator.predicate(
    "pagination.pages is non-negative",
    pagination1.pages >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoStatus";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate that the Todo status listing endpoint honors the `isActiveOnly`
 * filter.
 *
 * Business goal: Ensure that when clients request only active Todo statuses
 * through PATCH /todoApp/todoStatuses with `isActiveOnly: true`, the backend
 * returns exclusively active statuses from the `todo_app_todo_statuses`
 * catalogue and excludes any inactive entries. Also verify that when
 * `isActiveOnly` is not enforced, inactive statuses may appear.
 *
 * High-level flow:
 *
 * 1. Register a todoAdmin account via POST /auth/todoAdmin/join to obtain an
 *    authenticated administrative context.
 * 2. As this todoAdmin, create a small catalogue of Todo statuses via POST
 *    /todoApp/todoAdmin/todoStatuses, mixing active and inactive entries.
 * 3. Call PATCH /todoApp/todoStatuses with `isActiveOnly: true` and a sufficiently
 *    large `limit`.
 * 4. Assert that only active statuses are returned and that the inactive ones
 *    created in step 2 are not present.
 * 5. Optionally, call the same endpoint without `isActiveOnly` (or with it set to
 *    false) and verify that inactive statuses can appear.
 */
export async function test_api_todo_status_list_active_only_filter(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin account and establish authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create a mix of active and inactive Todo statuses as todoAdmin
  const activeStatusBodies: ITodoAppTodoStatus.ICreate[] = [
    {
      code: `ACTIVE_${RandomGenerator.alphaNumeric(8)}`,
      label: "Active Status 1",
      description: RandomGenerator.paragraph({ sentences: 3 }),
      group: "test-group",
      sort_order: 1 as number & tags.Type<"int32">,
      is_default: true,
      is_active: true,
    },
    {
      code: `ACTIVE_${RandomGenerator.alphaNumeric(8)}`,
      label: "Active Status 2",
      description: RandomGenerator.paragraph({ sentences: 3 }),
      group: "test-group",
      sort_order: 2 as number & tags.Type<"int32">,
      is_default: false,
      is_active: true,
    },
  ];

  const inactiveStatusBody: ITodoAppTodoStatus.ICreate = {
    code: `INACTIVE_${RandomGenerator.alphaNumeric(8)}`,
    label: "Inactive Status",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "test-group",
    sort_order: 3 as number & tags.Type<"int32">,
    is_default: false,
    is_active: false,
  };

  const createdActiveStatuses: ITodoAppTodoStatus[] = [];
  for (const body of activeStatusBodies) {
    const created: ITodoAppTodoStatus =
      await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
        body,
      });
    typia.assert(created);
    createdActiveStatuses.push(created);
  }

  const createdInactiveStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: inactiveStatusBody,
    });
  typia.assert(createdInactiveStatus);

  // 3. Call PATCH /todoApp/todoStatuses with isActiveOnly: true
  const listActiveOnlyBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 20 as number & tags.Type<"int32">,
    isActiveOnly: true,
    sortKey: "sort_order" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const activeOnlyPage: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: listActiveOnlyBody,
    });
  typia.assert(activeOnlyPage);

  // 4. Assert all returned statuses are active
  for (const status of activeOnlyPage.data) {
    TestValidator.predicate(
      "every listed status must be active when isActiveOnly is true",
      status.is_active === true,
    );
  }

  // Ensure at least one of the known active statuses appears in the active-only list
  const activeIds = createdActiveStatuses.map((s) => s.id);
  const foundKnownActive = activeOnlyPage.data.some((s) =>
    activeIds.includes(s.id),
  );
  TestValidator.predicate(
    "at least one known active status should appear in active-only result",
    foundKnownActive,
  );

  // Ensure the known inactive status does not appear when isActiveOnly is true
  const foundInactiveInActiveOnly = activeOnlyPage.data.some(
    (s) => s.id === createdInactiveStatus.id,
  );
  TestValidator.predicate(
    "inactive status must not appear in active-only result",
    foundInactiveInActiveOnly === false,
  );

  // 5. Optionally call without isActiveOnly (or with false) and verify
  const listAllBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 20 as number & tags.Type<"int32">,
    isActiveOnly: false,
    sortKey: "sort_order" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const allStatusesPage: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: listAllBody,
    });
  typia.assert(allStatusesPage);

  // Active-only result should not have more records than the full listing
  TestValidator.predicate(
    "total records with active-only filter should be less than or equal to all statuses",
    activeOnlyPage.pagination.records <= allStatusesPage.pagination.records,
  );

  // At least one inactive status should appear when isActiveOnly is false (if dataset permits)
  const hasInactiveInAll = allStatusesPage.data.some(
    (s) => s.is_active === false,
  );
  TestValidator.predicate(
    "inactive status should appear when isActiveOnly is false",
    hasInactiveInAll,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoStatus";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate free-text search over Todo statuses by `code` and `label`.
 *
 * Business goal: Ensure that the public listing endpoint PATCH
 * /todoApp/todoStatuses applies the `query` field from
 * ITodoAppTodoStatus.IRequest as a case-insensitive (or at least
 * substring-based) text filter over the `code` and `label` fields of Todo
 * status catalogue entries. The test sets up a controlled data set of statuses,
 * then issues search requests and inspects which statuses appear.
 *
 * High-level flow:
 *
 * 1. Register a todoAdmin administrator using POST /auth/todoAdmin/join so that we
 *    can create Todo status entries via the admin-only endpoint.
 * 2. As the authenticated todoAdmin, create three Todo statuses with intentionally
 *    distinct and recognizable `code` and `label` values:
 *
 *    - `ACTIVE_TASK` / `Active Task`
 *    - `ARCHIVED_TASK` / `Archived Task`
 *    - `PENDING_REVIEW` / `Pending Review` Ensure they are active (is_active = true)
 *         and have distinct sort_order so they can all appear in listings.
 * 3. Call PATCH /todoApp/todoStatuses with a `query` that should only match the
 *    first status (for example, `"Active"`).
 *
 *    - Use a small `limit` (e.g., 10) and page = 1 so all matching rows fit.
 *    - Assert that:
 *
 *         - The call succeeds and returns a valid IPageITodoAppTodoStatus.ISummary
 *         - The `data` array contains the ACTIVE_TASK status (by code/label)
 *         - The `data` array does NOT contain ARCHIVED_TASK or PENDING_REVIEW.
 * 4. Call PATCH /todoApp/todoStatuses again with a query that should match a
 *    different subset, e.g. `"Archived"` (matching ARCHIVED_TASK only) or
 *    `"Pending"` (matching PENDING_REVIEW only) and perform similar presence /
 *    absence checks.
 * 5. Optionally, call PATCH /todoApp/todoStatuses with `query` omitted or an empty
 *    string to confirm that the endpoint returns at least the three created
 *    statuses when no text filter is applied (subject to pagination).
 *
 * Assertions:
 *
 * - Use typia.assert() to validate response shapes for:
 *
 *   - ITodoAppTodoAdmin.IAuthorized from join
 *   - ITodoAppTodoStatus from create
 *   - IPageITodoAppTodoStatus.ISummary from index
 * - Use TestValidator.equals / TestValidator.notEquals / TestValidator.predicate
 *   with descriptive titles for business assertions, such as:
 *
 *   - "Active query returns ACTIVE_TASK only"
 *   - "Archived query excludes ACTIVE_TASK"
 * - Do not rely on behavior outside what the DTOs and comments guarantee; treat
 *   the search as substring matching over `code` and `label`.
 */
export async function test_api_todo_status_list_text_search_by_code_and_label(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin account so that we can create statuses.
  const adminJoinBody = {
    email: `admin+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/admin/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 2. Create three Todo statuses with distinct code/label pairs.
  const activeStatusBody = {
    code: "ACTIVE_TASK",
    label: "Active Task",
    description: "Status used for currently active tasks",
    group: "lifecycle",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const archivedStatusBody = {
    code: "ARCHIVED_TASK",
    label: "Archived Task",
    description: "Status for tasks that have been archived",
    group: "lifecycle",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const pendingStatusBody = {
    code: "PENDING_REVIEW",
    label: "Pending Review",
    description: "Status for tasks waiting for review",
    group: "workflow",
    sort_order: 3 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusBody,
    });
  typia.assert(activeStatus);

  const archivedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: archivedStatusBody,
    });
  typia.assert(archivedStatus);

  const pendingStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: pendingStatusBody,
    });
  typia.assert(pendingStatus);

  // Helper to extract codes from summary list
  const extractCodes = (page: IPageITodoAppTodoStatus.ISummary): string[] =>
    page.data.map((s) => s.code);

  // 3. Query for "Active" to match only ACTIVE_TASK.
  const activeQueryBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    query: "Active",
    isActiveOnly: true,
    sortKey: "code" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const activeQueryResult: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: activeQueryBody,
    });
  typia.assert(activeQueryResult);

  const activeCodes = extractCodes(activeQueryResult);
  TestValidator.predicate(
    "Active query result contains ACTIVE_TASK",
    activeCodes.includes("ACTIVE_TASK"),
  );
  TestValidator.predicate(
    "Active query result does not contain ARCHIVED_TASK",
    !activeCodes.includes("ARCHIVED_TASK"),
  );
  TestValidator.predicate(
    "Active query result does not contain PENDING_REVIEW",
    !activeCodes.includes("PENDING_REVIEW"),
  );

  // 4. Query for "Archived" to match only ARCHIVED_TASK.
  const archivedQueryBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    query: "Archived",
    isActiveOnly: true,
    sortKey: "code" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const archivedQueryResult: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: archivedQueryBody,
    });
  typia.assert(archivedQueryResult);

  const archivedCodes = extractCodes(archivedQueryResult);
  TestValidator.predicate(
    "Archived query result contains ARCHIVED_TASK",
    archivedCodes.includes("ARCHIVED_TASK"),
  );
  TestValidator.predicate(
    "Archived query result does not contain ACTIVE_TASK",
    !archivedCodes.includes("ACTIVE_TASK"),
  );
  TestValidator.predicate(
    "Archived query result does not contain PENDING_REVIEW",
    !archivedCodes.includes("PENDING_REVIEW"),
  );

  // 5. Query for "Pending" to match only PENDING_REVIEW.
  const pendingQueryBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    query: "Pending",
    isActiveOnly: true,
    sortKey: "code" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const pendingQueryResult: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: pendingQueryBody,
    });
  typia.assert(pendingQueryResult);

  const pendingCodes = extractCodes(pendingQueryResult);
  TestValidator.predicate(
    "Pending query result contains PENDING_REVIEW",
    pendingCodes.includes("PENDING_REVIEW"),
  );
  TestValidator.predicate(
    "Pending query result does not contain ACTIVE_TASK",
    !pendingCodes.includes("ACTIVE_TASK"),
  );
  TestValidator.predicate(
    "Pending query result does not contain ARCHIVED_TASK",
    !pendingCodes.includes("ARCHIVED_TASK"),
  );

  // 6. Query without text filter (no `query` at all) should return at
  //    least the three created statuses when pagination allows.
  const unfilteredBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 20 as number & tags.Type<"int32">,
    isActiveOnly: true,
    sortKey: "code" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const unfilteredResult: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: unfilteredBody,
    });
  typia.assert(unfilteredResult);

  const unfilteredCodes = extractCodes(unfilteredResult);
  TestValidator.predicate(
    "Unfiltered list contains ACTIVE_TASK",
    unfilteredCodes.includes("ACTIVE_TASK"),
  );
  TestValidator.predicate(
    "Unfiltered list contains ARCHIVED_TASK",
    unfilteredCodes.includes("ARCHIVED_TASK"),
  );
  TestValidator.predicate(
    "Unfiltered list contains PENDING_REVIEW",
    unfilteredCodes.includes("PENDING_REVIEW"),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoStatus";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate sorting of Todo status list by `sort_order` in both ascending and
 * descending directions.
 *
 * Business goal
 *
 * - Ensure that the public Todo status listing endpoint correctly honors the
 *   `sortKey` = "sort_order" and `sortDirection` = "asc" | "desc" contract.
 * - Ensure that list responses are stable and that switching sort direction
 *   reorders the same set of status summaries without changing their content.
 *
 * High-level flow
 *
 * 1. Register a todoAdmin account via POST /auth/todoAdmin/join so that subsequent
 *    administrative operations are authenticated.
 * 2. As this todoAdmin, create three Todo status rows via POST
 *    /todoApp/todoAdmin/todoStatuses with controlled `sort_order` values 10,
 *    20, and 30. Use distinct `code` and `label` values for each so we can
 *    identify them unambiguously.
 * 3. Call PATCH /todoApp/todoStatuses with a request body { page: 1, limit:
 *    largeEnough, sortKey: "sort_order", sortDirection: "asc" }.
 *
 *    - Validate the shape and types of the response using typia.assert.
 *    - Filter the returned `data` to the three created codes.
 *    - Assert that these three appear in ascending order of the configured
 *         `sort_order` (10, 20, 30) using TestValidator.equals.
 * 4. Call PATCH /todoApp/todoStatuses again with the same pagination and filters,
 *    but `sortDirection: "desc"`.
 *
 *    - Again validate the response shape with typia.assert.
 *    - Filter to the same three codes.
 *    - Assert that these three appear in descending order of `sort_order` (30, 20,
 *         10).
 * 5. Finally, assert that the sets of summaries obtained from the asc and desc
 *    calls are identical as sets (same id/code/label/is_default/is_active
 *    combinations), only ordered differently.
 */
export async function test_api_todo_status_list_sorting_by_sort_order(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin to obtain an authenticated context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-admin.test/join",
    referrer: "https://todo-admin.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create three Todo status rows with deterministic sort_order values.
  const baseCodePrefix: string = RandomGenerator.alphabets(8).toUpperCase();

  const statusInputs: ITodoAppTodoStatus.ICreate[] = [
    {
      code: `${baseCodePrefix}_A`,
      label: `${baseCodePrefix} Label A`,
      description: "First status with sort_order 10",
      group: "sorting-test",
      sort_order: 10 as number & tags.Type<"int32">,
      is_default: false,
      is_active: true,
    },
    {
      code: `${baseCodePrefix}_B`,
      label: `${baseCodePrefix} Label B`,
      description: "Second status with sort_order 20",
      group: "sorting-test",
      sort_order: 20 as number & tags.Type<"int32">,
      is_default: false,
      is_active: true,
    },
    {
      code: `${baseCodePrefix}_C`,
      label: `${baseCodePrefix} Label C`,
      description: "Third status with sort_order 30",
      group: "sorting-test",
      sort_order: 30 as number & tags.Type<"int32">,
      is_default: false,
      is_active: true,
    },
  ];

  const createdStatuses: ITodoAppTodoStatus[] = [];
  for (const input of statusInputs) {
    const created = await api.functional.todoApp.todoAdmin.todoStatuses.create(
      connection,
      { body: input },
    );
    typia.assert(created);
    createdStatuses.push(created);
  }

  // Helper: map of code -> sort_order for our created statuses
  const createdByCode = new Map<string, ITodoAppTodoStatus>(
    createdStatuses.map((s) => [s.code, s]),
  );

  // 3. List statuses sorted ascending by sort_order.
  const ascResponse: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32">,
        limit: 50 as number & tags.Type<"int32">,
        query: undefined,
        isActiveOnly: undefined,
        sortKey: "sort_order",
        sortDirection: "asc",
      } satisfies ITodoAppTodoStatus.IRequest,
    });
  typia.assert(ascResponse);

  const ascDataForCodes: ITodoAppTodoStatus.ISummary[] =
    ascResponse.data.filter((summary) => createdByCode.has(summary.code));

  TestValidator.equals(
    "all three created statuses must appear in ascending result set",
    ascDataForCodes.length,
    createdStatuses.length,
  );

  const ascCodes = ascDataForCodes.map((s) => s.code);

  // 4. List statuses sorted descending by sort_order.
  const descResponse: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32">,
        limit: 50 as number & tags.Type<"int32">,
        query: undefined,
        isActiveOnly: undefined,
        sortKey: "sort_order",
        sortDirection: "desc",
      } satisfies ITodoAppTodoStatus.IRequest,
    });
  typia.assert(descResponse);

  const descDataForCodes: ITodoAppTodoStatus.ISummary[] =
    descResponse.data.filter((summary) => createdByCode.has(summary.code));

  TestValidator.equals(
    "all three created statuses must appear in descending result set",
    descDataForCodes.length,
    createdStatuses.length,
  );

  const descCodes = descDataForCodes.map((s) => s.code);

  // 5. Verify ascending vs descending order and same record sets.
  const expectedAscCodes = [
    statusInputs[0].code,
    statusInputs[1].code,
    statusInputs[2].code,
  ];
  const expectedDescCodes = [...expectedAscCodes].reverse();

  TestValidator.equals(
    "ascending list should be ordered by configured sort_order ascending",
    ascCodes,
    expectedAscCodes,
  );

  TestValidator.equals(
    "descending list should be ordered by configured sort_order descending",
    descCodes,
    expectedDescCodes,
  );

  // Compare sets of summaries for equality (ignoring order).
  const sortSummaries = (items: ITodoAppTodoStatus.ISummary[]) =>
    [...items].sort((a, b) => a.code.localeCompare(b.code));

  const ascSortedByCode = sortSummaries(ascDataForCodes);
  const descSortedByCode = sortSummaries(descDataForCodes);

  TestValidator.equals(
    "asc/desc result sets should have identical summaries when sorted by code",
    ascSortedByCode,
    descSortedByCode,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoStatus";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate sorting behavior of Todo status list by `code` and `label`.
 *
 * Business purpose:
 *
 * - Ensure that the public Todo status listing endpoint (PATCH
 *   /todoApp/todoStatuses) properly sorts records when `sortKey` is `"code"` or
 *   `"label"` and `sortDirection` is `"asc"` or `"desc"`.
 * - Guarantee deterministic ordering for UI dropdowns and configuration panels
 *   using status catalogues.
 *
 * Scenario steps:
 *
 * 1. Register a new todoAdmin account via /auth/todoAdmin/join.
 * 2. As the authenticated admin, create multiple Todo status records with distinct
 *    `code` and `label` values that have a clear lexicographical order: e.g.
 *    ALPHA/Alpha, BRAVO/Bravo, CHARLIE/Charlie.
 * 3. List Todo statuses with sortKey `"code"`, direction `"asc"` and a `limit`
 *    that ensures all created statuses fit on one page.
 * 4. Verify that the subset of returned records matching the created status IDs
 *    are ordered ascending by `code`.
 * 5. List again with sortKey `"code"`, direction `"desc"` and verify that, for the
 *    created subset, ordering is the reverse of the ascending result.
 * 6. Repeat steps 3–5 using sortKey `"label"` instead of `"code"`, and validate
 *    ordering by `label`.
 * 7. Confirm that all created statuses appear in each listing and that pagination
 *    metadata is consistent with the number of records found.
 */
export async function test_api_todo_status_list_sorting_by_code_and_label(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin to obtain an authenticated context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo.example.com/admin/join",
    referrer: "https://todo.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);
  typia.assert<IAuthorizationToken>(admin.token);

  // 2. Create several deterministic Todo status records.
  const statusInputs: ITodoAppTodoStatus.ICreate[] = [
    {
      code: "ALPHA",
      label: "Alpha",
      description: "First test status for sorting by code and label",
      group: "sorting-test",
      sort_order: 1 as number & tags.Type<"int32">,
      is_default: true,
      is_active: true,
    },
    {
      code: "BRAVO",
      label: "Bravo",
      description: "Second test status",
      group: "sorting-test",
      sort_order: 2 as number & tags.Type<"int32">,
      is_default: false,
      is_active: true,
    },
    {
      code: "CHARLIE",
      label: "Charlie",
      description: "Third test status",
      group: "sorting-test",
      sort_order: 3 as number & tags.Type<"int32">,
      is_default: false,
      is_active: true,
    },
  ];

  const createdStatuses: ITodoAppTodoStatus[] = [];
  for (const body of statusInputs) {
    const created: ITodoAppTodoStatus =
      await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
        body,
      });
    typia.assert(created);
    createdStatuses.push(created);
  }

  // Helper to map IDs for easier comparisons.
  const createdIds: string[] = createdStatuses.map((s) => s.id);

  // Helper function: assert that an array of summaries contains
  // all created IDs and is sorted by a specific key.
  const assertSortedSubset = (
    titlePrefix: string,
    data: ITodoAppTodoStatus.ISummary[],
    key: "code" | "label",
    direction: "asc" | "desc",
  ) => {
    const subset = data.filter((row) => createdIds.includes(row.id));

    TestValidator.equals(
      `${titlePrefix} - subset length`,
      subset.length,
      createdIds.length,
    );

    const subsetIdsSortedByKey = [...subset]
      .sort((a, b) =>
        direction === "asc"
          ? a[key].localeCompare(b[key])
          : b[key].localeCompare(a[key]),
      )
      .map((s) => s.id);

    const actualOrderIds = subset.map((s) => s.id);

    TestValidator.equals(
      `${titlePrefix} - ordering by ${key} (${direction})`,
      actualOrderIds,
      subsetIdsSortedByKey,
    );
  };

  // 3. List by code ascending.
  const listByCodeAscBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 50 as number & tags.Type<"int32">,
    query: undefined,
    isActiveOnly: undefined,
    sortKey: "code" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const listByCodeAsc: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: listByCodeAscBody,
    });
  typia.assert(listByCodeAsc);

  TestValidator.predicate(
    "pagination.records should be >= created count (code asc)",
    listByCodeAsc.pagination.records >= createdStatuses.length,
  );

  assertSortedSubset("sort by code asc", listByCodeAsc.data, "code", "asc");

  // 4. List by code descending.
  const listByCodeDescBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 50 as number & tags.Type<"int32">,
    query: undefined,
    isActiveOnly: undefined,
    sortKey: "code" as const,
    sortDirection: "desc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const listByCodeDesc: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: listByCodeDescBody,
    });
  typia.assert(listByCodeDesc);

  TestValidator.predicate(
    "pagination.records should be >= created count (code desc)",
    listByCodeDesc.pagination.records >= createdStatuses.length,
  );

  assertSortedSubset("sort by code desc", listByCodeDesc.data, "code", "desc");

  // Compare asc vs desc subset ordering for created IDs.
  const ascSubsetIds = listByCodeAsc.data
    .filter((row) => createdIds.includes(row.id))
    .map((row) => row.id);
  const descSubsetIds = listByCodeDesc.data
    .filter((row) => createdIds.includes(row.id))
    .map((row) => row.id);

  const reversedAscSubsetIds = [...ascSubsetIds].reverse();

  TestValidator.equals(
    "descending code order should be reverse of ascending for created subset",
    descSubsetIds,
    reversedAscSubsetIds,
  );

  // 5. List by label ascending.
  const listByLabelAscBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 50 as number & tags.Type<"int32">,
    query: undefined,
    isActiveOnly: undefined,
    sortKey: "label" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const listByLabelAsc: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: listByLabelAscBody,
    });
  typia.assert(listByLabelAsc);

  TestValidator.predicate(
    "pagination.records should be >= created count (label asc)",
    listByLabelAsc.pagination.records >= createdStatuses.length,
  );
  assertSortedSubset("sort by label asc", listByLabelAsc.data, "label", "asc");

  // 6. List by label descending.
  const listByLabelDescBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 50 as number & tags.Type<"int32">,
    query: undefined,
    isActiveOnly: undefined,
    sortKey: "label" as const,
    sortDirection: "desc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const listByLabelDesc: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: listByLabelDescBody,
    });
  typia.assert(listByLabelDesc);

  TestValidator.predicate(
    "pagination.records should be >= created count (label desc)",
    listByLabelDesc.pagination.records >= createdStatuses.length,
  );
  assertSortedSubset(
    "sort by label desc",
    listByLabelDesc.data,
    "label",
    "desc",
  );

  const ascLabelSubsetIds = listByLabelAsc.data
    .filter((row) => createdIds.includes(row.id))
    .map((row) => row.id);
  const descLabelSubsetIds = listByLabelDesc.data
    .filter((row) => createdIds.includes(row.id))
    .map((row) => row.id);
  const reversedAscLabelSubsetIds = [...ascLabelSubsetIds].reverse();

  TestValidator.equals(
    "descending label order should be reverse of ascending for created subset",
    descLabelSubsetIds,
    reversedAscLabelSubsetIds,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoStatus";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Verify that the Todo status list exposes the `is_default` flag correctly and
 * that, when the catalogue is configured with exactly one default status, the
 * listing reflects exactly one summary entry as default.
 *
 * Business flow:
 *
 * 1. A new todoAdmin joins the system via `/auth/todoAdmin/join` so that
 *    privileged admin endpoints can be invoked.
 * 2. The admin creates multiple Todo status catalogue entries via
 *    `/todoApp/todoAdmin/todoStatuses`, configuring exactly one as default
 *    (`is_default = true`) and others as non-default (`is_default = false`).
 * 3. The public listing endpoint `/todoApp/todoStatuses` is called with pagination
 *    and active-only filter to retrieve the status summaries.
 * 4. The response is asserted to be a valid page and the `data` collection is
 *    inspected to ensure exactly one status has `is_default === true`, matching
 *    the configured catalogue state.
 */
export async function test_api_todo_status_list_includes_default_status_flag(
  connection: api.IConnection,
) {
  // 1. Register (join) a todoAdmin account to obtain admin privileges.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo.example.com/admin/join",
    referrer: "https://todo.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create multiple Todo status entries, exactly one with is_default = true.
  const baseCodePrefix = RandomGenerator.alphaNumeric(8).toUpperCase();

  const defaultStatusBody = {
    code: `${baseCodePrefix}_DEFAULT`,
    label: "Default Status",
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const nonDefaultStatusBody1 = {
    code: `${baseCodePrefix}_ALT1`,
    label: "Alt Status 1",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const nonDefaultStatusBody2 = {
    code: `${baseCodePrefix}_ALT2`,
    label: "Alt Status 2",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 3 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdDefault: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: defaultStatusBody,
    });
  typia.assert(createdDefault);

  const createdAlt1: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: nonDefaultStatusBody1,
    });
  typia.assert(createdAlt1);

  const createdAlt2: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: nonDefaultStatusBody2,
    });
  typia.assert(createdAlt2);

  // 3. List Todo statuses with pagination and active-only filter.
  const listBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    query: undefined,
    isActiveOnly: true,
    sortKey: "sort_order" as const,
    sortDirection: "asc" as const,
  } satisfies ITodoAppTodoStatus.IRequest;

  const pageResult: IPageITodoAppTodoStatus.ISummary =
    await api.functional.todoApp.todoStatuses.index(connection, {
      body: listBody,
    });
  typia.assert(pageResult);

  // 4. Validate pagination shape and default flag semantics.
  const pagination = pageResult.pagination;
  const summaries = pageResult.data;

  TestValidator.predicate(
    "pagination records should be at least number of created statuses",
    pagination.records >= 3,
  );
  TestValidator.predicate(
    "data length should be at least number of created statuses on first page",
    summaries.length >= 3,
  );

  const defaultSummaries = summaries.filter((s) => s.is_default === true);

  TestValidator.equals(
    "exactly one default status should appear in list",
    defaultSummaries.length,
    1,
  );

  const defaultSummary = defaultSummaries[0];
  if (defaultSummary !== undefined) {
    TestValidator.equals(
      "default summary code should match created default status code",
      defaultSummary.code,
      createdDefault.code,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate retrieving a Todo status detail by an existing business status code.
 *
 * Business workflow:
 *
 * 1. Register a todoAdmin via /auth/todoAdmin/join to obtain an authenticated
 *    admin context.
 * 2. As the authenticated todoAdmin, create a new Todo status catalogue entry with
 *    a known `code`.
 * 3. Call the public detail endpoint /todoApp/todoStatuses/{statusCode} using that
 *    `code`.
 * 4. Ensure the returned ITodoAppTodoStatus exactly reflects the created
 *    configuration (code, label, description, group, sort_order, is_default,
 *    is_active, and lifecycle timestamps).
 */
export async function test_api_todo_status_detail_by_existing_code(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin (join) to establish authenticated admin context
  const joinRequestBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password-1234",
    displayName: RandomGenerator.name(1),
    ip: null,
    href: "https://admin.todo-app.local/register",
    referrer: "https://admin.todo-app.local/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequestBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(adminAuthorized);

  // 2. Create a Todo status via admin endpoint with a known business code
  const statusCode: string = `STATUS_${RandomGenerator.alphaNumeric(8)}`;

  const createBody = {
    code: statusCode,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<0>
    >() satisfies number as number,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodoStatus>(createdStatus);

  // 3. Retrieve the Todo status by its business code using public endpoint
  const fetchedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoStatuses.at(connection, {
      statusCode,
    });
  typia.assert<ITodoAppTodoStatus>(fetchedStatus);

  // 4. Validate that fetched status matches the created one for core fields
  TestValidator.equals(
    "todo status code should match between created and fetched",
    fetchedStatus.code,
    createdStatus.code,
  );
  TestValidator.equals(
    "todo status label should match between created and fetched",
    fetchedStatus.label,
    createdStatus.label,
  );
  TestValidator.equals(
    "todo status description should match between created and fetched",
    fetchedStatus.description,
    createdStatus.description,
  );
  TestValidator.equals(
    "todo status group should match between created and fetched",
    fetchedStatus.group,
    createdStatus.group,
  );
  TestValidator.equals(
    "todo status sort_order should match between created and fetched",
    fetchedStatus.sort_order,
    createdStatus.sort_order,
  );
  TestValidator.equals(
    "todo status is_default should match between created and fetched",
    fetchedStatus.is_default,
    createdStatus.is_default,
  );
  TestValidator.equals(
    "todo status is_active should match between created and fetched",
    fetchedStatus.is_active,
    createdStatus.is_active,
  );

  // Also ensure lifecycle timestamps exist and are consistent in type
  TestValidator.predicate(
    "created_at should be a non-empty string",
    fetchedStatus.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at should be a non-empty string",
    fetchedStatus.updated_at.length > 0,
  );

  // deleted_at may be null/undefined for fresh row; just ensure equality
  TestValidator.equals(
    "todo status deleted_at should match between created and fetched",
    fetchedStatus.deleted_at ?? null,
    createdStatus.deleted_at ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Verify that requesting a Todo status detail with an unknown statusCode
 * results in a not-found style error and does not return a ITodoAppTodoStatus.
 *
 * Business context: The todoApp service maintains a catalogue of valid Todo
 * statuses in the `todo_app_todo_statuses` table. Clients can look up a
 * specific status by its stable business `code` using GET
 * /todoApp/todoStatuses/{statusCode}. When a client passes a code that does not
 * exist, the backend should not fabricate a status; instead it must signal that
 * the resource is not found via an HTTP error. This test ensures that behavior,
 * using a realistic setup where the catalogue is not empty.
 *
 * Steps:
 *
 * 1. Register (join) a new todoAdmin account using /auth/todoAdmin/join so that we
 *    have administrative privileges and valid JWT tokens attached to the SDK
 *    connection.
 * 2. As that admin, create at least one real Todo status using POST
 *    /todoApp/todoAdmin/todoStatuses with a unique `code`.
 * 3. Choose another `statusCode` string that is guaranteed not to exist in the
 *    catalogue (for example, by prefixing/suffixing the known code with a
 *    random token).
 * 4. Call GET /todoApp/todoStatuses/{statusCode} with this non-existent code.
 * 5. Assert that the call fails with an error (no ITodoAppTodoStatus is returned)
 *    using TestValidator.error, focusing on the fact that an error is thrown
 *    rather than on specific status codes or error payload shapes.
 */
export async function test_api_todo_status_detail_not_found_for_unknown_code(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin and obtain authorized context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.example.com/join",
    referrer: "https://admin.todo-app.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create at least one real Todo status in the catalogue
  const existingStatusBody = {
    code: `ACTIVE_${RandomGenerator.alphaNumeric(8)}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: 1,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const existingStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: existingStatusBody,
    });
  typia.assert(existingStatus);
  TestValidator.equals(
    "created status code should match request body code",
    existingStatus.code,
    existingStatusBody.code,
  );

  // 3. Choose a guaranteed non-existent statusCode
  const unknownStatusCode: string = `${existingStatus.code}__UNKNOWN_${RandomGenerator.alphaNumeric(12)}`;
  TestValidator.notEquals(
    "unknown status code must be different from existing code",
    unknownStatusCode,
    existingStatus.code,
  );

  // 4 & 5. Call detail endpoint with unknown code and assert error
  await TestValidator.error(
    "unknown status code should result in error",
    async () => {
      await api.functional.todoApp.todoStatuses.at(connection, {
        statusCode: unknownStatusCode,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate that the Todo status detail endpoint correctly reflects lifecycle
 * flags for active and inactive statuses, and that freshly created statuses are
 * not logically deleted.
 *
 * Business intent:
 *
 * - An administrator (todoAdmin) can define Todo status catalogue entries,
 *   including whether a status is active or inactive.
 * - The public detail endpoint `/todoApp/todoStatuses/{statusCode}` should expose
 *   a consistent view of the status definition regardless of its active flag,
 *   at least for freshly created (non-deleted) statuses.
 * - While logical deletion via `deleted_at` is supported at the schema level, no
 *   delete/update admin endpoint is available in the current SDK, so this test
 *   limits itself to asserting that `deleted_at` is null/undefined for newly
 *   created statuses.
 *
 * Scenario:
 *
 * 1. Register a todoAdmin via `POST /auth/todoAdmin/join`, obtaining an authorized
 *    context on the shared `connection`.
 * 2. As that admin, create an ACTIVE Todo status via `POST
 *    /todoApp/todoAdmin/todoStatuses` with `is_active = true`.
 * 3. Fetch the same status via `GET /todoApp/todoStatuses/{statusCode}` and verify
 *    that key properties (`code`, `label`, `sort_order`, `is_default`,
 *    `is_active`, `deleted_at`) are consistent between create and detail.
 * 4. Create an INACTIVE Todo status via the same admin create endpoint with
 *    `is_active = false`.
 * 5. Fetch the inactive status via the detail endpoint using its `code`.
 * 6. Verify that the inactive status is still returned, with `is_active = false`
 *    and `deleted_at` remaining null/undefined, confirming that inactive but
 *    non-deleted statuses remain visible through the detail API.
 */
export async function test_api_todo_status_detail_reflects_inactive_and_deleted_statuses(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin to obtain an authorized admin context.
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://todo-admin.example.com/register",
    referrer: "https://todo-admin.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinRequest,
    });
  typia.assert(adminAuthorized);

  // 2. Create an ACTIVE Todo status from the admin side.
  const activeCodeBase = RandomGenerator.alphabets(8).toUpperCase();
  const activeStatusCreate = {
    code: `ACTIVE_${activeCodeBase}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdActiveStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusCreate,
    });
  typia.assert(createdActiveStatus);

  // Basic consistency checks on the created active status.
  TestValidator.equals(
    "created active status code should match input",
    createdActiveStatus.code,
    activeStatusCreate.code,
  );
  TestValidator.predicate(
    "created active status should be active",
    createdActiveStatus.is_active === true,
  );
  TestValidator.predicate(
    "created active status should not be logically deleted",
    createdActiveStatus.deleted_at === null ||
      createdActiveStatus.deleted_at === undefined,
  );

  // 3. Fetch the active status via the public detail endpoint by its code.
  const activeStatusFromDetail: ITodoAppTodoStatus =
    await api.functional.todoApp.todoStatuses.at(connection, {
      statusCode: createdActiveStatus.code,
    });
  typia.assert(activeStatusFromDetail);

  // Validate that the detail response matches the created active status.
  TestValidator.equals(
    "detail active status code matches created",
    activeStatusFromDetail.code,
    createdActiveStatus.code,
  );
  TestValidator.equals(
    "detail active status label matches created",
    activeStatusFromDetail.label,
    createdActiveStatus.label,
  );
  TestValidator.equals(
    "detail active status sort_order matches created",
    activeStatusFromDetail.sort_order,
    createdActiveStatus.sort_order,
  );
  TestValidator.equals(
    "detail active status is_default matches created",
    activeStatusFromDetail.is_default,
    createdActiveStatus.is_default,
  );
  TestValidator.equals(
    "detail active status is_active matches created",
    activeStatusFromDetail.is_active,
    createdActiveStatus.is_active,
  );
  TestValidator.predicate(
    "detail active status should not be logically deleted",
    activeStatusFromDetail.deleted_at === null ||
      activeStatusFromDetail.deleted_at === undefined,
  );

  // 4. Create an INACTIVE Todo status via the admin endpoint.
  const inactiveCodeBase = RandomGenerator.alphabets(8).toUpperCase();
  const inactiveStatusCreate = {
    code: `INACTIVE_${inactiveCodeBase}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_default: false,
    is_active: false,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdInactiveStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: inactiveStatusCreate,
    });
  typia.assert(createdInactiveStatus);

  // Confirm that the creation response reflects inactivity and no logical deletion.
  TestValidator.equals(
    "created inactive status code should match input",
    createdInactiveStatus.code,
    inactiveStatusCreate.code,
  );
  TestValidator.predicate(
    "created inactive status should be inactive",
    createdInactiveStatus.is_active === false,
  );
  TestValidator.predicate(
    "created inactive status should not be logically deleted",
    createdInactiveStatus.deleted_at === null ||
      createdInactiveStatus.deleted_at === undefined,
  );

  // 5. Fetch the inactive status via the public detail endpoint by its code.
  const inactiveStatusFromDetail: ITodoAppTodoStatus =
    await api.functional.todoApp.todoStatuses.at(connection, {
      statusCode: createdInactiveStatus.code,
    });
  typia.assert(inactiveStatusFromDetail);

  // 6. Validate that inactive statuses are still exposed and consistent.
  TestValidator.equals(
    "detail inactive status code matches created",
    inactiveStatusFromDetail.code,
    createdInactiveStatus.code,
  );
  TestValidator.equals(
    "detail inactive status label matches created",
    inactiveStatusFromDetail.label,
    createdInactiveStatus.label,
  );
  TestValidator.equals(
    "detail inactive status sort_order matches created",
    inactiveStatusFromDetail.sort_order,
    createdInactiveStatus.sort_order,
  );
  TestValidator.equals(
    "detail inactive status is_default matches created",
    inactiveStatusFromDetail.is_default,
    createdInactiveStatus.is_default,
  );
  TestValidator.predicate(
    "detail inactive status should be inactive",
    inactiveStatusFromDetail.is_active === false,
  );
  TestValidator.predicate(
    "detail inactive status should not be logically deleted",
    inactiveStatusFromDetail.deleted_at === null ||
      inactiveStatusFromDetail.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestuser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate that a todoAdmin can permanently delete a guest user identity and
 * that the deletion is reflected in subsequent guest user listings.
 *
 * Business workflow covered by this test:
 *
 * 1. Register a new todoAdmin and obtain admin authorization.
 * 2. As admin, create an ACTIVE-like Todo status so that real todos can be
 *    created.
 * 3. Register a new todoUser and obtain user authorization.
 * 4. As todoUser, create a Todo item that uses the created status code. (This
 *    ensures realistic pre-existing application data.)
 * 5. Switch back to the todoAdmin actor by logging in with admin credentials.
 * 6. As admin, query guest users with PATCH /todoApp/todoAdmin/guestUsers.
 * 7. Choose a concrete guestUserId from the returned page and delete it using
 *    DELETE /todoApp/todoAdmin/guestUsers/{guestUserId}.
 * 8. Query guest users again to verify that the deleted guest id is no longer
 *    present in the listing.
 *
 * Notes and constraints:
 *
 * - Only APIs defined in the provided SDK are used; no fictional endpoints.
 * - We do not attempt unauthenticated calls because connection.headers must not
 *   be manipulated directly. Instead, we focus on the positive admin-only
 *   deletion path and on verifying post-delete visibility.
 * - All responses are validated via typia.assert for strict type safety, and
 *   logical expectations are asserted with TestValidator.
 */
export async function test_api_todoadmin_delete_guest_user_after_data_cleanup(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin (join) and obtain admin authorization
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinRequest = {
    email: adminEmail,
    password: "AdminPassword!123",
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorizedFromJoin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinRequest,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. As this admin, create an active Todo status
  const todoStatusCreateBody = {
    code: `ACTIVE-${RandomGenerator.alphaNumeric(8)}`,
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: todoStatusCreateBody,
    });
  typia.assert(createdStatus);

  // 3. Register a new todoUser and obtain user authorization
  const userEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const userJoinRequest = {
    email: userEmail,
    password: "UserPassword!123" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorizedFromJoin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinRequest,
    });
  typia.assert(userAuthorizedFromJoin);

  // 4. As todoUser, create a Todo item referencing the created status code
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: typia.random<string & tags.Format<"date-time">>(),
    status_code: createdStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 5. Switch back to the todoAdmin actor by logging in with the same credentials
  const adminLoginRequest = {
    email: adminEmail,
    password: "AdminPassword!123",
    ip: null,
    href: "https://admin.todo-app.test/login",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminAuthorizedFromLogin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginRequest,
    });
  typia.assert(adminAuthorizedFromLogin);

  // 6. As admin, query guest users (must exist for deletion test to proceed)
  const guestIndexRequest = {
    page: 0 as number & tags.Type<"int32">,
    limit: 20 as number & tags.Type<"int32">,
  } satisfies ITodoAppGuestUser.IRequest;

  const guestPageBefore: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
      body: guestIndexRequest,
    });
  typia.assert(guestPageBefore);

  // Ensure we have at least one guest user to delete; otherwise, fail explicitly.
  TestValidator.predicate(
    "there must be at least one guest user available for deletion",
    guestPageBefore.data.length > 0 && guestPageBefore.pagination.records > 0,
  );

  const targetGuest: ITodoAppGuestUser.ISummary = guestPageBefore.data[0];

  // 7. Delete the selected guest user
  await api.functional.todoApp.todoAdmin.guestUsers.erase(connection, {
    guestUserId: targetGuest.id,
  });

  // 8. Query guest users again and verify that the deleted id is not present
  const guestPageAfter: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
      body: guestIndexRequest,
    });
  typia.assert(guestPageAfter);

  const existsAfterDeletion: boolean = guestPageAfter.data.some(
    (guest) => guest.id === targetGuest.id,
  );

  TestValidator.predicate(
    "deleted guest user should no longer appear in guest user listings",
    existsAfterDeletion === false,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestuser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate deletion behavior for non-existent guest user identities.
 *
 * Business goal: Ensure that when an authenticated todoAdmin attempts to delete
 * a guest user by an id that does not exist in `todo_app_guestusers`, the
 * system:
 *
 * - Fails the operation (throws an error from the SDK), and
 * - Does not delete or mutate any existing guest user records.
 *
 * Test workflow:
 *
 * 1. Register a new todoAdmin using /auth/todoAdmin/join to obtain an
 *    authenticated administrative context (SDK sets Authorization header).
 * 2. Fetch a baseline snapshot of guest users via /todoApp/todoAdmin/guestUsers
 *    (PATCH) with deterministic pagination (e.g., page=1, limit=10). Capture:
 *
 *    - The full response object as `beforePage`.
 *    - The list of guest user ids from `beforePage.data`.
 * 3. Generate a random UUID and ensure it does not collide with any id in the
 *    first page snapshot (loop until unique vs the captured id list).
 * 4. Attempt to delete this non-existent guest user via DELETE
 *    /todoApp/todoAdmin/guestUsers/{guestUserId} using
 *    api.functional.todoApp.todoAdmin.guestUsers.erase.
 *
 *    - Wrap the call inside TestValidator.error with an async callback and await the
 *         validator call so we assert that some error is thrown.
 *    - We do not inspect HTTP status or error payload; only that an error occurs for
 *         the non-existent resource.
 * 5. Re-fetch the first page of guest users with the same filter as step 2 into
 *    `afterPage`.
 * 6. Validate that there were no deletions or unintended mutations:
 *
 *    - TestValidator.equals("records count unchanged", afterPage.pagination.records,
 *         beforePage.pagination.records).
 *    - TestValidator.equals("first page ids unchanged", afterIds, beforeIds), where
 *         `beforeIds` and `afterIds` are the arrays of id strings for the first
 *         page.
 *
 * Technical notes:
 *
 * - Use ITodoAppTodoAdminJoin.IRequest for join body with typia.random.
 * - Use ITodoAppGuestUser.IRequest for guestUsers.index body with explicit page
 *   and limit to make comparisons deterministic.
 * - Use typia.assert for ITodoAppTodoAdmin.IAuthorized and
 *   IPageITodoAppGuestuser.ISummary responses.
 * - Never touch connection.headers manually; rely on the SDK for auth.
 * - Avoid any HTTP status-specific expectations; only assert that the deletion
 *   attempt fails and that data remains stable.
 */
export async function test_api_todoadmin_delete_guest_user_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin to obtain an authenticated context
  const joinBody = typia.random<ITodoAppTodoAdminJoin.IRequest>();
  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Fetch baseline guest users page (deterministic pagination)
  const beforePage: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32">,
        limit: 10 as number & tags.Type<"int32">,
      } satisfies ITodoAppGuestUser.IRequest,
    });
  typia.assert(beforePage);

  const beforeIds: (string & tags.Format<"uuid">)[] = beforePage.data.map(
    (g) => g.id,
  );

  // 3. Generate a UUID that does not collide with any id in the first page
  let nonExistingId: string & tags.Format<"uuid">;
  while (true) {
    const candidate = typia.random<string & tags.Format<"uuid">>();
    if (beforeIds.includes(candidate) === false) {
      nonExistingId = candidate;
      break;
    }
  }

  // 4. Attempt to delete the non-existent guest user and assert error
  await TestValidator.error(
    "deleting non-existent guest user must fail",
    async () => {
      await api.functional.todoApp.todoAdmin.guestUsers.erase(connection, {
        guestUserId: nonExistingId,
      });
    },
  );

  // 5. Re-fetch guest users with the same pagination filter
  const afterPage: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.todoAdmin.guestUsers.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32">,
        limit: 10 as number & tags.Type<"int32">,
      } satisfies ITodoAppGuestUser.IRequest,
    });
  typia.assert(afterPage);

  const afterIds: (string & tags.Format<"uuid">)[] = afterPage.data.map(
    (g) => g.id,
  );

  // 6. Assert that counts and first-page ids are unchanged
  TestValidator.equals(
    "guest user records count must remain unchanged after failed delete",
    afterPage.pagination.records,
    beforePage.pagination.records,
  );

  TestValidator.equals(
    "first page guest user ids must remain unchanged after failed delete",
    afterIds,
    beforeIds,
  );
}

