/**
 * Validate listing of todoAdmin administrator accounts with basic search and
 * pagination.
 *
 * Business goal: Ensure that an authenticated todoAdmin can call PATCH
 * /todoApp/todoAdmin/todoAdmins to retrieve a paginated list of administrator
 * summaries filtered by a search term, and that the response type and
 * pagination metadata align with the documented DTOs.
 *
 * Steps:
 *
 * 1. Register a primary todoAdmin via /auth/todoAdmin/join. This both creates an
 *    admin record and authenticates the connection as that admin.
 * 2. Optionally register a second todoAdmin to make the dataset less trivial.
 * 3. While authenticated as an admin, create a Todo status via
 *    /todoApp/todoAdmin/todoStatuses to simulate a minimally configured
 *    system.
 * 4. Register a todoUser via /auth/todoUser/join and create at least one Todo via
 *    /todoApp/todoUser/todos/create to ensure the system has operational data
 *    (not directly used by listing, but makes the test environment more
 *    realistic).
 * 5. Re-authenticate as the primary admin using /auth/todoAdmin/login, so the
 *    Authorization header contains the admin token when we call the listing
 *    endpoint.
 * 6. Call api.functional.todoApp.todoAdmin.todoAdmins.index with a body satisfying
 *    ITodoAppTodoAdmin.IRequest, specifying page and limit (e.g. page=1,
 *    limit=10) and a search term which matches the primary admin’s email or
 *    display_name.
 * 7. Assert that the response matches IPageITodoAppTodoadmin.ISummary via
 *    typia.assert and then:
 *
 *    - Pagination.current is a non-negative integer
 *    - Pagination.limit equals the requested limit
 *    - Pagination.records >= data.length
 *    - When data is non-empty, pagination.pages >= 1
 *    - Data array is non-empty
 *    - At least one summary in data matches the primary admin’s id and email
 *    - Summaries expose only non-sensitive fields as per ITodoAppTodoAdmin.ISummary
 *         (typia.assert already guarantees structure).
 * 8. Call the same endpoint again with a non-matching search term and assert that
 *    either the result set does not include the primary admin or is empty,
 *    demonstrating that search filtering is effective.
 */
export async function test_api_todoadmin_list_admin_accounts_basic_search(
  connection: api.IConnection,
) {
  // 1. Register primary todoAdmin (join acts as registration + authentication).
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    displayName: RandomGenerator.name(2),
    ip: null,
    href: "https://todo-app.example.com/admin/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const primaryAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(primaryAdmin);

  // 2. Optionally register a secondary admin to enrich listing.
  const secondaryAdminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const secondaryAdminPassword: string = RandomGenerator.alphaNumeric(12);

  const secondaryAdminBody = {
    email: secondaryAdminEmail,
    password: secondaryAdminPassword,
    displayName: RandomGenerator.name(2),
    ip: null,
    href: "https://todo-app.example.com/admin/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const secondaryAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: secondaryAdminBody,
    });
  typia.assert(secondaryAdmin);

  // 3. Create at least one Todo status as admin.
  const statusBody = {
    code: `STATUS_${RandomGenerator.alphaNumeric(8)}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusBody,
    });
  typia.assert(status);

  // 4. Register todoUser and create at least one Todo
  const userEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const userPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const userJoinBody = {
    email: userEmail,
    password: userPassword,
    display_name: RandomGenerator.name(2),
    ip: null,
    href: "https://todo-app.example.com/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUser: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(todoUser);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: new Date().toISOString() as string & tags.Format<"date-time">,
    status_code: status.code,
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo = await api.functional.todoApp.todoUser.todos.create(
    connection,
    {
      body: todoCreateBody,
    },
  );
  typia.assert(todo);

  // 5. Re-authenticate as primary admin using login
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://todo-app.example.com/admin/login",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const loggedInAdmin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(loggedInAdmin);

  // 6. Call listing with a matching search term (use part of adminEmail)
  const searchTerm = adminEmail.split("@")[0];

  const listRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    search: searchTerm,
    status: null,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppTodoAdmin.IRequest;

  const pageResult: IPageITodoAppTodoadmin.ISummary =
    await api.functional.todoApp.todoAdmin.todoAdmins.index(connection, {
      body: listRequestBody,
    });
  typia.assert(pageResult);

  const pagination = pageResult.pagination;
  const admins = pageResult.data;

  // 7. Business assertions on pagination and data
  TestValidator.predicate(
    "pagination.current should be non-negative",
    pagination.current >= 0,
  );
  TestValidator.equals(
    "pagination.limit should equal requested limit",
    pagination.limit,
    listRequestBody.limit,
  );
  TestValidator.predicate(
    "pagination.records should be >= data.length",
    pagination.records >= admins.length,
  );
  TestValidator.predicate(
    "admins array should be non-empty for matching search term",
    admins.length > 0,
  );

  const foundPrimary = admins.find(
    (a) => a.id === primaryAdmin.id && a.email === primaryAdmin.email,
  );

  TestValidator.predicate(
    "listing should contain primary admin matching id and email",
    foundPrimary !== undefined,
  );

  if (admins.length > 0) {
    TestValidator.predicate(
      "pagination.pages should be at least 1 when data is non-empty",
      pagination.pages >= 1,
    );
  }

  // 8. Call listing with a non-matching search term and ensure primary admin is not returned
  const nonMatchingSearch = `nonexistent_${RandomGenerator.alphaNumeric(8)}`;

  const nonMatchRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    search: nonMatchingSearch,
    status: null,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppTodoAdmin.IRequest;

  const nonMatchResult: IPageITodoAppTodoadmin.ISummary =
    await api.functional.todoApp.todoAdmin.todoAdmins.index(connection, {
      body: nonMatchRequestBody,
    });
  typia.assert(nonMatchResult);

  const nonMatchAdmins = nonMatchResult.data;

  const stillContainsPrimary = nonMatchAdmins.some(
    (a) => a.id === primaryAdmin.id && a.email === primaryAdmin.email,
  );

  TestValidator.predicate(
    "non-matching search should not return primary admin in results",
    !stillContainsPrimary,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodoadmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoadmin";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Verify that the admin listing endpoint correctly filters administrator
 * accounts by lifecycle status and that pagination metadata reflects the
 * filtered result set.
 *
 * Business context:
 *
 * - Admin operators (todoAdmin) need to search and list other admin accounts.
 * - The listing endpoint supports filtering by lifecycle status (e.g., "active",
 *   "suspended").
 * - The response is a paginated collection of ITodoAppTodoAdmin.ISummary with
 *   IPage.IPagination metadata.
 *
 * Test workflow (single E2E scenario):
 *
 * 1. Create two todoAdmin accounts via /auth/todoAdmin/join with distinct emails.
 *    The backend initializes their lifecycle status (likely "active" by
 *    default).
 * 2. Authenticate as the first admin (using login) so subsequent calls run in an
 *    admin context.
 * 3. Create at least one Todo status via /todoApp/todoAdmin/todoStatuses to
 *    simulate realistic configuration.
 * 4. Create a todoUser via /auth/todoUser/join and a Todo via
 *    /todoApp/todoUser/todos to simulate business data existing in the system;
 *    this does not affect the admin listing directly, but ensures realistic
 *    environment.
 * 5. Call PATCH /todoApp/todoAdmin/todoAdmins with status filter equal to a known
 *    status value (e.g., "active"), and a small pagination limit (e.g., 10).
 * 6. Assert that:
 *
 *    - The response type matches IPageITodoAppTodoadmin.ISummary via typia.assert.
 *    - Every ITodoAppTodoAdmin.ISummary in data has status === requested status.
 *    - At least one admin is returned when using a status that matches created
 *         admins.
 *    - Pagination metadata (pagination.records and pagination.pages) is consistent
 *         with the size of data for the requested page (e.g., records >=
 *         data.length, pages >= 1, current and limit non-negative).
 * 7. Optionally, perform a second call with a different status filter value that
 *    is unlikely to match (e.g., "suspended") and assert that data is empty and
 *    pagination.records is 0 or at least coherent with zero matches.
 *
 * Constraints and notes:
 *
 * - We do not have an explicit API to mutate admin status after creation, so we
 *   rely on whatever status the backend assigns (commonly "active") and filter
 *   using that value.
 * - We must use the concrete DTO types: ITodoAppTodoAdmin.IRequest as the body
 *   for the listing call, and IPageITodoAppTodoadmin.ISummary as the response
 *   type.
 * - We must not touch connection.headers directly; authentication is handled
 *   automatically by join/login SDKs.
 */
export async function test_api_todoadmin_list_admin_accounts_filtered_by_status(
  connection: api.IConnection,
) {
  // 1. Register two todoAdmin accounts with different emails
  const adminJoinBody1 = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminJoinBody2 = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin1: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody1,
    });
  typia.assert(admin1);

  const admin2: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody2,
    });
  typia.assert(admin2);

  // 2. Authenticate explicitly as the first admin (login), even though join already authenticates,
  //    to exercise login flow and ensure admin context is active.
  const adminLoginBody = {
    email: admin1.email,
    password: adminJoinBody1.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminLogin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLogin);

  // 3. Create a Todo status to ensure configuration exists
  const todoStatusBody = {
    code: `STATUS_${RandomGenerator.alphaNumeric(8)}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: null,
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const todoStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: todoStatusBody,
    });
  typia.assert(todoStatus);

  // 4. Create a todoUser and a Todo for realistic environment
  const todoUserJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://app.example.com/join",
    referrer: "https://app.example.com/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUser: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: todoUserJoinBody,
    });
  typia.assert(todoUser);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: new Date().toISOString() as string & tags.Format<"date-time">,
    status_code: todoStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo = await api.functional.todoApp.todoUser.todos.create(
    connection,
    {
      body: todoCreateBody,
    },
  );
  typia.assert(todo);

  // 5. Call admin listing endpoint with a known status filter (admin1.status)
  const targetStatus: string = admin1.status;

  const listRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    search: null,
    status: targetStatus,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppTodoAdmin.IRequest;

  const pageResult: IPageITodoAppTodoadmin.ISummary =
    await api.functional.todoApp.todoAdmin.todoAdmins.index(connection, {
      body: listRequestBody,
    });
  typia.assert(pageResult);

  const pagination = pageResult.pagination;
  const admins = pageResult.data;

  // Basic sanity checks on pagination
  TestValidator.predicate(
    "pagination current page is non-negative",
    pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit is non-negative",
    pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    pagination.pages >= 0,
  );

  // Assert that all returned admins match the status filter
  for (const summary of admins) {
    TestValidator.equals(
      "admin summary status matches filter",
      summary.status,
      targetStatus,
    );
  }

  // Ensure at least one admin is returned for the known status when possible
  TestValidator.predicate(
    "at least one admin with target status should be returned (including the ones we created)",
    admins.length >= 1,
  );

  // 6. Optionally test a different status filter that likely yields zero results
  const unlikelyStatus = `${targetStatus}_NON_EXISTENT`; // unlikely to exist

  const listRequestBodyUnlikely = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    search: null,
    status: unlikelyStatus,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppTodoAdmin.IRequest;

  const pageResultUnlikely: IPageITodoAppTodoadmin.ISummary =
    await api.functional.todoApp.todoAdmin.todoAdmins.index(connection, {
      body: listRequestBodyUnlikely,
    });
  typia.assert(pageResultUnlikely);

  TestValidator.equals(
    "no admins should match unlikely status filter",
    pageResultUnlikely.data.length,
    0,
  );

  TestValidator.predicate(
    "pagination records for unlikely status is coherent (>= data length)",
    pageResultUnlikely.pagination.records >= pageResultUnlikely.data.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppActorSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorSession";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

export async function test_api_todo_admin_actor_session_detail_view_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin to obtain authorized context and tokens.
  //    join() will also set connection.headers.Authorization automatically.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    // Use plausible URLs for href and referrer.
    href: "https://console.todoapp.example.com/admin/join",
    referrer: "https://console.todoapp.example.com/landing",
    // Optional ip; can be null or omitted. Here we send a realistic IPv4.
    ip: "203.0.113.10",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // Sanity: token must look non-empty; rely on type-level structure plus
  // a basic business-level predicate.
  TestValidator.predicate(
    "admin token access must be non-empty",
    () => admin.token.access.length > 0,
  );

  // 2. Generate a sessionId to query.
  //    In real systems this would come from a session search/list endpoint or
  //    from decoded token context, but such APIs are not provided here. We
  //    therefore use a random UUID consistent with the mock test pattern and
  //    rely on the backend or simulator to provide a corresponding session
  //    record.
  const sessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 3. Call the admin-only session detail endpoint.
  const session: ITodoAppActorSession =
    await api.functional.todoApp.todoAdmin.actors.sessions.at(connection, {
      sessionId,
    });
  typia.assert<ITodoAppActorSession>(session);

  // 4. Business-level validations on the returned session.
  // 4-1. The session id in the payload should match the id we requested.
  TestValidator.equals(
    "session.id must match requested sessionId",
    session.id,
    sessionId,
  );

  // 4-2. actorType should be one of the logical categories described by
  //      ITodoAppActorSession documentation.
  const allowedActorTypes = ["admin", "user", "guest"] as const;
  TestValidator.predicate("actorType must be one of admin|user|guest", () =>
    (allowedActorTypes as readonly string[]).includes(session.actorType),
  );

  // 4-3. actorId is a non-empty UUID-shaped string (format is already
  //      validated by typia; here we only require non-empty for business
  //      semantics).
  TestValidator.predicate(
    "actorId must be non-empty string",
    () => session.actorId.length > 0,
  );

  // 4-4. Core metadata fields must be non-empty strings.
  TestValidator.predicate("ip must be non-empty", () => session.ip.length > 0);
  TestValidator.predicate(
    "href must be non-empty",
    () => session.href.length > 0,
  );
  TestValidator.predicate(
    "referrer must be non-empty",
    () => session.referrer.length > 0,
  );
  TestValidator.predicate(
    "createdAt must be non-empty",
    () => session.createdAt.length > 0,
  );

  // 5. Read-only semantics: calling the endpoint twice for the same id should
  //    not change the data, so the second response should equal the first.
  const sessionAgain: ITodoAppActorSession =
    await api.functional.todoApp.todoAdmin.actors.sessions.at(connection, {
      sessionId,
    });
  typia.assert<ITodoAppActorSession>(sessionAgain);

  TestValidator.equals(
    "re-fetching the same session must return identical data (read-only)",
    sessionAgain,
    session,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppActorSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorSession";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";

/**
 * Validate that requesting a non-existent actor session as a todoAdmin
 * administrator does not succeed and does not return any session payload.
 *
 * Business context:
 *
 * - TodoAdmin operators can inspect actor sessions via GET
 *   /todoApp/todoAdmin/actors/sessions/{sessionId} for security and auditing
 *   purposes.
 * - When an admin queries a sessionId that does not exist in any of the
 *   underlying session tables, the system must fail the request rather than
 *   returning fabricated or misleading session data.
 *
 * This test covers the negative path where a validly authenticated admin calls
 * the detail endpoint with a random UUID that should not correspond to any real
 * session record.
 *
 * Steps:
 *
 * 1. Register a new todoAdmin account using POST /auth/todoAdmin/join, which also
 *    authenticates the connection by setting the Authorization header via the
 *    SDK.
 * 2. Generate a random UUID value to use as a non-existent sessionId.
 * 3. Invoke GET /todoApp/todoAdmin/actors/sessions/{sessionId} with this random
 *    UUID.
 * 4. Use TestValidator.error to assert that the call fails, ensuring that no
 *    ITodoAppActorSession instance is returned for the bogus sessionId.
 */
export async function test_api_todo_admin_actor_session_detail_not_found(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a todoAdmin operator.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://admin.todoapp.example.com/register",
    referrer: "https://admin.todoapp.example.com/login",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin = await api.functional.auth.todoAdmin.join(connection, {
    body: joinBody,
  });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // 2. Generate a random UUID that should not match any real session.
  const nonExistentSessionId = typia.random<string & tags.Format<"uuid">>();

  // 3 & 4. Expect an error when querying a non-existent session.
  await TestValidator.error(
    "requesting a non-existent actor session should fail",
    async () => {
      await api.functional.todoApp.todoAdmin.actors.sessions.at(connection, {
        sessionId: nonExistentSessionId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
