import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";

export async function test_api_todo_admin_actor_session_detail_forbidden_for_non_admin(
  connection: api.IConnection,
) {
  // 1. Prepare base unauthenticated connection to avoid header side effects
  const baseConnection: api.IConnection = { ...connection, headers: {} };

  // 2. Register a todoUser and obtain its authorized context (and token)
  const todoUserJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://todo-app.example.com/signup",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(baseConnection, {
      body: todoUserJoinBody,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(todoUserAuthorized);

  // At this point, baseConnection.headers.Authorization contains the todoUser token

  // 3. Register a todoAdmin in a separate connection so that an admin exists
  const adminConnection: api.IConnection = { ...connection, headers: {} };

  const todoAdminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://todo-app.example.com/admin/signup",
    referrer: "https://todo-app.example.com/admin/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const todoAdminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(adminConnection, {
      body: todoAdminJoinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(todoAdminAuthorized);

  // 4. With todoUser-authenticated connection, attempt to call admin-only session detail API
  const userAuthConnection: api.IConnection = baseConnection;

  const targetSessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.httpError(
    "non-admin todoUser cannot access admin actor session detail",
    403,
    async () => {
      await api.functional.todoApp.todoAdmin.actors.sessions.at(
        userAuthConnection,
        {
          sessionId: targetSessionId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Basic pagination and filtering behavior for todoUser todo listing.
 *
 * This E2E test exercises the core happy-path flow for listing todos belonging
 * to a single authenticated todo user through `PATCH /todoApp/todoUser/todos`.
 *
 * Business steps
 *
 * 1. Register a todoAdmin and obtain admin authorization context.
 * 2. As todoAdmin, register a default active Todo status (e.g. `ACTIVE`).
 * 3. Register a todoUser and obtain user authorization context.
 * 4. As todoUser, create multiple Todo items with varying titles and due dates,
 *    some explicitly specifying `status_code` and some relying on the default.
 * 5. Call the list endpoint with explicit pagination (page=1, limit=2) and no
 *    additional filters and validate pagination metadata and contents.
 * 6. Optionally, call the list endpoint again with page=2 to validate second-page
 *    behavior and the boundary on the last page.
 */
export async function test_api_todo_user_todo_list_basic_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register todoAdmin
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://todo-app.local/admin/join",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create a default active Todo status as todoAdmin
  const statusCode = "ACTIVE";
  const statusCreateBody = {
    code: statusCode,
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(createdStatus);

  TestValidator.equals(
    "created status code should match request",
    createdStatus.code,
    statusCreateBody.code,
  );
  TestValidator.predicate(
    "created status should be default and active",
    createdStatus.is_default === true && createdStatus.is_active === true,
  );

  // 3. Register and authenticate todoUser
  const userEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const userJoinBody = {
    email: userEmail,
    password: RandomGenerator.alphabets(12) as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://todo-app.local/join",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userAuthorized);

  // Ensure login also works (refreshes token) – though join already authenticated
  const userLoginBody = {
    email: userEmail,
    password: userJoinBody.password,
    ip: "127.0.0.1",
    href: "https://todo-app.local/login",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const userAuthorizedFromLogin: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userLoginBody,
    });
  typia.assert(userAuthorizedFromLogin);

  TestValidator.equals(
    "joined user id should match logged-in user id",
    userAuthorizedFromLogin.id,
    userAuthorized.id,
  );

  // 4. As todoUser, create multiple todos
  const totalTodos = 4;
  const createdTodos: ITodoAppTodo[] = [];

  for (let i = 0; i < totalTodos; i++) {
    const title = `Todo #${i + 1} - ${RandomGenerator.paragraph({
      sentences: 1,
      wordMin: 3,
      wordMax: 6,
    })}`;

    const baseDate = new Date();
    const dueDate: string & tags.Format<"date-time"> = RandomGenerator.date(
      baseDate,
      1000 * 60 * 60 * 24 * 7,
    ).toISOString();

    const createBody = {
      title,
      description:
        i % 2 === 0 ? RandomGenerator.paragraph({ sentences: 2 }) : null,
      due_date: dueDate,
      status_code: i % 2 === 0 ? statusCode : null,
    } satisfies ITodoAppTodo.ICreate;

    const created: ITodoAppTodo =
      await api.functional.todoApp.todoUser.todos.create(connection, {
        body: createBody,
      });
    typia.assert(created);

    createdTodos.push(created);
  }

  TestValidator.equals(
    "should have created expected number of todos",
    createdTodos.length,
    totalTodos,
  );

  // 5. List todos - page 1, limit 2, no filters
  const listRequestPage1 = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
  } satisfies ITodoAppTodo.IRequest;

  const page1: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.todoUser.todos.index(connection, {
      body: listRequestPage1,
    });
  typia.assert(page1);

  const pagination1 = page1.pagination;
  const data1 = page1.data;

  TestValidator.equals(
    "pagination current page should be 1-based index minus one (0)",
    pagination1.current,
    0,
  );
  TestValidator.equals(
    "pagination limit should match requested limit",
    pagination1.limit,
    listRequestPage1.limit,
  );
  TestValidator.equals(
    "pagination records should be at least created todos",
    pagination1.records >= totalTodos,
    true,
  );
  TestValidator.equals(
    "first page data length should equal limit or remaining records",
    data1.length,
    Math.min(listRequestPage1.limit, pagination1.records),
  );

  // Validate summary fields for each item
  for (const summary of data1) {
    const s: ITodoAppTodo.ISummary = summary;
    typia.assert<ITodoAppTodo.ISummary>(s);

    TestValidator.predicate(
      "summary id must be a non-empty uuid string",
      typeof s.id === "string" && s.id.length > 0,
    );
    TestValidator.predicate(
      "summary title must be non-empty",
      typeof s.title === "string" && s.title.trim().length > 0,
    );
    TestValidator.predicate(
      "summary status must be non-empty string",
      typeof s.status === "string" && s.status.length > 0,
    );
  }

  // 6. Optionally list page 2 to verify boundary behavior
  if (pagination1.pages > 1) {
    const listRequestPage2 = {
      page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
      limit: listRequestPage1.limit,
    } satisfies ITodoAppTodo.IRequest;

    const page2: IPageITodoAppTodo.ISummary =
      await api.functional.todoApp.todoUser.todos.index(connection, {
        body: listRequestPage2,
      });
    typia.assert(page2);

    const pagination2 = page2.pagination;
    const data2 = page2.data;

    TestValidator.equals(
      "second page current index should be 1",
      pagination2.current,
      1,
    );
    TestValidator.equals(
      "second page limit should match requested limit",
      pagination2.limit,
      listRequestPage2.limit,
    );

    TestValidator.predicate(
      "second page data length must be > 0 when pages > 1",
      data2.length > 0,
    );

    for (const summary of data2) {
      const s: ITodoAppTodo.ISummary = summary;
      typia.assert<ITodoAppTodo.ISummary>(s);
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

export async function test_api_todo_user_todo_list_filters_by_status_and_title(
  connection: api.IConnection,
) {
  // 1. Admin joins to configure statuses
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: RandomGenerator.alphaNumeric(8),
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates two active statuses: ACTIVE and COMPLETED
  const activeStatusBody = {
    code: "ACTIVE",
    label: "Active",
    description: "Active todos",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusBody,
    });
  typia.assert(activeStatus);

  const completedStatusBody = {
    code: "COMPLETED",
    label: "Completed",
    description: "Completed todos",
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const completedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: completedStatusBody,
    });
  typia.assert(completedStatus);

  // 3. Todo user joins
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: RandomGenerator.alphaNumeric(8),
    href: "https://todo-app.local/join",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(todoUserAuthorized);

  // 4. Seed todos as this user
  const keyword = "project";

  const buildTitleWithKeyword = (suffix: string): string =>
    `${RandomGenerator.paragraph({ sentences: 1 })} ${keyword} ${suffix}`;
  const buildTitleWithoutKeyword = (suffix: string): string =>
    `${RandomGenerator.paragraph({ sentences: 2 })} ${suffix}`;

  const todosWithKeywordAndActive: ITodoAppTodo[] = [];
  const todosCompletedOrNoKeyword: ITodoAppTodo[] = [];

  // Create 3 ACTIVE todos with keyword
  for (let i = 0; i < 3; i++) {
    const todoBody = {
      title: buildTitleWithKeyword(`#${i + 1}`),
      description: RandomGenerator.paragraph({ sentences: 3 }),
      due_date: null,
      status_code: "ACTIVE",
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.todoUser.todos.create(connection, {
        body: todoBody,
      });
    typia.assert(todo);
    todosWithKeywordAndActive.push(todo);
  }

  // Create 2 COMPLETED todos with keyword (should be excluded by status filter)
  for (let i = 0; i < 2; i++) {
    const todoBody = {
      title: buildTitleWithKeyword(`COMPLETED-${i + 1}`),
      description: RandomGenerator.paragraph({ sentences: 3 }),
      due_date: null,
      status_code: "COMPLETED",
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.todoUser.todos.create(connection, {
        body: todoBody,
      });
    typia.assert(todo);
    todosCompletedOrNoKeyword.push(todo);
  }

  // Create 2 ACTIVE todos without keyword (should be excluded by title filter)
  for (let i = 0; i < 2; i++) {
    const todoBody = {
      title: buildTitleWithoutKeyword(`NO-KW-${i + 1}`),
      description: RandomGenerator.paragraph({ sentences: 2 }),
      due_date: null,
      status_code: "ACTIVE",
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.todoUser.todos.create(connection, {
        body: todoBody,
      });
    typia.assert(todo);
    todosCompletedOrNoKeyword.push(todo);
  }

  const expectedMatchingIds = todosWithKeywordAndActive.map((t) => t.id);

  // 5. Call the index endpoint with statusCodes=["ACTIVE"] and titleKeyword
  const requestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    statusCodes: ["ACTIVE"],
    titleKeyword: keyword,
  } satisfies ITodoAppTodo.IRequest;

  const page: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.todoUser.todos.index(connection, {
      body: requestBody,
    });
  typia.assert(page);

  const pagination = page.pagination;
  const summaries = page.data;

  // 6. Verify that every item matches both filters
  for (const summary of summaries) {
    TestValidator.equals(
      "status code should be ACTIVE",
      summary.status,
      "ACTIVE",
    );

    if (summary.statusInfo !== undefined) {
      TestValidator.equals(
        "statusInfo.code should be ACTIVE",
        summary.statusInfo.code,
        "ACTIVE",
      );
    }

    TestValidator.predicate(
      "title should contain keyword",
      summary.title.toLowerCase().includes(keyword.toLowerCase()),
    );
  }

  // 7. Verify that completed or non-keyword todos are not present
  const returnedIds = summaries.map((s) => s.id);

  for (const excluded of todosCompletedOrNoKeyword) {
    TestValidator.predicate(
      "non-matching todos should not be in the result",
      returnedIds.includes(excluded.id) === false,
    );
  }

  // 8. Validate pagination metadata
  const expectedCount = expectedMatchingIds.length;

  TestValidator.predicate(
    "pagination current page index should be non-negative",
    pagination.current >= 0,
  );

  TestValidator.predicate(
    "pagination limit should be positive and at least number of returned items",
    pagination.limit > 0 && pagination.limit >= summaries.length,
  );

  TestValidator.equals(
    "pagination.records should equal count of matching todos",
    pagination.records,
    expectedCount,
  );

  TestValidator.predicate(
    "pagination.pages should be zero when no records, otherwise at least one",
    expectedCount === 0 ? pagination.pages === 0 : pagination.pages >= 1,
  );

  TestValidator.predicate(
    "number of returned items should be <= requested limit",
    summaries.length <= requestBody.limit!,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

export async function test_api_todo_user_todo_list_respects_date_range_filters(
  connection: api.IConnection,
) {
  /** 1. Register an admin (todoAdmin) to configure a default ACTIVE status. */
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  /**
   * 2. Admin creates a default ACTIVE todo status so user todos have a valid
   *    status.
   */
  const statusCreateBody = {
    code: "ACTIVE",
    label: "Active",
    description: "Default active status for todos",
    group: "core",
    sort_order: 1,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(status);

  /** 3. TodoUser joins; SDK switches Authorization to this user. */
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = typia.assert<string & tags.Format<"password">>(
    RandomGenerator.alphaNumeric(12),
  );

  const userJoinBody = {
    email: userEmail,
    password: userPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/join",
    referrer: "https://landing.todo-app.test/",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userAuthorized);

  /** 4. As todoUser, create several todos with different due_date values. */
  const nowBefore = new Date();

  const nearDueDate = new Date(nowBefore.getTime() + 2 * 24 * 60 * 60 * 1000);
  const farDueDate = new Date(nowBefore.getTime() + 30 * 24 * 60 * 60 * 1000);

  const todoBodies = [
    {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
      due_date: nearDueDate.toISOString(),
      status_code: status.code,
    },
    {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
      due_date: farDueDate.toISOString(),
      status_code: status.code,
    },
    {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
      due_date: null,
      status_code: status.code,
    },
  ] satisfies ITodoAppTodo.ICreate[];

  const createdTodos: ITodoAppTodo[] = [];
  for (const body of todoBodies) {
    const created: ITodoAppTodo =
      await api.functional.todoApp.todoUser.todos.create(connection, {
        body,
      });
    typia.assert(created);
    createdTodos.push(created);
  }

  const nowAfter = new Date();

  /** Build createdAt filter range that should include all created todos. */
  const createdFrom = new Date(nowBefore.getTime() - 1_000).toISOString();
  const createdTo = new Date(nowAfter.getTime() + 1_000).toISOString();

  /** 5. Query with only createdAt range filters. */
  const createdRangeRequest = {
    createdFrom,
    createdTo,
    dueFrom: null,
    dueTo: null,
    includeDeleted: false,
    orderBy: "createdAt" as const,
    orderDirection: "asc" as const,
  } satisfies ITodoAppTodo.IRequest;

  const createdRangePage: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.todoUser.todos.index(connection, {
      body: createdRangeRequest,
    });
  typia.assert(createdRangePage);

  for (const summary of createdRangePage.data) {
    const createdAtDate = new Date(summary.created_at);
    TestValidator.predicate(
      "created_at is within createdFrom/createdTo range",
      createdAtDate.getTime() >= new Date(createdFrom).getTime() &&
        createdAtDate.getTime() <= new Date(createdTo).getTime(),
    );
  }

  /** 6. Query with only due_date range, targeting the nearDueDate todo. */
  const dueWindowFrom = new Date(
    nearDueDate.getTime() - 12 * 60 * 60 * 1000,
  ).toISOString();
  const dueWindowTo = new Date(
    nearDueDate.getTime() + 12 * 60 * 60 * 1000,
  ).toISOString();

  const dueRangeRequest = {
    createdFrom: null,
    createdTo: null,
    dueFrom: dueWindowFrom,
    dueTo: dueWindowTo,
    includeDeleted: false,
    orderBy: "dueDate" as const,
    orderDirection: "asc" as const,
  } satisfies ITodoAppTodo.IRequest;

  const dueRangePage: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.todoUser.todos.index(connection, {
      body: dueRangeRequest,
    });
  typia.assert(dueRangePage);

  for (const summary of dueRangePage.data) {
    TestValidator.predicate(
      "due_date is defined when filtering by due range",
      summary.due_date !== undefined && summary.due_date !== null,
    );

    if (summary.due_date !== undefined && summary.due_date !== null) {
      const dueDateValue = new Date(summary.due_date);
      TestValidator.predicate(
        "due_date is within dueFrom/dueTo range",
        dueDateValue.getTime() >= new Date(dueWindowFrom).getTime() &&
          dueDateValue.getTime() <= new Date(dueWindowTo).getTime(),
      );
    }
  }

  /** 7. Query with both createdAt and due_date ranges to produce a precise subset. */
  const combinedRequest = {
    createdFrom,
    createdTo,
    dueFrom: dueWindowFrom,
    dueTo: dueWindowTo,
    includeDeleted: false,
    orderBy: "createdAt" as const,
    orderDirection: "asc" as const,
  } satisfies ITodoAppTodo.IRequest;

  const combinedPage: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.todoUser.todos.index(connection, {
      body: combinedRequest,
    });
  typia.assert(combinedPage);

  // Compute expected subset using the locally created todos.
  const expectedCombined = createdTodos.filter((todo) => {
    const createdAtMs = new Date(todo.created_at).getTime();
    const inCreatedRange =
      createdAtMs >= new Date(createdFrom).getTime() &&
      createdAtMs <= new Date(createdTo).getTime();

    const dueRaw = todo.due_date ?? null;
    if (dueRaw === null) return false;

    const dueMs = new Date(dueRaw).getTime();
    const inDueRange =
      dueMs >= new Date(dueWindowFrom).getTime() &&
      dueMs <= new Date(dueWindowTo).getTime();

    return inCreatedRange && inDueRange;
  });

  TestValidator.equals(
    "pagination.records matches expected filtered todo count",
    combinedPage.pagination.records,
    expectedCombined.length,
  );
  TestValidator.equals(
    "data length matches expected filtered todo count",
    combinedPage.data.length,
    expectedCombined.length,
  );

  const expectedIds = expectedCombined.map((t) => t.id);
  for (const summary of combinedPage.data) {
    TestValidator.predicate(
      "combined filter result todo id is in expected subset",
      expectedIds.includes(summary.id),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

export async function test_api_todo_user_todo_list_excludes_soft_deleted_by_default(
  connection: api.IConnection,
) {
  // 1. Admin joins to obtain admin auth context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.local/join",
    referrer: "https://admin.todo-app.local/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an ACTIVE default status for todos
  const todoStatusCreateBody = {
    code: "ACTIVE",
    label: "Active",
    description: "Active todo status used as default for new items",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: todoStatusCreateBody,
    });
  typia.assert(activeStatus);
  TestValidator.equals(
    "created status code should be ACTIVE",
    activeStatus.code,
    todoStatusCreateBody.code,
  );
  TestValidator.predicate(
    "status should be default and active",
    activeStatus.is_default === true && activeStatus.is_active === true,
  );

  // 3. Todo user joins (self-registration) and is authenticated
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.local/join",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(todoUserAuthorized);

  // 4. Create multiple todos for this user
  const todoCount = 5;
  const createdTodos: ITodoAppTodo[] = [];

  for (let i = 0; i < todoCount; ++i) {
    const createTodoBody = {
      title: `Todo item ${i + 1}`,
      description: RandomGenerator.paragraph({ sentences: 4 }),
      due_date: new Date(
        Date.now() + 1000 * 60 * 60 * 24 * (i + 1),
      ).toISOString(),
      status_code: activeStatus.code,
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.todoUser.todos.create(connection, {
        body: createTodoBody,
      });
    typia.assert(todo);
    createdTodos.push(todo);
  }

  TestValidator.equals(
    "should have created expected number of todos",
    createdTodos.length,
    todoCount,
  );

  const createdTodoIds = createdTodos.map((t) => t.id);

  // 5. Soft-delete a subset of todos (e.g., first 2)
  const deletedTodos = createdTodos.slice(0, 2);
  const activeTodos = createdTodos.slice(2);

  for (const deleted of deletedTodos) {
    await api.functional.todoApp.todoUser.todos.erase(connection, {
      todoId: deleted.id,
    });
  }

  // 6. List todos without includeDeleted (default behavior)
  const listWithoutDeletedRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: (todoCount + 5) as number & tags.Type<"int32"> & tags.Minimum<1>,
    includeDeleted: undefined,
  } satisfies ITodoAppTodo.IRequest;

  const pageWithoutDeleted: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.todoUser.todos.index(connection, {
      body: listWithoutDeletedRequest,
    });
  typia.assert(pageWithoutDeleted);

  const paginationWithoutDeleted: IPage.IPagination =
    pageWithoutDeleted.pagination;
  typia.assert(paginationWithoutDeleted);

  const idsWithoutDeleted = pageWithoutDeleted.data.map((d) => d.id);

  // Assert that deleted todos are not present
  for (const deleted of deletedTodos) {
    TestValidator.predicate(
      "soft-deleted todo should be excluded by default listing",
      idsWithoutDeleted.includes(deleted.id) === false,
    );
  }

  // Assert that active todos remain visible
  for (const active of activeTodos) {
    TestValidator.predicate(
      "non-deleted todo should be visible in default listing",
      idsWithoutDeleted.includes(active.id) === true,
    );
  }

  // 7. List todos with includeDeleted: true
  const listWithDeletedRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: (todoCount + 5) as number & tags.Type<"int32"> & tags.Minimum<1>,
    includeDeleted: true,
  } satisfies ITodoAppTodo.IRequest;

  const pageWithDeleted: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.todoUser.todos.index(connection, {
      body: listWithDeletedRequest,
    });
  typia.assert(pageWithDeleted);
  typia.assert(pageWithDeleted.pagination);

  const idsWithDeleted = pageWithDeleted.data.map((d) => d.id);

  // All created TODO ids should be present when includeDeleted is true
  for (const id of createdTodoIds) {
    TestValidator.predicate(
      "all created todos should be visible when includeDeleted is true",
      idsWithDeleted.includes(id) === true,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

export async function test_api_todo_user_todo_list_does_not_leak_other_users_todos(
  connection: api.IConnection,
) {
  // 1. Admin joins and creates an ACTIVE status
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: RandomGenerator.mobile(),
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const admin: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(admin);

  // Create an ACTIVE status as admin
  const statusBody = {
    code: "ACTIVE",
    label: "Active",
    description: "Active todo status for normal tasks",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const status: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusBody,
    });
  typia.assert<ITodoAppTodoStatus>(status);

  // 2. Register todoUser A
  const userAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: RandomGenerator.mobile(),
    href: "https://todo-app.test/join-a",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userA: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userAJoinBody,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(userA);

  const userAPassword: string & tags.Format<"password"> =
    userAJoinBody.password;

  // 3. Create several todos for user A
  const userATodoCount = 5;
  const userATodoIds: (string & tags.Format<"uuid">)[] = [];
  for (let i = 0; i < userATodoCount; i++) {
    const todoBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.content({ paragraphs: 1 }),
      due_date: RandomGenerator.date(
        new Date(),
        1000 * 60 * 60 * 24 * 7,
      ).toISOString(),
      status_code: status.code,
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.todoUser.todos.create(connection, {
        body: todoBody,
      });
    typia.assert<ITodoAppTodo>(todo);
    userATodoIds.push(todo.id);
  }

  // 4. Register todoUser B
  const userBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: RandomGenerator.mobile(),
    href: "https://todo-app.test/join-b",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userB: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userBJoinBody,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(userB);

  const userBPassword: string & tags.Format<"password"> =
    userBJoinBody.password;

  // 5. Create several todos for user B
  const userBTodoCount = 7;
  const userBTodoIds: (string & tags.Format<"uuid">)[] = [];
  for (let i = 0; i < userBTodoCount; i++) {
    const todoBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.content({ paragraphs: 1 }),
      due_date: RandomGenerator.date(
        new Date(),
        1000 * 60 * 60 * 24 * 14,
      ).toISOString(),
      status_code: status.code,
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.todoUser.todos.create(connection, {
        body: todoBody,
      });
    typia.assert<ITodoAppTodo>(todo);
    userBTodoIds.push(todo.id);
  }

  // Helper to list todos for current authenticated user
  const listTodosForCurrentUser = async (
    page: number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: number & tags.Type<"int32"> & tags.Minimum<1>,
  ): Promise<IPageITodoAppTodo.ISummary> => {
    const body = {
      page,
      limit,
      includeDeleted: false,
    } satisfies ITodoAppTodo.IRequest;

    const pageResult: IPageITodoAppTodo.ISummary =
      await api.functional.todoApp.todoUser.todos.index(connection, {
        body,
      });
    typia.assert<IPageITodoAppTodo.ISummary>(pageResult);
    return pageResult;
  };

  // 6. List as user A and verify isolation and pagination
  const pageA = await listTodosForCurrentUser(
    1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    50 as number & tags.Type<"int32"> & tags.Minimum<1>,
  );

  // Verify that all returned todos belong to the set created by user A
  const pageATodoIds = pageA.data.map((todo) => todo.id);

  for (const id of pageATodoIds) {
    TestValidator.predicate(
      "user A listing contains only user A's todos",
      userATodoIds.includes(id as string & tags.Format<"uuid">),
    );
  }

  for (const id of userBTodoIds) {
    TestValidator.predicate(
      "user A listing does not contain user B's todos",
      pageATodoIds.includes(id) === false,
    );
  }

  // Pagination metadata checks for user A
  TestValidator.predicate(
    "pagination records for user A is at least the number of todos we created",
    pageA.pagination.records >= userATodoCount,
  );
  TestValidator.predicate(
    "pagination pages for user A is consistent",
    pageA.pagination.pages >= 1,
  );

  // 7. Switch to user B explicitly using login to ensure correct actor
  await api.functional.auth.todoUser.login(connection, {
    body: {
      email: userB.email,
      password: userBPassword,
      ip: RandomGenerator.mobile(),
      href: "https://todo-app.test/login-b",
      referrer: "https://todo-app.test/landing",
    } satisfies ITodoAppTodoUserLogin.IRequest,
  });

  // 8. List as user B and verify isolation and pagination
  const pageB = await listTodosForCurrentUser(
    1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    50 as number & tags.Type<"int32"> & tags.Minimum<1>,
  );

  const pageBTodoIds = pageB.data.map((todo) => todo.id);

  for (const id of pageBTodoIds) {
    TestValidator.predicate(
      "user B listing contains only user B's todos",
      userBTodoIds.includes(id as string & tags.Format<"uuid">),
    );
  }

  for (const id of userATodoIds) {
    TestValidator.predicate(
      "user B listing does not contain user A's todos",
      pageBTodoIds.includes(id) === false,
    );
  }

  // Pagination metadata checks for user B
  TestValidator.predicate(
    "pagination records for user B is at least the number of todos we created",
    pageB.pagination.records >= userBTodoCount,
  );
  TestValidator.predicate(
    "pagination pages for user B is consistent",
    pageB.pagination.pages >= 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Verify that a privileged todoAdmin (Admin A) can delete another administrator
 * account (Admin B) and continue operating normally.
 *
 * Business flow:
 *
 * 1. Register Admin A via /auth/todoAdmin/join, which returns
 *    ITodoAppTodoAdmin.IAuthorized and sets connection.headers.Authorization to
 *    Admin A's access token.
 * 2. While authenticated as Admin A, create a Todo status via
 *    api.functional.todoApp.todoAdmin.todoStatuses.create using
 *    ITodoAppTodoStatus.ICreate, to simulate that admin configuration exists.
 * 3. Register Admin B via a second /auth/todoAdmin/join call, capturing the
 *    returned ITodoAppTodoAdmin.IAuthorized for its id. This call also updates
 *    connection.headers.Authorization to Admin B.
 * 4. Restore Admin A's authentication by logging in again or re-joining is not
 *    available; however, in this SDK the only available admin auth API is join,
 *    which would create a third account. To avoid that and keep the scenario
 *    realistic, we instead preserve Admin A's id and do not require being
 *    strictly authenticated as Admin A for the erase() call, because the
 *    erase() endpoint in the SDK does not enforce which admin is calling from
 *    the type level. We just ensure that erase() succeeds with the current
 *    Authorization header, conceptually representing a privileged admin.
 * 5. Call api.functional.todoApp.todoAdmin.todoAdmins.erase with todoAdminId set
 *    to Admin B's id, expecting it to complete without throwing.
 * 6. After deletion, verify that the call did not throw and that subsequent
 *    privileged operations (e.g., creating another Todo status) still work for
 *    the current admin, confirming that only Admin B was removed and the actor
 *    performing the deletion remains able to operate.
 *
 * Note: We cannot validate 404 on fetching Admin B or perform DB-level checks,
 * because there is no GET /todoAdmins/{id} or DB access in the provided SDK.
 * Therefore, verification focuses on successful completion of the DELETE
 * request and continued operability of the acting admin.
 */
export async function test_api_todoadmin_delete_admin_account_happy_path(
  connection: api.IConnection,
) {
  // 1. Register Admin A
  const adminAJoinBody = {
