import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Validate todoAdmin status lifecycle transitions via profile update.
 *
 * Business goals:
 *
 * - Ensure that allowed status transitions for a todoAdmin account (e.g., from an
 *   initial status to "SUSPENDED" and then to "CLOSED") succeed and reflect
 *   correctly in the admin profile returned by the update API.
 * - Ensure that forbidden transitions (such as reactivating a "CLOSED" admin to
 *   "ACTIVE") are rejected with an error and do not change persisted state.
 * - Confirm that non-credential fields like `status` and `display_name` are the
 *   only mutable fields, that `id` and `email` remain stable across updates,
 *   and that `updated_at` changes only on successful updates.
 *
 * Flow:
 *
 * 1. Register a todoAdmin (adminA) with /auth/todoAdmin/join to obtain an
 *    authenticated context (Authorization header set on connection) and capture
 *    its id/email/initial timestamps.
 * 2. Configure lifecycle status catalogue entries via POST
 *    /todoApp/todoAdmin/todoStatuses for codes "ACTIVE", "SUSPENDED", and
 *    "CLOSED" to mirror business lifecycle states.
 * 3. Perform an allowed transition to "SUSPENDED" using PUT
 *    /todoApp/todoAdmin/todoAdmins/{todoAdminId} with
 *    ITodoAppTodoAdmin.IUpdate.status and validate that:
 *
 *    - The response status equals "SUSPENDED".
 *    - `id` and `email` are unchanged.
 *    - `updated_at` is different from the original `updated_at`.
 * 4. Perform another allowed transition to "CLOSED" and validate analogous
 *    invariants, capturing the resulting `updated_at` for comparison.
 * 5. Attempt a forbidden transition from "CLOSED" back to "ACTIVE" via the same
 *    update endpoint and assert that an error occurs using TestValidator.error
 *    (without checking status codes).
 * 6. Confirm logically that the admin entity we hold from the last successful
 *    update still represents the latest persisted state (status "CLOSED"), and
 *    rely on transactional semantics that invalid updates do not partially
 *    apply.
 */
export async function test_api_todoadmin_profile_update_status_transition_rules(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin (adminA) and obtain authorized context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.example.com/register",
    referrer: "https://admin.todo-app.example.com/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const authorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(authorized);

  const adminId = authorized.id;
  const adminEmail = authorized.email;
  const initialUpdatedAt = authorized.updated_at;

  // 2. Create Todo status catalogue entries: ACTIVE, SUSPENDED, CLOSED.
  const createStatus = async (
    code: string,
    label: string,
    sortOrder: number & tags.Type<"int32">,
    isDefault: boolean,
    isActive: boolean,
  ): Promise<ITodoAppTodoStatus> => {
    const body = {
      code,
      label,
      description: null,
      group: null,
      sort_order: sortOrder,
      is_default: isDefault,
      is_active: isActive,
    } satisfies ITodoAppTodoStatus.ICreate;

    const status: ITodoAppTodoStatus =
      await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
        body,
      });
    typia.assert<ITodoAppTodoStatus>(status);
    return status;
  };

  await createStatus(
    "ACTIVE",
    "Active",
    typia.random<number & tags.Type<"int32">>(),
    true,
    true,
  );
  await createStatus(
    "SUSPENDED",
    "Suspended",
    typia.random<number & tags.Type<"int32">>(),
    false,
    true,
  );
  await createStatus(
    "CLOSED",
    "Closed",
    typia.random<number & tags.Type<"int32">>(),
    false,
    false,
  );

  // 3. Perform an allowed transition from initial status to "SUSPENDED".
  const suspendedUpdateBody = {
    status: "SUSPENDED",
  } satisfies ITodoAppTodoAdmin.IUpdate;

  const suspended: ITodoAppTodoAdmin =
    await api.functional.todoApp.todoAdmin.todoAdmins.update(connection, {
      todoAdminId: adminId,
      body: suspendedUpdateBody,
    });
  typia.assert<ITodoAppTodoAdmin>(suspended);

  TestValidator.equals(
    "id should remain unchanged after suspension",
    suspended.id,
    adminId,
  );
  TestValidator.equals(
    "email should remain unchanged after suspension",
    suspended.email,
    adminEmail,
  );
  TestValidator.equals(
    "status should transition to SUSPENDED",
    suspended.status,
    "SUSPENDED",
  );
  TestValidator.notEquals(
    "updated_at should change after suspension",
    suspended.updated_at,
    initialUpdatedAt,
  );

  const suspendedUpdatedAt = suspended.updated_at;

  // 4. Perform another allowed transition from "SUSPENDED" to "CLOSED".
  const closedUpdateBody = {
    status: "CLOSED",
  } satisfies ITodoAppTodoAdmin.IUpdate;

  const closed: ITodoAppTodoAdmin =
    await api.functional.todoApp.todoAdmin.todoAdmins.update(connection, {
      todoAdminId: adminId,
      body: closedUpdateBody,
    });
  typia.assert<ITodoAppTodoAdmin>(closed);

  TestValidator.equals(
    "id should remain unchanged after closing",
    closed.id,
    adminId,
  );
  TestValidator.equals(
    "email should remain unchanged after closing",
    closed.email,
    adminEmail,
  );
  TestValidator.equals(
    "status should transition to CLOSED",
    closed.status,
    "CLOSED",
  );
  TestValidator.notEquals(
    "updated_at should change after closing",
    closed.updated_at,
    suspendedUpdatedAt,
  );

  const closedUpdatedAt = closed.updated_at;

  // 5. Attempt a forbidden transition from "CLOSED" back to "ACTIVE".
  const forbiddenUpdateBody = {
    status: "ACTIVE",
  } satisfies ITodoAppTodoAdmin.IUpdate;

  await TestValidator.error(
    "forbidden transition from CLOSED to ACTIVE should fail",
    async () => {
      await api.functional.todoApp.todoAdmin.todoAdmins.update(connection, {
        todoAdminId: adminId,
        body: forbiddenUpdateBody,
      });
    },
  );

  // 6. Logically confirm that the latest successful state remains CLOSED and
  // that its updated_at timestamp is the last successful one we observed.
  TestValidator.equals(
    "admin status remains CLOSED after failed reactivation attempt",
    closed.status,
    "CLOSED",
  );
  TestValidator.equals(
    "admin updated_at remains the last successful value after failed transition",
    closed.updated_at,
    closedUpdatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Verify that updating a todoAdmin profile without a valid authentication
 * context is rejected.
 *
 * Business goal: Ensure that the privileged endpoint PUT
 * /todoApp/todoAdmin/todoAdmins/{todoAdminId}, which updates non-credential
 * fields (like display_name or status) of an administrative account, cannot be
 * used by unauthenticated clients. Unauthorized callers must receive an error
 * instead of an updated admin record.
 *
 * High-level steps:
 *
 * 1. Register a new todoAdmin account using /auth/todoAdmin/join to obtain a valid
 *    administrative identity and token.
 * 2. As an authenticated admin, create at least one Todo status via POST
 *    /todoApp/todoAdmin/todoStatuses, satisfying the scenario's prerequisite
 *    that status catalogue data exists.
 * 3. Prepare an ITodoAppTodoAdmin.IUpdate payload that would change mutable fields
 *    such as display_name and status.
 * 4. Construct a new IConnection instance with an empty headers object to simulate
 *    a completely unauthenticated client (no Authorization).
 * 5. Perform the update call using this unauthenticated connection and assert,
 *    using TestValidator.error, that the operation fails rather than returning
 *    a successful ITodoAppTodoAdmin record.
 *
 * Due to the limited API surface provided (no dedicated admin GET by id), we
 * validate behavior purely through the error condition on the unauthorized
 * update attempt rather than re-reading the admin record to compare pre- and
 * post-state.
 */
export async function test_api_todoadmin_profile_update_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register a new todoAdmin account (join) and obtain authorized context
  const joinBody = typia.random<ITodoAppTodoAdminJoin.IRequest>();
  const authorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(authorized);

  // 2. Create at least one Todo status as an authenticated admin
  //    (using the token implicitly set by the join call).
  const statusCodeSuffix = RandomGenerator.alphabets(8);
  const statusCreateBody = {
    code: `ACTIVE_${statusCodeSuffix}`,
    label: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert<ITodoAppTodoStatus>(createdStatus);

  // 3. Prepare update payload that would change display_name and status
  const updateBody = {
    display_name: RandomGenerator.paragraph({ sentences: 1 }),
    status: "suspended",
  } satisfies ITodoAppTodoAdmin.IUpdate;

  // 4. Build an unauthenticated connection, with empty headers, to simulate
  //    a client that has no Authorization token at all.
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 5. Attempt the unauthorized update and assert that it fails.
  await TestValidator.error(
    "todoAdmin profile update without auth must fail",
    async () => {
      await api.functional.todoApp.todoAdmin.todoAdmins.update(
        unauthConnection,
        {
          todoAdminId: authorized.id,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";

/**
 * Cross-admin profile update access control for todoAdmin accounts.
 *
 * This test verifies that the administrative profile update endpoint `PUT
 * /todoApp/todoAdmin/todoAdmins/{todoAdminId}` correctly updates the targeted
 * admin account while preserving non-updated fields, and that the result is
 * consistent when updating another admin versus updating the currently
 * authenticated admin.
 *
 * Business-flow covered in this test:
 *
 * 1. Register the first admin (adminA) using POST /auth/todoAdmin/join.
 * 2. Bootstrap a Todo status row using POST /todoApp/todoAdmin/todoStatuses,
 *    mirroring the real-world prerequisite that status catalogue exists.
 * 3. Register the second admin (adminB) using POST /auth/todoAdmin/join. This also
 *    sets the connection's Authorization header for adminB.
 * 4. While authenticated as adminB, perform a cross-admin update targeting adminA
 *    via PUT /todoApp/todoAdmin/todoAdmins/{todoAdminId} and change adminA's
 *    display_name and status.
 * 5. Assert that the response represents adminA with updated display_name and
 *    status, unchanged email, and a different updated_at timestamp.
 * 6. Still authenticated as adminB, perform a self-update on adminB's own record,
 *    changing only the display_name, and verify that email and status remain
 *    unchanged while display_name and updated_at are updated.
 */
export async function test_api_todoadmin_profile_update_cross_admin_access_control(
  connection: api.IConnection,
) {
  // 1. Register the first admin (adminA).
  const adminAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password-123",
    displayName: RandomGenerator.name(2),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAAuth: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert(adminAAuth);

  const adminAId = adminAAuth.id;

  // 2. Bootstrap a Todo status row for catalogue readiness.
  const sortOrder = typia.random<number & tags.Type<"int32">>();

  const statusCreateBody = {
    code: "ACTIVE",
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: null,
    sort_order: sortOrder,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const createdStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: statusCreateBody,
    });
  typia.assert(createdStatus);

  // 3. Register the second admin (adminB). Connection will now represent adminB.
  const adminBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password-123",
    displayName: RandomGenerator.name(2),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminBAuth: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert(adminBAuth);

  const adminBId = adminBAuth.id;

  // 4. Cross-admin update: currently authenticated admin (adminB) updates adminA's profile.
  const newAdminADisplayName = RandomGenerator.name(2);
  const newAdminAStatus = "suspended";

  const crossUpdateBody = {
    display_name: newAdminADisplayName,
    status: newAdminAStatus,
  } satisfies ITodoAppTodoAdmin.IUpdate;

  const updatedAdminA: ITodoAppTodoAdmin =
    await api.functional.todoApp.todoAdmin.todoAdmins.update(connection, {
      todoAdminId: adminAId,
      body: crossUpdateBody,
    });
  typia.assert(updatedAdminA);

  // 5. Assertions for cross-admin update effects.
  TestValidator.equals(
    "cross-admin update targets adminA record",
    updatedAdminA.id,
    adminAId,
  );
  TestValidator.equals(
    "cross-admin update keeps adminA email unchanged",
    updatedAdminA.email,
    adminAAuth.email,
  );
  TestValidator.equals(
    "cross-admin update changes adminA display_name",
    updatedAdminA.display_name,
    newAdminADisplayName,
  );
  TestValidator.equals(
    "cross-admin update changes adminA status",
    updatedAdminA.status,
    newAdminAStatus,
  );
  TestValidator.notEquals(
    "adminA updated_at must change after cross-admin update",
    updatedAdminA.updated_at,
    adminAAuth.updated_at,
  );

  // 6. Self-update sanity check for adminB.
  const newAdminBDisplayName = RandomGenerator.name(2);

  const selfUpdateBody = {
    display_name: newAdminBDisplayName,
  } satisfies ITodoAppTodoAdmin.IUpdate;

  const updatedAdminB: ITodoAppTodoAdmin =
    await api.functional.todoApp.todoAdmin.todoAdmins.update(connection, {
      todoAdminId: adminBId,
      body: selfUpdateBody,
    });
  typia.assert(updatedAdminB);

  TestValidator.equals(
    "self update targets adminB record",
    updatedAdminB.id,
    adminBId,
  );
  TestValidator.equals(
    "self update keeps adminB email unchanged",
    updatedAdminB.email,
    adminBAuth.email,
  );
  TestValidator.equals(
    "self update changes adminB display_name",
    updatedAdminB.display_name,
    newAdminBDisplayName,
  );
  TestValidator.equals(
    "self update keeps adminB status unchanged",
    updatedAdminB.status,
    adminBAuth.status,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
