/**
 * Validate completing an active todo owned by an authenticated todoUser.
 *
 * Business flow:
 *
 * 1. Register a todoAdmin and obtain admin authorization.
 * 2. As admin, create a COMPLETED-like status in the status catalogue.
 * 3. Register a todoUser and obtain user authorization.
 * 4. As todoUser, create a new todo (implicitly active via default status).
 * 5. Complete the todo using POST /todoApp/todoUser/todos/{todoId}/complete.
 * 6. Verify lifecycle timestamps and business fields after completion.
 */
export async function test_api_todo_completion_basic_flow(
  connection: api.IConnection,
) {
  // 1. Register a todoAdmin and obtain admin authorization
  const adminEmail = typia.random<string & tags.Format<"email">>();

  const adminJoinBody = {
    email: adminEmail,
    password: "admin-password",
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todo-app.test/join",
    referrer: "https://admin.todo-app.test/landing",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As admin, create a COMPLETED-like status in the catalogue
  const completedStatusBody = {
    code: "COMPLETED",
    label: "Completed",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const completedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: completedStatusBody,
    });
  typia.assert(completedStatus);

  // 3. Register a todoUser and obtain user authorization
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "user-password";

  const userJoinBody = {
    email: userEmail,
    password: userPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userAuthorized);

  // 4. As todoUser, create a new todo (implicitly active)
  const dueDate = new Date(Date.now() + 60 * 60 * 1000).toISOString();

  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: dueDate,
    status_code: null,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  const originalId = createdTodo.id;
  const originalTitle = createdTodo.title;
  const originalDescription = createdTodo.description ?? null;
  const originalDueDate = createdTodo.due_date ?? null;
  const originalStatusCode = createdTodo.status.code;
  const originalCreatedAt = createdTodo.created_at;
  const originalUpdatedAt = createdTodo.updated_at;
  const originalCompletedAt = createdTodo.completed_at ?? null;
  const originalDeletedAt = createdTodo.deleted_at ?? null;

  TestValidator.equals(
    "created todo should not be completed yet",
    originalCompletedAt,
    null,
  );
  TestValidator.equals(
    "created todo should not be deleted",
    originalDeletedAt,
    null,
  );

  // 5. Complete the todo
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(completedTodo);

  // 6. Verify lifecycle timestamps and business fields after completion
  TestValidator.equals(
    "todo id remains unchanged after completion",
    completedTodo.id,
    originalId,
  );
  TestValidator.equals(
    "title remains unchanged after completion",
    completedTodo.title,
    originalTitle,
  );
  TestValidator.equals(
    "description remains unchanged after completion",
    completedTodo.description ?? null,
    originalDescription,
  );
  TestValidator.equals(
    "due_date remains unchanged after completion",
    completedTodo.due_date ?? null,
    originalDueDate,
  );

  TestValidator.predicate(
    "completed_at should be set after completion",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  const createdAtMs = new Date(originalCreatedAt).getTime();
  const updatedAtBeforeMs = new Date(originalUpdatedAt).getTime();
  const updatedAtAfterMs = new Date(completedTodo.updated_at).getTime();
  const completedAtMs = new Date(
    completedTodo.completed_at ?? originalCreatedAt,
  ).getTime();

  TestValidator.predicate(
    "updated_at should be later than before completion",
    updatedAtAfterMs > updatedAtBeforeMs,
  );

  TestValidator.predicate(
    "completed_at should be at or after created_at",
    completedAtMs >= createdAtMs,
  );

  TestValidator.equals(
    "deleted_at should remain null after completion",
    completedTodo.deleted_at ?? null,
    null,
  );

  TestValidator.predicate(
    "status code after completion should reflect a potentially different state",
    completedTodo.status.code === originalStatusCode ||
      completedTodo.status.code === completedStatus.code,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate idempotent completion of a todo item.
 *
 * Business goal:
 *
 * - Ensure that completing an already-completed todo via POST
 *   /todoApp/todoUser/todos/{todoId}/complete does not corrupt state and
 *   behaves idempotently: a second completion returns the same completed state
 *   without further side effects.
 *
 * High level steps:
 *
 * 1. Register and log in a todoAdmin account.
 * 2. Using the admin, create two Todo statuses in the catalogue: ACTIVE and
 *    COMPLETED.
 * 3. Register and log in a todoUser account.
 * 4. As the todoUser, create a new todo (which will start in ACTIVE or default
 *    status).
 * 5. Complete the todo once and assert it is marked as completed with completed_at
 *    set.
 * 6. Immediately call complete again on the same todo.
 * 7. Assert that:
 *
 *    - The todo id remains the same.
 *    - Completed_at is still non-null and equal to the first completion's value.
 *    - Deleted_at stays null.
 *    - Core fields (title, description, due_date, status.code) are unchanged between
 *         the first and second completion responses.
 */
export async function test_api_todo_completion_idempotent_when_already_completed(
  connection: api.IConnection,
) {
  // 1. Register todoAdmin via /auth/todoAdmin/join (auto-login via SDK)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://admin.todo-app.test/join" as string & tags.Format<"uri">,
    referrer: "https://admin.todo-app.test/" as string & tags.Format<"uri">,
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create ACTIVE and COMPLETED statuses via admin API
  const activeStatusBody = {
    code: "ACTIVE",
    label: "Active",
    description: "Active todo that is not yet completed",
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusBody,
    });
  typia.assert(activeStatus);

  const completedStatusBody = {
    code: "COMPLETED",
    label: "Completed",
    description: "Completed todo",
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const completedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: completedStatusBody,
    });
  typia.assert(completedStatus);

  // Sanity check: created statuses
  TestValidator.equals(
    "ACTIVE status code",
    activeStatus.code,
    activeStatusBody.code,
  );
  TestValidator.equals(
    "COMPLETED status code",
    completedStatus.code,
    completedStatusBody.code,
  );

  // 3. Register todoUser via /auth/todoUser/join (auto-login via SDK)
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12) as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: "127.0.0.1",
    href: "https://todo-app.test/join" as string & tags.Format<"uri">,
    referrer: "https://todo-app.test/" as string & tags.Format<"uri">,
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert(userAuthorized);

  // 4. Create a new todo as todoUser (let backend default the status or use ACTIVE)
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date().toISOString() as string & tags.Format<"date-time">,
    status_code: activeStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // Validate initial todo state
  TestValidator.equals(
    "created todo title matches request",
    createdTodo.title,
    todoCreateBody.title,
  );
  TestValidator.equals(
    "created todo description matches request",
    createdTodo.description ?? null,
    todoCreateBody.description ?? null,
  );
  TestValidator.equals(
    "created todo due_date matches request",
    createdTodo.due_date ?? null,
    todoCreateBody.due_date ?? null,
  );
  TestValidator.equals(
    "created todo deleted_at is null",
    createdTodo.deleted_at ?? null,
    null,
  );
  TestValidator.equals(
    "created todo completed_at is null",
    createdTodo.completed_at ?? null,
    null,
  );

  // 5. First completion call
  const firstCompleted: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(firstCompleted);

  TestValidator.equals(
    "first completion todo id matches created",
    firstCompleted.id,
    createdTodo.id,
  );
  TestValidator.predicate(
    "first completion completed_at is non-null",
    firstCompleted.completed_at !== null &&
      firstCompleted.completed_at !== undefined,
  );
  TestValidator.equals(
    "first completion deleted_at remains null",
    firstCompleted.deleted_at ?? null,
    null,
  );

  const completedAtAfterFirst = firstCompleted.completed_at ?? null;
  const statusCodeAfterFirst = firstCompleted.status.code;

  // 6. Second completion call (idempotency check)
  const secondCompleted: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(secondCompleted);

  // 7. Idempotency validations
  TestValidator.equals(
    "second completion todo id matches created",
    secondCompleted.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "completed_at is stable between first and second completion",
    secondCompleted.completed_at ?? null,
    completedAtAfterFirst,
  );
  TestValidator.equals(
    "second completion deleted_at remains null",
    secondCompleted.deleted_at ?? null,
    null,
  );

  // Fields unchanged relative to first completion
  TestValidator.equals(
    "title unchanged between first and second completion",
    secondCompleted.title,
    firstCompleted.title,
  );
  TestValidator.equals(
    "description unchanged between first and second completion",
    secondCompleted.description ?? null,
    firstCompleted.description ?? null,
  );
  TestValidator.equals(
    "due_date unchanged between first and second completion",
    secondCompleted.due_date ?? null,
    firstCompleted.due_date ?? null,
  );
  TestValidator.equals(
    "status code unchanged between first and second completion",
    secondCompleted.status.code,
    statusCodeAfterFirst,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate that only the owning todoUser can complete a Todo.
 *
 * Business goals:
 *
 * - A todo created by user A cannot be completed by user B.
 * - Cross-user isolation is enforced by returning an error for non-owners,
 *   without relying on specific HTTP status codes.
 * - The happy-path behavior (owner can complete their own todo) still works when
 *   proper statuses exist.
 *
 * Steps:
 *
 * 1. Register and authenticate a todoAdmin, then create two statuses:
 *
 *    - ACTIVE (default, active)
 *    - COMPLETED (non-default, active)
 * 2. Register todoUser A and todoUser B, each with their own credentials.
 * 3. As todoUser A, create a Todo in ACTIVE status.
 * 4. Switch to todoUser B and attempt to complete A's Todo; assert that the call
 *    fails (ownership enforcement).
 * 5. Switch back to todoUser A and successfully complete the Todo, asserting it
 *    transitions to COMPLETED and has a non-null completed_at.
 */
export async function test_api_todo_completion_only_by_owner(
  connection: api.IConnection,
) {
  // 1. Admin bootstrap: join and login, then create ACTIVE and COMPLETED statuses.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: "https://admin.todoapp.local/join",
    referrer: "https://admin.todoapp.local/",
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // Explicit login to exercise login flow and ensure token refresh behavior.
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.todoapp.local/login",
    referrer: "https://admin.todoapp.local/",
  } satisfies ITodoAppTodoAdminLogin.IRequest;

  const adminLoggedIn: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // Create ACTIVE status (default, active)
  const activeStatusBody = {
    code: "ACTIVE",
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusBody,
    });
  typia.assert(activeStatus);

  // Create COMPLETED status (non-default, active)
  const completedStatusBody = {
    code: "COMPLETED",
    label: "Completed",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const completedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: completedStatusBody,
    });
  typia.assert(completedStatus);

  // 2. Register todoUser A and B.
  const userAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.local/signup",
    referrer: "https://todoapp.local/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userAJoinBody,
    });
  typia.assert(userAAuthorized);

  const userBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.local/signup",
    referrer: "https://todoapp.local/landing",
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userBAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userBJoinBody,
    });
  typia.assert(userBAuthorized);

  // Explicit login as user A to ensure we are in A's context.
  const userALoginBody = {
    email: userAJoinBody.email,
    password: userAJoinBody.password,
    ip: null,
    href: "https://todoapp.local/login",
    referrer: "https://todoapp.local/landing",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const userALoggedIn: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userALoginBody,
    });
  typia.assert(userALoggedIn);

  // 3. As user A, create an ACTIVE todo.
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
    status_code: activeStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const todoOwnedByA: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todoOwnedByA);

  TestValidator.equals(
    "new todo should initially be ACTIVE",
    todoOwnedByA.status.code,
    "ACTIVE",
  );

  // 4. Switch to user B and attempt unauthorized completion.
  const userBLoginBody = {
    email: userBJoinBody.email,
    password: userBJoinBody.password,
    ip: null,
    href: "https://todoapp.local/login",
    referrer: "https://todoapp.local/landing",
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const userBLoggedIn: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userBLoginBody,
    });
  typia.assert(userBLoggedIn);

  await TestValidator.error(
    "non-owner cannot complete another user's todo",
    async () => {
      await api.functional.todoApp.todoUser.todos.complete(connection, {
        todoId: todoOwnedByA.id,
      });
    },
  );

  // 5. Switch back to user A and complete successfully.
  const userALoggedInAgain: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userALoginBody,
    });
  typia.assert(userALoggedInAgain);

  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.complete(connection, {
      todoId: todoOwnedByA.id,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "owner completion should set status to COMPLETED",
    completedTodo.status.code,
    completedStatus.code,
  );

  TestValidator.predicate(
    "completed_at should be set after successful completion",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
