  // 2. Ensure core Todo statuses exist: ACTIVE and COMPLETED
  const activeStatusBody = {
    code: "ACTIVE",
    label: "Active",
    description: null,
    group: null,
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusBody,
    });
  typia.assert(activeStatus);

  const completedStatusBody = {
    code: "COMPLETED",
    label: "Completed",
    description: null,
    group: null,
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const completedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: completedStatusBody,
    });
  typia.assert(completedStatus);

  // 3. Register todoUser A and authenticate
  const userAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const userAPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const userAJoinBody = {
    email: userAEmail,
    password: userAPassword,
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userAJoinBody,
    });
  typia.assert(userAAuthorized);

  // 4. As user A, create a Todo with initial ACTIVE status
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 8 }),
    due_date: typia.random<string & tags.Format<"date-time">>(),
    status_code: activeStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const todoA: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todoA);

  TestValidator.equals(
    "newly created todo should be ACTIVE",
    todoA.status.code,
    activeStatus.code,
  );

  // 5. As user A, complete the Todo
  const completedTodoA: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.complete(connection, {
      todoId: todoA.id,
    });
  typia.assert(completedTodoA);

  TestValidator.predicate(
    "completed todo must have non-null completed_at",
    completedTodoA.completed_at !== null &&
      completedTodoA.completed_at !== undefined,
  );

  TestValidator.equals(
    "completed todo id should match original todo id",
    completedTodoA.id,
    todoA.id,
  );

  // 6. Register todoUser B (implicitly authenticates as B)
  const userBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const userBPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const userBJoinBody = {
    email: userBEmail,
    password: userBPassword,
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userBAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userBJoinBody,
    });
  typia.assert(userBAuthorized);

  // 7. As user B, attempt to restore A's completed Todo and expect error
  await TestValidator.error(
    "non-owner todoUser must not be able to restore another user's todo",
    async () => {
      await api.functional.todoApp.todoUser.todos.restore(connection, {
        todoId: todoA.id,
      });
    },
  );

  // 8. Log back in as user A
  const userALoginBody = {
    email: userAEmail,
    password: userAPassword,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const userALoggedIn: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: userALoginBody,
    });
  typia.assert(userALoggedIn);

  // 9. As user A, restore the Todo successfully
  const restoredTodoA: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.restore(connection, {
      todoId: todoA.id,
    });
  typia.assert(restoredTodoA);

  TestValidator.equals(
    "restored todo id should match original todo id",
    restoredTodoA.id,
    todoA.id,
  );

  TestValidator.equals(
    "restored todo should have completed_at cleared",
    restoredTodoA.completed_at,
    null,
  );

  TestValidator.predicate(
    "restored todo should still be associated with an active status entry",
    restoredTodoA.status.is_active === true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Verify that restoring a soft-deleted todo is disallowed.
 *
 * Business objective:
 *
 * - Ensure that the restore endpoint `/todoApp/todoUser/todos/{todoId}/restore`
 *   only works for non-deleted todos and that, once a todo is soft-deleted,
 *   restore cannot bring it back.
 *
 * Scenario:
 *
 * 1. Create a todoUser (owner) via /auth/todoUser/join.
 * 2. Create a todoAdmin via /auth/todoAdmin/join.
 * 3. As admin, configure ACTIVE and COMPLETED statuses via
 *    /todoApp/todoAdmin/todoStatuses.
 * 4. Switch back to the todoUser via /auth/todoUser/login.
 * 5. Create a todo as the todoUser via /todoApp/todoUser/todos with status_code
 *    "ACTIVE".
 * 6. Complete the todo via /todoApp/todoUser/todos/{todoId}/complete.
 * 7. Soft-delete the todo via DELETE /todoApp/todoUser/todos/{todoId}.
 * 8. Attempt to restore the deleted todo via
 *    /todoApp/todoUser/todos/{todoId}/restore.
 * 9. Assert that restore throws an error and does not succeed.
 * 10. Optionally attempt to complete the deleted todo again and assert that it also
 *     fails, reinforcing that soft-deleted todos are immutable.
 */
export async function test_api_todo_restore_disallows_soft_deleted_todo(
  connection: api.IConnection,
) {
  // 1. Register todoUser (owner) and obtain authenticated context
  const todoUserJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const todoUserAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: todoUserJoinBody,
    });
  typia.assert(todoUserAuthorized);

  // 2. Register todoAdmin and authenticate as admin
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. As admin, configure ACTIVE and COMPLETED statuses
  const activeStatusBody = {
    code: "ACTIVE",
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusBody,
    });
  typia.assert(activeStatus);

  const completedStatusBody = {
    code: "COMPLETED",
    label: "Completed",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const completedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: completedStatusBody,
    });
  typia.assert(completedStatus);

  // 4. Switch back to todoUser explicitly via login
  const todoUserLoginBody = {
    email: todoUserAuthorized.email,
    password: todoUserJoinBody.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserLogin.IRequest;

  const reauthorizedTodoUser: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.login(connection, {
      body: todoUserLoginBody,
    });
  typia.assert(reauthorizedTodoUser);

  // 5. Create a todo with ACTIVE status
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    due_date: RandomGenerator.date(
      new Date(),
      1000 * 60 * 60 * 24 * 7,
    ).toISOString() as string & tags.Format<"date-time">,
    status_code: activeStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  // 6. Complete the todo
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(completedTodo);

  await TestValidator.predicate(
    "todo completed_at should be set",
    () =>
      completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  // 7. Soft-delete the todo
  await api.functional.todoApp.todoUser.todos.erase(connection, {
    todoId: createdTodo.id,
  });

  // 8. Attempt to restore the deleted todo and expect an error
  await TestValidator.error("cannot restore soft-deleted todo", async () => {
    await api.functional.todoApp.todoUser.todos.restore(connection, {
      todoId: createdTodo.id,
    });
  });

  // 9. Optionally, attempting to complete the deleted todo should also fail
  await TestValidator.error("cannot complete soft-deleted todo", async () => {
    await api.functional.todoApp.todoUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import type { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import type { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import type { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import type { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";

/**
 * Validate that restoring a completed todo only changes lifecycle fields and
 * preserves user-managed fields.
 *
 * Business context:
 *
 * - Todo statuses are centrally managed catalogue entries (ACTIVE, COMPLETED,
 *   etc.).
 * - A todo belongs to a todoUser and has user-managed content (title,
 *   description, due_date) and lifecycle fields (status, completed_at,
 *   updated_at, deleted_at).
 * - Completing a todo moves it to a completed state and sets completed_at.
 * - Restoring a todo should move it back to an active status, clear completed_at,
 *   and bump updated_at, WITHOUT mutating title, description, or due_date.
 *
 * Steps:
 *
 * 1. Join as todoAdmin and create ACTIVE and COMPLETED status catalogue entries.
 * 2. Join as todoUser (this overwrites connection Authorization to todoUser
 *    context).
 * 3. Create a todo with explicit title, description, and due_date, and bind it to
 *    ACTIVE status.
 * 4. Complete the todo; verify lifecycle changes and preservation of user-managed
 *    fields.
 * 5. Restore the todo; verify:
 *
 *    - Title/description/due_date are unchanged from original,
 *    - Status is ACTIVE again,
 *    - Completed_at is null,
 *    - Updated_at is strictly greater than original and completed updated_at.
 */
export async function test_api_todo_restore_preserves_user_managed_fields(
  connection: api.IConnection,
) {
  // 1. Admin: register a todoAdmin account and get authorized
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoAdminJoin.IRequest;

  const adminAuthorized: ITodoAppTodoAdmin.IAuthorized =
    await api.functional.auth.todoAdmin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppTodoAdmin.IAuthorized>(adminAuthorized);

  // 1-2. Admin: create ACTIVE and COMPLETED statuses
  const activeStatusBody = {
    code: "ACTIVE",
    label: "Active",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 1 as number & tags.Type<"int32">,
    is_default: true,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const completedStatusBody = {
    code: "COMPLETED",
    label: "Completed",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    group: "core",
    sort_order: 2 as number & tags.Type<"int32">,
    is_default: false,
    is_active: true,
  } satisfies ITodoAppTodoStatus.ICreate;

  const activeStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: activeStatusBody,
    });
  typia.assert<ITodoAppTodoStatus>(activeStatus);

  const completedStatus: ITodoAppTodoStatus =
    await api.functional.todoApp.todoAdmin.todoStatuses.create(connection, {
      body: completedStatusBody,
    });
  typia.assert<ITodoAppTodoStatus>(completedStatus);

  TestValidator.equals(
    "ACTIVE status code should be ACTIVE",
    activeStatus.code,
    "ACTIVE",
  );
  TestValidator.equals(
    "COMPLETED status code should be COMPLETED",
    completedStatus.code,
    "COMPLETED",
  );

  // 2. User: register a todoUser, which also authenticates as that user
  const userJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppTodoUserJoin.IRequest;

  const userAuthorized: ITodoAppTodoUser.IAuthorized =
    await api.functional.auth.todoUser.join(connection, {
      body: userJoinBody,
    });
  typia.assert<ITodoAppTodoUser.IAuthorized>(userAuthorized);

  // 3. User: create a todo with explicit user-managed fields
  const todoTitle = RandomGenerator.paragraph({ sentences: 2 });
  const todoDescription = RandomGenerator.paragraph({ sentences: 5 });
  const todoDueDate = new Date().toISOString() as string &
    tags.Format<"date-time">;

  const todoCreateBody = {
    title: todoTitle,
    description: todoDescription,
    due_date: todoDueDate,
    status_code: activeStatus.code,
  } satisfies ITodoAppTodo.ICreate;

  const originalTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert<ITodoAppTodo>(originalTodo);

  TestValidator.equals(
    "original todo title matches request",
    originalTodo.title,
    todoTitle,
  );
  TestValidator.equals(
    "original todo description matches request",
    originalTodo.description,
    todoDescription,
  );
  TestValidator.equals(
    "original todo due_date matches request",
    originalTodo.due_date,
    todoDueDate,
  );
  TestValidator.equals(
    "original todo status is ACTIVE",
    originalTodo.status.code,
    activeStatus.code,
  );

  const originalUpdatedAtMs = new Date(originalTodo.updated_at).getTime();

  // 4. User: complete the todo
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.complete(connection, {
      todoId: originalTodo.id,
    });
  typia.assert<ITodoAppTodo>(completedTodo);

  // User-managed fields must remain identical after completion
  TestValidator.equals(
    "completed todo title preserved from original",
    completedTodo.title,
    originalTodo.title,
  );
  TestValidator.equals(
    "completed todo description preserved from original",
    completedTodo.description,
    originalTodo.description,
  );
  TestValidator.equals(
    "completed todo due_date preserved from original",
    completedTodo.due_date,
    originalTodo.due_date,
  );

  // Lifecycle expectations after completion
  TestValidator.predicate(
    "completed_at is set after completion",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  const completedUpdatedAtMs = new Date(completedTodo.updated_at).getTime();
  const completedCompletedAtMs = completedTodo.completed_at
    ? new Date(completedTodo.completed_at).getTime()
    : 0;

  TestValidator.predicate(
    "completed updated_at is later than original updated_at",
    completedUpdatedAtMs > originalUpdatedAtMs,
  );
  TestValidator.predicate(
    "completed_at timestamp is not before original updated_at",
    completedCompletedAtMs >= originalUpdatedAtMs,
  );

  // 5. User: restore the todo
  const restoredTodo: ITodoAppTodo =
    await api.functional.todoApp.todoUser.todos.restore(connection, {
      todoId: originalTodo.id,
    });
  typia.assert<ITodoAppTodo>(restoredTodo);

  // 6. Validate restore behavior
  // 6-1. User-managed fields should be unchanged vs original
  TestValidator.equals(
    "restored todo title preserved from original",
    restoredTodo.title,
    originalTodo.title,
  );
  TestValidator.equals(
    "restored todo description preserved from original",
    restoredTodo.description,
    originalTodo.description,
  );
  TestValidator.equals(
    "restored todo due_date preserved from original",
    restoredTodo.due_date,
    originalTodo.due_date,
  );

  // 6-2. Lifecycle fields: status, completed_at, updated_at
  TestValidator.equals(
    "restored todo status reverted to ACTIVE",
    restoredTodo.status.code,
    activeStatus.code,
  );

  TestValidator.equals(
    "restored todo completed_at cleared to null",
    restoredTodo.completed_at,
    null,
  );

  const restoredUpdatedAtMs = new Date(restoredTodo.updated_at).getTime();
  TestValidator.predicate(
    "restored updated_at is later than original and completed updated_at",
    restoredUpdatedAtMs > originalUpdatedAtMs &&
      restoredUpdatedAtMs > completedUpdatedAtMs,
  );

  // Optional: ensure todo remains not soft-deleted
  TestValidator.equals(
    "restored todo is not soft-deleted",
    restoredTodo.deleted_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import type { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

/**
 * Validate that an authorized guestUser can retrieve details of one of their
 * own guest sessions and that cross-guest access to sessions is denied.
 *
 * Business flow:
 *
 * 1. A first visitor joins as guestUser via POST /auth/guestUser/join, creating a
 *    guest identity and session.
 * 2. Using that same authorized context, the test calls GET
 *    /todoApp/guestUser/guestUsers/{guestUserId}/sessions/{sessionId} to
 *    retrieve the detailed session record.
 * 3. The test confirms that the returned ITodoAppGuestUserSession matches the
 *    requested session id and contains non-empty telemetry fields (ip, href,
 *    referrer) and valid timestamps.
 * 4. A second, independent guestUser joins, establishing its own identity and
 *    session.
 * 5. The second guestUser then attempts to fetch the first guest's session by
 *    mixing its own guestUserId with the first guest's sessionId, which must
 *    fail because the backend enforces ownership via
 *    todo_app_guestuser_sessions.todo_app_guestuser_id.
 */
export async function test_api_guestuser_session_detail_by_authorized_guest(
  connection: api.IConnection,
) {
  // 1. First guestUser joins, creating guest identity + session and obtaining tokens.
  const firstJoinBody = typia.random<ITodoAppGuestUserJoin.IRequest>();

  const firstAuthorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: firstJoinBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(firstAuthorized);

  const firstGuestId = firstAuthorized.guest.id;
  const firstSessionId = firstAuthorized.session.id;

  // 2. Authorized guest fetches their own session detail.
  const ownSession: ITodoAppGuestUserSession =
    await api.functional.todoApp.guestUser.guestUsers.sessions.at(connection, {
      guestUserId: firstGuestId,
      sessionId: firstSessionId,
    });
  typia.assert<ITodoAppGuestUserSession>(ownSession);

  // Validate that the session id matches the requested id.
  TestValidator.equals(
    "session id matches requested id",
    ownSession.id,
    firstSessionId,
  );

  // Telemetry fields should be non-empty strings for ip, href, and referrer.
  TestValidator.predicate("session ip non-empty", ownSession.ip.length > 0);

  TestValidator.predicate("session href non-empty", ownSession.href.length > 0);

  TestValidator.predicate(
    "session referrer non-empty",
    ownSession.referrer.length > 0,
  );

  // 3. Second guestUser joins independently, getting its own identity and session.
  const secondJoinBody = typia.random<ITodoAppGuestUserJoin.IRequest>();

  const secondAuthorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: secondJoinBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(secondAuthorized);

  const secondGuestId = secondAuthorized.guest.id;

  // 4. Cross-guest access: second guest tries to access the first guest's session.
  await TestValidator.error("other guest cannot access session", async () => {
    await api.functional.todoApp.guestUser.guestUsers.sessions.at(connection, {
      guestUserId: secondGuestId,
      sessionId: firstSessionId,
    });
  });
}

