import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import { IPageITodoAppGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestuser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function patchTodoAppTodoAdminGuestUsers(props: {
  todoAdmin: TodoadminPayload;
  body: ITodoAppGuestUser.IRequest;
}): Promise<IPageITodoAppGuestuser.ISummary> {
  const body = props.body;

  const pageInput = body.page === undefined ? 1 : body.page;
  const limitInput = body.limit === undefined ? 100 : body.limit;

  const safePage = pageInput < 1 ? 1 : pageInput;
  const safeLimit = limitInput < 1 ? 100 : limitInput;

  const skip = (safePage - 1) * safeLimit;

  const whereCondition = (() => {
    const andConditions: { [key: string]: unknown }[] = [];

    // Status filtering: statusList takes precedence over single status
    if (body.statusList !== undefined) {
      if (body.statusList.length > 0) {
        andConditions.push({
          status: {
            in: body.statusList,
          },
        });
      }
    } else if (body.status !== undefined) {
      andConditions.push({
        status: body.status,
      });
    }

    if (body.externalReference !== undefined) {
      andConditions.push({
        external_reference: body.externalReference,
      });
    }

    if (body.externalReferenceLike !== undefined) {
      andConditions.push({
        external_reference: {
          contains: body.externalReferenceLike,
        },
      });
    }

    if (body.displayNameLike !== undefined) {
      andConditions.push({
        display_name: {
          contains: body.displayNameLike,
        },
      });
    }

    if (body.createdFrom !== undefined || body.createdTo !== undefined) {
      const createdAtRange: {
        gte?: string & tags.Format<"date-time">;
        lte?: string & tags.Format<"date-time">;
      } = {};

      if (body.createdFrom !== undefined) {
        createdAtRange.gte = body.createdFrom;
      }
      if (body.createdTo !== undefined) {
        createdAtRange.lte = body.createdTo;
      }

      andConditions.push({
        created_at: createdAtRange,
      });
    }

    if (andConditions.length === 0) {
      return {};
    }

    return {
      AND: andConditions,
    };
  })();

  const orderField =
    body.orderBy === undefined || body.orderBy === null
      ? "created_at"
      : body.orderBy;
  const orderDirection =
    body.orderDirection === undefined || body.orderDirection === null
      ? "desc"
      : body.orderDirection;

  const orderBy: Prisma.todo_app_guestusersOrderByWithRelationInput = (() => {
    const direction: Prisma.SortOrder =
      orderDirection === "asc" ? "asc" : "desc";

    if (orderField === "created_at") {
      return {
        created_at: direction,
      } satisfies Prisma.todo_app_guestusersOrderByWithRelationInput as Prisma.todo_app_guestusersOrderByWithRelationInput;
    }
    if (orderField === "updated_at") {
      return {
        updated_at: direction,
      } satisfies Prisma.todo_app_guestusersOrderByWithRelationInput as Prisma.todo_app_guestusersOrderByWithRelationInput;
    }
    if (orderField === "status") {
      return {
        status: direction,
      } satisfies Prisma.todo_app_guestusersOrderByWithRelationInput as Prisma.todo_app_guestusersOrderByWithRelationInput;
    }
    if (orderField === "display_name") {
      return {
        display_name: direction,
      } satisfies Prisma.todo_app_guestusersOrderByWithRelationInput as Prisma.todo_app_guestusersOrderByWithRelationInput;
    }
    if (orderField === "external_reference") {
      return {
        external_reference: direction,
      } satisfies Prisma.todo_app_guestusersOrderByWithRelationInput as Prisma.todo_app_guestusersOrderByWithRelationInput;
    }

    // Fallback to created_at when an unsupported orderBy is provided
    return {
      created_at: "desc" as Prisma.SortOrder,
    } satisfies Prisma.todo_app_guestusersOrderByWithRelationInput as Prisma.todo_app_guestusersOrderByWithRelationInput;
  })();

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_guestusers.findMany({
      where: whereCondition,
      skip: skip,
      take: safeLimit,
      orderBy: orderBy,
    }),
    MyGlobal.prisma.todo_app_guestusers.count({
      where: whereCondition,
    }),
  ]);

  const data: ITodoAppGuestUser.ISummary[] = rows.map((row) => {
    const external_reference =
      row.external_reference === null ? null : row.external_reference;
    const display_name = row.display_name === null ? null : row.display_name;

    return {
      id: row.id,
      external_reference: external_reference,
      display_name: display_name,
      status: row.status,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    };
  });

  const effectiveLimit: number & tags.Type<"int32"> & tags.Minimum<0> =
    safeLimit satisfies number as number;
  const totalPages = total === 0 ? 0 : Math.ceil(total / effectiveLimit);
  const currentIndex = total === 0 ? 0 : safePage - 1;

  const pagination: IPage.IPagination = {
    current: currentIndex,
    limit: effectiveLimit,
    records: total,
    pages: totalPages,
  };

  return {
    pagination: pagination,
    data: data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemConfig";
import { IPageITodoAppSystemConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemConfig";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function patchTodoAppTodoAdminSystemConfigs(props: {
  todoAdmin: TodoadminPayload;
  body: ITodoAppSystemConfig.IRequest;
}): Promise<IPageITodoAppSystemConfig.ISummary> {
  const maxLimit = 100;
  const requestedPage = props.body.page;
  const requestedLimit = props.body.limit;

  const effectiveLimit = requestedLimit > maxLimit ? maxLimit : requestedLimit;
  const effectivePage = requestedPage < 0 ? 0 : requestedPage;
  const skip = effectivePage * effectiveLimit;

  const includeDeleted = props.body.include_deleted;
  const isActiveFilter = props.body.is_active;
  const scopeFilter = props.body.scope;
  const keyFilter = props.body.key;

  const baseWhere: Prisma.todo_app_system_configsWhereInput = {
    ...(includeDeleted ? {} : { deleted_at: null }),
    ...(typeof isActiveFilter === "boolean"
      ? { is_active: isActiveFilter }
      : {}),
    ...(scopeFilter !== null && scopeFilter !== undefined && scopeFilter !== ""
      ? { scope: scopeFilter }
      : {}),
    ...(keyFilter !== null && keyFilter !== undefined && keyFilter !== ""
      ? { key: keyFilter }
      : {}),
  };

  const orderByField = props.body.order_by;
  const orderDirectionRaw = props.body.order_direction;
  const orderDirection: Prisma.SortOrder =
    orderDirectionRaw === "desc" ? "desc" : "asc";

  const orderByList: Prisma.todo_app_system_configsOrderByWithRelationInput[] =
    [];

  if (
    orderByField === "scope" ||
    orderByField === "key" ||
    orderByField === "created_at"
  ) {
    if (orderByField === "scope") {
      orderByList.push({ scope: orderDirection });
    } else if (orderByField === "key") {
      orderByList.push({ key: orderDirection });
    } else if (orderByField === "created_at") {
      orderByList.push({ created_at: orderDirection });
    }
  }

  if (orderByList.length === 0) {
    orderByList.push({ scope: "asc" });
    orderByList.push({ key: "asc" });
  }

  const [rows, totalCount] = await Promise.all([
    MyGlobal.prisma.todo_app_system_configs.findMany({
      where: baseWhere,
      orderBy: orderByList,
      skip,
      take: effectiveLimit,
    }),
    MyGlobal.prisma.todo_app_system_configs.count({
      where: baseWhere,
    }),
  ]);

  const data = rows.map(
    (row): ITodoAppSystemConfig.ISummary => ({
      id: row.id,
      scope: row.scope,
      key: row.key,
      value: row.value,
      description: row.description === null ? null : row.description,
      is_active: row.is_active,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
      deleted_at:
        row.deleted_at === null ? null : toISOStringSafe(row.deleted_at),
    }),
  );

  const pages =
    totalCount === 0 || effectiveLimit === 0
      ? 0
      : Math.ceil(totalCount / effectiveLimit);

  const pagination: IPage.IPagination = {
    current: effectivePage satisfies number as number,
    limit: effectiveLimit satisfies number as number,
    records: totalCount,
    pages,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminSession";
import { IPageITodoAppTodoadminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoadminSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function patchTodoAppTodoAdminTodoAdminsTodoAdminIdSessions(props: {
  todoAdmin: TodoadminPayload;
  todoAdminId: string;
  body: ITodoAppTodoAdminSession.IRequest;
}): Promise<IPageITodoAppTodoadminSession.ISummary> {
  const requestedAdminId = props.todoAdminId;

  // Pagination parameters with sensible defaults and non-negative clamping
  const rawPage = props.body.page ?? 0;
  const rawLimit = props.body.limit ?? 20;

  const page = rawPage < 0 ? 0 : rawPage;
  const limit = rawLimit <= 0 ? 20 : rawLimit;
  const skip = page * limit;

  // OrderBy allowlist to prevent arbitrary column usage
  const baseOrderMap = {
    created_at: { created_at: "asc" as const },
    expired_at: { expired_at: "asc" as const },
    id: { id: "asc" as const },
  } as const;

  const requestedOrderBy = props.body.orderBy ?? "created_at";
  const baseOrder = Object.prototype.hasOwnProperty.call(
    baseOrderMap,
    requestedOrderBy,
  )
    ? baseOrderMap[requestedOrderBy as keyof typeof baseOrderMap]
    : baseOrderMap.created_at;

  const direction: "asc" | "desc" =
    props.body.orderDirection === "asc" ? "asc" : "desc";

  const orderBy = Object.keys(baseOrder).reduce(
    (acc, key) => {
      return {
        ...acc,
        [key]: direction,
      };
    },
    {} as Record<string, "asc" | "desc">,
  );

  const where = {
    todoAdmin: {
      id: requestedAdminId,
    },
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todoadmin_sessions.findMany({
      where,
      orderBy,
      skip,
      take: limit,
      include: {
        todoAdmin: true,
      },
    }),
    MyGlobal.prisma.todo_app_todoadmin_sessions.count({ where }),
  ]);

  const data: ITodoAppTodoAdminSession.ISummary[] = rows.map((row) => {
    const admin = row.todoAdmin;

    const todoAdminSummary: ITodoAppTodoAdmin.ISummary = {
      id: admin.id,
      email: admin.email,
      display_name:
        admin.display_name === null ? undefined : admin.display_name,
      status: admin.status,
      last_login_at:
        admin.last_login_at === null
          ? undefined
          : toISOStringSafe(admin.last_login_at),
      created_at: toISOStringSafe(admin.created_at),
      updated_at: toISOStringSafe(admin.updated_at),
    };

    const expiredAt =
      row.expired_at === null ? null : toISOStringSafe(row.expired_at);

    const summary: ITodoAppTodoAdminSession.ISummary = {
      id: row.id,
      todoAdmin: todoAdminSummary,
      ip: row.ip,
      href: row.href,
      referrer: row.referrer,
      created_at: toISOStringSafe(row.created_at),
      expired_at: expiredAt,
    };

    return summary;
  });

  const pagination: IPage.IPagination = {
    current: page satisfies number as number,
    limit: limit satisfies number as number,
    records: total satisfies number as number,
    pages: (limit === 0
      ? 0
      : Math.ceil(total / limit)) satisfies number as number,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { IPageITodoAppTodouser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodouser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function patchTodoAppTodoAdminTodoUsers(props: {
  todoAdmin: TodoadminPayload;
  body: ITodoAppTodoUser.IRequest;
}): Promise<IPageITodoAppTodouser.ISummary> {
  // Authorization: props.todoAdmin is already a validated todoAdmin payload
  // according to the controller-level decorator, so no further checks here.

  const pageInput = props.body.page;
  const limitInput = props.body.limit;

  const page = pageInput !== undefined && pageInput > 0 ? pageInput : 1;
  const maxLimit = 100;
  const limit =
    limitInput !== undefined && limitInput > 0
      ? limitInput > maxLimit
        ? maxLimit
        : limitInput
      : 10;

  const skip = (page - 1) * limit;

  const whereCondition = {
    ...(props.body.email !== undefined &&
      props.body.email !== null && {
        email: props.body.email,
      }),
    ...(props.body.status !== undefined &&
      props.body.status !== null && {
        status: props.body.status,
      }),
    ...(() => {
      const createdFrom = props.body.created_from;
      const createdTo = props.body.created_to;
      if (!createdFrom && !createdTo) return {};
      return {
        created_at: {
          ...(createdFrom && { gte: createdFrom }),
          ...(createdTo && { lte: createdTo }),
        },
      };
    })(),
    ...(() => {
      const lastLoginFrom = props.body.last_login_from;
      const lastLoginTo = props.body.last_login_to;
      if (!lastLoginFrom && !lastLoginTo) return {};
      return {
        last_login_at: {
          ...(lastLoginFrom && { gte: lastLoginFrom }),
          ...(lastLoginTo && { lte: lastLoginTo }),
        },
      };
    })(),
  };

  const orderField = props.body.order_by ?? "created_at";
  const directionRaw = props.body.order_direction ?? "desc";
  const direction = directionRaw === "asc" ? "asc" : "desc";

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todousers.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy: (() => {
        if (orderField === "email") return { email: direction };
        if (orderField === "last_login_at") return { last_login_at: direction };
        return { created_at: direction };
      })(),
    }),
    MyGlobal.prisma.todo_app_todousers.count({
      where: whereCondition,
    }),
  ]);

  const data = rows.map((row) => {
    return {
      id: row.id,
      email: row.email,
      display_name: row.display_name === null ? undefined : row.display_name,
      status: row.status,
      created_at: toISOStringSafe(row.created_at),
    };
  });

  const pagination: IPage.IPagination = {
    current: page - 1,
    limit: limit satisfies number as number,
    records: total,
    pages: total === 0 ? 0 : Math.ceil(total / limit),
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoAdminJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminJoin";
import { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoAdminJoin(props: {
  body: ITodoAppTodoAdminJoin.IRequest;
}): Promise<ITodoAppTodoAdmin.IAuthorized> {
  const password = props.body.password;

  // Business-level password policy: at least 8 chars, must contain letters and numbers.
  const hasMinimumLength = password.length >= 8;
  const hasLetter = /[A-Za-z]/.test(password);
  const hasNumber = /[0-9]/.test(password);

  if (!hasMinimumLength || !hasLetter || !hasNumber) {
    throw new HttpException(
      "Password does not meet complexity requirements",
      400,
    );
  }

  // Pre-check for existing admin with same email to provide deterministic conflict error.
  const existingAdmin = await MyGlobal.prisma.todo_app_todoadmins.findFirst({
    where: { email: props.body.email },
  });

  if (existingAdmin) {
    throw new HttpException("Email already registered", 409);
  }

  // Current timestamp as ISO string.
  const now = toISOStringSafe(new Date());

  // Compute expiration timestamps for access and refresh tokens.
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  const adminId = v4();

  try {
    // Create admin account with hashed password.
    const passwordHash = await PasswordUtil.hash(password);

    const admin = await MyGlobal.prisma.todo_app_todoadmins.create({
      data: {
        id: adminId,
        email: props.body.email,
        password_hash: passwordHash,
        display_name:
          props.body.displayName === undefined ? null : props.body.displayName,
        status: "active",
        last_login_at: null,
        created_at: now,
        updated_at: now,
      },
    });

    // Create initial admin session.
    const sessionId = v4();

    const session = await MyGlobal.prisma.todo_app_todoadmin_sessions.create({
      data: {
        id: sessionId,
        todo_app_todoadmin_id: admin.id,
        // Prisma column expects non-nullable string, so normalize nullable ip into string.
        ip: props.body.ip ?? "",
        href: props.body.href,
        referrer: props.body.referrer,
        created_at: now,
        expired_at: accessExpires,
      },
    });

    const tokenCreatedAt = now;

    const accessToken = jwt.sign(
      {
        type: "todoAdmin",
        id: admin.id,
        session_id: session.id,
        created_at: tokenCreatedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    );

    const refreshToken = jwt.sign(
      {
        type: "todoAdmin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: tokenCreatedAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    );

    const token: IAuthorizationToken = {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    };

    return {
      id: admin.id,
      email: admin.email,
      display_name: admin.display_name,
      status: admin.status,
      // ITodoAppTodoAdmin.IAuthorized expects (string & Format<"date-time">) | null | undefined
      // while Prisma field is Date | null; convert non-null Date via toISOStringSafe.
      last_login_at:
        admin.last_login_at === null
          ? null
          : toISOStringSafe(admin.last_login_at as unknown as Date),
      // created_at / updated_at are Date in Prisma and string & Format<"date-time"> in DTO.
      created_at: toISOStringSafe(admin.created_at as unknown as Date),
      updated_at: toISOStringSafe(admin.updated_at as unknown as Date),
      token,
    };
  } catch (error) {
    // Handle possible race-condition unique constraint violation.
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      throw new HttpException("Email already registered", 409);
    }

    throw error;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoAdminLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminLogin";
import { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoAdminLogin(props: {
  body: ITodoAppTodoAdminLogin.IRequest;
}): Promise<ITodoAppTodoAdmin.IAuthorized> {
  const { body } = props;

  const admin = await MyGlobal.prisma.todo_app_todoadmins.findFirst({
    where: {
      email: body.email,
    },
  });

  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }

  const passwordValid = await PasswordUtil.verify(
    body.password,
    admin.password_hash,
  );
  if (!passwordValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  if (admin.status !== "active") {
    throw new HttpException("Account is not allowed to login", 403);
  }

  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const sessionId = v4();

  const session = await MyGlobal.prisma.todo_app_todoadmin_sessions.create({
    data: {
      id: sessionId,
      todo_app_todoadmin_id: admin.id,
      ip: body.ip ?? "",
      href: body.href,
      referrer: body.referrer,
      created_at: toISOStringSafe(now),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  const tokenCreatedAt = toISOStringSafe(now);

  const accessToken = jwt.sign(
    {
      type: "todoAdmin",
      id: admin.id,
      session_id: session.id,
      created_at: tokenCreatedAt,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "todoAdmin",
      id: admin.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: tokenCreatedAt,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  const lastLoginAt: string | null = admin.last_login_at
    ? toISOStringSafe(admin.last_login_at)
    : null;

  return {
    id: admin.id,
    email: admin.email,
    display_name: admin.display_name ?? null,
    status: admin.status,
    last_login_at: lastLoginAt,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoAdminRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminRefresh";
import { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoAdminRefresh(props: {
  body: ITodoAppTodoAdminRefresh.IRequest;
}): Promise<ITodoAppTodoAdmin.IAuthorized> {
  // Define the expected JWT payload shape to avoid using 'any'
  interface ITodoAdminJwtPayload extends jwt.JwtPayload {
    type: "todoAdmin";
    id: string;
    session_id: string;
  }

  let decoded: ITodoAdminJwtPayload | null = null;

  try {
    const raw = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      {
        issuer: "autobe",
      },
    );

    // jwt.verify can return string | JwtPayload; ensure it's an object
    if (typeof raw !== "object" || raw === null) {
      throw new HttpException("Invalid refresh token payload", 401);
    }

    const payload = raw as ITodoAdminJwtPayload;

    // Basic runtime shape validation for required fields
    if (
      payload.type !== "todoAdmin" ||
      typeof payload.id !== "string" ||
      typeof payload.session_id !== "string"
    ) {
      throw new HttpException("Invalid refresh token payload", 401);
    }

    decoded = payload;
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (!decoded || decoded.type !== "todoAdmin") {
    throw new HttpException("Invalid refresh token type", 403);
  }

  const session = await MyGlobal.prisma.todo_app_todoadmin_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_app_todoadmin_id: decoded.id,
    },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  // Fetch the related admin record explicitly since include relation is not
  // exposed on the session type in this environment.
  const admin = await MyGlobal.prisma.todo_app_todoadmins.findUnique({
    where: {
      id: session.todo_app_todoadmin_id,
    },
  });

  if (!admin) {
    throw new HttpException("Session expired or revoked", 401);
  }

  if (admin.status === "suspended" || admin.status === "closed") {
    throw new HttpException("Administrator account is not active", 403);
  }

  if (session.expired_at) {
    const expiredAtTime = new Date(session.expired_at).getTime();
    const nowMillis = Date.now();
    if (!Number.isFinite(expiredAtTime) || expiredAtTime <= nowMillis) {
      throw new HttpException("Session expired or revoked", 401);
    }
  }

  const nowMillis = Date.now();
  const accessExpiresMillis = nowMillis + 60 * 60 * 1000;
  const refreshExpiresMillis = nowMillis + 7 * 24 * 60 * 60 * 1000;

  const accessExpiresIso = toISOStringSafe(new Date(accessExpiresMillis));
  const refreshExpiresIso = toISOStringSafe(new Date(refreshExpiresMillis));

  const accessToken = jwt.sign(
    {
      type: "todoAdmin",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "todoAdmin",
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  await MyGlobal.prisma.todo_app_todoadmin_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: new Date(refreshExpiresMillis),
    },
  });

  const displayNameValue =
    admin.display_name === null ? null : admin.display_name;
  const lastLoginAtValue =
    admin.last_login_at === null ? null : toISOStringSafe(admin.last_login_at);

  return {
    id: admin.id,
    email: admin.email,
    display_name: displayNameValue,
    status: admin.status,
    last_login_at: lastLoginAtValue,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiresIso,
      refreshable_until: refreshExpiresIso,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserJoin";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserJoin(props: {
  body: ITodoAppTodoUserJoin.IRequest;
}): Promise<ITodoAppTodoUser.IAuthorized> {
  const { body } = props;

  const existingUser = await MyGlobal.prisma.todo_app_todousers.findFirst({
    where: {
      email: body.email,
    },
  });

  if (existingUser !== null) {
    throw new HttpException("Email already registered", 409);
  }

  const passwordHash = await PasswordUtil.hash(body.password);

  const now = new Date();
  const nowIso = toISOStringSafe(now);

  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const accessExpiresIso = toISOStringSafe(accessExpires);
  const refreshExpiresIso = toISOStringSafe(refreshExpires);

  const { user, session } = await MyGlobal.prisma.$transaction(async (tx) => {
    const createdUser = await tx.todo_app_todousers.create({
      data: {
        id: v4(),
        email: body.email,
        password_hash: passwordHash,
        display_name:
          body.display_name === null || body.display_name === undefined
            ? null
            : body.display_name,
        status: "active",
        last_login_at: null,
        created_at: nowIso,
        updated_at: nowIso,
      },
    });

    const createdSession = await tx.todo_app_todouser_sessions.create({
      data: {
        id: v4(),
        todo_app_todouser_id: createdUser.id,
        ip: body.ip ?? "",
        href: body.href,
        referrer: body.referrer,
        created_at: nowIso,
        expired_at: accessExpiresIso,
      },
    });

    return {
      user: createdUser,
      session: createdSession,
    };
  });

  const tokenCreatedAt = nowIso;

  const accessToken = jwt.sign(
    {
      type: "todouser",
      id: user.id,
      session_id: session.id,
      created_at: tokenCreatedAt,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "todouser",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: tokenCreatedAt,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresIso,
    refreshable_until: refreshExpiresIso,
  };

  const result: ITodoAppTodoUser.IAuthorized = {
    id: user.id,
    email: user.email,
    displayName: user.display_name === null ? null : user.display_name,
    status: user.status,
    last_login_at: null,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserLogin";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserLogin(props: {
  body: ITodoAppTodoUserLogin.IRequest;
}): Promise<ITodoAppTodoUser.IAuthorized> {
  const body = props.body;

  const user = await MyGlobal.prisma.todo_app_todousers.findFirst({
    where: {
      email: body.email,
    },
  });

  const invalidCredentialsMessage = "Invalid credentials";

  if (!user) {
    throw new HttpException(invalidCredentialsMessage, 401);
  }

  if (user.status !== "active") {
    throw new HttpException(invalidCredentialsMessage, 401);
  }

  const passwordOk = await PasswordUtil.verify(
    body.password,
    user.password_hash,
  );

  if (!passwordOk) {
    throw new HttpException(invalidCredentialsMessage, 401);
  }

  const nowDate = new Date();
  const nowIso = toISOStringSafe(nowDate);

  const updatedUser = await MyGlobal.prisma.todo_app_todousers.update({
    where: {
      id: user.id,
    },
    data: {
      last_login_at: nowIso,
      updated_at: nowIso,
    },
  });

  const sessionId = v4();

  const session = await MyGlobal.prisma.todo_app_todouser_sessions.create({
    data: {
      id: sessionId,
      todo_app_todouser_id: updatedUser.id,
      // Columns are non-nullable string, so do not pass null; use empty string when value is absent.
      ip: body.ip ?? "",
      href:
        (body.href ?? null) !== null
          ? ((body.href ?? "") satisfies string as string)
          : "",
      referrer:
        (body.referrer ?? null) !== null
          ? ((body.referrer ?? "") satisfies string as string)
          : "",
      created_at: nowIso,
      expired_at: null,
    },
  });

  const accessExpiresDate = new Date(nowDate.getTime() + 60 * 60 * 1000);
  const refreshExpiresDate = new Date(
    nowDate.getTime() + 7 * 24 * 60 * 60 * 1000,
  );
  const accessExpiresIso = toISOStringSafe(accessExpiresDate);
  const refreshExpiresIso = toISOStringSafe(refreshExpiresDate);

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "todouser",
        id: updatedUser.id,
        session_id: session.id,
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "todouser",
        id: updatedUser.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpiresIso,
    refreshable_until: refreshExpiresIso,
  };

  // Convert Prisma Date | null field to the expected string | null | undefined using toISOStringSafe.
  const lastLoginAtRaw = updatedUser.last_login_at;
  const lastLoginAt: (string & tags.Format<"date-time">) | null | undefined =
    lastLoginAtRaw !== null && lastLoginAtRaw !== undefined
      ? toISOStringSafe(lastLoginAtRaw)
      : null;

  return {
    id: updatedUser.id,
    email: updatedUser.email,
    displayName: updatedUser.display_name ?? null,
    status: updatedUser.status,
    last_login_at: lastLoginAt,
    created_at: toISOStringSafe(updatedUser.created_at),
    updated_at: toISOStringSafe(updatedUser.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function putTodoAppTodoUserTodosTodoId(props: {
  todoUser: TodouserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoAppTodo.IUpdate;
}): Promise<ITodoAppTodo> {
  // 1. Locate the todo belonging to this authenticated todo user
  const existing = await MyGlobal.prisma.todo_app_todos.findFirst({
    where: {
      id: props.todoId,
      // Filter by owning user using the correct foreign key column
      todo_user_id: props.todoUser.id,
      deleted_at: null,
    },
  });

  if (existing === null) {
    // Use 404 to avoid leaking whether another user's todo exists
    throw new HttpException("Todo not found", 404);
  }

  // 2. Determine target status and lifecycle changes if status is updated
  const hasStatusUpdate = props.body.todo_status_id !== undefined;
  const targetStatusId = hasStatusUpdate
    ? props.body.todo_status_id
    : existing.todo_status_id;

  // Load target status to validate and to infer completion semantics
  const targetStatus = await MyGlobal.prisma.todo_app_todo_statuses.findUnique({
    where: {
      id: targetStatusId,
    },
  });

  if (targetStatus === null || targetStatus.is_active !== true) {
    throw new HttpException("Invalid todo status", 400);
  }

  const isTargetCompleted = targetStatus.code === "COMPLETED";

  const currentCompletedAt = existing.completed_at;
  const shouldSetCompletedAt = isTargetCompleted && currentCompletedAt === null;
  const shouldClearCompletedAt =
    !isTargetCompleted && currentCompletedAt !== null;

  // 3. Build update payload inline according to provided fields (partial update)
  const now = new Date();

  const updated = await MyGlobal.prisma.todo_app_todos.update({
    where: {
      id: existing.id,
    },
    data: {
      ...(props.body.title !== undefined && {
        title: props.body.title,
      }),
      ...(props.body.description !== undefined && {
        description: props.body.description,
      }),
      ...(props.body.due_date !== undefined && {
        due_date:
          props.body.due_date === null ? null : new Date(props.body.due_date),
      }),
      ...(hasStatusUpdate && {
        todo_status_id: props.body.todo_status_id,
      }),
      ...(shouldSetCompletedAt && {
        completed_at: now,
      }),
      ...(shouldClearCompletedAt && {
        completed_at: null,
      }),
      updated_at: now,
    },
  });

  // 4. Map DB record to ITodoAppTodo DTO, converting Date objects to ISO strings
  // Note: we never expose Date types directly; all date-time fields use toISOStringSafe.
  return {
    id: updated.id,
    title: updated.title,
    description: updated.description,
    due_date:
      updated.due_date === null ? null : toISOStringSafe(updated.due_date),
    status: {
      id: targetStatus.id,
      code: targetStatus.code,
      label: targetStatus.label,
      is_default: targetStatus.is_default,
      is_active: targetStatus.is_active,
    },
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    completed_at:
      updated.completed_at === null
        ? null
        : toISOStringSafe(updated.completed_at),
    deleted_at:
      updated.deleted_at === null ? null : toISOStringSafe(updated.deleted_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function deleteTodoAppTodoUserTodosTodoId(props: {
  todoUser: TodouserPayload;
  todoId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Look up the todo by its primary key.
  const existingTodo = await MyGlobal.prisma.todo_app_todos.findUnique({
    where: {
      id: props.todoId,
    },
  });

  // If the todo does not exist at all, treat delete as idempotent and succeed.
  if (existingTodo === null) {
    return;
  }

  // Enforce ownership: only the owning todo user can delete this todo.
  // To avoid leaking information about other users' data, respond with
  // a not-found error when the todo is not owned by the caller.
  if (existingTodo.todo_user_id !== props.todoUser.id) {
    throw new HttpException("Todo not found", 404);
  }

  // Perform a hard delete of the todo record.
  await MyGlobal.prisma.todo_app_todos.delete({
    where: {
      id: props.todoId,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppActorSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorSession";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function getTodoAppTodoAdminActorsSessionsSessionId(props: {
  todoAdmin: TodoadminPayload;
  sessionId: string & tags.Format<"uuid">;
}): Promise<ITodoAppActorSession> {
  // Read-only lookup of a session across admin, user, and guest session tables.
  // Auth has already been enforced by the controller via TodoadminAuth.

  // 1. Try to find an admin session with this ID.
  const adminSession =
    await MyGlobal.prisma.todo_app_todoadmin_sessions.findUnique({
      where: { id: props.sessionId },
      include: {
        todoAdmin: true,
      },
    });

  if (adminSession !== null) {
    return {
      id: adminSession.id,
      actorType: "admin",
      actorId: adminSession.todoAdmin.id,
      ip: adminSession.ip,
      href: adminSession.href,
      referrer: adminSession.referrer,
      createdAt: toISOStringSafe(adminSession.created_at),
      expiredAt:
        adminSession.expired_at === null
          ? null
          : toISOStringSafe(adminSession.expired_at),
    };
  }

  // 2. Try to find a registered todo user session.
  const userSession =
    await MyGlobal.prisma.todo_app_todouser_sessions.findUnique({
      where: { id: props.sessionId },
      include: {
        todoUser: true,
      },
    });

  if (userSession !== null) {
    return {
      id: userSession.id,
      actorType: "user",
      actorId: userSession.todoUser.id,
      ip: userSession.ip,
      href: userSession.href,
      referrer: userSession.referrer,
      createdAt: toISOStringSafe(userSession.created_at),
      expiredAt:
        userSession.expired_at === null
          ? null
          : toISOStringSafe(userSession.expired_at),
    };
  }

  // 3. Finally, try to find a guest user session.
  const guestSession =
    await MyGlobal.prisma.todo_app_guestuser_sessions.findUnique({
      where: { id: props.sessionId },
      // Use the correct include property name as suggested by the compiler,
      // so that the relation is properly resolved when needed.
      include: {
        guestUser: true,
      },
    });

  if (guestSession !== null) {
    return {
      id: guestSession.id,
      actorType: "guest",
      // The session row exposes the owning guest user's id via its foreign key
      // `todo_app_guestuser_id`, so use that as the actor identifier instead
      // of a non-existent nested `guestuser` relation.
      actorId: guestSession.todo_app_guestuser_id,
      ip: guestSession.ip,
      href: guestSession.href,
      referrer: guestSession.referrer,
      createdAt: toISOStringSafe(guestSession.created_at),
      expiredAt:
        guestSession.expired_at === null
          ? null
          : toISOStringSafe(guestSession.expired_at),
    };
  }

  // 4. No session found in any table.
  throw new HttpException("Session not found", 404);
}

