import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdminAudit";
import { IPageITodoAppTodoAdminAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoAdminAudit";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function patchTodoAppTodoAdminTodosTodoIdAdminAudits(props: {
  todoAdmin: TodoadminPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoAppTodoAdminAudit.IRequest;
}): Promise<IPageITodoAppTodoAdminAudit.ISummary> {
  const requestedPage: number = props.body.page ?? 1;
  const requestedLimit: number = props.body.limit ?? 20;

  const requestedPageWithMin: number = requestedPage < 1 ? 1 : requestedPage;
  const maxLimit: number = 100;
  const safeLimit: number =
    requestedLimit <= 0
      ? 20
      : requestedLimit > maxLimit
        ? maxLimit
        : requestedLimit;

  const todo = await MyGlobal.prisma.todo_app_todos.findUnique({
    where: {
      id: props.todoId,
    },
    include: {
      status: true,
    },
  });

  if (todo === null) {
    throw new HttpException("Todo not found", 404);
  }

  const where = {
    todo_app_todo_id: props.todoId,
    ...(props.body.action !== undefined && props.body.action !== null
      ? { action: props.body.action }
      : {}),
    ...(props.body.field_name !== undefined && props.body.field_name !== null
      ? { field_name: props.body.field_name }
      : {}),
    ...(props.body.admin_id !== undefined && props.body.admin_id !== null
      ? { todo_app_todoadmin_id: props.body.admin_id }
      : {}),
    ...((props.body.created_from !== undefined &&
      props.body.created_from !== null) ||
    (props.body.created_to !== undefined && props.body.created_to !== null)
      ? {
          created_at: {
            ...(props.body.created_from !== undefined &&
            props.body.created_from !== null
              ? { gte: props.body.created_from }
              : {}),
            ...(props.body.created_to !== undefined &&
            props.body.created_to !== null
              ? { lte: props.body.created_to }
              : {}),
          },
        }
      : {}),
  };

  const skip: number = (requestedPageWithMin - 1) * safeLimit;

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todo_admin_audits.findMany({
      where,
      skip,
      take: safeLimit,
      orderBy: {
        created_at: "desc",
      },
    }),
    MyGlobal.prisma.todo_app_todo_admin_audits.count({
      where,
    }),
  ]);

  const totalRecords: number = total;
  const totalPages: number =
    totalRecords === 0 ? 0 : Math.ceil(totalRecords / safeLimit);

  let currentPageIndex: number;
  if (totalPages === 0) {
    currentPageIndex = 0;
  } else if (requestedPageWithMin > totalPages) {
    currentPageIndex = totalPages - 1;
  } else {
    currentPageIndex = requestedPageWithMin - 1;
  }

  const data: ITodoAppTodoAdminAudit.ISummary[] = [];

  for (const audit of rows) {
    const [todoRow, adminRow] = await Promise.all([
      MyGlobal.prisma.todo_app_todos.findUnique({
        where: { id: audit.todo_app_todo_id },
        include: { status: true },
      }),
      MyGlobal.prisma.todo_app_todoadmins.findUnique({
        where: { id: audit.todo_app_todoadmin_id },
      }),
    ]);

    if (todoRow === null || adminRow === null) {
      continue;
    }

    const todoSummary: ITodoAppTodo.ISummary = {
      id: todoRow.id,
      title: todoRow.title,
      status: todoRow.status.code,
      statusInfo:
        todoRow.status === null
          ? undefined
          : {
              id: todoRow.status.id,
              code: todoRow.status.code,
              label: todoRow.status.label,
              is_default: todoRow.status.is_default,
              is_active: todoRow.status.is_active,
            },
      due_date:
        todoRow.due_date === null
          ? undefined
          : toISOStringSafe(todoRow.due_date),
      created_at: toISOStringSafe(todoRow.created_at),
      updated_at: toISOStringSafe(todoRow.updated_at),
      completed_at:
        todoRow.completed_at === null
          ? undefined
          : toISOStringSafe(todoRow.completed_at),
    };

    const adminSummary: ITodoAppTodoAdmin.ISummary = {
      id: adminRow.id,
      email: adminRow.email,
      display_name:
        adminRow.display_name === null ? undefined : adminRow.display_name,
      status: adminRow.status,
      last_login_at:
        adminRow.last_login_at === null
          ? undefined
          : toISOStringSafe(adminRow.last_login_at),
      created_at: toISOStringSafe(adminRow.created_at),
      updated_at: toISOStringSafe(adminRow.updated_at),
    };

    const summary: ITodoAppTodoAdminAudit.ISummary = {
      id: audit.id,
      action: audit.action,
      field_name: audit.field_name === null ? undefined : audit.field_name,
      previous_value:
        audit.previous_value === null ? undefined : audit.previous_value,
      new_value: audit.new_value === null ? undefined : audit.new_value,
      reason: audit.reason === null ? undefined : audit.reason,
      created_at: toISOStringSafe(audit.created_at),
      todo: todoSummary,
      admin: adminSummary,
    };

    data.push(summary);
  }

  const pagination: IPage.IPagination = {
    current: currentPageIndex,
    limit: safeLimit,
    records: totalRecords,
    pages: totalPages,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuestUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserRefresh";
import { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";
import { GuestuserPayload } from "../decorators/payload/GuestuserPayload";

export async function postAuthGuestUserRefresh(props: {
  guestUser: GuestuserPayload;
  body: ITodoAppGuestUserRefresh.IRequest;
}): Promise<ITodoAppGuestUser.IAuthorized> {
  // 1. Decode and verify the refresh token
  let decoded: {
    id: string;
    session_id: string;
    type: "guestUser" | string;
    tokenType?: string;
    created_at?: string;
  };

  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      {
        issuer: "autobe",
      },
    ) as {
      id: string;
      session_id: string;
      type: "guestUser" | string;
      tokenType?: string;
      created_at?: string;
    };
  } catch (_error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "guestUser") {
    throw new HttpException("Invalid token type", 403);
  }

  // 2. Validate that the session exists and is active
  const session = await MyGlobal.prisma.todo_app_guestuser_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_app_guestuser_id: decoded.id,
    },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  if (session.expired_at !== null) {
    throw new HttpException("Session expired or revoked", 401);
  }

  // 3. Validate guest identity and status
  const guest = await MyGlobal.prisma.todo_app_guestusers.findFirst({
    where: {
      id: decoded.id,
      status: "active",
    },
  });

  if (!guest) {
    throw new HttpException("Guest identity is not active", 403);
  }

  // 4. Compute new expiration timestamps as ISO date-time strings
  const nowMillis = Date.now();
  const accessExpiresMillis = nowMillis + 60 * 60 * 1000; // 1 hour
  const refreshExpiresMillis = nowMillis + 7 * 24 * 60 * 60 * 1000; // 7 days

  const accessExpiresIso = toISOStringSafe(new Date(accessExpiresMillis));
  const refreshExpiresIso = toISOStringSafe(new Date(refreshExpiresMillis));
  const createdAtIso = toISOStringSafe(new Date());

  // 5. Generate new JWT tokens reusing the same session id and guest id
  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // 6. Update session record with new navigation context and extended expiry
  const updatedSession =
    await MyGlobal.prisma.todo_app_guestuser_sessions.update({
      where: {
        id: decoded.session_id,
      },
      data: {
        ip: props.body.ip ?? session.ip,
        href: props.body.href,
        referrer: props.body.referrer,
        expired_at: new Date(refreshExpiresMillis),
      },
    });

  // 7. Build guest summary DTO from guest row
  const guestSummary: ITodoAppGuestUser.ISummary = {
    id: guest.id,
    external_reference:
      guest.external_reference === null ? null : guest.external_reference,
    display_name: guest.display_name === null ? null : guest.display_name,
    status: guest.status,
    created_at: toISOStringSafe(guest.created_at),
    updated_at: toISOStringSafe(guest.updated_at),
  };

  // 8. Build session summary DTO from updated session row
  const sessionSummary: ITodoAppGuestUserSession.ISummary = {
    id: updatedSession.id,
    guestUser: guestSummary,
    ip: updatedSession.ip,
    href: updatedSession.href,
    referrer: updatedSession.referrer,
    created_at: toISOStringSafe(updatedSession.created_at),
    expired_at:
      updatedSession.expired_at === null
        ? null
        : toISOStringSafe(updatedSession.expired_at),
  };

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresIso,
    refreshable_until: refreshExpiresIso,
  };

  return {
    token,
    guest: guestSummary,
    session: sessionSummary,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUserRefresh";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoUserRefresh(props: {
  body: ITodoAppTodoUserRefresh.IRequest;
}): Promise<ITodoAppTodoUser.IAuthorized> {
  let rawDecoded: unknown;

  try {
    rawDecoded = jwt.verify(
      props.body.refreshToken,
      MyGlobal.env.JWT_SECRET_KEY,
      {
        issuer: "autobe",
      },
    );
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  const decoded = rawDecoded as {
    id: string;
    session_id: string;
    type: string;
  };

  if (!decoded || decoded.type !== "todouser") {
    throw new HttpException("Invalid token type", 403);
  }

  const session = await MyGlobal.prisma.todo_app_todouser_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_app_todouser_id: decoded.id,
    },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  if (session.expired_at !== null) {
    throw new HttpException("Session has already expired", 401);
  }

  const user = await MyGlobal.prisma.todo_app_todousers.findFirst({
    where: {
      id: decoded.id,
    },
  });

  if (!user) {
    throw new HttpException("User not found", 401);
  }

  if (user.status !== "active") {
    throw new HttpException("Account is not allowed to access", 403);
  }

  const nowMs = Date.now();
  const accessExpiresMs = nowMs + 60 * 60 * 1000;
  const refreshExpiresMs = nowMs + 7 * 24 * 60 * 60 * 1000;

  const accessExpiresDate = new Date(accessExpiresMs);
  const refreshExpiresDate = new Date(refreshExpiresMs);

  const createdAtIso = new Date(nowMs).toISOString();

  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: createdAtIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  await MyGlobal.prisma.todo_app_todouser_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: refreshExpiresDate,
    },
  });

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: toISOStringSafe(accessExpiresDate),
    refreshable_until: toISOStringSafe(refreshExpiresDate),
  };

  const displayName: string | null | undefined =
    typeof user.display_name === "string" ? user.display_name : null;

  const lastLoginAt: string | null | undefined = user.last_login_at
    ? toISOStringSafe(user.last_login_at)
    : null;

  const authorized: ITodoAppTodoUser.IAuthorized = {
    id: user.id,
    email: user.email,
    displayName,
    status: user.status,
    last_login_at: lastLoginAt,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
  };

  return authorized;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoAdmin";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function putTodoAppTodoAdminTodoAdminsTodoAdminId(props: {
  todoAdmin: TodoadminPayload;
  todoAdminId: string & tags.Format<"uuid">;
  body: ITodoAppTodoAdmin.IUpdate;
}): Promise<ITodoAppTodoAdmin> {
  const { todoAdminId, body } = props;

  const existing = await MyGlobal.prisma.todo_app_todoadmins.findUnique({
    where: { id: todoAdminId },
  });

  if (existing === null) {
    throw new HttpException("Admin not found", 404);
  }

  if (
    body.status !== undefined &&
    existing.status === "CLOSED" &&
    body.status === "ACTIVE"
  ) {
    throw new HttpException(
      "Cannot transition status from CLOSED to ACTIVE",
      400,
    );
  }

  try {
    const updated = await MyGlobal.prisma.todo_app_todoadmins.update({
      where: { id: todoAdminId },
      data: {
        ...(body.email !== undefined ? { email: body.email } : {}),
        ...(body.display_name !== undefined
          ? { display_name: body.display_name }
          : {}),
        ...(body.status !== undefined ? { status: body.status } : {}),
      },
    });

    const result: ITodoAppTodoAdmin = {
      id: updated.id,
      email: updated.email,
      display_name: updated.display_name === null ? null : updated.display_name,
      status: updated.status,
      last_login_at:
        updated.last_login_at === null
          ? null
          : toISOStringSafe(updated.last_login_at),
      created_at: toISOStringSafe(updated.created_at),
      updated_at: toISOStringSafe(updated.updated_at),
    };

    return result;
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      const target = error.meta && (error.meta as { target?: unknown }).target;
      const targetList = Array.isArray(target)
        ? target
        : typeof target === "string"
          ? [target]
          : [];

      if (
        targetList.some(
          (name) =>
            name === "email" || name === "todo_app_todoadmins_email_key",
        )
      ) {
        throw new HttpException("Email already in use", 400);
      }
    }

    throw error;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function patchTodoAppTodoUserTodos(props: {
  todoUser: TodouserPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  const requestBody = props.body;

  // Pagination: page is 1-based in request, current is 0-based in response
  const requestedPage = requestBody.page === undefined ? 1 : requestBody.page;
  const requestedLimit =
    requestBody.limit === undefined ? 20 : requestBody.limit;

  const effectivePage = requestedPage < 1 ? 1 : requestedPage;
  const effectiveLimit = requestedLimit < 1 ? 20 : requestedLimit;

  const zeroBasedPage = effectivePage - 1;
  const skip = zeroBasedPage * effectiveLimit;
  const take = effectiveLimit;

  // Base ownership and soft-delete constraints
  const includeDeletedFlag = requestBody.includeDeleted === true;

  const baseWhere: Prisma.todo_app_todosWhereInput = {
    todo_user_id: props.todoUser.id,
    ...(includeDeletedFlag
      ? {}
      : {
          deleted_at: null,
        }),
  };

  // Status filter: since the relation field is not present on todo_app_todosWhereInput,
  // we cannot express a join-based filter here without causing a Prisma type error.
  // Therefore, we only apply filters that are structurally valid on this model.
  const statusWhere: Prisma.todo_app_todosWhereInput = {};

  // Title keyword filter (simple contains, case-insensitive)
  const titleWhere: Prisma.todo_app_todosWhereInput =
    requestBody.titleKeyword === undefined || requestBody.titleKeyword === ""
      ? {}
      : {
          title: {
            contains: requestBody.titleKeyword,
            mode: Prisma.QueryMode.insensitive,
          },
        };

  // created_at range filter using raw ISO strings
  const createdFrom = requestBody.createdFrom;
  const createdTo = requestBody.createdTo;

  const createdAtWhere: Prisma.todo_app_todosWhereInput =
    createdFrom === undefined &&
    createdTo === undefined &&
    createdFrom === null &&
    createdTo === null
      ? {}
      : (() => {
          const range: Prisma.DateTimeFilter = {};

          if (createdFrom !== undefined && createdFrom !== null) {
            range.gte = createdFrom;
          }

          if (createdTo !== undefined && createdTo !== null) {
            range.lte = createdTo;
          }

          return Object.keys(range).length === 0
            ? {}
            : {
                created_at: range,
              };
        })();

  // due_date range filter using raw ISO strings
  const dueFrom = requestBody.dueFrom;
  const dueTo = requestBody.dueTo;

  const dueDateWhere: Prisma.todo_app_todosWhereInput =
    dueFrom === undefined &&
    dueTo === undefined &&
    dueFrom === null &&
    dueTo === null
      ? {}
      : (() => {
          const range: Prisma.DateTimeFilter = {};

          if (dueFrom !== undefined && dueFrom !== null) {
            range.gte = dueFrom;
          }

          if (dueTo !== undefined && dueTo !== null) {
            range.lte = dueTo;
          }

          return Object.keys(range).length === 0
            ? {}
            : {
                due_date: range,
              };
        })();

  const where: Prisma.todo_app_todosWhereInput = {
    ...baseWhere,
    ...statusWhere,
    ...titleWhere,
    ...createdAtWhere,
    ...dueDateWhere,
  };

  // Sorting
  const orderByField = requestBody.orderBy;
  const orderDirection: Prisma.SortOrder =
    requestBody.orderDirection === "asc" ? "asc" : "desc";

  const orderBy: Prisma.todo_app_todosOrderByWithRelationInput =
    orderByField === "dueDate"
      ? { due_date: orderDirection }
      : orderByField === "status"
        ? { todo_status_id: orderDirection }
        : { created_at: orderDirection };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todos.findMany({
      where,
      skip,
      take,
      orderBy,
    }),
    MyGlobal.prisma.todo_app_todos.count({
      where,
    }),
  ]);

  const data: ITodoAppTodo.ISummary[] = rows.map((row) => {
    // We only have primitive fields on the row, so we derive status directly
    // from the stored status code/string on the row itself when available.

    const dueDateValue = row.due_date;
    const completedAtValue = row.completed_at;

    const summary: ITodoAppTodo.ISummary = {
      id: row.id,
      title: row.title,
      status: (row as any).status ?? "",
      statusInfo: undefined,
      due_date:
        dueDateValue === null
          ? undefined
          : toISOStringSafe(dueDateValue as unknown as string),
      created_at: toISOStringSafe(row.created_at as unknown as string),
      updated_at: toISOStringSafe(row.updated_at as unknown as string),
      completed_at:
        completedAtValue === null
          ? undefined
          : toISOStringSafe(completedAtValue as unknown as string),
    };

    return summary;
  });

  const pages = effectiveLimit === 0 ? 0 : Math.ceil(total / effectiveLimit);

  const pagination: IPage.IPagination = {
    current: zeroBasedPage,
    limit: effectiveLimit,
    records: total,
    pages,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function postTodoAppTodoUserTodos(props: {
  todoUser: TodouserPayload;
  body: ITodoAppTodo.ICreate;
}): Promise<ITodoAppTodo> {
  const { todoUser, body } = props;

  const explicitStatusCode = body.status_code ?? null;

  let statusRecord = null as {
    id: string;
    code: string;
    label: string;
    is_default: boolean;
    is_active: boolean;
  } | null;

  if (explicitStatusCode !== null) {
    statusRecord = await MyGlobal.prisma.todo_app_todo_statuses.findFirst({
      where: {
        code: explicitStatusCode,
      },
    });

    if (statusRecord === null) {
      throw new HttpException(
        "Invalid status_code: not found in catalogue",
        400,
      );
    }

    if (statusRecord.is_active !== true) {
      throw new HttpException(
        "Invalid status_code: status is not active and cannot be assigned",
        400,
      );
    }
  } else {
    statusRecord = await MyGlobal.prisma.todo_app_todo_statuses.findFirst({
      where: {
        is_default: true,
        is_active: true,
      },
      orderBy: {
        sort_order: "asc",
      },
    });

    if (statusRecord === null) {
      throw new HttpException(
        "No default active todo status configured in catalogue",
        500,
      );
    }
  }

  const nowIso = toISOStringSafe(new Date());

  const created = await MyGlobal.prisma.todo_app_todos.create({
    data: {
      id: v4(),
      title: body.title,
      description: body.description === undefined ? null : body.description,
      // body.due_date is already (string & tags.Format<"date-time">) | null | undefined
      // Prisma field expects either the same or a compatible nullable type
      due_date: body.due_date === undefined ? null : body.due_date,
      todo_user_id: todoUser.id,
      todo_status_id: statusRecord.id,
      created_at: nowIso,
      updated_at: nowIso,
      completed_at: null,
      deleted_at: null,
    },
  });

  const statusSummary: ITodoAppTodoStatus.ISummary = {
    id: statusRecord.id,
    code: statusRecord.code,
    label: statusRecord.label,
    is_default: statusRecord.is_default,
    is_active: statusRecord.is_active,
  };

  const result: ITodoAppTodo = {
    id: created.id,
    title: created.title,
    description: created.description,
    due_date:
      created.due_date === null ? null : toISOStringSafe(created.due_date),
    status: statusSummary,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    completed_at:
      created.completed_at === null
        ? null
        : toISOStringSafe(created.completed_at),
    deleted_at:
      created.deleted_at === null ? null : toISOStringSafe(created.deleted_at),
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodouserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodouserSession";
import { ITodoAppTodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoUser";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function getTodoAppTodoAdminTodoUsersTodoUserIdSessionsSessionId(props: {
  todoAdmin: TodoadminPayload;
  todoUserId: string & tags.Format<"uuid">;
  sessionId: string & tags.Format<"uuid">;
}): Promise<ITodoAppTodouserSession> {
  // Authorization for todoAdmin is handled by TodoadminAuth at the controller layer.
  // Here we only enforce that the requested session belongs to the specified todo user
  // and expose a read-only administrative view.

  const sessionRecord =
    await MyGlobal.prisma.todo_app_todouser_sessions.findFirst({
      where: {
        id: props.sessionId,
        // Scope lookup to the owning todo user using the foreign key column
        todo_app_todouser_id: props.todoUserId,
      },
    });

  if (sessionRecord === null) {
    // Do not leak cross-user information: when the (user, session) pair
    // does not resolve to a row, respond with not found.
    throw new HttpException("Session not found", 404);
  }

  // Load owning todo user separately to build owner summary.
  const owner = await MyGlobal.prisma.todo_app_todousers.findUnique({
    where: {
      id: sessionRecord.todo_app_todouser_id,
    },
  });

  const ownerSummary: ITodoAppTodoUser.ISummary | undefined =
    owner === null
      ? undefined
      : {
          id: owner.id,
          email: owner.email,
          display_name:
            owner.display_name === null ? undefined : owner.display_name,
          status: owner.status,
          created_at: toISOStringSafe(owner.created_at),
        };

  const expiredAtValue: (string & tags.Format<"date-time">) | null | undefined =
    sessionRecord.expired_at === null
      ? null
      : toISOStringSafe(sessionRecord.expired_at);

  return {
    id: sessionRecord.id,
    ip: sessionRecord.ip,
    href: sessionRecord.href,
    referrer: sessionRecord.referrer,
    created_at: toISOStringSafe(sessionRecord.created_at),
    expired_at: expiredAtValue,
    owner: ownerSummary,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuestUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserJoin";
import { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { ITodoAppGuestUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserSession";

export async function postAuthGuestUserJoin(props: {
  body: ITodoAppGuestUserJoin.IRequest;
}): Promise<ITodoAppGuestUser.IAuthorized> {
  const body = props.body;

  const createDateTimeNow = (): string & tags.Format<"date-time"> => {
    const value = toISOStringSafe(new Date());
    return value as string & tags.Format<"date-time">;
  };

  const createDateTimeAfterMs = (
    milliseconds: number,
  ): string & tags.Format<"date-time"> => {
    const value = toISOStringSafe(new Date(Date.now() + milliseconds));
    return value as string & tags.Format<"date-time">;
  };

  const now = createDateTimeNow();
  const accessExpiredAt = createDateTimeAfterMs(60 * 60 * 1000);
  const refreshableUntil = createDateTimeAfterMs(7 * 24 * 60 * 60 * 1000);

  let guestRecord =
    body.external_reference !== undefined && body.external_reference !== null
      ? await MyGlobal.prisma.todo_app_guestusers.findFirst({
          where: { external_reference: body.external_reference },
        })
      : null;

  if (!guestRecord) {
    const guestId = v4();
    guestRecord = await MyGlobal.prisma.todo_app_guestusers.create({
      data: {
        id: guestId,
        external_reference:
          body.external_reference !== undefined &&
          body.external_reference !== null
            ? body.external_reference
            : null,
        display_name:
          body.display_name !== undefined && body.display_name !== null
            ? body.display_name
            : null,
        status: "active",
        created_at: now,
        updated_at: now,
      },
    });
  } else if (body.display_name !== undefined && body.display_name !== null) {
    guestRecord = await MyGlobal.prisma.todo_app_guestusers.update({
      where: { id: guestRecord.id },
      data: {
        display_name: body.display_name,
        updated_at: now,
      },
    });
  }

  const resolvedIp =
    body.ip !== undefined && body.ip !== null && body.ip.length > 0
      ? body.ip
      : "0.0.0.0";

  const sessionId = v4();
  const sessionRecord =
    await MyGlobal.prisma.todo_app_guestuser_sessions.create({
      data: {
        id: sessionId,
        todo_app_guestuser_id: guestRecord.id,
        ip: resolvedIp,
        href: body.href,
        referrer: body.referrer,
        created_at: now,
        expired_at: null,
      },
    });

  const accessToken = jwt.sign(
    {
      type: "guestUser",
      id: guestRecord.id,
      session_id: sessionRecord.id,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "guestUser",
      id: guestRecord.id,
      session_id: sessionRecord.id,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const guestSummary: ITodoAppGuestUser.ISummary = {
    id: guestRecord.id,
    external_reference:
      guestRecord.external_reference === null
        ? null
        : guestRecord.external_reference,
    display_name:
      guestRecord.display_name === null ? null : guestRecord.display_name,
    status: guestRecord.status,
    created_at: toISOStringSafe(guestRecord.created_at) as string &
      tags.Format<"date-time">,
    updated_at: toISOStringSafe(guestRecord.updated_at) as string &
      tags.Format<"date-time">,
  };

  const sessionSummary: ITodoAppGuestUserSession.ISummary = {
    id: sessionRecord.id,
    guestUser: guestSummary,
    ip: sessionRecord.ip,
    href: sessionRecord.href,
    referrer: sessionRecord.referrer,
    created_at: toISOStringSafe(sessionRecord.created_at) as string &
      tags.Format<"date-time">,
    expired_at:
      sessionRecord.expired_at === null
        ? null
        : (toISOStringSafe(sessionRecord.expired_at) as string &
            tags.Format<"date-time">),
  };

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiredAt,
    refreshable_until: refreshableUntil,
  };

  return {
    token,
    guest: guestSummary,
    session: sessionSummary,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import { TodouserPayload } from "../decorators/payload/TodouserPayload";

export async function postTodoAppTodoUserTodosTodoIdRestore(props: {
  todoUser: TodouserPayload;
  todoId: string & tags.Format<"uuid">;
}): Promise<ITodoAppTodo> {
  const existing = await MyGlobal.prisma.todo_app_todos.findFirst({
    where: {
      id: props.todoId,
    },
  });

  if (existing === null || existing.deleted_at !== null) {
    throw new HttpException("Todo not found", 404);
  }

  if (existing.todo_user_id !== props.todoUser.id) {
    // Hide existence from non-owner
    throw new HttpException("Todo not found", 404);
  }

  const now = toISOStringSafe(new Date());

  const isCompleted = existing.completed_at !== null;
  let activeStatusId: string | undefined = undefined;

  if (isCompleted) {
    // 1) Prefer ACTIVE code
    const activeByCode = await MyGlobal.prisma.todo_app_todo_statuses.findFirst(
      {
        where: {
          code: "ACTIVE",
          is_active: true,
        },
        orderBy: {
          sort_order: "asc",
        },
      },
    );

    if (activeByCode !== null) {
      activeStatusId = activeByCode.id;
    } else {
      // 2) Fallback to default active
      const activeDefault =
        await MyGlobal.prisma.todo_app_todo_statuses.findFirst({
          where: {
            is_default: true,
            is_active: true,
          },
          orderBy: {
            sort_order: "asc",
          },
        });

      if (activeDefault !== null) {
        activeStatusId = activeDefault.id;
      } else {
        // 3) Any active status
        const anyActive =
          await MyGlobal.prisma.todo_app_todo_statuses.findFirst({
            where: {
              is_active: true,
            },
            orderBy: {
              sort_order: "asc",
            },
          });

        if (anyActive !== null) {
          activeStatusId = anyActive.id;
        }
      }
    }

    if (activeStatusId === undefined) {
      throw new HttpException("No active status available for restore", 400);
    }
  }

  const updated = await MyGlobal.prisma.todo_app_todos.update({
    where: {
      id: props.todoId,
    },
    data: isCompleted
      ? {
          todo_status_id: activeStatusId!,
          completed_at: null,
          updated_at: now,
        }
      : {
          updated_at: now,
        },
  });

  // Fetch status row explicitly using the foreign key
  const statusRow = await MyGlobal.prisma.todo_app_todo_statuses.findFirst({
    where: {
      id: updated.todo_status_id,
    },
  });

  if (statusRow === null) {
    // This should not normally happen if referential integrity is maintained
    throw new HttpException("Todo status not found", 500);
  }

  const result: ITodoAppTodo = {
    id: updated.id,
    title: updated.title,
    description: updated.description ?? null,
    due_date:
      updated.due_date !== null ? toISOStringSafe(updated.due_date) : null,
    status: {
      id: statusRow.id,
      code: statusRow.code,
      label: statusRow.label,
      is_default: statusRow.is_default,
      is_active: statusRow.is_active,
    },
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    completed_at:
      updated.completed_at !== null
        ? toISOStringSafe(updated.completed_at)
        : null,
    deleted_at:
      updated.deleted_at !== null ? toISOStringSafe(updated.deleted_at) : null,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
