export async function postTodoAppTodoAdminTodoStatuses(props: {
  todoAdmin: TodoadminPayload;
  body: ITodoAppTodoStatus.ICreate;
}): Promise<ITodoAppTodoStatus> {
  // Timestamp for created_at and updated_at
  const now = new Date();

  try {
    const created = await MyGlobal.prisma.todo_app_todo_statuses.create({
      data: {
        id: v4(),
        code: props.body.code,
        label: props.body.label,
        description:
          props.body.description === undefined ? null : props.body.description,
        group: props.body.group === undefined ? null : props.body.group,
        sort_order: props.body.sort_order,
        is_default: props.body.is_default,
        is_active: props.body.is_active,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });

    return {
      id: created.id,
      code: created.code,
      label: created.label,
      description:
        created.description === null ? null : (created.description ?? null),
      group: created.group === null ? null : (created.group ?? null),
      sort_order: created.sort_order,
      is_default: created.is_default,
      is_active: created.is_active,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
      deleted_at:
        created.deleted_at === null
          ? undefined
          : toISOStringSafe(created.deleted_at),
    };
  } catch (err) {
    if (err instanceof Prisma.PrismaClientKnownRequestError) {
      if (err.code === "P2002") {
        // Unique constraint violation on code
        throw new HttpException("Todo status code must be unique", 409);
      }
    }

    throw new HttpException("Failed to create todo status", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function putTodoAppTodoAdminTodoStatusesStatusCode(props: {
  todoAdmin: TodoadminPayload;
  statusCode: string;
  body: ITodoAppTodoStatus.IUpdate;
}): Promise<ITodoAppTodoStatus> {
  const code = props.statusCode;
  const body = props.body;

  const updatedRow = await MyGlobal.prisma.$transaction(async (tx) => {
    const existing = await tx.todo_app_todo_statuses.findUnique({
      where: { code },
    });

    if (existing === null) {
      throw new HttpException("Status not found", 404);
    }

    const data = {
      updated_at: toISOStringSafe(new Date()),
      ...(body.label !== undefined && { label: body.label }),
      ...(Object.prototype.hasOwnProperty.call(body, "description") && {
        description: body.description,
      }),
      ...(Object.prototype.hasOwnProperty.call(body, "group") && {
        group: body.group,
      }),
      ...(body.sort_order !== undefined && { sort_order: body.sort_order }),
      ...(body.is_default !== undefined && { is_default: body.is_default }),
      ...(body.is_active !== undefined && { is_active: body.is_active }),
    };

    const updated = await tx.todo_app_todo_statuses.update({
      where: { code },
      data,
    });

    if (body.is_default === true) {
      await tx.todo_app_todo_statuses.updateMany({
        where: {
          code: { not: code },
          is_default: true,
        },
        data: {
          is_default: false,
          updated_at: toISOStringSafe(new Date()),
        },
      });
    }

    const reloaded = await tx.todo_app_todo_statuses.findUnique({
      where: { code },
    });

    if (reloaded === null) {
      throw new HttpException("Status not found after update", 500);
    }

    return reloaded;
  });

  return {
    id: updatedRow.id,
    code: updatedRow.code,
    label: updatedRow.label,
    description: updatedRow.description ?? undefined,
    group: updatedRow.group ?? undefined,
    sort_order: updatedRow.sort_order,
    is_default: updatedRow.is_default,
    is_active: updatedRow.is_active,
    created_at: toISOStringSafe(updatedRow.created_at),
    updated_at: toISOStringSafe(updatedRow.updated_at),
    deleted_at:
      updatedRow.deleted_at === null || updatedRow.deleted_at === undefined
        ? undefined
        : toISOStringSafe(updatedRow.deleted_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { TodoadminPayload } from "../decorators/payload/TodoadminPayload";

export async function deleteTodoAppTodoAdminTodoStatusesStatusCode(props: {
  todoAdmin: TodoadminPayload;
  statusCode: string;
}): Promise<void> {
  // Step 1: find the target status by its business code
  const existing = await MyGlobal.prisma.todo_app_todo_statuses.findUnique({
    where: {
      code: props.statusCode,
    },
  });

  if (existing === null) {
    throw new HttpException("Todo status not found", 404);
  }

  // Step 2: enforce business rules
  // - Default statuses cannot be deprecated
  if (existing.is_default === true) {
    throw new HttpException(
      "Default Todo status cannot be deprecated while configured as default",
      400,
    );
  }

  // - Already inactive statuses are considered already deprecated
  if (existing.is_active === false) {
    throw new HttpException("Todo status is already deprecated", 400);
  }

  // Step 3: logically deprecate the status by marking it inactive
  await MyGlobal.prisma.todo_app_todo_statuses.update({
    where: {
      code: props.statusCode,
    },
    data: {
      is_active: false,
    },
  });
}

